DROP TABLE IF EXISTS `evaluation_questions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `evaluation_questions` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `ai_reasoning` text COLLATE utf8mb4_unicode_ci,
  `content_category` text COLLATE utf8mb4_unicode_ci,
  `correct_answer` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime(6) DEFAULT NULL,
  `evaluation_id` bigint NOT NULL,
  `is_correct` bit(1) DEFAULT NULL,
  `knowledge_point` text COLLATE utf8mb4_unicode_ci,
  `max_score` int DEFAULT NULL,
  `media_url` text COLLATE utf8mb4_unicode_ci,
  `primary_project` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `question_category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `question_content` text COLLATE utf8mb4_unicode_ci,
  `question_id` bigint NOT NULL,
  `question_image_url` text COLLATE utf8mb4_unicode_ci,
