INSERT INTO `questions` VALUES (1,'发汗解表、宣肺平喘、利水消肿。主治风寒感冒、胸闷喘咳、风水浮肿。',NULL,'麻黄为辛温解表药之首，善于开腠理、透毛窍、发汗解表。其宣肺平喘之功，用于风寒外束、肺气不宣之喘咳；利水消肿之功，用于风水水肿。',NULL,'中医知识库','解表药','麻黄为发汗解表第一药，性温味辛，归肺、膀胱经，善于宣散肺气、开泄腠理','2026-04-17 06:30:00.000000',NULL,NULL,'麻黄；辛温解表；发汗解表；宣肺平喘',NULL,NULL,NULL,NULL,'中药学','麻黄的功效与主治是什么？','中药学',NULL,'中药','解表药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(2,'发汗解肌、温通经脉、助阳化气。主治风寒感冒、寒湿痹痛、痰饮蓄水。',NULL,'桂枝辛甘温，归心肺膀胱经。既可发散风寒，又可温通经脉，为治疗风寒感冒之要药。与麻黄相须为用，增强发汗之力。',NULL,'中医知识库','解表药','桂枝性辛甘温，既可解表又可温里，是调和营卫的重要药物','2026-04-17 06:30:00.000000',NULL,NULL,'桂枝；辛温解表；发汗解肌；温通经脉',NULL,NULL,NULL,NULL,'中药学','桂枝的功效与主治是什么？','中药学',NULL,'中药','解表药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(3,'清热泻火、除烦止渴。主治温热病气分实热证、肺热喘咳、胃火牙痛。',NULL,'石膏辛甘大寒，归肺胃经。为清解阳明胃经实热之要药。生用清热泻火，煅用收湿敛疮。与知母相须为用，治气分实热。',NULL,'中医知识库','清热药','石膏为清热泻火之重镇药，善清肺胃之热，为白虎汤之君药','2026-04-17 06:30:00.000000',NULL,NULL,'石膏；清热泻火；气分实热；白虎汤',NULL,NULL,NULL,NULL,'中药学','石膏的功效与主治是什么？','中药学',NULL,'中药','清热药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(4,'清热燥湿、泻火解毒、止血安胎。主治湿温暑湿、肺热咳嗽、血热出血、胎动不安。',NULL,'黄芩苦寒，归肺胆脾大肠经。善清肺火及上焦之热，又能清热燥湿、泻火解毒。炒炭止血，清热安胎。',NULL,'中医知识库','清热药','黄芩为清热燥湿之要药，尤善清肺火，主治上焦热证','2026-04-17 06:30:00.000000',NULL,NULL,'黄芩；清热燥湿；泻火解毒；清热安胎',NULL,NULL,NULL,NULL,'中药学','黄芩的功效与主治是什么？','中药学',NULL,'中药','清热药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(5,'清热燥湿、泻火解毒。主治湿热痞满、呕吐吞酸、泻痢、高热神昏、心烦不寐。',NULL,'黄连苦寒，归心脾胃肝胆大肠经。为清热燥湿、泻火解毒之要药，尤善清中焦湿热、泻心胃之火。',NULL,'中医知识库','清热药','黄连为清热燥湿第一要药，大苦大寒，尤善清心胃之火','2026-04-17 06:30:00.000000',NULL,NULL,'黄连；清热燥湿；泻火解毒；中焦湿热',NULL,NULL,NULL,NULL,'中药学','黄连的功效与主治是什么？','中药学',NULL,'中药','清热药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(6,'泻下攻积、清热泻火、凉血止血、解毒祛瘀。主治积滞便秘、血热吐衄、目赤咽肿、热毒疮疡。',NULL,'大黄苦寒，归脾胃大肠肝心经。为泻下攻积之要药，有\"将军\"之称。既能泻下通便，又能清热泻火、活血祛瘀。',NULL,'中医知识库','泻下药','大黄性猛善走，有将军之名，为泻热通便、推陈致新之要药','2026-04-17 06:30:00.000000',NULL,NULL,'大黄；泻下攻积；清热泻火；活血祛瘀',NULL,NULL,NULL,NULL,'中药学','大黄的功效与主治是什么？','中药学',NULL,'中药','泻下药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(7,'祛风除湿、通痹止痛。主治风寒湿痹、腰膝酸痛、少阴伏风头痛。',NULL,'独活辛苦微温，归肾膀胱经。善祛下焦风寒湿邪，为治风寒湿痹、腰膝酸痛之要药。与羌活相须为用，羌活治上，独活治下。',NULL,'中医知识库','祛风湿药','独活善祛下焦风寒湿邪，为治疗腰膝酸痛之要药','2026-04-17 06:30:00.000000',NULL,NULL,'独活；祛风除湿；通痹止痛；下焦风湿',NULL,NULL,NULL,NULL,'中药学','独活的功效与主治是什么？','中药学',NULL,'中药','祛风湿药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(8,'燥湿健脾、祛风散寒。主治湿阻中焦、脘腹胀满、风湿痹痛、风寒感冒。',NULL,'苍术辛苦温，归脾胃肝经。芳香燥烈，内化湿浊以健脾，外散风寒以祛湿。为治湿阻中焦之要药。',NULL,'中医知识库','化湿药','苍术芳香燥烈，善燥湿健脾，为治疗湿邪困脾之主药','2026-04-17 06:30:00.000000',NULL,NULL,'苍术；燥湿健脾；祛风散寒；湿阻中焦',NULL,NULL,NULL,NULL,'中药学','苍术的功效与主治是什么？','中药学',NULL,'中药','化湿药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(9,'利水渗湿、健脾、宁心。主治水肿尿少、痰饮眩悸、脾虚食少、便溏泄泻、心神不安。',NULL,'茯苓甘淡平，归心脾肾经。既能利水渗湿，又可健脾宁心。药性平和，利水而不伤正气，为利水渗湿之要药。',NULL,'中医知识库','利水渗湿药','茯苓药性平和，既能利水渗湿，又能健脾宁心，为补泻兼施之品','2026-04-17 06:30:00.000000',NULL,NULL,'茯苓；利水渗湿；健脾宁心；四君子汤',NULL,NULL,NULL,NULL,'中药学','茯苓的功效与主治是什么？','中药学',NULL,'中药','利水渗湿药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(10,'回阳救逆、补火助阳、散寒止痛。主治亡阳证、阳虚证、寒痹证。',NULL,'附子辛甘大热，有毒，归心肾脾经。为回阳救逆第一要药。上助心阳以通脉，下补肾阳以益火，能挽救散失之元阳。',NULL,'中医知识库','温里药','附子性大热有毒，为回阳救逆第一要药，善补命门之火','2026-04-17 06:30:00.000000',NULL,NULL,'附子；回阳救逆；补火助阳；有毒',NULL,NULL,NULL,NULL,'中药学','附子的功效与主治是什么？','中药学',NULL,'中药','温里药','中级','2026-04-20 23:49:54.000000',NULL,NULL),(11,'温中散寒、回阳通脉、温肺化饮。主治脘腹冷痛、呕吐泄泻、亡阳证、寒饮喘咳。',NULL,'干姜辛热，归脾胃心肺经。为温中散寒之要药，善温脾胃之阳。与附子相须为用，增强回阳救逆之力。',NULL,'中医知识库','温里药','干姜辛热守而不走，善温中散寒，为治疗脾胃寒证之主药','2026-04-17 06:30:00.000000',NULL,NULL,'干姜；温中散寒；回阳通脉；温肺化饮',NULL,NULL,NULL,NULL,'中药学','干姜的功效与主治是什么？','中药学',NULL,'中药','温里药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(12,'理气健脾、燥湿化痰。主治脘腹胀满、食少吐泻、咳嗽痰多。',NULL,'陈皮辛苦温，归脾肺经。为理气健脾、燥湿化痰之要药。辛散苦降，温和不峻，为临床最常用之理气药。',NULL,'中医知识库','理气药','陈皮为理气调中之佳品，以陈久者良，故称陈皮','2026-04-17 06:30:00.000000',NULL,NULL,'陈皮；理气健脾；燥湿化痰；二陈汤',NULL,NULL,NULL,NULL,'中药学','陈皮的功效与主治是什么？','中药学',NULL,'中药','理气药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(13,'消食化积、活血散瘀。主治肉食积滞、胃脘胀满、泻痢腹痛、瘀血经闭。',NULL,'山楂酸甘微温，归脾胃肝经。善于消化肉食积滞，为消食化积之要药。又能活血散瘀，治妇人瘀血诸证。',NULL,'中医知识库','消食药','山楂善消肉食之积，为消食化积之要药，兼能活血化瘀','2026-04-17 06:30:00.000000',NULL,NULL,'山楂；消食化积；活血散瘀；消化肉积',NULL,NULL,NULL,NULL,'中药学','山楂的功效与主治是什么？','中药学',NULL,'中药','消食药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(14,'化瘀止血、活血定痛。主治出血证、跌打损伤、瘀血肿痛。',NULL,'三七甘微苦温，归肝胃经。既能止血，又能散瘀，药效卓著，有\"止血不留瘀，化瘀不伤正\"之特点。为伤科要药。',NULL,'中医知识库','止血药','三七有止血神药之称，止血而不留瘀，化瘀而不伤正','2026-04-17 06:30:00.000000',NULL,NULL,'三七；化瘀止血；活血定痛；止血不留瘀',NULL,NULL,NULL,NULL,'中药学','三七的功效与主治是什么？','中药学',NULL,'中药','止血药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(15,'活血祛瘀、通经止痛、清心除烦、凉血消痈。主治月经不调、痛经经闭、胸痹心痛、疮疡肿毒。',NULL,'丹参苦微寒，归心肝经。为活血化瘀之要药，前人有\"一味丹参散，功同四物汤\"之说。善治血瘀诸证。',NULL,'中医知识库','活血化瘀药','丹参为活血化瘀之要药，有\"一味丹参功同四物\"之说','2026-04-17 06:30:00.000000',NULL,NULL,'丹参；活血祛瘀；通经止痛；一味丹参散功同四物汤',NULL,NULL,NULL,NULL,'中药学','丹参的功效与主治是什么？','中药学',NULL,'中药','活血化瘀药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(16,'燥湿化痰、降逆止呕、消痞散结。主治湿痰咳嗽、呕吐反胃、胸脘痞闷、梅核气。',NULL,'半夏辛温，有毒，归脾胃肺经。为燥湿化痰、降逆止呕之要药。善治脏腑之湿痰，为止呕之良药。',NULL,'中医知识库','化痰止咳药','半夏为化痰止呕之要药，尤善治湿痰与胃气上逆之呕吐','2026-04-17 06:30:00.000000',NULL,NULL,'半夏；燥湿化痰；降逆止呕；有毒；二陈汤',NULL,NULL,NULL,NULL,'中药学','半夏的功效与主治是什么？','中药学',NULL,'中药','化痰止咳药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(17,'养心益肝、安神、敛汗。主治虚烦不眠、惊悸多梦、体虚多汗。',NULL,'酸枣仁甘酸平，归心肝胆经。为养心安神之要药，善治心肝血虚之失眠。与柏子仁相须为用。',NULL,'中医知识库','安神药','酸枣仁为养心安神之要药，善治心肝血虚所致失眠','2026-04-17 06:30:00.000000',NULL,NULL,'酸枣仁；养心安神；敛汗；失眠',NULL,NULL,NULL,NULL,'中药学','酸枣仁的功效与主治是什么？','中药学',NULL,'中药','安神药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(18,'息风止痉、平抑肝阳、祛风通络。主治小儿惊风、癫痫抽搐、头痛眩晕、手足不遂。',NULL,'天麻甘平，归肝经。为治风之圣药，既能息风止痉，又能平抑肝阳、祛风通络。善治肝风内动之眩晕。',NULL,'中医知识库','平肝熄风药','天麻为治风要药，尤善治肝风内动之眩晕头痛','2026-04-17 06:30:00.000000',NULL,NULL,'天麻；息风止痉；平抑肝阳；治风圣药',NULL,NULL,NULL,NULL,'中药学','天麻的功效与主治是什么？','中药学',NULL,'中药','平肝熄风药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(19,'大补元气、补脾益肺、生津止渴、安神益智。主治气虚欲脱、脾气不足、肺气亏虚、津伤口渴。',NULL,'人参甘微苦微温，归脾肺心经。为补气第一要药，能大补元气、挽救虚脱。补脾益肺之力尤强。',NULL,'中医知识库','补气药','人参为补气之长，善大补元气，为拯危救脱之要药','2026-04-17 06:30:00.000000',NULL,NULL,'人参；大补元气；补脾益肺；补气第一要药',NULL,NULL,NULL,NULL,'中药学','人参的功效与主治是什么？','中药学',NULL,'中药','补虚药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(20,'补气升阳、益卫固表、利水消肿、托毒生肌。主治气虚乏力、食少便溏、中气下陷、表虚自汗。',NULL,'黄芪甘微温，归脾肺经。为补气升阳之要药，善补脾肺之气，又能益卫固表。与人参相比，人参补气于内，黄芪补气于外。',NULL,'中医知识库','补气药','黄芪善补脾肺之气，升阳举陷，为补气升阳之要药','2026-04-17 06:30:00.000000',NULL,NULL,'黄芪；补气升阳；益卫固表；补中益气汤',NULL,NULL,NULL,NULL,'中药学','黄芪的功效与主治是什么？','中药学',NULL,'中药','补虚药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(21,'健脾益气、燥湿利水、止汗安胎。主治脾虚食少、腹胀泄泻、痰饮眩悸、水肿、胎动不安。',NULL,'白术苦甘温，归脾胃经。为健脾益气之要药，善补脾胃、燥湿浊。与苍术相比，白术重在健脾，苍术重在燥湿。',NULL,'中医知识库','补气药','白术为健脾第一要药，善健脾益气、燥湿利水','2026-04-17 06:30:00.000000',NULL,NULL,'白术；健脾益气；燥湿利水；四君子汤',NULL,NULL,NULL,NULL,'中药学','白术的功效与主治是什么？','中药学',NULL,'中药','补虚药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(22,'补血活血、调经止痛、润肠通便。主治血虚萎黄、月经不调、经闭痛经、虚寒腹痛、肠燥便秘。',NULL,'当归甘辛温，归肝心脾经。为补血调经之要药，既能补血，又能活血，补中有动，行中有补。前人称其为\"妇科圣药\"。',NULL,'中医知识库','补血药','当归为补血调经之要药，补血活血兼能止痛，有\"妇科圣药\"之称','2026-04-17 06:30:00.000000',NULL,NULL,'当归；补血活血；调经止痛；妇科圣药',NULL,NULL,NULL,NULL,'中药学','当归的功效与主治是什么？','中药学',NULL,'中药','补虚药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(23,'补血滋阴、益精填髓。主治血虚萎黄、心悸怔忡、月经不调、肝肾阴虚、腰膝酸软。',NULL,'熟地黄甘微温，归肝肾经。为补血滋阴之要药，善补肝肾之阴血。与生地黄相比，生地偏于清热凉血，熟地偏于补血滋阴。',NULL,'中医知识库','补血药','熟地黄为补血滋阴之要药，善补肝肾精血','2026-04-17 06:30:00.000000',NULL,NULL,'熟地黄；补血滋阴；益精填髓；四物汤',NULL,NULL,NULL,NULL,'中药学','熟地黄的功效与主治是什么？','中药学',NULL,'中药','补虚药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(24,'滋补肝肾、益精明目。主治肝肾阴虚、精血不足、腰膝酸痛、眩晕耳鸣、内热消渴、目昏不明。',NULL,'枸杞子甘平，归肝肾经。为滋补肝肾之要药，既能补阴，又能补阳，平补肝肾，为常用的养生保健中药。',NULL,'中医知识库','补阴药','枸杞子药性平和，为滋补肝肾、益精明目之佳品','2026-04-17 06:30:00.000000',NULL,NULL,'枸杞子；滋补肝肾；益精明目；平补肝肾',NULL,NULL,NULL,NULL,'中药学','枸杞子的功效与主治是什么？','中药学',NULL,'中药','补虚药','入门','2026-04-20 23:49:54.000000',NULL,NULL),(25,'补肾阳、益精血、强筋骨。主治肾阳不足、精血亏虚、阳痿滑精、宫冷不孕、骨软行迟。',NULL,'鹿茸甘咸温，归肾肝经。为补肾阳、益精血之要药，补力峻猛。善补肾阳、益精血、强筋骨、调冲任。',NULL,'中医知识库','补阳药','鹿茸为峻补肾阳之要药，善补肾阳益精血，药力峻猛','2026-04-17 06:30:00.000000',NULL,NULL,'鹿茸；补肾阳；益精血；峻补要药',NULL,NULL,NULL,NULL,'中药学','鹿茸的功效与主治是什么？','中药学',NULL,'中药','补虚药','中级','2026-04-20 23:49:54.000000',NULL,NULL),(26,'收敛固涩、益气生津、补肾宁心。主治久咳虚喘、自汗盗汗、遗精滑精、久泻不止、津伤口渴。',NULL,'五味子酸甘温，归肺心肾经。五味俱全，以酸收为主。上敛肺气而止咳，下滋肾阴而涩精，内益气生津，外敛汗止泻。',NULL,'中医知识库','收涩药','五味子酸收甘补，性温而不燥，为收敛固涩之要药',