L,NULL,NULL,'解表剂','分经论治','2026-04-17 06:28:47.000000',NULL,NULL,'分经论治代表方',NULL,NULL,NULL,NULL,NULL,'九味羌活汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(180,'【组成】麻黄、芍药、细辛、干姜、炙甘草、桂枝各9g，五味子6g，半夏9g\n【功用】解表散寒，温肺化饮。\n【主治】外寒内饮证。恶寒发热，无汗，喘咳，痰多而稀，或痰饮咳喘，不得平卧，或身体疼重。\n【方解】麻黄、桂枝解表散寒为君；干姜、细辛温肺化饮为臣；五味子敛肺，芍药敛阴，防温燥伤正为佐；半夏燥湿化痰，甘草调和诸药。',NULL,NULL,NULL,NULL,'解表剂','解表化饮','2026-04-17 06:28:47.000000',NULL,NULL,'外寒内饮代表方',NULL,NULL,NULL,NULL,NULL,'小青龙汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(181,'【组成】金银花、连翘各30g，桔梗、薄荷、牛蒡子各18g，竹叶、荆芥穗各12g，淡豆豉、甘草各15g\n【功用】辛凉透表，清热解毒。\n【主治】温病初起。发热无汗，或有汗不畅，微恶风寒，头痛口渴，咳嗽咽痛，舌尖红，苔薄白或薄黄。\n【方解】金银花、连翘清热解毒、芳香辟秽为君；薄荷、牛蒡子疏散风热为臣；荆芥穗、淡豆豉透邪外出为佐。',NULL,NULL,NULL,NULL,'解表剂','辛凉平剂','2026-04-17 06:28:47.000000',NULL,NULL,'辛凉解表代表方',NULL,NULL,NULL,NULL,NULL,'银翘散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(182,'【组成】桑叶7.5g、菊花3g、杏仁6g、连翘5g、薄荷2.5g、桔梗6g、甘草2.5g、芦根6g\n【功用】疏风清热，宣肺止咳。\n【主治】风温初起。但咳，身热不甚，口微渴。\n【方解】桑叶、菊花疏风清热为君；杏仁、桔梗宣肺止咳为臣；薄荷助疏散风热，连翘清热解毒，芦根清热生津为佐。',NULL,NULL,NULL,NULL,'解表剂','辛凉轻剂','2026-04-17 06:28:47.000000',NULL,NULL,'风温咳嗽首选方',NULL,NULL,NULL,NULL,NULL,'桑菊饮','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(183,'【组成】麻黄6g、杏仁9g、石膏24g、炙甘草6g\n【功用】辛凉宣泄，清肺平喘。\n【主治】表邪化热壅肺证。身热不解，咳逆气急鼻煽，口渴，有汗或无汗，舌苔薄白或黄，脉滑而数。\n【方解】麻黄宣肺平喘为君；石膏清泄肺热为臣，麻黄与石膏相配，宣肺而不助热，清肺而不留邪。',NULL,NULL,NULL,NULL,'解表剂','宣肺泄热','2026-04-17 06:28:47.000000',NULL,NULL,'清肺平喘代表方',NULL,NULL,NULL,NULL,NULL,'麻杏石甘汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(184,'【组成】柴胡、前胡、川芎、枳壳、羌活、独活、茯苓、桔梗、人参、甘草各9g\n【功用】散寒祛湿，益气解表。\n【主治】气虚外感证。憎寒壮热，头项强痛，肢体酸痛，无汗，鼻塞声重，咳嗽有痰。\n【方解】羌活、独活散寒祛湿为君；柴胡、川芎散风邪行气血为臣；人参益气扶正为佐。',NULL,NULL,NULL,NULL,'解表剂','益气解表','2026-04-17 06:28:47.000000',NULL,NULL,'益气解表代表方',NULL,NULL,NULL,NULL,NULL,'败毒散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(185,'【组成】大黄12g、厚朴15g、枳实12g、芒硝9g\n【功用】峻下热结。\n【主治】阳明腑实证。大便不通，频转矢气，脘腹痞满，腹痛拒按，按之则硬，日晡潮热，神昏谵语。\n【方解】大黄泻热通便为君；芒硝软坚润燥为臣；厚朴、枳实行气散结为佐。',NULL,NULL,NULL,NULL,'泻下剂','寒下第一方','2026-04-17 06:28:47.000000',NULL,NULL,'峻下热结代表方',NULL,NULL,NULL,NULL,NULL,'大承气汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(186,'【组成】大黄15g、当归、干姜各9g、附子、人参、芒硝、甘草各6g\n【功用】攻下冷积，温补脾阳。\n【主治】阳虚寒积证。腹痛便秘，脐下绞结，绕脐不止，手足不温，苔白不渴，脉沉弦。\n【方解】附子、干姜温阳散寒为君；大黄泻下通便为臣；人参、当归益气养血为佐。',NULL,NULL,NULL,NULL,'泻下剂','攻补兼施','2026-04-17 06:28:47.000000',NULL,NULL,'温下代表方',NULL,NULL,NULL,NULL,NULL,'温脾汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(187,'【组成】麻子仁500g、芍药250g、枳实250g、大黄500g、厚朴250g、杏仁250g\n【功用】润肠泄热，行气通便。\n【主治】脾约证。肠胃燥热，脾津不足，大便干结，小便频数。\n【方解】麻子仁润肠通便为君；大黄泄热通便，杏仁降气润肠为臣。',NULL,NULL,NULL,NULL,'泻下剂','脾约便秘','2026-04-17 06:28:47.000000',NULL,NULL,'润下代表方',NULL,NULL,NULL,NULL,NULL,'麻子仁丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(188,'【组成】柴胡24g、黄芩9g、人参9g、半夏9g、甘草9g、生姜9g、大枣4枚\n【功用】和解少阳。\n【主治】少阳病证。往来寒热，胸胁苦满，默默不欲饮食，心烦喜呕，口苦，咽干，目眩。\n【方解】柴胡疏解少阳为君；黄芩清泄少阳为臣；半夏、生姜和胃降逆，人参、大枣益气扶正为佐。',NULL,NULL,NULL,NULL,'和解剂','和解少阳','2026-04-17 06:28:47.000000',NULL,NULL,'和解少阳代表方',NULL,NULL,NULL,NULL,NULL,'小柴胡汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(189,'【组成】柴胡、当归、白芍、白术、茯苓各30g，甘草15g，薄荷少许，生姜少许\n【功用】疏肝解郁，养血健脾。\n【主治】肝郁血虚脾弱证。两胁作痛，头痛目眩，口燥咽干，神疲食少，或月经不调，乳房胀痛。\n【方解】柴胡疏肝解郁为君；当归、白芍养血柔肝为臣；白术、茯苓健脾祛湿为佐。',NULL,NULL,NULL,NULL,'和解剂','肝郁脾虚','2026-04-17 06:28:47.000000',NULL,NULL,'调肝养血代表方',NULL,NULL,NULL,NULL,NULL,'逍遥散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(190,'【组成】半夏12g、黄芩、干姜、人参各9g，黄连3g、大枣4枚、炙甘草9g\n【功用】寒热平调，消痞散结。\n【主治】寒热互结之痞证。心下痞满而不痛，呕吐，肠鸣下利。\n【方解】半夏散结消痞、降逆止呕为君；黄芩、黄连泄热为臣；干姜温中散寒，人参、大枣补中为佐。',NULL,NULL,NULL,NULL,'和解剂','寒热平调','2026-04-17 06:28:47.000000',NULL,NULL,'调和肠胃代表方',NULL,NULL,NULL,NULL,NULL,'半夏泻心汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(191,'【组成】柴胡、芍药、枳实、甘草各等分\n【功用】透邪解郁，疏肝理脾。\n【主治】阳郁厥逆证。手足不温，或腹痛，或泄利下重，脉弦。\n【方解】柴胡疏肝解郁为君；芍药柔肝养血为臣；枳实理气解郁为佐；甘草调和诸药为使。',NULL,NULL,NULL,NULL,'和解剂','透邪解郁','2026-04-17 06:28:47.000000',NULL,NULL,'疏肝理脾代表方',NULL,NULL,NULL,NULL,NULL,'四逆散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(192,'【组成】白术90g、白芍60g、陈皮45g、防风30g\n【功用】补脾柔肝，祛湿止泻。\n【主治】脾虚肝旺之痛泻。肠鸣腹痛，大便泄泻，泻必腹痛，舌苔薄白。\n【方解】白术补脾燥湿为君；白芍柔肝缓急为臣；陈皮理气为佐；防风散肝舒脾为使。',NULL,NULL,NULL,NULL,'和解剂','扶土抑木','2026-04-17 06:28:47.000000',NULL,NULL,'扶土抑木代表方',NULL,NULL,NULL,NULL,NULL,'痛泻要方','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(193,'【组成】石膏50g、知母18g、炙甘草6g、粳米9g\n【功用】清热生津。\n【主治】阳明气分热盛证。壮热面赤，烦渴引饮，大汗出，脉洪大有力。\n【方解】石膏清阳明胃热为君；知母清热滋阴为臣；粳米、甘草益胃护津为佐。',NULL,NULL,NULL,NULL,'清热剂','清气分热','2026-04-17 06:28:47.000000',NULL,NULL,'清气分热代表方',NULL,NULL,NULL,NULL,NULL,'白虎汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(194,'【组成】犀角(水牛角代)30g、生地15g、玄参9g、竹叶心3g、麦冬9g、丹参6g、黄连5g、金银花9g、连翘6g\n【功用】清营解毒，透热养阴。\n【主治】热入营分证。身热夜甚，神烦少寐，斑疹隐隐，舌绛而干。\n【方解】水牛角清营凉血为君；生地、玄参、麦冬清热养阴为臣；金银花、连翘透热转气为佐。',NULL,NULL,NULL,NULL,'清热剂','清营透热','2026-04-17 06:28:47.000000',NULL,NULL,'清营凉血代表方',NULL,NULL,NULL,NULL,NULL,'清营汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(195,'【组成】黄连9g、黄芩6g、黄柏6g、栀子9g\n【功用】泻火解毒。\n【主治】三焦火毒证。大热烦躁，错语不眠，热病吐衄，发斑，外科痈肿疔毒。\n【方解】黄连泻心火为君；黄芩泻上焦之火，黄柏泻下焦之火为臣；栀子泻三焦之火为佐。',NULL,NULL,NULL,NULL,'清热剂','泻火解毒','2026-04-17 06:28:47.000000',NULL,NULL,'苦寒直折代表方',NULL,NULL,NULL,NULL,NULL,'黄连解毒汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(196,'【组成】龙胆草6g、黄芩9g、栀子9g、泽泻12g、木通9g、车前子9g、当归3g、生地9g、柴胡6g、甘草6g\n【功用】泻肝胆实火，清下焦湿热。\n【主治】肝胆实火上炎或湿热下注证。头痛目赤，胁痛口苦，耳聋耳肿，或小便淋浊，阴肿阴痒。\n【方解】龙胆草泻肝胆实火为君；黄芩、栀子苦寒泻火为臣；泽泻、木通、车前子清利湿热为佐。',NULL,NULL,NULL,NULL,'清热剂','泻肝火','2026-04-17 06:28:47.000000',NULL,NULL,'泻肝胆实火代表方',NULL,NULL,NULL,NULL,NULL,'龙胆泻肝汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(197,'【组成】白芷、贝母、防风、赤芍、当归尾、甘草、皂角刺、穿山甲、天花粉、乳香、没药各3g，金银花、陈皮各9g\n【功用】清热解毒，消肿溃坚，活血止痛。\n【主治】疮疡肿毒初起。红肿焮痛，身热微恶寒。\n【方解】金银花清热解毒为君；当归、赤芍、乳香、没药活血散瘀为臣；穿山甲、皂角刺消肿溃坚为佐。',NULL,NULL,NULL,NULL,'清热剂','清热解毒','2026-04-17 06:28:47.000000',NULL,NULL,'疮疡之圣药',NULL,NULL,NULL,NULL,NULL,'仙方活命饮','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(198,'【组成】黄连180g、吴茱萸30g\n【功用】清泻肝火，降逆止呕。\n【主治】肝火犯胃证。胁肋胀痛，嘈杂吞酸，呕吐口苦，舌红苔黄，脉弦数。\n【方解】黄连泻心火、清胃热为君；吴茱萸散肝郁、降逆气为臣佐。',NULL,NULL,NULL,NULL,'清热剂','清肝和胃','2026-04-17 06:28:47.000000',NULL,NULL,'肝火犯胃代表方',NULL,NULL,NULL,NULL,NULL,'左金丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(199,'【组成】苇茎60g、薏苡仁30g、瓜瓣24g、桃仁9g\n【功用】清肺化痰，逐瘀排脓。\n【主治】肺痈。咳嗽痰多，咳吐腥臭脓血，胸中隐隐作痛，舌红苔黄腻。\n【方解】苇茎清肺泄热为君；薏苡仁清热利湿为臣；瓜瓣、桃仁化痰逐瘀为佐。',NULL,NULL,NULL,NULL,'清热剂','清肺排脓','2026-04-17 06:28:47.000000',NULL,NULL,'肺痈代表方',NULL,NULL,NULL,NULL,NULL,'苇茎汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(200,'【组成】人参、干姜、炙甘草、白术各9g\n【功用】温中散寒，补气健脾。\n【主治】脾胃虚寒证。脘腹冷痛，呕吐下利，不欲饮食，四肢不温，舌淡苔白，脉沉细。\n【方解】干姜温中散寒为君；人参补气健脾为臣；白术健脾燥湿为佐；甘草调和诸药为使。',NULL,NULL,NULL,NULL,'温里剂','温中健脾','2026-04-17 06:28:47.000000',NULL,NULL,'温中散寒代表方',NULL,NULL,NULL,NULL,NULL,'理中丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(201,'【组成】桂枝9g、芍药18g、炙甘草6g、生姜9g、大枣4枚、饴糖30g\n【功用】温中补虚，和里缓急。\n【主治】虚劳里急证。腹中拘急疼痛，喜温喜按，面色无华，舌淡苔白。\n【方解】饴糖温中补虚为君；芍药益阴和里为臣；桂枝温阳化气为佐。',NULL,NULL,NULL,NULL,'温里剂','建中缓急','2026-04-17 06:28:47.000000',NULL,NULL,'温中补虚缓急代表方',NULL,NULL,NULL,NULL,NULL,'小建中汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(202,'【组成】附子15g、干姜6g、炙甘草6g\n【功用】回阳救逆。\n【主治】心肾阳虚寒厥证。四肢厥逆，恶寒蜷卧，神衰欲寐，呕吐下利，舌淡苔白滑，脉微细。\n【方解】附子温肾回阳为君；干姜温中散寒为臣；甘草益气和中为佐。',NULL,NULL,NULL,NULL,'温里剂','回阳救逆','2026-04-17 06:28:47.000000',NULL,NULL,'回阳救逆代表方',NULL,NULL,NULL,NULL,NULL,'四逆汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(203,'【组成】当归9g、桂枝9g、芍药9g、细辛3g、炙甘草6g、通草6g、大枣8枚\n【功用】温经散寒，养血通脉。\n【主治】血虚寒厥证。手足厥寒，舌淡苔白，脉细欲绝。\n【方解】当归养血和血为君；桂枝温经通脉为臣；芍药益阴和营，细辛散寒为佐。',NULL,NULL,NULL,NULL,'温里剂','温经通脉','2026-04-17 06:28:47.000000',NULL,NULL,'养血通脉代表方',NULL,NULL,NULL,NULL,NULL,'当归四逆汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(204,'【组成】熟地30g、肉桂3g、麻黄2g、鹿角胶9g、白芥子6g、姜炭2g、生甘草3g\n【功用】温阳补血，散寒通滞。\n【主治】阴疽证。患处漫肿无头，皮色不变，酸痛无热，口中不渴，舌淡苔白。\n【方解】熟地、鹿角胶温阳补血为君；肉桂、姜炭温阳散寒为臣；麻黄开腠理、白芥子祛痰为佐。',NULL,NULL,NULL,NULL,'温里剂','温阳消疽','2026-04-17 06:28:47.000000',NULL,NULL,'阴疽圣药',NULL,NULL,NULL,NULL,NULL,'阳和汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(205,'【组成】人参9g、白术9g、茯苓9g、炙甘草6g\n【功用】益气健脾。\n【主治】脾胃气虚证。面色萎白，语声低微，气短乏力，食少便溏，舌淡苔白，脉虚缓。\n【方解】人参补气健脾为君；白术健脾燥湿为臣；茯苓渗湿健脾为佐；甘草调和诸药为使。',NULL,NULL,NULL,NULL,'补益剂','补气','2026-04-17 06:28:47.000000',NULL,NULL,'补气健脾基本方',NULL,NULL,NULL,NULL,NULL,'四君子汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(206,'【组成】人参、白术、茯苓、山药、莲子、薏苡仁、扁豆、砂仁、桔梗、甘草\n【功用】益气健脾，渗湿止泻。\n【主治】脾虚湿盛证。饮食不化，胸脘痞闷，肠鸣泄泻，四肢乏力，面色萎黄。\n【方解】人参、白术、茯苓益气健脾为君；山药、莲子助健脾为臣；薏苡仁、扁豆渗湿为佐。',NULL,NULL,NULL,NULL,'补益剂','健脾渗湿','2026-04-17 06:28:47.000000',NULL,NULL,'培土生金代表方',NULL,NULL,NULL,NULL,NULL,'参苓白术散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(207,'【组成】黄芪18g、人参6g、白术9g、炙甘草9g、当归3g、陈皮6g、升麻6g、柴胡6g\n【功用】补中益气，升阳举陷。\n【主治】脾胃气虚证及气虚下陷证。少气懒言，体倦肢软，面色萎白，饮食减少，或脱肛、子宫脱垂。\n【方解】黄芪补中益气、升阳举陷为君；人参、白术、甘草益气健脾为臣；升麻、柴胡升阳举陷为佐。',NULL,NULL,NULL,NULL,'补益剂','升阳举陷','2026-04-17 06:28:47.000000',NULL,NULL,'益气升阳代表方',NULL,NULL,NULL,NULL,NULL,'补中益气汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(208,'【组成】人参9g、麦冬9g、五味子6g\n【功用】益气生津，敛阴止汗。\n【主治】气阴两虚证。体倦气短，咽干口渴，自汗，舌干红少苔，脉虚数。\n【方解】人参大补元气为君；麦冬养阴清热为臣；五味子敛阴止汗为佐。',NULL,NULL,NULL,NULL,'补益剂','益气养阴','2026-04-17 06:28:47.000000',NULL,NULL,'气阴双补代表方',NULL,NULL,NULL,NULL,NULL,'生脉散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(209,'【组成】熟地12g、当归9g、白芍9g、川芎6g\n【功用】补血调血。\n【主治】营血虚滞证。头晕目眩，心悸失眠，面色无华，妇人月经不调，量少或经闭。\n【方解】熟地滋阴养血为君；当归补血活血为臣；白芍敛阴和营，川芎活血行气为佐。',NULL,NULL,NULL,NULL,'补益剂','补血','2026-04-17 06:28:47.000000',NULL,NULL,'补血调经基本方',NULL,NULL,NULL,NULL,NULL,'四物汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(210,'【组成】白术、茯神、黄芪、龙眼肉、酸枣仁各9g，人参、木香各6g，甘草3g，当归3g，远志3g\n【功用】益气补血，健脾养心。\n【主治】心脾气血两虚证。心悸怔忡，健忘失眠，盗汗虚热，食少体倦，面色萎黄。\n【方解】黄芪、人参补气健脾为君；当归、龙眼肉补血养心为臣；酸枣仁、远志宁心安神为佐。',NULL,NULL,NULL,NULL,'补益剂','补益心脾','2026-04-17 06:28:47.000000',NULL,NULL,'心脾两补代表方',NULL,NULL,NULL,NULL,NULL,'归脾汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(211,'【组成】黄芪30g、当归6g\n【功用】补气生血。\n【主治】血虚发热证。肌热面赤，烦渴欲饮，脉洪大而虚，重按无力。\n【方解】黄芪大补脾肺之气，以资生血之源为君；当归养血和营为臣。',NULL,NULL,NULL,NULL,'补益剂','补气生血','2026-04-17 06:28:47.000000',NULL,NULL,'补气生血代表方',NULL,NULL,NULL,NULL,NULL,'当归补血汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(212,'【组成】人参、白术、茯苓、当归、川芎、白芍、熟地各9g，甘草6g\n【功用】益气补血。\n【主治】气血两虚证。面色苍白或萎黄，头晕目眩，四肢倦怠，气短懒言，心悸怔忡。\n【方解】四君子汤补气，四物汤补血，气血双补。',NULL,NULL,NULL,NULL,'补益剂','气血双补','2026-04-17 06:28:47.000000',NULL,NULL,'气血双补代表方',NULL,NULL,NULL,NULL,NULL,'八珍汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(213,'【组成】熟地24g、山萸肉12g、山药12g、泽泻9g、牡丹皮9g、茯苓9g\n【功用】滋阴补肾。\n【主治】肾阴虚证。头晕耳鸣，腰膝酸软，骨蒸潮热，盗汗遗精，消渴，手足心热，舌红少苔。\n【方解】熟地滋阴补肾为君；山萸肉、山药补肝脾为臣；三泻（泽泻、丹皮、茯苓）泻浊为佐。',NULL,NULL,NULL,NULL,'补益剂','滋补肝肾','2026-04-17 06:28:47.000000',NULL,NULL,'滋阴补肾代表方',NULL,NULL,NULL,NULL,NULL,'六味地黄丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(214,'【组成】干地黄24g、山药12g、山茱萸12g、泽泻9g、茯苓9g、牡丹皮9g、桂枝3g、附子3g\n【功用】补肾助阳。\n【主治】肾阳不足证。腰痛脚软，身半以下常有冷感，小便不利或小便反多，舌淡而胖。\n【方解】附子、桂枝温补肾阳为君；地黄、山茱萸滋阴为臣。',NULL,NULL,NULL,NULL,'补益剂','温补肾阳','2026-04-17 06:28:47.000000',NULL,NULL,'补肾阳代表方',NULL,NULL,NULL,NULL,NULL,'肾气丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(215,'【组成】熟地、山药、枸杞、山茱萸、菟丝子、鹿角胶、龟板胶、川牛膝\n【功用】滋阴补肾，填精益髓。\n【主治】肾阴不足证。头目眩晕，腰酸腿软，遗精滑泄，自汗盗汗，口燥咽干。\n【方解】熟地滋肾填精为君；山茱萸、枸杞滋阴为臣。',NULL,NULL,NULL,NULL,'补益剂','填精补髓','2026-04-17 06:28:47.000000',NULL,NULL,'纯补无泻之滋阴方',NULL,NULL,NULL,NULL,NULL,'左归丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(216,'【组成】熟地、山药、山茱萸、枸杞、菟丝子、杜仲、当归、肉桂、附子、鹿角胶\n【功用】温补肾阳，填精补血。\n【主治】肾阳不足证。气怯神疲，腹痛腰酸，肢冷，阳痿遗精。\n【方解】附子、肉桂温补肾阳为君；鹿角胶补肾填精为臣。',NULL,NULL,NULL,NULL,'补益剂','温阳填精','2026-04-17 06:28:47.000000',NULL,NULL,'温补肾阳填精方',NULL,NULL,NULL,NULL,NULL,'右归丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(217,'【组成】北沙参、麦冬、当归各9g，生地18g，枸杞12g，川楝子4.5g\n【功用】滋阴疏肝。\n【主治】肝肾阴虚，肝气不舒证。胸脘胁痛，吞酸吐苦，咽干口燥，舌红少津。\n【方解】生地滋阴养血为君；枸杞滋肾为臣；沙参、麦冬养阴为佐；川楝子疏肝泄热。',NULL,NULL,NULL,NULL,'补益剂','滋阴疏肝','2026-04-17 06:28:47.000000',NULL,NULL,'滋阴疏肝代表方',NULL,NULL,NULL,NULL,NULL,'一贯煎','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(218,'【组成】百合12g、熟地、生地、当归各9g，白芍、甘草各3g，桔梗、玄参各6g，贝母、麦冬各9g\n【功用】滋阴润肺，化痰止咳。\n【主治】肺肾阴虚，虚火上炎证。咳嗽气喘，痰中带血，咽喉燥痛，手足心热。\n【方解】百合滋阴清热为君；生地、熟地滋阴补肾为臣；麦冬、玄参养阴清热为佐。',NULL,NULL,NULL,NULL,'补益剂','滋阴润肺','2026-04-17 06:28:47.000000',NULL,NULL,'滋阴润肺代表方',NULL,NULL,NULL,NULL,NULL,'百合固金汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(219,'【组成】炙甘草12g、生姜9g、桂枝9g、人参6g、生地30g、阿胶6g、麦冬12g、麻仁12g、大枣10枚\n【功用】益气滋阴，通阳复脉。\n【主治】气虚血弱证。脉结代，心动悸，虚赢少气，舌光少苔。\n【方解】炙甘草益气养心为君；人参、大枣补气为臣；生地、阿胶、麦冬滋阴养血为佐。',NULL,NULL,NULL,NULL,'补益剂','益气复脉','2026-04-17 06:28:47.000000',NULL,NULL,'复脉定悸代表方',NULL,NULL,NULL,NULL,NULL,'炙甘草汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(220,'【组成】人参、茯苓、玄参、丹参、桔梗、远志各15g，当归、五味子、麦冬、天冬、柏子仁、酸枣仁各30g，生地120g\n【功用】滋阴养血，补心安神。\n【主治】阴虚血少，神志不安证。心悸怔忡，虚烦失眠，神疲健忘，手足心热，舌红少苔。\n【方解】生地滋阴养血为君；天冬、麦冬滋阴清热为臣；酸枣仁、柏子仁养心安神为佐。',NULL,NULL,NULL,NULL,'安神剂','滋阴安神','2026-04-17 06:28:47.000000',NULL,NULL,'滋阴安神代表方',NULL,NULL,NULL,NULL,NULL,'天王补心丹','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(221,'【组成】酸枣仁15g、甘草3g、知母6g、茯苓6g、川芎6g\n【功用】养血安神，清热除烦。\n【主治】虚烦不眠证。虚烦不得眠，心悸盗汗，头目眩晕，咽干口燥，舌红。\n【方解】酸枣仁养肝安神为君；茯苓宁心安神为臣；知母清热除烦，川芎调畅气血为佐。',NULL,NULL,NULL,NULL,'安神剂','养肝安神','2026-04-17 06:28:47.000000',NULL,NULL,'养血安神代表方',NULL,NULL,NULL,NULL,NULL,'酸枣仁汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(222,'【组成】牛黄、郁金、犀角(水牛角代)、黄连、朱砂、栀子、雄黄、黄芩、珍珠、冰片、麝香\n【功用】清热解毒，豁痰开窍。\n【主治】邪热内陷心包证。高热烦躁，神昏谵语，中风昏迷，惊厥。\n【方解】牛黄清心解毒、豁痰开窍为君；麝香、冰片芳香开窍为臣。',NULL,NULL,NULL,NULL,'开窍剂','清热开窍','2026-04-17 06:28:47.000000',NULL,NULL,'凉开三宝之首',NULL,NULL,NULL,NULL,NULL,'安宫牛黄丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(223,'【组成】黄芪、麻黄根、牡蛎各30g，浮小麦30g\n【功用】敛阴止汗，益气固表。\n【主治】体虚自汗、盗汗证。常自汗出，夜卧更甚，心悸惊惕，短气烦倦。\n【方解】牡蛎敛阴止汗为君；黄芪益气固表为臣；麻黄根止汗为佐。',NULL,NULL,NULL,NULL,'固涩剂','敛阴止汗','2026-04-17 06:28:47.000000',NULL,NULL,'固表止汗代表方',NULL,NULL,NULL,NULL,NULL,'牡蛎散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(224,'【组成】人参、当归、白术各6g，肉豆蔻、肉桂、炙甘草各3g，白芍15g，木香4.5g，诃子12g，罂粟壳20g\n【功用】涩肠固脱，温补脾肾。\n【主治】久泻久痢，脾肾虚寒证。大便滑脱不禁，腹痛喜温喜按，食少神疲。\n【方解】罂粟壳涩肠止泻为君；肉豆蔻、诃子温涩为臣。',NULL,NULL,NULL,NULL,'固涩剂','涩肠固脱','2026-04-17 06:28:47.000000',NULL,NULL,'涩肠止泻代表方',NULL,NULL,NULL,NULL,NULL,'真人养脏汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(225,'【组成】肉豆蔻60g、补骨脂120g、五味子60g、吴茱萸30g\n【功用】温肾暖脾，固肠止泻。\n【主治】脾肾阳虚之五更泄。五更泄泻，不思饮食，食不消化，或久泻不愈，腹痛腰酸。\n【方解】补骨脂温补肾阳为君；肉豆蔻温脾涩肠为臣；五味子涩肠止泻为佐。',NULL,NULL,NULL,NULL,'固涩剂','温肾固肠','2026-04-17 06:28:47.000000',NULL,NULL,'五更泄泻代表方',NULL,NULL,NULL,NULL,NULL,'四神丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(226,'【组成】沙苑蒺藜、芡实、莲须各60g，龙骨、牡蛎各30g\n【功用】补肾涩精。\n【主治】肾虚精关不固证。遗精滑泄，腰痛耳鸣，四肢酸软，神疲乏力。\n【方解】沙苑蒺藜补肾固精为君；芡实益肾涩精为臣；龙骨、牡蛎收敛固涩为佐。',NULL,NULL,NULL,NULL,'固涩剂','补肾固精','2026-04-17 06:28:47.000000',NULL,NULL,'固精止遗代表方',NULL,NULL,NULL,NULL,NULL,'金锁固精丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(227,'【组成】白术、山药各30g，人参6g，白芍15g，车前子9g，苍术9g，甘草3g，陈皮2g，黑芥穗2g，柴胡2g\n【功用】补脾疏肝，化湿止带。\n【主治】脾虚肝郁，湿浊带下证。带下色白或淡黄，清稀无臭，面色苍白，倦怠便溏。\n【方解】白术、山药补脾祛湿为君；人参、苍术益气燥湿为臣。',NULL,NULL,NULL,NULL,'固涩剂','健脾止带','2026-04-17 06:28:47.000000',NULL,NULL,'健脾止带代表方',NULL,NULL,NULL,NULL,NULL,'完带汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(228,'【组成】香附、川芎、苍术、神曲、栀子各等分\n【功用】行气解郁。\n【主治】六郁证。胸膈痞闷，脘腹胀痛，嗳腐吞酸，恶心呕吐，饮食不消。\n【方解】香附行气解郁为君，治气郁；川芎活血治血郁；苍术燥湿治湿郁；栀子清热治火郁；神曲消食治食郁。',NULL,NULL,NULL,NULL,'理气剂','行气解郁','2026-04-17 06:28:47.000000',NULL,NULL,'通治六郁代表方',NULL,NULL,NULL,NULL,NULL,'越鞠丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(229,'【组成】半夏12g、厚朴9g、茯苓12g、生姜15g、苏叶6g\n【功用】行气散结，降逆化痰。\n【主治】梅核气。咽中如有物阻，咯吐不出，吞咽不下，胸胁满闷。\n【方解】半夏化痰散结、降逆为君；厚朴行气开郁为臣；茯苓渗湿为佐。',NULL,NULL,NULL,NULL,'理气剂','行气散结','2026-04-17 06:28:47.000000',NULL,NULL,'梅核气代表方',NULL,NULL,NULL,NULL,NULL,'半夏厚朴汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(230,'【组成】瓜蒌实12g、薤白12g、白酒适量\n【功用】通阳散结，行气祛痰。\n【主治】胸痹。胸中闷痛，甚至胸痛彻背，喘息咳唾，短气，舌苔白腻。\n【方解】瓜蒌涤痰宽胸为君；薤白通阳散结为臣。',NULL,NULL,NULL,NULL,'理气剂','通阳宽胸','2026-04-17 06:28:47.000000',NULL,NULL,'胸痹基础方',NULL,NULL,NULL,NULL,NULL,'瓜蒌薤白白酒汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(231,'【组成】苏子9g、半夏9g、当归6g、甘草6g、前胡6g、厚朴6g、肉桂3g\n【功用】降气平喘，祛痰止咳。\n【主治】上实下虚之喘咳。咳嗽喘逆，痰多胸闷，呼多吸少，腰酸腿软。\n【方解】苏子降气祛痰为君；半夏、厚朴祛痰降逆为臣；肉桂温肾纳气为佐。',NULL,NULL,NULL,NULL,'理气剂','降气化痰','2026-04-17 06:28:47.000000',NULL,NULL,'降气平喘代表方',NULL,NULL,NULL,NULL,NULL,'苏子降气汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(232,'【组成】旋覆花9g、人参6g、生姜15g、代赭石9g、甘草9g、半夏9g、大枣4枚\n【功用】降逆化痰，益气和胃。\n【主治】胃虚痰阻气逆证。心下痞硬，噫气不除，或反胃呕逆。\n【方解】旋覆花下气消痰为君；代赭石重镇降逆为臣；半夏、生姜散结降逆为佐。',NULL,NULL,NULL,NULL,'理气剂','和胃降逆','2026-04-17 06:28:47.000000',NULL,NULL,'降逆止呕代表方',NULL,NULL,NULL,NULL,NULL,'旋覆代赭汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(233,'【组成】桃仁12g、红花9g、当归9g、生地9g、川芎5g、赤芍6g、牛膝9g、桔梗5g、柴胡3g、枳壳6g、甘草3g\n【功用】活血化瘀，行气止痛。\n【主治】胸中血瘀证。胸痛，头痛日久，痛如针刺而有定处，或呃逆日久不止，内热烦闷。\n【方解】桃仁、红花活血祛瘀为君；川芎、赤芍助活血为臣；柴胡、枳壳行气为佐。',NULL,NULL,NULL,NULL,'理血剂','活血化瘀','2026-04-17 06:28:47.000000',NULL,NULL,'活血化瘀代表方',NULL,NULL,NULL,NULL,NULL,'血府逐瘀汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(234,'【组成】黄芪120g、当归尾6g、赤芍5g、地龙3g、川芎3g、红花3g、桃仁3g\n【功用】补气活血通络。\n【主治】中风之气虚血瘀证。半身不遂，口眼歪斜，语言謇涩，口角流涎，下肢痿废。\n【方解】黄芪大补元气为君；当归尾活血为臣；赤芍、川芎、桃仁、红花活血化瘀为佐。',NULL,NULL,NULL,NULL,'理血剂','补气活血','2026-04-17 06:28:47.000000',NULL,NULL,'益气活血通络代表方',NULL,NULL,NULL,NULL,NULL,'补阳还五汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(235,'【组成】全当归24g、川芎9g、桃仁6g、干姜2g、炙甘草2g\n【功用】养血祛瘀，温经止痛。\n【主治】产后瘀滞腹痛。恶露不行，小腹冷痛。\n【方解】当归养血活血为君；川芎活血行气为臣；桃仁活血祛瘀为佐。',NULL,NULL,NULL,NULL,'理血剂','化瘀生新','2026-04-17 06:28:47.000000',NULL,NULL,'产后化瘀代表方',NULL,NULL,NULL,NULL,NULL,'生化汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(236,'【组成】吴茱萸、麦冬各9g，当归、芍药、川芎、人参、桂枝、阿胶、牡丹皮、生姜、甘草、半夏各6g\n【功用】温经散寒，养血祛瘀。\n【主治】冲任虚寒，瘀血阻滞证。漏下不止，月经不调，或前或后，或一月再行，或经停不至，傍晚发热，手心烦热。\n【方解】吴茱萸、桂枝温经散寒为君；当归、川芎活血为臣。',NULL,NULL,NULL,NULL,'理血剂','温经调经','2026-04-17 06:28:47.000000',NULL,NULL,'调经祖方',NULL,NULL,NULL,NULL,NULL,'温经汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(237,'【组成】青黛6g、瓜蒌仁9g、海粉9g、栀子9g、诃子6g\n【功用】清肝宁肺，凉血止血。\n【主治】肝火犯肺之咳血证。咳嗽痰稠带血，咯吐不爽，心烦易怒，胸胁作痛。\n【方解】青黛、栀子清肝泻火为君；瓜蒌仁清热化痰为臣。',NULL,NULL,NULL,NULL,'理血剂','清肝止血','2026-04-17 06:28:47.000000',NULL,NULL,'肝火犯肺咳血代表方',NULL,NULL,NULL,NULL,NULL,'咳血方','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(238,'【组成】槐花12g、柏叶12g、荆芥穗6g、枳壳6g\n【功用】清肠止血，疏风行气。\n【主治】肠风脏毒下血。便前出血，或便后出血，或粪中带血，血色鲜红或晦暗。\n【方解】槐花清肠止血为君；侧柏叶助止血为臣。',NULL,NULL,NULL,NULL,'理血剂','清肠止血','2026-04-17 06:28:47.000000',NULL,NULL,'肠风下血代表方',NULL,NULL,NULL,NULL,NULL,'槐花散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(239,'【组成】灶心黄土30g、白术、附子、甘草、干地黄、阿胶、黄芩各9g\n【功用】温阳健脾，养血止血。\n【主治】脾阳不足，脾不统血证。大便下血，先便后血，或吐血、衄血，面色萎黄，四肢不温。\n【方解】灶心黄土温中止血为君；白术、附子温阳健脾为臣。',NULL,NULL,NULL,NULL,'理血剂','温阳止血','2026-04-17 06:28:47.000000',NULL,NULL,'温脾摄血代表方',NULL,NULL,NULL,NULL,NULL,'黄土汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(240,'【组成】川芎、荆芥各12g，白芷、羌活、甘草各6g，细辛3g，防风4.5g，薄荷24g\n【功用】疏风止痛。\n【主治】外感风邪头痛。偏正头痛，巅顶作痛，恶寒发热，目眩鼻塞。\n【方解】川芎活血行气、祛风止痛为君；薄荷、荆芥疏风为臣。',NULL,NULL,NULL,NULL,'治风剂','疏散外风','2026-04-17 06:28:47.000000',NULL,NULL,'治头痛基本方',NULL,NULL,NULL,NULL,NULL,'川芎茶调散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(241,'【组成】怀牛膝30g、代赭石30g、龙骨15g、牡蛎15g、龟板15g、玄参15g、天冬15g、茵陈6g、川楝子6g、麦芽6g、甘草4.5g\n【功用】镇肝熄风，滋阴潜阳。\n【主治】类中风。头目眩晕，目胀耳鸣，脑部热痛，心中烦热，面色如醉，或肢体不利。\n【方解】怀牛膝引血下行为君；代赭石镇肝降逆为臣。',NULL,NULL,NULL,NULL,'治风剂','镇肝潜阳','2026-04-17 06:28:47.000000',NULL,NULL,'镇肝熄风代表方',NULL,NULL,NULL,NULL,NULL,'镇肝熄风汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(242,'【组成】天麻9g、钩藤12g、石决明18g、栀子9g、黄芩9g、牛膝12g、杜仲、益母草、桑寄生、夜交藤、朱茯神各9g\n【功用】平肝熄风，清热活血，补益肝肾。\n【主治】肝阳偏亢，肝风上扰证。头痛，眩晕，失眠多梦，舌红苔黄。\n【方解】天麻、钩藤平肝熄风为君；石决明平肝潜阳为臣。',NULL,NULL,NULL,NULL,'治风剂','平肝潜阳','2026-04-17 06:28:47.000000',NULL,NULL,'平肝熄风代表方',NULL,NULL,NULL,NULL,NULL,'天麻钩藤饮','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(243,'【组成】生白芍18g、阿胶9g、生龟板12g、干地黄18g、麻仁6g、五味子6g、生牡蛎12g、麦冬18g、炙甘草12g、鸡子黄2枚、鳖甲12g\n【功用】滋阴熄风。\n【主治】阴虚动风证。温病后期，神倦瘈疭，脉气虚弱，舌绛苔少。\n【方解】鸡子黄、阿胶滋阴养血为君；白芍、地黄、麦冬滋阴柔肝为臣。',NULL,NULL,NULL,NULL,'治风剂','滋阴熄风','2026-04-17 06:28:47.000000',NULL,NULL,'滋阴熄风代表方',NULL,NULL,NULL,NULL,NULL,'大定风珠','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(244,'【组成】苍术15g、厚朴9g、陈皮9g、甘草4g\n【功用】燥湿运脾，行气和胃。\n【主治】湿滞脾胃证。脘腹胀满，不思饮食，口淡无味，恶心呕吐，嗳气吞酸，肢体沉重。\n【方解】苍术燥湿健脾为君；厚朴行气化湿为臣；陈皮理气和胃为佐。',NULL,NULL,NULL,NULL,'祛湿剂','燥湿和胃','2026-04-17 06:28:47.000000',NULL,NULL,'燥湿和胃代表方',NULL,NULL,NULL,NULL,NULL,'平胃散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(245,'【组成】藿香、苏叶、白芷、大腹皮、茯苓各9g，白术、半夏曲、陈皮、厚朴、桔梗各6g，甘草3g\n【功用】解表化湿，理气和中。\n【主治】外感风寒，内伤湿滞证。恶寒发热，头痛，胸膈满闷，脘腹疼痛，恶心呕吐，肠鸣泄泻。\n【方解】藿香化湿和胃为君；苏叶、白芷解表为臣。',NULL,NULL,NULL,NULL,'祛湿剂','芳香化湿','2026-04-17 06:28:47.000000',NULL,NULL,'化湿和中代表方',NULL,NULL,NULL,NULL,NULL,'藿香正气散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(246,'【组成】茵陈18g、栀子9g、大黄6g\n【功用】清热利湿退黄。\n【主治】湿热黄疸。一身面目俱黄，黄色鲜明，腹微满，小便不利。\n【方解】茵陈清热利湿退黄为君；栀子清泄三焦为臣；大黄泄热通便为佐。',NULL,NULL,NULL,NULL,'祛湿剂','清热退黄','2026-04-17 06:28:47.000000',NULL,NULL,'湿热黄疸代表方',NULL,NULL,NULL,NULL,NULL,'茵陈蒿汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(247,'【组成】杏仁15g、薏苡仁18g、白蔻仁6g、厚朴6g、半夏15g、通草6g、竹叶6g、滑石18g\n【功用】宣畅气机，清利湿热。\n【主治】湿温初起及暑温夹湿。头痛恶寒，身重疼痛，面色淡黄，胸闷不饥，午后身热。\n【方解】杏仁宣上焦，白蔻仁畅中焦，薏苡仁渗下焦，三仁同用。',NULL,NULL,NULL,NULL,'祛湿剂','宣畅三焦','2026-04-17 06:28:47.000000',NULL,NULL,'湿温初起代表方',NULL,NULL,NULL,NULL,NULL,'三仁汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(248,'【组成】猪苓9g、泽泻15g、白术9g、茯苓9g、桂枝6g\n【功用】利水渗湿，温阳化气。\n【主治】蓄水证。小便不利，头痛微热，烦渴欲饮，水入即吐，舌苔白，脉浮。\n【方解】泽泻利水渗湿为君；茯苓、猪苓助利水为臣；白术健脾，桂枝化气为佐。',NULL,NULL,NULL,NULL,'祛湿剂','利水渗湿','2026-04-17 06:28:47.000000',NULL,NULL,'化气利水代表方',NULL,NULL,NULL,NULL,NULL,'五苓散','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(249,'【组成】茯苓9g、芍药9g、白术6g、生姜9g、附子15g\n【功用】温阳利水。\n【主治】阳虚水泛证。畏寒肢冷，小便不利，四肢沉重，下肢水肿，或腹痛下利。\n【方解】附子温肾助阳为君；茯苓、白术健脾利水为臣；生姜温散水气为佐。',NULL,NULL,NULL,NULL,'祛湿剂','温阳化水','2026-04-17 06:28:47.000000',NULL,NULL,'温阳利水代表方',NULL,NULL,NULL,NULL,NULL,'真武汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(250,'【组成】半夏15g、橘红15g、白茯苓9g、炙甘草5g\n【功用】燥湿化痰，理气和中。\n【主治】湿痰证。咳嗽痰多，色白易咯，胸膈满闷，恶心呕吐，肢体倦怠。\n【方解】半夏燥湿化痰为君；橘红理气化痰为臣；茯苓健脾渗湿为佐。',NULL,NULL,NULL,NULL,'祛痰剂','燥湿化痰','2026-04-17 06:28:47.000000',NULL,NULL,'治痰通用方',NULL,NULL,NULL,NULL,NULL,'二陈汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(251,'【组成】半夏、竹茹、枳实各6g，陈皮9g，茯苓5g，甘草3g\n【功用】理气化痰，清胆和胃。\n【主治】胆胃不和，痰热内扰证。虚烦不眠，或呕吐呃逆，惊悸不宁，癫痫。\n【方解】半夏燥湿化痰为君；竹茹清热化痰为臣；枳实、陈皮理气为佐。',NULL,NULL,NULL,NULL,'祛痰剂','清胆和胃','2026-04-17 06:28:47.000000',NULL,NULL,'理气化痰清胆代表方',NULL,NULL,NULL,NULL,NULL,'温胆汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(252,'【组成】半夏9g、天麻6g、茯苓6g、橘红6g、白术15g、甘草3g\n【功用】化痰熄风，健脾祛湿。\n【主治】风痰上扰证。眩晕头痛，胸膈痞闷，恶心呕吐，舌苔白腻，脉弦滑。\n【方解】半夏燥湿化痰为君；天麻平肝熄风为臣；白术健脾为佐。',NULL,NULL,NULL,NULL,'祛痰剂','化痰熄风','2026-04-17 06:28:47.000000',NULL,NULL,'风痰眩晕代表方',NULL,NULL,NULL,NULL,NULL,'半夏白术天麻汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(253,'【组成】山楂18g、神曲6g、半夏、茯苓各9g，陈皮、连翘、莱菔子各3g\n【功用】消食和胃。\n【主治】食滞胃脘证。脘腹痞满胀痛，嗳腐吞酸，恶食呕逆，舌苔厚腻。\n【方解】山楂消食化积为君；神曲消食健胃为臣；半夏、陈皮理气化湿为佐。',NULL,NULL,NULL,NULL,'消食剂','消食和胃','2026-04-17 06:28:47.000000',NULL,NULL,'消食导滞代表方',NULL,NULL,NULL,NULL,NULL,'保和丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(254,'【组成】人参、白术、陈皮、麦芽各60g，山楂45g，枳实90g\n【功用】健脾和胃，消食止泻。\n【主治】脾胃虚弱，食积内停证。食少难消，脘腹痞满，大便溏薄，苔腻微黄。\n【方解】人参、白术健脾为君；山楂、神曲消食为臣。',NULL,NULL,NULL,NULL,'消食剂','健脾消食','2026-04-17 06:28:47.000000',NULL,NULL,'健脾消食代表方',NULL,NULL,NULL,NULL,NULL,'健脾丸','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(255,'【组成】西洋参5g、石斛15g、麦冬9g、黄连3g、竹叶6g、荷梗15g、知母6g、甘草3g、粳米15g、西瓜翠衣30g\n【功用】清暑益气，养阴生津。\n【主治】暑热气津两伤证。身热汗多，口渴心烦，小便短赤，体倦少气，精神不振。\n【方解】西瓜翠衣清热解暑为君；西洋参益气生津为臣。',NULL,NULL,NULL,NULL,'祛暑剂','清暑益气','2026-04-17 06:28:47.000000',NULL,NULL,'暑伤气阴代表方',NULL,NULL,NULL,NULL,NULL,'清暑益气汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(256,'【组成】石膏15g、熟地15g、麦冬6g、知母5g、牛膝5g\n【功用】清胃热，滋肾阴。\n【主治】胃热阴虚证。头痛，牙痛，齿松牙衄，烦热干渴，舌红苔黄而干。\n【方解】石膏清胃热为君；熟地滋肾阴为臣；麦冬、知母滋阴清热为佐。',NULL,NULL,NULL,NULL,'清热剂','清胃滋阴','2026-04-17 06:28:47.000000',NULL,NULL,'清胃滋阴代表方',NULL,NULL,NULL,NULL,NULL,'玉女煎','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(257,'【组成】芍药30g、当归15g、黄连15g、槟榔6g、木香6g、甘草6g、大黄9g、黄芩15g、肉桂5g\n【功用】清热燥湿，调气和血。\n【主治】湿热痢疾。腹痛，便脓血，赤白相兼，里急后重，肛门灼热。\n【方解】芍药调和气血为君；黄连、黄芩清热燥湿为臣。',NULL,NULL,NULL,NULL,'清热剂','清热治痢','2026-04-17 06:28:47.000000',NULL,NULL,'湿热痢疾代表方',NULL,NULL,NULL,NULL,NULL,'芍药汤','方剂学',NULL,'方剂',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(258,'阴阳是对自然界相互关联的某些事物和现象对立双方的概括。阴阳既可以代表两个相互对立的事物，也可以代表同一事物内部所存在的相互对立的两个方面。',NULL,'阴阳是中国古代哲学的一对范畴，最初指日光的向背，向日为阳，背日为阴。后来引申为气候的寒暖，方位的上下、左右、内外，运动状态的躁动和宁静等。阴阳学说认为，宇宙间任何事物都包含着阴和阳两个方面。',NULL,'中医知识库','阴阳学说','阴阳是对自然界相互关联事物对立双方的概括','2026-04-17 06:30:00.000000',NULL,NULL,'阴阳；基本概念；对立统一',NULL,NULL,NULL,NULL,'中医基础理论','阴阳的基本概念是什么？','中医基础理论',NULL,'理论','阴阳学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(259,'阴阳对立制约是指阴阳双方在一个统一体中相互斗争、相互制约和相互排斥。阴阳之间的相互制约，主要体现为相互斗争和相互制约的过程。',NULL,'阴阳对立制约是阴阳双方之间的相互斗争、相互制约关系。如寒与热、动与静、升与降等都是阴阳对立制约的体现。阴主静、阳主动，阴阳双方相互制约，使事物保持协调平衡。如果阴阳对立制约关系失调，就会出现阴阳偏盛偏衰的异常现象。',NULL,'中医知识库','阴阳学说','阴阳双方在统一体中相互斗争制约以维持动态平衡','2026-04-17 06:30:00.000000',NULL,NULL,'阴阳；对立制约；相互斗争',NULL,NULL,NULL,NULL,'中医基础理论','阴阳的对立制约体现在哪些方面？','中医基础理论',NULL,'理论','阴阳学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(260,'阴阳互根互用是指阴阳双方各以对方为自己存在的前提和条件，任何一方都不能脱离另一方而单独存在。阴以阳为根，阳以阴为根。',NULL,'阴阳互根指阴阳双方各以对方为存在的依据，互为其根。互用指阴阳双方不断地相互资生、相互促进。如气与血，气属阳，血属阴，气能生血、行血，血能载气、养气。阴阳互根互用是事物发展变化的前提条件，若互根关系遭到破坏，则会导致\"孤阴不生，独阳不长\"。',NULL,'中医知识库','阴阳学说','阴阳双方互为存在前提，相互资生促进','2026-04-17 06:30:00.000000',NULL,NULL,'阴阳；互根互用；互为依据',NULL,NULL,NULL,NULL,'中医基础理论','阴阳的互根互用有何意义？','中医基础理论',NULL,'理论','阴阳学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(261,'阴阳消长平衡是指阴阳双方的量和比例不是固定不变的，而是处于不断的消长变化之中，消长变化在一定范围内维持着相对的动态平衡。',NULL,'阴阳消长是指阴阳双方的增减变化，包括此消彼长、此长彼消、此消彼消、此长彼长等形式。阴阳平衡是指阴阳双方在相互消长的过程中维持相对的动态平衡状态。正常的阴阳消长是事物发展的动力，若消长过度或不及，打破平衡，则产生疾病。',NULL,'中医知识库','阴阳学说','阴阳在消长变化中维持动态平衡','2026-04-17 06:30:00.000000',NULL,NULL,'阴阳；消长平衡；动态平衡',NULL,NULL,NULL,NULL,'中医基础理论','阴阳的消长平衡是怎样的？','中医基础理论',NULL,'理论','阴阳学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(262,'阴阳转化是指阴阳双方在一定条件下可以向其各自相反的方向转化，即阳可以转化为阴，阴可以转化为阳。所谓\"重阴必阳，重阳必阴\"。',NULL,'阴阳转化是阴阳消长的极端结果。当事物的阴阳消长达到一定限度时，就会发生质的转化。如寒极生热、热极生寒。阴阳转化必须具备一定条件，\"物极必反\"是其基本规律。在疾病过程中，寒证和热证的互相转化就是阴阳转化的具体表现。',NULL,'中医知识库','阴阳学说','阴阳在极端条件下向对立面转化','2026-04-17 06:30:00.000000',NULL,NULL,'阴阳；相互转化；物极必反',NULL,NULL,NULL,NULL,'中医基础理论','阴阳的相互转化如何理解？','中医基础理论',NULL,'理论','阴阳学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(263,'人体上部为阳，下部为阴；体表为阳，体内为阴；背部为阳，腹部为阴；四肢外侧为阳，内侧为阴。五脏为阴，六腑为阳。',NULL,'就人体部位而言，上半身属阳，下半身属阴；体表属阳，体内属阴。就背腹而言，背部属阳，腹部属阴。就四肢而言，四肢外侧属阳，内侧属阴。就脏腑而言，五脏藏精气属阴，六腑传化物属阳。在五脏之中，心肺居于上属阳，肝肾居于下属阴。',NULL,'中医知识库','阴阳学说','阴阳在人体各部位有系统分布规律','2026-04-17 06:30:00.000000',NULL,NULL,'阴阳；人体分布；上下内外',NULL,NULL,NULL,NULL,'中医基础理论','阴阳在人体是如何分布的？','中医基础理论',NULL,'理论','阴阳学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(264,'疾病的发生是阴阳失调的结果。无论疾病怎样复杂，都可用阴阳失调来概括说明。阳胜则热，阴胜则寒，阳虚则寒，阴虚则热。',NULL,'中医认为疾病的发生，从根本上说是阴阳平衡被破坏，即阴阳失调。阳邪致病可使阳气偏盛，出现热证；阴邪致病可使阴气偏盛，出现寒证。阳气不足则出现虚寒证；阴液不足则出现虚热证。因此调整阴阳是治病的根本原则。',NULL,'中医知识库','阴阳学说','疾病本质是阴阳平衡被破坏','2026-04-17 06:30:00.000000',NULL,NULL,'阴阳；疾病关系；阴阳失调',NULL,NULL,NULL,NULL,'中医基础理论','阴阳与疾病的关系是什么？','中医基础理论',NULL,'理论','阴阳学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(265,'阴虚主要表现为五心烦热、潮热盗汗、口干咽燥、形体消瘦、舌红少苔、脉细数等。阴虚则热，属于虚热证。',NULL,'阴虚是指机体阴液不足，滋润、宁静功能减退的病理状态。临床表现为形体消瘦、口燥咽干、五心烦热、潮热盗汗、颧红、舌红少苔或无苔、脉细数。阴虚则阳气相对偏亢，出现虚热内生之象，即\"阴虚则热\"。常见于肺阴虚、心阴虚、肝阴虚、肾阴虚等。',NULL,'中医知识库','阴阳学说','阴液不足导致虚热内生','2026-04-17 06:30:00.000000',NULL,NULL,'阴虚；虚热；五心烦热；盗汗',NULL,NULL,NULL,NULL,'中医基础理论','阴虚的主要表现有哪些？','中医基础理论',NULL,'理论','阴阳学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(266,'阳虚主要表现为畏寒肢冷、面色苍白、神疲乏力、口淡不渴、小便清长、大便溏薄、舌淡胖、脉沉迟无力等。阳虚则寒，属于虚寒证。',NULL,'阳虚是指机体阳气不足，温煦、推动功能减退的病理状态。临床表现为畏寒肢冷、面色㿠白、神疲乏力、少气懒言、口淡不渴或喜热饮、小便清长、大便溏薄、舌淡胖嫩、苔白润、脉沉迟无力。阳气不足，温煦功能下降，出现虚寒内生之象，即\"阳虚则寒\"。',NULL,'中医知识库','阴阳学说','阳气不足导致虚寒内生','2026-04-17 06:30:00.000000',NULL,NULL,'阳虚；虚寒；畏寒肢冷',NULL,NULL,NULL,NULL,'中医基础理论','阳虚的主要表现有哪些？','中医基础理论',NULL,'理论','阴阳学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(267,'阴阳两虚是指阴液和阳气均不足，既有阴虚的表现，又有阳虚的表现。常见于久病之后，正气大伤，阴阳俱损。',NULL,'阴阳两虚多由久病不愈，阴阳相互损及所致。临床表现既有阴虚的虚热征象，如五心烦热、口干咽燥，又有阳虚的虚寒征象，如畏寒肢冷、面色苍白。多见于慢性病的后期，如慢性肾衰竭、肺痿等。治疗应阴阳双补，但需分清主次。',NULL,'中医知识库','阴阳学说','阴液与阳气均不足的病理状态','2026-04-17 06:30:00.000000',NULL,NULL,'阴阳两虚；久病；阴阳俱损',NULL,NULL,NULL,NULL,'中医基础理论','什么是阴阳两虚？','中医基础理论',NULL,'理论','阴阳学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(268,'阴盛则寒是指阴气偏盛，导致寒象丛生的病理变化。表现为实寒证，如形寒肢冷、腹痛喜暖、舌淡苔白、脉紧或迟等。',NULL,'阴盛则寒属于阴气绝对偏盛的病理状态，表现为实寒证。由于感受寒邪或过食生冷，致使体内阴气偏盛，阳气受到遏制。临床表现为形寒肢冷、脘腹冷痛、得温则减、口淡不渴、小便清长、大便稀溏、舌淡苔白、脉紧或迟等。治宜温散寒邪。',NULL,'中医知识库','阴阳学说','阴气偏盛导致的实寒病理变化','2026-04-17 06:30:00.000000',NULL,NULL,'阴盛则寒；实寒证；寒邪',NULL,NULL,NULL,NULL,'中医基础理论','阴盛则寒的含义是什么？','中医基础理论',NULL,'理论','阴阳学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(269,'阳盛则热是指阳气偏盛，导致热象丛生的病理变化。表现为实热证，如壮热、口渴、面红、舌红苔黄、脉数等。',NULL,'阳盛则热属于阳气绝对偏盛的病理状态，表现为实热证。由于感受热邪或素体阳盛，致使体内阳气偏盛。临床表现为壮热、烦渴、面红目赤、大便秘结、小便短赤、舌红苔黄、脉数有力等。治宜清热泻火。',NULL,'中医知识库','阴阳学说','阳气偏盛导致的实热病理变化','2026-04-17 06:30:00.000000',NULL,NULL,'阳盛则热；实热证；热邪',NULL,NULL,NULL,NULL,'中医基础理论','阳盛则热的含义是什么？','中医基础理论',NULL,'理论','阴阳学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(270,'阴损及阳是指阴液亏损，累及阳气，导致以阴虚为主的阴阳两虚证。即先有阴虚，后因阴虚而导致阳气生化不足。',NULL,'阴损及阳是在阴虚的基础上进一步发展，阴液亏损导致阳气生化乏源。如慢性消耗性疾病，长期阴虚，最终出现畏寒肢冷等阳虚表现。临床以阴虚为主，兼见阳虚症状。治疗应在滋阴的基础上兼顾温阳。',NULL,'中医知识库','阴阳学说','阴虚累及阳气，以阴虚为主的阴阳两虚','2026-04-17 06:30:00.000000',NULL,NULL,'阴损及阳；阴虚为主；阴阳两虚',NULL,NULL,NULL,NULL,'中医基础理论','什么是阴损及阳？','中医基础理论',NULL,'理论','阴阳学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(271,'阳损及阴是指阳气亏损，累及阴液，导致以阳虚为主的阴阳两虚证。即先有阳虚，后因阳虚而导致阴液化生不足。',NULL,'阳损及阴是在阳虚的基础上进一步发展，阳气亏损导致阴液不能化生。如水肿日久，阳气虚衰，最终出现阴液亏损的表现。临床以阳虚为主，兼见阴虚症状。治疗应在温阳的基础上兼顾滋阴。',NULL,'中医知识库','阴阳学说','阳虚累及阴液，以阳虚为主的阴阳两虚','2026-04-17 06:30:00.000000',NULL,NULL,'阳损及阴；阳虚为主；阴阳两虚',NULL,NULL,NULL,NULL,'中医基础理论','什么是阳损及阴？','中医基础理论',NULL,'理论','阴阳学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(272,'阴虚火旺是阴虚发展到一定程度，虚火内生的病理状态。表现为五心烦热、骨蒸潮热、颧红盗汗、失眠多梦、舌红少津、脉细数。',NULL,'阴虚火旺是在阴虚基础上，因阴不制阳，虚火内生。阴液亏损不能制约阳气，导致阳气相对偏亢而化火。临床表现为午后潮热、骨蒸劳热、五心烦热、颧红、盗汗、失眠多梦、口干舌燥、舌红少苔、脉细数。治宜滋阴降火。',NULL,'中医知识库','阴阳学说','阴虚不制阳导致虚火内生','2026-04-17 06:30:00.000000',NULL,NULL,'阴虚火旺；虚火内生；骨蒸潮热',NULL,NULL,NULL,NULL,'中医基础理论','阴虚火旺的表现与机理是什么？','中医基础理论',NULL,'理论','阴阳学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(273,'亡阴是指阴液突然大量消耗或丢失，表现为汗出如油、烦躁不安、口渴欲饮、舌红而干、脉细数无力。亡阳是阳气突然大量脱失，表现为冷汗淋漓、面色苍白、四肢厥冷、舌淡润、脉微欲绝。',NULL,'亡阴多由高热大汗、剧烈吐泻等原因，导致阴液突然大量耗损。表现为汗热而粘、口渴引饮、面红肢温、烦躁不安、舌红而干、脉细数疾。亡阳多由亡阴进一步发展或大汗大出血等，导致阳气突然脱失。表现为冷汗淋漓、面色苍白、四肢厥冷、精神萎靡、舌淡而润、脉微欲绝。亡阴亡阳可相互影响，密切相关。',NULL,'中医知识库','阴阳学说','阴液或阳气突然大量脱失的危重证候','2026-04-17 06:30:00.000000',NULL,NULL,'亡阴；亡阳；危重证候',NULL,NULL,NULL,NULL,'中医基础理论','亡阴亡阳如何区别？','中医基础理论',NULL,'理论','阴阳学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(274,'调和阴阳的方法包括药物调理、饮食调养、起居有常、精神调摄、运动锻炼等。药物治疗根据阴阳偏盛偏衰，分别采用泻其有余、补其不足的原则。',NULL,'调和阴阳是中医养生的基本原则。药物方面，阳盛者清热泻火，阴盛者温散寒邪，阴虚者滋阴，阳虚者温阳。饮食方面，热体宜凉，寒体宜温。起居方面，顺应四时阴阳变化。精神方面，保持平和心态。运动方面，动静结合，适度锻炼。此外，还可通过针灸、推拿等方法调和阴阳。',NULL,'中医知识库','阴阳学说','通过各种方法使阴阳恢复平衡','2026-04-17 06:30:00.000000',NULL,NULL,'调和阴阳；养生；治病求本',NULL,NULL,NULL,NULL,'中医基础理论','调和阴阳的方法有哪些？','中医基础理论',NULL,'理论','阴阳学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(275,'春夏养阳，秋冬养阴是中医顺应四时的养生原则。春夏阳气升发，应顺应阳气生长；秋冬阴气渐盛，应顺应阴精收藏，使阴阳协调。',NULL,'此原则出自《黄帝内经》，强调顺应自然界阴阳消长变化来养生。春夏季节，自然界阳气升发，人体应借助自然之势养护阳气，宜早起、适当运动、饮食温养。秋冬季节，自然界阴气渐盛，人体应顺应阴精收藏之势养护阴精，宜早卧、收敛神气、饮食滋阴。如此则能顺应四时，保持阴阳平衡。',NULL,'中医知识库','阴阳学说','顺应四时阴阳变化以养生','2026-04-17 06:30:00.000000',NULL,NULL,'春夏养阳；秋冬养阴；四时养生',NULL,NULL,NULL,NULL,'中医基础理论','春夏养阳秋冬养阴的养生意义是什么？','中医基础理论',NULL,'理论','阴阳学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(276,'阴平阳秘是指阴气平顺、阳气固密，阴阳双方保持平衡协调的状态，是人体健康的根本保证。语出《素问·生气通天论》。',NULL,'\"阴平阳秘，精神乃治\"出自《素问·生气通天论》。阴平指阴气平顺、宁静；阳秘指阳气固密、不外泄。阴平阳秘是阴阳平衡的最佳状态，是维持生命活动的根本。若阴阳失调，则疾病丛生，即\"阴阳离决，精气乃绝\"。因此调和阴阳、保持阴平阳秘是养生和治病的最高准则。',NULL,'中医知识库','阴阳学说','阴阳平衡协调的最佳健康状态','2026-04-17 06:30:00.000000',NULL,NULL,'阴平阳秘；阴阳平衡；健康状态',NULL,NULL,NULL,NULL,'中医基础理论','阴平阳秘的含义是什么？','中医基础理论',NULL,'理论','阴阳学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(277,'阴阳辨证是八纲辨证的总纲。表、热、实属阳，里、寒、虚属阴。阳气偏盛多为阳证，阴气偏盛多为阴证。辨别阴阳是诊断疾病的第一步。',NULL,'阴阳辨证统领其他辨证方法。阳证表现为面色红赤、身热喜凉、烦躁不安、口渴喜冷饮、小便短赤、大便秘结、舌红苔黄、脉数有力。阴证表现为面色苍白或晦暗、畏寒肢冷、精神萎靡、口淡不渴、小便清长、大便稀溏、舌淡苔白、脉沉迟无力。辨明阴阳是指导治疗的关键。',NULL,'中医知识库','阴阳学说','阴阳辨证是八纲辨证的总纲','2026-04-17 06:30:00.000000',NULL,NULL,'阴阳辨证；八纲总纲；阳证阴证',NULL,NULL,NULL,NULL,'中医基础理论','中医诊断中如何进行阴阳辨证？','中医基础理论',NULL,'理论','阴阳学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(278,'五行即木、火、土、金、水五种基本物质的运动变化。五行学说认为世界上一切事物都是由木、火、土、金、水五种基本物质之间的运动变化而生成的。',NULL,'五行是中国古代哲学的基本概念，木、火、土、金、水五种物质的运动变化构成世界的基础。五行学说以五行的特性来分析事物属性，以五行的生克制化规律来阐释事物之间的相互关系。五行之间存在相生、相克、相乘、相侮等关系，构成了一个完整的系统论体系。',NULL,'中医知识库','五行学说','木火土金水五种物质及其运动变化规律','2026-04-17 06:30:00.000000',NULL,NULL,'五行；木火土金水；基本概念',NULL,NULL,NULL,NULL,'中医基础理论','五行的基本概念是什么？','中医基础理论',NULL,'理论','五行学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(279,'木曰曲直，具有生长、升发、条达、舒畅的特性。在脏腑归属上，肝属木，胆为肝之腑。肝主疏泄，性喜条达，与木的特性相符。',NULL,'木的特性是\"曲直\"，引申为生长、升发、条达、舒畅。凡具有此类特性的事物和现象都归属于木。在人体，肝属木，肝主疏泄，性喜条达，主筋，开窍于目，其华在爪。肝的升发、疏泄功能与木的生长、条达特性一致。肝在志为怒，在液为泪，在体为筋。',NULL,'中医知识库','五行学说','木主生长升发，肝属木主疏泄','2026-04-17 06:30:00.000000',NULL,NULL,'木；曲直；肝属木；疏泄',NULL,NULL,NULL,NULL,'中医基础理论','木的特性及脏腑归属是什么？','中医基础理论',NULL,'理论','五行学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(280,'火曰炎上，具有温热、上升、光明的特性。在脏腑归属上，心属火，小肠为心之腑。心主神明，主血脉，与火的温煦特性相符。',NULL,'火的特性是\"炎上\"，引申为温热、上升、光明。凡具有此类特性的事物和现象都归属于火。在人体，心属火，心主血脉、主神明，心阳有温煦作用。心开窍于舌，其华在面，在体为脉，在志为喜，在液为汗。心为阳脏，阳气最盛，与火的温热特性一致。',NULL,'中医知识库','五行学说','火主温热上升，心属火主神明','2026-04-17 06:30:00.000000',NULL,NULL,'火；炎上；心属火；温煦',NULL,NULL,NULL,NULL,'中医基础理论','火的特性及脏腑归属是什么？','中医基础理论',NULL,'理论','五行学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(281,'土爰稼穑，具有生化、承载、受纳的特性。在脏腑归属上，脾属土，胃为脾之腑。脾主运化，为后天之本，与土的生化特性相符。',NULL,'土的特性是\"稼穑\"，引申为生化、承载、受纳。凡具有此类特性的事物和现象都归属于土。在人体，脾属土，脾主运化水谷精微，为气血生化之源，后天之本。脾开窍于口，其华在唇，在体为肉，在志为思，在液为涎。脾的运化功能与土的生化特性一致。',NULL,'中医知识库','五行学说','土主生化承载，脾属土主运化','2026-04-17 06:30:00.000000',NULL,NULL,'土；稼穑；脾属土；运化',NULL,NULL,NULL,NULL,'中医基础理论','土的特性及脏腑归属是什么？','中医基础理论',NULL,'理论','五行学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(282,'金曰从革，具有沉降、肃杀、收敛、清洁的特性。在脏腑归属上，肺属金，大肠为肺之腑。肺主气、主肃降，与金的收敛特性相符。',NULL,'金的特性是\"从革\"，引申为沉降、肃杀、收敛、清洁。凡具有此类特性的事物和现象都归属于金。在人体，肺属金，肺主气、司呼吸、主宣发肃降，具有清肃下降的特性。肺开窍于鼻，其华在皮毛，在体为皮，在志为悲，在液为涕。肺的肃降功能与金的收敛特性一致。',NULL,'中医知识库','五行学说','金主收敛肃降，肺属金主气','2026-04-17 06:30:00.000000',NULL,NULL,'金；从革；肺属金；肃降',NULL,NULL,NULL,NULL,'中医基础理论','金的特性及脏腑归属是什么？','中医基础理论',NULL,'理论','五行学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(283,'水曰润下，具有滋润、下行、寒凉、闭藏的特性。在脏腑归属上，肾属水，膀胱为肾之腑。肾主水、主藏精，与水的润下特性相符。',NULL,'水的特性是\"润下\"，引申为滋润、下行、寒凉、闭藏。凡具有此类特性的事物和现象都归属于水。在人体，肾属水，肾主水液代谢、主藏精，具有滋润和闭藏的特性。肾开窍于耳及二阴，其华在发，在体为骨，在志为恐，在液为唾。肾的藏精和主水功能与水的润下闭藏特性一致。',NULL,'中医知识库','五行学说','水主滋润闭藏，肾属水主藏精','2026-04-17 06:30:00.000000',NULL,NULL,'水；润下；肾属水；藏精',NULL,NULL,NULL,NULL,'中医基础理论','水的特性及脏腑归属是什么？','中医基础理论',NULL,'理论','五行学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(284,'五行相生是指五行之间相互资生、相互促进的关系。相生顺序为木生火、火生土、土生金、金生水、水生木，循环不息。',NULL,'五行相生，即相互资生、促进。木生火，木可燃烧生火；火生土，火燃烧后成灰烬归土；土生金，金属矿藏于土中；金生水，金属熔化成液态；水生木，水滋润草木生长。相生关系中，生我者为母，我生者为子，故又称\"母子关系\"。如木生火，木为火之母，火为木之子。',NULL,'中医知识库','五行学说','五行之间相互资生促进的循环关系','2026-04-17 06:30:00.000000',NULL,NULL,'五行相生；母子关系；资生促进',NULL,NULL,NULL,NULL,'中医基础理论','五行相生的含义及顺序是什么？','中医基础理论',NULL,'理论','五行学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(285,'五行相克是指五行之间相互制约、相互克制的关系。相克顺序为木克土、土克水、水克火、火克金、金克木，循环不息。',NULL,'五行相克，即相互制约、克制。木克土，树木扎根于土中；土克水，堤坝可挡水；水克火，水可灭火；火克金，火可熔金；金克木，金属工具可伐木。相克关系中，克我者为所不胜，我克者为所胜。相克关系维持五行之间的平衡协调，是正常现象。',NULL,'中医知识库','五行学说','五行之间相互制约克制的循环关系','2026-04-17 06:30:00.000000',NULL,NULL,'五行相克；制约克制；所胜所不胜',NULL,NULL,NULL,NULL,'中医基础理论','五行相克的含义及顺序是什么？','中医基础理论',NULL,'理论','五行学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(286,'五行相乘是指五行中某一行对其所胜一行的过度克制，即克制太过。相乘的顺序与相克一致，但程度过度，属于异常变化。',NULL,'相乘即乘虚侵袭，是五行之间克制太过的异常变化。如木气偏亢，对土的克制超过正常限度，称为\"木旺乘土\"。或土气本虚，木气相对偏亢而过度克土，称为\"土虚木乘\"。相乘是病理性的，导致被乘者受损。临床常见肝木乘脾土，出现腹痛泄泻等症状。',NULL,'中医知识库','五行学说','五行过度克制的异常变化','2026-04-17 06:30:00.000000',NULL,NULL,'五行相乘；克制太过；木旺乘土',NULL,NULL,NULL,NULL,'中医基础理论','什么是五行相乘？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(287,'五行相侮是指五行中某一行对其所不胜一行的反向克制，即反克。相侮是与正常相克方向相反的异常变化。',NULL,'相侮即恃强凌弱，是五行之间反克的异常变化。如木气过亢，不仅不受金的正常克制，反而反克金，称为\"木火刑金\"。或金气不足，不能正常克木，反被木所侮。相侮也是病理性的，表明克制关系被颠倒。临床常见肝火犯肺，出现咳嗽咯血等症状。',NULL,'中医知识库','五行学说','五行反向克制的异常变化','2026-04-17 06:30:00.000000',NULL,NULL,'五行相侮；反向克制；木火刑金',NULL,NULL,NULL,NULL,'中医基础理论','什么是五行相侮？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(288,'五行制化是指五行之间相生与相克结合的调节机制，通过相生相克的相互制约，维持五行系统的动态平衡。',NULL,'制化是五行系统中的自我调节机制。相生中有相克，相克中有相生，生克结合才能维持平衡。如火受木生，但被水所克，使火不至太过。正如张景岳所说：\"造化之机，不可无生，亦不可无制。无生则发育无由，无制则亢而为害。\"制化保证了五行系统的协调稳定。',NULL,'中医知识库','五行学说','相生相克结合维持系统平衡','2026-04-17 06:30:00.000000',NULL,NULL,'五行制化；生克结合；动态平衡',NULL,NULL,NULL,NULL,'中医基础理论','五行制化的含义是什么？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(289,'五行胜复是指五行系统在遭到过度克制后，通过其所生之子的报复性克制来恢复平衡的调节机制。即\"子复母仇\"。',NULL,'胜复是五行系统的一种自我恢复机制。当一行过度克制另一行（胜），被克者的子行会反过来克制太过者（复）。如木过度克土（胜），土之子金会反过来克木（复），使系统恢复平衡。这种反馈调节机制保证了五行系统不会出现某一行的持续亢盛或衰弱。',NULL,'中医知识库','五行学说','过度克制后的报复性调节恢复平衡','2026-04-17 06:30:00.000000',NULL,NULL,'五行胜复；子复母仇；反馈调节',NULL,NULL,NULL,NULL,'中医基础理论','五行胜复的含义是什么？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(290,'母病及子是指五行中母行异常波及子行的病理传变。如水（母）不足，不能生木（子），导致肝肾精血同亏。',NULL,'母病及子是按相生方向传变的病理过程。母行异常导致子行也出现病变。如肾水不足，不能滋养肝木，出现肝肾阴虚；心火不足，不能温煦脾土，出现心脾两虚。治疗应在补母的基础上兼顾治子，即\"虚则补其母\"。',NULL,'中医知识库','五行学说','母行异常沿相生方向传至子行','2026-04-17 06:30:00.000000',NULL,NULL,'母病及子；相生传变；虚则补其母',NULL,NULL,NULL,NULL,'中医基础理论','什么是母病及子？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(291,'子病及母是指五行中子行异常波及母行的病理传变。如心火亢盛（子），导致肝火上炎（母），出现心肝火旺。',NULL,'子病及母是逆相生方向传变的病理过程。子行异常导致母行也出现病变。如心火亢盛引动肝火，出现心肝火旺；脾土不足导致心气虚衰，出现心脾两虚。治疗应泻其亢盛之脏，兼顾调理母脏。',NULL,'中医知识库','五行学说','子行异常逆相生方向传至母行','2026-04-17 06:30:00.000000',NULL,NULL,'子病及母；逆相生传变',NULL,NULL,NULL,NULL,'中医基础理论','什么是子病及母？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(292,'培土生金法是通过补益脾土来滋补肺金的治法。用于脾肺气虚证，如食欲不振、腹胀便溏、咳嗽气短等。',NULL,'培土生金法是根据五行相生规律确定的治疗方法。土生金，脾为肺之母。通过补益脾气来间接补益肺气。临床用于脾肺气虚证，表现为食欲不振、腹胀便溏、咳嗽气短、面色萎黄、舌淡苔白、脉细弱。常用方如六君子汤、参苓白术散等。',NULL,'中医知识库','五行学说','补脾以补肺的治法','2026-04-17 06:30:00.000000',NULL,NULL,'培土生金；脾肺气虚；虚则补其母',NULL,NULL,NULL,NULL,'中医基础理论','培土生金法的含义及应用是什么？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(293,'滋水涵木法是通过滋补肝肾之阴来治疗肝肾阴虚证的治法。水生木，肾为肝之母，滋肾以养肝。',NULL,'滋水涵木法是根据五行相生规律确定的治疗方法。水生木，肾为肝之母。通过滋补肾阴来滋养肝阴。临床用于肝肾阴虚证，表现为头晕目眩、耳鸣、腰膝酸软、口燥咽干、五心烦热、舌红少苔、脉细数。常用方如六味地黄丸、杞菊地黄丸等。',NULL,'中医知识库','五行学说','滋肾阴以养肝阴的治法','2026-04-17 06:30:00.000000',NULL,NULL,'滋水涵木；肝肾阴虚；滋肾养肝',NULL,NULL,NULL,NULL,'中医基础理论','滋水涵木法的含义及应用是什么？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(294,'泻南补北法是泻心火、补肾水的治法。南方属火属心，北方属水属肾，用于心肾不交证。',NULL,'泻南补北法是根据五行关系确定的治疗方法。南方丙丁火属心，北方壬癸水属肾。泻心火、补肾水，使心肾相交，水火既济。临床用于心肾不交证，表现为心烦失眠、心悸、头晕耳鸣、腰膝酸软、梦遗、舌红、脉细数。常用方如黄连阿胶汤、交泰丸等。',NULL,'中医知识库','五行学说','泻心火补肾水以交通心肾','2026-04-17 06:30:00.000000',NULL,NULL,'泻南补北；心肾不交；水火既济',NULL,NULL,NULL,NULL,'中医基础理论','泻南补北法的含义及应用是什么？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(295,'佐金平木法是清泻肝火、清肺降逆的治法。用于肝火犯肺证，即木火刑金的病证。',NULL,'佐金平木法是根据五行相克关系确定的治疗方法。金克木，当肝木过旺反侮肺金时，应清泻肝火、清肺降逆。临床用于肝火犯肺证，表现为咳嗽阵作、咯血、胸痛、急躁易怒、口苦、舌红苔黄、脉弦数。常用方如黛蛤散合泻白散等。',NULL,'中医知识库','五行学说','清肝泻肺以治肝火犯肺','2026-04-17 06:30:00.000000',NULL,NULL,'佐金平木；肝火犯肺；木火刑金',NULL,NULL,NULL,NULL,'中医基础理论','佐金平木法的含义及应用是什么？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(296,'益火补土法是温补肾阳以补脾阳的治法。用于肾阳虚不能温煦脾土，出现五更泄泻、腹痛喜温等症。',NULL,'益火补土法是根据五行相生规律确定的治疗方法。火生土，心为脾之母。但在临床实际中，益火补土多指温补肾阳以温煦脾土，因为命门之火（肾阳）能温煦脾阳。临床用于脾肾阳虚证，表现为五更泄泻、腹痛喜温喜按、腰膝酸冷、舌淡胖、脉沉迟。常用方如四神丸、附子理中丸等。',NULL,'中医知识库','五行学说','温补肾阳以温煦脾土的治法','2026-04-17 06:30:00.000000',NULL,NULL,'益火补土；脾肾阳虚；温肾暖脾',NULL,NULL,NULL,NULL,'中医基础理论','益火补土法的含义及应用是什么？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(297,'五行在诊断中通过望、闻、问、切四诊所获得的信息，用五行归类进行综合分析判断。如面青属肝，面赤属心，面黄属脾，面白属肺，面黑属肾。',NULL,'五行在诊断中的应用广泛。望诊方面：五色配五脏，青为肝、赤为心、黄为脾、白为肺、黑为肾。五味配五脏，酸入肝、苦入心、甘入脾、辛入肺、咸入肾。脉诊方面：弦脉属肝、洪脉属心、缓脉属脾、浮脉属肺、沉脉属肾。通过五行关系可推断疾病的传变趋势和预后。',NULL,'中医知识库','五行学说','运用五行归类分析病情辅助诊断','2026-04-17 06:30:00.000000',NULL,NULL,'五行诊断；五色主病；五脏归属',NULL,NULL,NULL,NULL,'中医基础理论','五行在诊断中有哪些应用？','中医基础理论',NULL,'理论','五行学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(298,'心主血脉包括心主血和心主脉两个方面。心气推动血液在脉中运行，流注全身，发挥营养和滋润作用。心气充沛，血液才能在脉内正常循环。',NULL,'心主血脉，指心气推动和调控血液在脉中运行，流注全身，发挥营养和滋润作用。心主血包括心行血和心生血。心行血依靠心气的推动；心生血指\"奉心化赤\"，水谷精微经心火化赤为血。心主脉指心气推动脉气，保持脉道通畅。心气充沛、血液充盈、脉道通利是心主血脉功能正常的基本条件。',NULL,'中医知识库','藏象学说','心气推动血液在脉中运行营养全身','2026-04-17 06:30:00.000000',NULL,NULL,'心；主血脉；心气；血液循环',NULL,NULL,NULL,NULL,'中医基础理论','心主血脉的功能体现在哪些方面？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(299,'心藏神又称心主神明，指心主宰人体的精神、意识、思维活动。心为五脏六腑之大主，精神之所舍。',NULL,'心藏神指心具有主宰人体精神、意识、思维等心理活动的功能。中医认为，人的精神活动虽然与五脏都有关，但主要由心来主宰。心主神明的功能正常，则精神振奋、神志清楚、思维敏捷。若心不藏神，则出现失眠多梦、健忘、神志不清、甚至昏迷。心主血脉和心藏神密不可分，血是神志活动的物质基础。',NULL,'中医知识库','藏象学说','心主宰人体精神意识思维活动','2026-04-17 06:30:00.000000',NULL,NULL,'心；藏神；主神明；精神意识',NULL,NULL,NULL,NULL,'中医基础理论','心藏神的功能如何理解？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(300,'肺主气包括主呼吸之气和主一身之气。肺司呼吸，吸入清气，呼出浊气，完成体内外气体交换。肺还参与宗气的生成，调节全身气机。',NULL,'肺主气司呼吸是肺的首要功能。肺主呼吸之气，指肺是体内外气体交换的场所，吸入清气，呼出浊气。肺主一身之气，指肺参与宗气的生成，调节全身气机的升降出入。肺吸入的清气与水谷精微结合形成宗气，积于胸中，推动呼吸和心血运行。肺朝百脉，主治节，辅助心脏调节气血运行。',NULL,'中医知识库','藏象学说','肺主呼吸之气与一身之气','2026-04-17 06:30:00.000000',NULL,NULL,'肺；主气；司呼吸；宗气',NULL,NULL,NULL,NULL,'中医基础理论','肺主气司呼吸的功能包括哪些？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(301,'肺主宣发指肺气向上向外升宣布散，肃降指肺气向下向内清肃下降。宣发肃降相互制约、相互配合，维持肺的正常功能。',NULL,'肺主宣发包括三个方面：排出体内浊气；将脾转输的津液和水谷精微布散全身；宣发卫气于体表。肺主肃降包括三个方面：吸入自然界清气；将吸入的清气和脾转输的津液及水谷精微向下布散；肃清肺和呼吸道的异物。宣发与肃降相反相成，是肺气运动的基本形式。',NULL,'中医知识库','藏象学说','肺气宣发肃降维持正常呼吸功能','2026-04-17 06:30:00.000000',NULL,NULL,'肺；宣发；肃降；气机升降',NULL,NULL,NULL,NULL,'中医基础理论','肺主宣发肃降的含义是什么？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(302,'肺主通调水道是指肺通过宣发肃降运动，调节体内水液的输布和排泄。肺为水之上源，宣发将水液布散体表，肃降将水液下输膀胱。',NULL,'肺主通调水道，指肺通过宣发肃降对体内水液输布和排泄起着疏通和调节作用。宣发使水液向上向外布散，化为汗液排出；肃降使水液向下输布于肾和膀胱，化为尿液排出。此外，肺还能将水谷精微中的水液通过三焦水道布散全身。肺为\"水之上源\"，若肺失宣降，可致水液停聚，出现水肿、痰饮等。',NULL,'中医知识库','藏象学说','肺通过宣发肃降调节水液输布排泄','2026-04-17 06:30:00.000000',NULL,NULL,'肺；通调水道；水之上源；水液代谢',NULL,NULL,NULL,NULL,'中医基础理论','肺主通调水道的含义是什么？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(303,'脾主运化包括运化水谷和运化水液两方面。运化水谷指消化吸收水谷精微并转输全身；运化水液指对水液的吸收、转输和布散。',NULL,'脾主运化是脾的首要功能。运化水谷，指脾对饮食物的消化吸收和转输，将水谷精微上输于肺，由肺布散全身，化生气血。运化水液，指脾在运化水谷精微的同时，对水液的吸收、转输和布散作用。脾为后天之本，气血生化之源。脾运化功能正常，则消化吸收良好，气血充盈，营养充足。',NULL,'中医知识库','藏象学说','脾主运化水谷精微和水液','2026-04-17 06:30:00.000000',NULL,NULL,'脾；主运化；后天之本；气血生化之源',NULL,NULL,NULL,NULL,'中医基础理论','脾主运化的功能包括哪些方面？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(304,'脾主统血是指脾气具有统摄血液在经脉之中运行，防止其逸出脉外的功能。脾为气血生化之源，气能摄血，脾气健旺则血不外溢。',NULL,'脾主统血，指脾气统摄血液在经脉之中流行，不致逸出脉外。脾统血的机理主要依赖脾气的固摄作用。脾气健旺，则气血充盈，气的固摄作用正常，血液在脉内运行不致外溢。若脾气虚弱，统摄无权，则血不循经，出现各种出血证，如便血、尿血、崩漏、肌衄等，称为\"脾不统血\"。',NULL,'中医知识库','藏象学说','脾气统摄血液防止逸出脉外','2026-04-17 06:30:00.000000',NULL,NULL,'脾；主统血；气能摄血；脾不统血',NULL,NULL,NULL,NULL,'中医基础理论','脾主统血的含义是什么？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(305,'脾气主升包括升清和升举两方面。升清指脾将水谷精微上输心肺头目；升举指脾气维持内脏的正常位置，不致下垂。',NULL,'脾气主升是脾气运动的特点。升清，指脾气的升运动将水谷精微上输于心、肺、头目，化生气血，营养全身。升举，指脾气上升能维持内脏的正常位置。若脾气不升反降，则为脾气下陷，出现头晕、乏力、腹胀、腹泻等升清不足症状，或出现胃下垂、肾下垂、子宫脱垂、脱肛等升举无力症状。',NULL,'中医知识库','藏象学说','脾气上升以升清和升举内脏','2026-04-17 06:30:00.000000',NULL,NULL,'脾；脾气主升；升清；升举内脏',NULL,NULL,NULL,NULL,'中医基础理论','脾气主升的功能体现在哪些方面？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(306,'肝主疏泄是指肝具有保持全身气机疏通畅达、通而不滞、散而不郁的功能。包括调畅气机、促进消化、调畅情志、调节生殖等。',NULL,'肝主疏泄是肝的核心功能。调畅气机：肝的疏泄功能使气机疏通畅达。促进消化：肝疏泄胆汁，促进消化吸收。调畅情志：肝疏泄正常则心情舒畅。调节生殖：肝疏泄调节女子月经和男子排精。此外，肝疏泄还能促进津血运行和水液代谢。肝喜条达而恶抑郁，疏泄太过则急躁易怒，疏泄不及则胸胁胀闷。',NULL,'中医知识库','藏象学说','肝保持气机疏通畅达，调畅情志消化','2026-04-17 06:30:00.000000',NULL,NULL,'肝；主疏泄；调畅气机；情志',NULL,NULL,NULL,NULL,'中医基础理论','肝主疏泄的功能包括哪些方面？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(307,'肝藏血是指肝具有贮藏血液、调节血量和防止出血的功能。肝为\"血海\"，能调节各部位血流量的分配。',NULL,'肝藏血包括三方面：贮藏血液，肝内贮存一定量的血液；调节血量，根据生理需要调节外周血流量，休息时血归于肝，活动时血运于外；防止出血，肝气能收摄血液。肝藏血还能滋养肝脏本身，维持肝的疏泄功能。肝藏血与心主血、脾统血共同维持血液的正常运行。',NULL,'中医知识库','藏象学说','肝贮藏血液、调节血量和防止出血','2026-04-17 06:30:00.000000',NULL,NULL,'肝；藏血；血海；调节血量',NULL,NULL,NULL,NULL,'中医基础理论','肝藏血的功能如何理解？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(308,'肝主筋是指肝的气血可以养筋，维持筋的正常功能。肝血充盈，筋得滋养，则运动灵活有力，指甲坚韧光泽。',NULL,'肝主筋，指肝的精血具有滋养筋膜的作用。筋附于骨而聚于关节，是连接关节、肌肉，主管运动的组织。肝血充盈则筋得其养，运动灵活有力。肝血不足则筋失濡养，出现肢体麻木、筋脉拘挛、关节屈伸不利等。\"肝者，罢极之本\"，说明肝与运动耐力有关。爪为筋之余，肝血充盈则指甲红润坚韧。',NULL,'中医知识库','藏象学说','肝血滋养筋膜维持运动功能','2026-04-17 06:30:00.000000',NULL,NULL,'肝；主筋；筋膜；爪为筋之余',NULL,NULL,NULL,NULL,'中医基础理论','肝主筋的含义是什么？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(309,'肾藏精包括藏先天之精和后天之精。先天之精禀受于父母，是构成胚胎的原始物质；后天之精来源于水谷精微，由脾胃化生。',NULL,'肾藏精是肾的首要功能。肾精包括先天之精和后天之精，二者相互依存、相互促进。先天之精禀受于父母，是生命的本原；后天之精来源于脾胃运化的水谷精微。肾精化生肾气，肾气分阴阳，即肾阴和肾阳。肾精充足则生长发育正常，生殖功能旺盛，骨骼强健，脑髓充实。肾为先天之本。',NULL,'中医知识库','藏象学说','肾贮藏先天之精和后天之精','2026-04-17 06:30:00.000000',NULL,NULL,'肾；藏精；先天之本；肾精',NULL,NULL,NULL,NULL,'中医基础理论','肾藏精的功能包括哪些方面？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(310,'肾主水是指肾具有主持和调节人体水液代谢的功能。肾的气化作用贯穿于水液代谢的始终，调节尿液的生成和排泄。',NULL,'肾主水，指肾具有主持和调节人体水液代谢的功能。肾主水的功能是通过肾的气化作用来实现的。肾阳的温煦蒸腾，使清者上升，浊者下降。肾气的固摄作用控制尿液的排泄。若肾的气化失常，则水液停聚，出现水肿、小便不利，或小便清长、夜尿增多等。',NULL,'中医知识库','藏象学说','肾主持调节水液代谢','2026-04-17 06:30:00.000000',NULL,NULL,'肾；主水；气化；水液代谢',NULL,NULL,NULL,NULL,'中医基础理论','肾主水的功能如何理解？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(311,'肾主纳气是指肾有摄纳肺所吸入的清气，防止呼吸表浅的功能。肺为气之主，肾为气之根，肺的呼吸需要肾的纳气功能协助。',NULL,'肾主纳气，指肾有摄纳肺吸入之清气、保持呼吸深度的功能。肾的纳气功能实际上是肾气的封藏作用在呼吸运动中的体现。正常情况下，肺吸入清气必须下达于肾，由肾来摄纳，呼吸才能均匀深沉。若肾不纳气，则出现呼多吸少、动则气喘、呼吸困难等，称为\"肾不纳气\"。',NULL,'中医知识库','藏象学说','肾摄纳肺吸入清气维持呼吸深沉','2026-04-17 06:30:00.000000',NULL,NULL,'肾；主纳气；肺为气之主肾为气之根',NULL,NULL,NULL,NULL,'中医基础理论','肾主纳气的功能如何理解？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(312,'命门之火即肾阳，又称真火、真阳，是人体阳气的根本，对各脏腑组织起着温煦和推动作用。命门之火不足则全身阳虚。',NULL,'命门之火，又称元阳、真阳、肾阳，是人体生命活动的原动力。命门之火温煦各脏腑，推动其功能活动。命门之火充足，则脾土得温而运化正常，肺金得温而宣降正常，心火得助而神明正常。命门之火不足，则畏寒肢冷、腰膝酸冷、阳痿精寒、五更泄泻，全身功能衰退。',NULL,'中医知识库','藏象学说','命门之火为人体阳气根本，温煦各脏腑','2026-04-17 06:30:00.000000',NULL,NULL,'命门之火；肾阳；真阳；温煦',NULL,NULL,NULL,NULL,'中医基础理论','命门之火的含义是什么？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(313,'胃主受纳腐熟指胃具有接受和容纳饮食物，并将其初步消化形成食糜的功能。胃为水谷之海，以降为和。',NULL,'胃主受纳，指胃具有接受和容纳饮食物的功能。饮食入口，经食管容纳于胃。胃主腐熟，指胃将饮食物初步消化变成食糜，然后下传小肠进一步消化。胃为\"太仓\"、\"水谷之海\"，人以胃气为本。胃气以降为和，胃气降则食糜下行入肠。胃气上逆则恶心呕吐。',NULL,'中医知识库','藏象学说','胃接受容纳饮食物并初步消化','2026-04-17 06:30:00.000000',NULL,NULL,'胃；受纳腐熟；水谷之海；胃气',NULL,NULL,NULL,NULL,'中医基础理论','胃主受纳腐熟的功能是什么？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(314,'小肠主受盛化物指小肠接受胃下传的食糜，进一步消化吸收。小肠还主泌别清浊，将水谷精微吸收，将糟粕下传大肠。',NULL,'小肠主受盛化物包括两个方面：受盛，指小肠接受胃下传的食糜；化物，指小肠对食糜进一步消化和吸收。小肠主泌别清浊，将食糜分为清浊两部分：清者为水谷精微，由小肠吸收；浊者为食物残渣和多余水分，分别下传大肠和膀胱。小肠泌别清浊功能失常，则便溏、小便异常。',NULL,'中医知识库','藏象学说','小肠接受食糜，泌别清浊，吸收精微','2026-04-17 06:30:00.000000',NULL,NULL,'小肠；受盛化物；泌别清浊',NULL,NULL,NULL,NULL,'中医基础理论','小肠主受盛化物的功能是什么？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(315,'大肠主传导指大肠接受小肠下传的食物残渣，吸收其中多余水分，形成粪便并排出体外的功能。',NULL,'大肠主传导糟粕，指大肠接受小肠下传的食物残渣，再吸收其中多余的水分，形成粪便，经肛门排出体外。大肠的传导功能是胃降浊功能的延续，与肺的肃降功能有关。大肠传导失常可出现便秘或腹泻。大肠还与津液代谢有关，大肠吸收水分的功能称为\"大肠主津\"。',NULL,'中医知识库','藏象学说','大肠传导糟粕并吸收水分','2026-04-17 06:30:00.000000',NULL,NULL,'大肠；传导；糟粕；大肠主津',NULL,NULL,NULL,NULL,'中医基础理论','大肠主传导的功能是什么？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(316,'膀胱主贮尿排尿是指膀胱具有贮存尿液和排泄尿液的功能。膀胱为州都之官，在肾气化作用下完成贮尿和排尿。',NULL,'膀胱为州都之官，津液之府。膀胱的主要功能是贮存和排泄尿液。水液经肾的气化作用后，清者上升复归于肺，浊者下注膀胱形成尿液。膀胱的贮尿排尿功能依赖肾的气化和固摄作用。肾气充足，则膀胱开合有度。若肾气不固，则小便频数、遗尿；若气化不利，则小便不利、尿潴留。',NULL,'中医知识库','藏象学说','膀胱贮存和排泄尿液','2026-04-17 06:30:00.000000',NULL,NULL,'膀胱；贮尿排尿；气化；州都之官',NULL,NULL,NULL,NULL,'中医基础理论','膀胱主贮尿排尿的功能是什么？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(317,'三焦具有通行元气、运行水液的功能。上焦如雾，主宣发；中焦如沤，主运化；下焦如渎，主排泄。三焦是水谷运行和水液代谢的通道。',NULL,'三焦的主要功能是通行元气和运行水液。通行元气：三焦是元气运行的通道，元气根于肾，通过三焦输布全身。运行水液：三焦是水液升降出入的通道。上焦如雾，主宣发卫气和津液；中焦如沤，主腐熟水谷，化生精微；下焦如渎，主排泄糟粕和尿液。三焦功能涵盖了消化、吸收、排泄全过程。',NULL,'中医知识库','藏象学说','三焦为元气和水液运行的通道','2026-04-17 06:30:00.000000',NULL,NULL,'三焦；通行元气；运行水液；上中下焦',NULL,NULL,NULL,NULL,'中医基础理论','三焦的功能有哪些？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(318,'胆为六腑之一，又属奇恒之府。胆贮藏和排泄胆汁，帮助消化。胆汁由肝之余气化生，贮藏于胆，排泄入肠以助消化。',NULL,'胆为奇恒之府，既属六腑又不同于一般六腑。胆的主要功能是贮藏和排泄胆汁。胆汁由肝之余气化生，味苦色黄绿。胆汁的排泄依赖肝的疏泄功能。肝疏泄正常，则胆汁排泄通畅，有助于饮食物的消化。若肝胆疏泄不利，则胆汁外溢，出现黄疸、口苦、胁痛等症。胆主决断，与勇怯有关。',NULL,'中医知识库','藏象学说','胆贮藏排泄胆汁以助消化','2026-04-17 06:30:00.000000',NULL,NULL,'胆；贮藏排泄胆汁；奇恒之府；主决断',NULL,NULL,NULL,NULL,'中医基础理论','胆贮藏排泄胆汁的功能是什么？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(319,'心包络简称心包，是心脏外围的组织，具有保护心脏的功能。外邪侵袭心脏时，心包先受其邪，代心受邪。',NULL,'心包络，又称膻中，是心脏外面的包膜。心包的功能是保护心脏，代心受邪。当外邪侵袭心脏时，首先侵犯心包。如温热病中出现的高热、神昏、谵语等神志症状，称为\"热入心包\"。心包在经络上属手厥阴经，与手少阳三焦经相表里。心包穴如内关、大陵等常用于治疗心胸疾病。',NULL,'中医知识库','藏象学说','心包保护心脏，代心受邪','2026-04-17 06:30:00.000000',NULL,NULL,'心包络；代心受邪；热入心包',NULL,NULL,NULL,NULL,'中医基础理论','心包络的功能是什么？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(320,'心与肺的关系主要体现在气血关系上。心主血，肺主气，心与肺相互配合，维持气血的正常运行。宗气贯心脉、司呼吸，是心肺关系的纽带。',NULL,'心主血，肺主气，心与肺实际上是气血关系。肺主宗气，宗气贯心脉以行气血，心脏跳动和血液运行需要宗气的推动。心主血脉，血液运载营气以养肺。气为血之帅，血为气之母。肺气虚可致心血运行不畅；心血虚可致肺气不足。临床常见心肺气虚、心肺阴虚等证。',NULL,'中医知识库','藏象学说','心肺以气血相互配合维持功能','2026-04-17 06:30:00.000000',NULL,NULL,'心与肺；气血关系；宗气',NULL,NULL,NULL,NULL,'中医基础理论','心与肺的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(321,'心与脾的关系主要体现在血液的生成和运行上。心主血，脾生血又统血。脾运化水谷精微化生血液，依赖心阳的温煦。',NULL,'心与脾的关系主要表现在血液的生成和运行方面。脾运化水谷精微，化生血液，上输于心。心主血脉，心阳温煦脾土，促进脾的运化。脾统血，使血液在脉中运行不致外溢。若脾虚不能化生血液，可致心血不足，出现心脾两虚证，表现为心悸、失眠、纳差、面色萎黄等。',NULL,'中医知识库','藏象学说','心脾协作完成血液生成和运行','2026-04-17 06:30:00.000000',NULL,NULL,'心与脾；血液生成运行；心脾两虚',NULL,NULL,NULL,NULL,'中医基础理论','心与脾的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(322,'心与肝的关系主要体现在血液运行和精神情志方面。心主血，肝藏血；心主神明，肝主疏泄。心肝配合，共同调节血液和精神活动。',NULL,'心主血，肝藏血，心肝共同维持血液的正常运行和分配。心血充盈则肝有所藏，肝藏血充足则心血供给有源。心主神明，肝主疏泄调畅情志，心肝协作维持精神情志的正常。心血虚与肝血虚常并见，出现心肝血虚证。心火亢盛常引动肝火，出现心肝火旺证。',NULL,'中医知识库','藏象学说','心肝协作调节血液和精神活动','2026-04-17 06:30:00.000000',NULL,NULL,'心与肝；血液运行；精神情志',NULL,NULL,NULL,NULL,'中医基础理论','心与肝的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(323,'心与肾的关系主要体现在心肾相交，即心火下降温煦肾水，肾水上济滋润心火，水火既济，阴阳平衡。',NULL,'心与肾的关系称为\"心肾相交\"或\"水火既济\"。心在五行属火，位居上；肾在五行属水，位居下。正常情况下，心火下降于肾，温煦肾水；肾水上济于心，滋润心火。心肾相交维持阴阳平衡。若心肾不交，则心烦失眠、腰膝酸软、梦遗盗汗。心与肾还共同主宰精血和神志。',NULL,'中医知识库','藏象学说','心肾水火既济维持阴阳平衡','2026-04-17 06:30:00.000000',NULL,NULL,'心与肾；心肾相交；水火既济',NULL,NULL,NULL,NULL,'中医基础理论','心与肾的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(324,'肺与脾的关系主要体现在气的生成和水液代谢方面。脾为生气之源，肺为主气之枢。脾运化水液，肺通调水道，二者协同维持水液代谢。',NULL,'肺与脾关系密切。气的生成方面：脾运化水谷精微上输于肺，与肺吸入的清气结合形成宗气。水液代谢方面：脾运化水液，上输于肺；肺宣发肃降，通调水道。脾为肺之母，脾虚可致肺气不足。肺虚也可影响脾的运化。临床常见脾肺气虚证，表现为咳嗽气短、纳差便溏等。',NULL,'中医知识库','藏象学说','肺脾协作完成气的生成和水液代谢','2026-04-17 06:30:00.000000',NULL,NULL,'肺与脾；气的生成；水液代谢',NULL,NULL,NULL,NULL,'中医基础理论','肺与脾的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(325,'肺与肝的关系主要体现在气机升降方面。肺气肃降，肝气升发，一降一升，相互协调，维持全身气机的畅达。',NULL,'肺在膈上，其气肃降；肝在膈下，其气升发。肝升肺降，相互协调，维持气机的升降平衡。若肝气郁结化火，上逆犯肺，称为肝火犯肺，出现咳嗽咯血。若肺失肃降，也可影响肝的升发，出现胁肋胀满。临床治疗时需兼顾肝肺，调理气机升降。',NULL,'中医知识库','藏象学说','肺肝升降协调维持全身气机畅达','2026-04-17 06:30:00.000000',NULL,NULL,'肺与肝；气机升降；肝火犯肺',NULL,NULL,NULL,NULL,'中医基础理论','肺与肝的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(326,'肺与肾的关系主要体现在水液代谢和呼吸方面。肺为水之上源，肾为主水之脏。肺主呼气，肾主纳气，共同完成呼吸功能。',NULL,'肺与肾的关系主要表现在水液代谢和呼吸功能上。水液代谢方面：肺通调水道，为水之上源；肾主水液，为主水之脏。肺肾协同，维持水液代谢平衡。呼吸方面：肺主呼气，肾主纳气，肺肾配合维持呼吸深沉平稳。金水相生，肺阴不足可损及肾阴，肾阴不足也可上损肺阴，出现肺肾阴虚。',NULL,'中医知识库','藏象学说','肺肾协作完成水液代谢和呼吸功能','2026-04-17 06:30:00.000000',NULL,NULL,'肺与肾；水液代谢；呼吸；金水相生',NULL,NULL,NULL,NULL,'中医基础理论','肺与肾的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(327,'肝与脾的关系主要体现在消化功能和血液运行方面。肝主疏泄促进脾的运化；脾运化水谷精微化生气血，滋养肝脏。',NULL,'肝与脾关系密切。消化方面：肝主疏泄，调畅脾胃气机，促进脾的运化。肝气郁结则脾失健运，出现腹痛泄泻，称为肝脾不和。血液方面：肝藏血，脾统血又生血，二者共同维持血液的正常。脾虚化源不足，肝血亦虚；肝血不足，脾失濡养。临床常见肝脾不调、肝郁脾虚证。',NULL,'中医知识库','藏象学说','肝疏泄促进脾运化，脾生血养肝','2026-04-17 06:30:00.000000',NULL,NULL,'肝与脾；疏泄运化；肝脾不和',NULL,NULL,NULL,NULL,'中医基础理论','肝与脾的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(328,'肝与肾的关系极为密切，有\"肝肾同源\"之说。肝藏血，肾藏精，精血同源。肝阴和肾阴互相滋养，肝用依赖肾精的充养。',NULL,'肝与肾的关系主要体现在精血同源和阴液互养上。肝藏血，肾藏精，精血相互化生，故称\"精血同源\"或\"肝肾同源\"。肾精充盈则肝血不虚，肝血充盈则精有化源。肝肾阴阳也相互资生，肾阴为一身阴液之根本，滋养肝阴。临床常见肝肾阴虚证，表现为头晕目眩、腰膝酸软、五心烦热等。',NULL,'中医知识库','藏象学说','肝肾精血同源，阴液互养','2026-04-17 06:30:00.000000',NULL,NULL,'肝与肾；精血同源；肝肾同源',NULL,NULL,NULL,NULL,'中医基础理论','肝与肾的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(329,'脾与肾的关系是后天与先天的关系。脾为后天之本，肾为先天之本。先天温养后天，后天补充先天，二者相互资生。',NULL,'脾为后天之本，气血生化之源；肾为先天之本，生命之根。脾运化水谷精微需要肾阳的温煦推动，即先天温养后天。肾精的充盈需要脾运化水谷精微的不断补充，即后天补充先天。若肾阳不足不能温煦脾土，则脾肾阳虚，出现五更泄泻、畏寒肢冷。脾虚日久也可及肾，导致脾肾两虚。',NULL,'中医知识库','藏象学说','脾肾先后天相互资生','2026-04-17 06:30:00.000000',NULL,NULL,'脾与肾；先天后天；脾肾阳虚',NULL,NULL,NULL,NULL,'中医基础理论','脾与肾的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(330,'六腑以通为用，以降为和。胆、胃、小肠、大肠、膀胱、三焦在饮食物的消化、吸收和排泄过程中相互配合，分工合作。',NULL,'六腑之间的主要关系体现在饮食物的消化、吸收和排泄过程中的分工协作。饮食入胃，经胃腐熟后下传小肠；小肠泌别清浊，清者吸收，浊者下传大肠；大肠吸收水分形成粪便排出；胆排泄胆汁助消化；膀胱贮尿排尿；三焦为水谷和水液运行的通道。六腑以通为用，以降为和，任何一腑不通都会影响整体功能。',NULL,'中医知识库','藏象学说','六腑分工协作完成消化吸收排泄','2026-04-17 06:30:00.000000',NULL,NULL,'六腑；以通为用；消化排泄',NULL,NULL,NULL,NULL,'中医基础理论','六腑之间的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(331,'脏属阴为里，腑属阳为表。心与小肠、肺与大肠、脾与胃、肝与胆、肾与膀胱互为表里，通过经脉相互络属，功能上相互配合。',NULL,'脏与腑的表里关系通过经脉的相互络属来体现。心与小肠相表里，手少阴经属心络小肠，手太阳经属小肠络心。肺与大肠相表里，脾与胃相表里，肝与胆相表里，肾与膀胱相表里。此外，心包与三焦相表里。表里脏腑在生理上相互配合，病理上相互影响。如肺热可传大肠，出现便秘；大肠不通也可影响肺的肃降。',NULL,'中医知识库','藏象学说','脏与腑通过经脉络属互为表里','2026-04-17 06:30:00.000000',NULL,NULL,'脏与腑；表里关系；经脉络属',NULL,NULL,NULL,NULL,'中医基础理论','脏与腑的表里关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(332,'气的主要作用包括推动作用、温煦作用、防御作用、固摄作用、气化作用和营养作用六个方面。',NULL,'气的作用：推动作用，推动人体的生长发育、脏腑功能和血液津液运行；温煦作用，维持正常体温和脏腑功能；防御作用，护卫体表，抵御外邪；固摄作用，固摄血液、汗液、尿液、精液等不外泄；气化作用，促进精气血津液之间的相互化生；营养作用，营气化生血液营养全身。',NULL,'中医知识库','藏象学说','气具有推动温煦防御固摄气化营养六大作用','2026-04-17 06:30:00.000000',NULL,NULL,'气；推动；温煦；防御；固摄；气化',NULL,NULL,NULL,NULL,'中医基础理论','气的主要作用有哪些？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(333,'血主要由营气和津液组成，来源于水谷精微。脾胃运化水谷精微，上输于心肺，经心肺气化作用变化而成血液。',NULL,'血的生成过程：脾胃运化水谷精微化为营气和津液，上输于肺；肺吸入清气与营气结合形成宗气；心火化赤，水谷精微奉心化赤而为血。此外，肾精也能化血，精血同源。肝藏血，也能参与血的调节和化生。血的生成与脾、胃、心、肺、肾等脏腑都密切相关，其中脾胃为气血生化之源。',NULL,'中医知识库','藏象学说','脾胃运化水谷精微经心肺化赤为血','2026-04-17 06:30:00.000000',NULL,NULL,'血；生成；水谷精微；奉心化赤',NULL,NULL,NULL,NULL,'中医基础理论','血的生成过程是怎样的？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(334,'津液的代谢包括生成、输布和排泄三个环节。脾胃运化生成津液，经脾的转输、肺的宣降、肾的气化、三焦的通调完成输布和排泄。',NULL,'津液代谢涉及多个脏腑：脾胃运化水液，吸收津液；脾将津液上输于肺；肺通过宣发将津液布散体表和全身，通过肃降将津液下输于肾；肾的气化将清者上升复归于肺，浊者下注膀胱形成尿液；三焦为水液运行的通道。此外，肝的疏泄有助于水液运行，心主血脉也与津液输布有关。',NULL,'中医知识库','藏象学说','津液经脾肺肾三焦协调完成代谢','2026-04-17 06:30:00.000000',NULL,NULL,'津液；代谢；脾肺肾；三焦',NULL,NULL,NULL,NULL,'中医基础理论','津液的代谢过程是怎样的？','中医基础理论',NULL,'理论','藏象学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(335,'气与血的关系极为密切。气为血之帅，血为气之母。气能生血、行血、摄血，血能载气、养气。',NULL,'气与血的关系：气为血之帅包括三个方面——气能生血，气化作用促进血的生成；气能行血，气推动血液运行；气能摄血，气固摄血液在脉中运行不外溢。血为气之母包括两个方面——血能载气，气存于血中，赖血的运载而运行全身；血能养气，血为气的功能活动提供营养。气血相互依存，不可分离。',NULL,'中医知识库','藏象学说','气帅血母，气血相互依存','2026-04-17 06:30:00.000000',NULL,NULL,'气血关系；气为血之帅；血为气之母',NULL,NULL,NULL,NULL,'中医基础理论','气与血的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(336,'气与津液的关系类似于气与血的关系。气能生津、行津、摄津，津能载气。气旺则津充，气虚则津亏。',NULL,'气与津液的关系：气能生津，气的气化作用促进津液的生成；气能行津，气的推动作用使津液正常输布和排泄；气能摄津，气的固摄作用防止津液无故流失。津能载气，津液中承载着气，津液的正常运行维持气的正常布散。若气虚不能生津，则口渴舌干；气虚不摄津，则多汗、多尿。',NULL,'中医知识库','藏象学说','气与津液相互资生相互依存','2026-04-17 06:30:00.000000',NULL,NULL,'气与津液；生津行津摄津',NULL,NULL,NULL,NULL,'中医基础理论','气与津液的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(337,'精、气、血、津液是构成人体和维持生命活动的基本物质，神是生命活动的总体表现。精气充足则神旺，精气亏虚则神疲。',NULL,'精、气、血、津液是人体的基本物质，神是这些物质功能的综合体现。精化气，气化精；气生血，血养气；津液与气血相互化生。神依赖于精气血津液的滋养，精气血津液充足则神明正常。精为生命之本原，气为生命之动力，血为营养之载体，津液为滋润之源泉，神为生命之主宰，五者相互依存。',NULL,'中医知识库','藏象学说','精气血津液为物质基础，神为功能体现','2026-04-17 06:30:00.000000',NULL,NULL,'精气血津液神；相互关系；生命活动',NULL,NULL,NULL,NULL,'中医基础理论','精气血津液神的关系是怎样的？','中医基础理论',NULL,'理论','藏象学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(338,'风为春季主气，为百病之长。风邪的性质和致病特点：风为阳邪，其性开泄，易袭阳位；善行而数变；风为百病之长，常兼他邪合而伤人。',NULL,'风邪的特性：风为阳邪，轻扬开泄，易袭阳位（上部、肌表）；善行数变，致病部位游移不定，发病急骤变化快；风为百病之长，是外邪致病的先导，常为外邪致病的先导，兼夹寒、热、湿等邪侵袭人体。风邪致病常见症状：头痛、汗出、恶风、关节游走疼痛、皮肤瘙痒等。',NULL,'中医知识库','病因学说','风为百病之长，善行数变','2026-04-17 06:30:00.000000',NULL,NULL,'风邪；百病之长；善行数变',NULL,NULL,NULL,NULL,'中医基础理论','六淫中风的致病特性是什么？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(339,'寒为冬季主气。寒邪的性质和致病特点：寒为阴邪，易伤阳气；寒性凝滞，主痛；寒性收引。寒邪致病常见恶寒、疼痛、拘挛等。',NULL,'寒邪的特性：寒为阴邪，易伤阳气，阳气受损则温煦功能下降；寒性凝滞，使气血运行不畅，不通则痛，故寒邪致病多见疼痛；寒性收引，使腠理毛孔收缩，筋脉拘急挛缩。寒邪分伤寒和中寒，伤寒指寒邪侵犯肌表，中寒指寒邪直中脏腑。常见症状：恶寒、无汗、身痛、腹痛喜温、脉紧。',NULL,'中医知识库','病因学说','寒为阴邪，凝滞主痛收引','2026-04-17 06:30:00.000000',NULL,NULL,'寒邪；凝滞；主痛；收引',NULL,NULL,NULL,NULL,'中医基础理论','六淫中寒的致病特性是什么？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(340,'暑为夏季主气，纯属外感，无内暑之说。暑邪的性质和致病特点：暑为阳邪，其性炎热；暑性升散，耗气伤津；暑多夹湿。',NULL,'暑邪的特性：暑为阳邪，其性炎热，致病出现高热、面赤等暑热症状；暑性升散，扰神耗津伤气，出现心烦、口渴、多汗、气短乏力；暑多夹湿，因夏季多雨潮湿，故暑病常兼湿邪。暑邪只有外感，无内生。常见暑病有中暑、暑温、暑湿等。注意暑邪伤人只有外感而无内生，不同于其他五邪。',NULL,'中医知识库','病因学说','暑为阳邪炎热升散耗气伤津','2026-04-17 06:30:00.000000',NULL,NULL,'暑邪；炎热；耗气伤津；暑多夹湿',NULL,NULL,NULL,NULL,'中医基础理论','六淫中暑的致病特性是什么？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(341,'湿为长夏主气。湿邪的性质和致病特点：湿为阴邪，易阻遏气机，损伤阳气；湿性重浊；湿性黏滞；湿性趋下，易袭阴位。',NULL,'湿邪的特性：湿为阴邪，易阻遏气机，损伤脾阳；湿性重浊，致病见头重如裹、身重困倦、分泌物浑浊；湿性黏滞，致病病程缠绵难愈，症状黏滞不爽；湿性趋下，易袭人体下部。湿邪外感与内生均常见，与脾的关系最为密切。常见症状：头身困重、关节酸痛重着、纳呆腹胀、大便黏滞、舌苔厚腻。',NULL,'中医知识库','病因学说','湿性重浊黏滞趋下，易伤脾阳','2026-04-17 06:30:00.000000',NULL,NULL,'湿邪；重浊；黏滞；趋下',NULL,NULL,NULL,NULL,'中医基础理论','六淫中湿的致病特性是什么？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(342,'燥为秋季主气。燥邪的性质和致病特点：燥性干涩，易伤津液；燥易伤肺。燥邪致病以口鼻干燥、皮肤皲裂、干咳少痰为主要特征。',NULL,'燥邪的特性：燥性干涩，易伤人体津液，出现口鼻干燥、咽干口渴、皮肤干燥皲裂、小便短少、大便干结；燥易伤肺，因肺为娇脏，喜润恶燥，燥邪经口鼻而入，最易伤肺。燥邪分温燥和凉燥：初秋尚热，多为温燥；深秋转凉，多为凉燥。常见症状：干咳少痰或无痰、鼻干咽燥、皮肤干涩。',NULL,'中医知识库','病因学说','燥性干涩伤津，最易伤肺','2026-04-17 06:30:00.000000',NULL,NULL,'燥邪；干涩伤津；燥易伤肺',NULL,NULL,NULL,NULL,'中医基础理论','六淫中燥的致病特性是什么？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(343,'火为夏季主气。火邪的性质和致病特点：火为阳邪，其性炎上；火易耗气伤津；火易生风动血；火易扰神；火易致疮痈。',NULL,'火邪的特性：火为阳邪，其性炎上，致病多见于人体上部；火易耗气伤津，高热大汗致津液亏损、气虚乏力；火易生风动血，热极生风出现抽搐，热迫血妄行出现出血；火易扰心神，出现烦躁、神昏、谵语；火易致疮痈，火热之邪入于血分，聚于局部形成疮疡痈肿。',NULL,'中医知识库','病因学说','火性炎上，耗气伤津，生风动血','2026-04-17 06:30:00.000000',NULL,NULL,'火邪；炎上；耗气伤津；生风动血',NULL,NULL,NULL,NULL,'中医基础理论','六淫中火的致病特性是什么？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(344,'七情即喜、怒、忧、思、悲、恐、惊七种情志变化。七情内伤致病直接伤及内脏，影响脏腑气机，以心、肝、脾三脏为多见。',NULL,'七情内伤致病特点：直接伤及内脏，怒伤肝、喜伤心、思伤脾、悲忧伤肺、惊恐伤肾；影响脏腑气机，怒则气上、喜则气缓、悲则气消、恐则气下、惊则气乱、思则气结；情志波动可致病情变化。七情致病以心肝脾三脏最为多见，因心主神明、肝主疏泄、脾主运化都与情志密切相关。',NULL,'中医知识库','病因学说','七情直接伤及内脏，影响气机','2026-04-17 06:30:00.000000',NULL,NULL,'七情；情志致病；气机失调',NULL,NULL,NULL,NULL,'中医基础理论','七情内伤的致病特点是什么？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(345,'饮食失宜包括饥饱失常、饮食不洁和饮食偏嗜三个方面。均可损伤脾胃，导致多种疾病的发生。',NULL,'饮食失宜致病分三类：饥饱失常，过饥则气血生化不足，过饱则损伤脾胃，出现食积；饮食不洁，进食腐败变质食物，可引起胃肠疾病、寄生虫病甚至食物中毒；饮食偏嗜，过食寒凉损伤脾阳，过食辛热助火伤阴，偏嗜五味影响脏腑功能。饮食失宜首先损伤脾胃，进而影响气血化生和全身功能。',NULL,'中医知识库','病因学说','饮食失宜损伤脾胃导致疾病','2026-04-17 06:30:00.000000',NULL,NULL,'饮食失宜；饥饱失常；饮食不洁；饮食偏嗜',NULL,NULL,NULL,NULL,'中医基础理论','饮食失宜如何致病？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(346,'劳逸失度包括过劳和过逸两个方面。过劳包括劳力过度、劳神过度和房劳过度；过逸则指长期不劳动不运动。',NULL,'过劳：劳力过度耗伤气血，出现气短乏力、形体消瘦；劳神过度损伤心脾，出现心悸失眠、纳差健忘；房劳过度耗伤肾精，出现腰膝酸软、遗精早泄。过逸：长期缺乏体力活动，气血运行不畅，脾胃功能减弱，出现食少乏力、肢体软弱。劳逸适度才能保持健康。',NULL,'中医知识库','病因学说','过度劳累或过度安逸均可致病','2026-04-17 06:30:00.000000',NULL,NULL,'劳逸失度；过劳；过逸',NULL,NULL,NULL,NULL,'中医基础理论','劳逸失度如何致病？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(347,'痰饮是水液代谢障碍形成的病理产物。多由肺、脾、肾及三焦等脏腑功能失调，水液代谢障碍，水湿停聚而成。',NULL,'痰饮的形成主要与肺、脾、肾、三焦功能失调有关。肺失宣降，津液不能布散，聚而为痰；脾失健运，水湿内停，聚而为痰；肾不化水，水液泛滥，聚而为饮；三焦不通，水道不利，水液停聚。痰饮分有形与无形：有形之痰指可见的痰液、饮液；无形之痰指表现为眩晕、昏迷、肿块等痰证症状。',NULL,'中医知识库','病因学说','水液代谢障碍形成痰饮','2026-04-17 06:30:00.000000',NULL,NULL,'痰饮；水液代谢；脾肺肾；有形无形',NULL,NULL,NULL,NULL,'中医基础理论','痰饮是如何形成的？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(348,'瘀血是指血液运行不畅，停滞于体内，或血液离经停积于局部的病理产物。气虚、气滞、血寒、血热、外伤等均可导致瘀血。',NULL,'瘀血的形成原因：气虚无力推动血行致瘀；气滞不能行血致瘀；寒凝血滞致瘀；热迫血妄行，离经之血致瘀；跌打损伤、出血等直接致瘀。瘀血的致病特点：疼痛（刺痛、固定不移、拒按、夜间加重）；肿块；出血（紫暗有块）；面色晦暗、唇甲青紫、舌有瘀斑瘀点、脉涩。',NULL,'中医知识库','病因学说','血行不畅或血离经脉停积为瘀','2026-04-17 06:30:00.000000',NULL,NULL,'瘀血；气虚气滞；血寒血热；刺痛',NULL,NULL,NULL,NULL,'中医基础理论','瘀血是如何形成的？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(349,'疠气是一类具有强烈传染性的病邪，又称疫气、疫毒、戾气等。疠气引起的疾病称为疫病，具有发病急骤、病情较重、症状相似、传染性强的特点。',NULL,'疠气是一类具有强烈传染性和流行性的外感病邪。疠气致病的特征：传染性强，可通过口鼻、接触等多种途径传播；发病急骤，来势凶猛；病情较重，病死率较高；症状相似，同一疫病流行时患者临床表现大致相同。疠气的发生与气候变化、环境卫生、社会因素等有关。预防疠气应避免接触传染源、保持环境卫生。',NULL,'中医知识库','病因学说','疠气为强烈传染性病邪','2026-04-17 06:30:00.000000',NULL,NULL,'疠气；疫气；传染性；疫病',NULL,NULL,NULL,NULL,'中医基础理论','什么是疠气？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(350,'结石是指体内某些部位形成的砂石样病理产物。多由湿热蕴结、气机郁滞、饮食偏嗜等原因，导致湿热煎熬尿液或胆汁，日久结为砂石。',NULL,'结石的形成与以下因素有关：饮食偏嗜，过食肥甘厚味或辛辣，湿热内生；情志不遂，肝胆气机郁滞；外感湿热，蕴结体内；体质因素。常见结石有胆结石、肾结石、膀胱结石等。结石致病特点：阻滞气机，损伤脉络，引起剧烈疼痛（绞痛），可伴有出血、感染等并发症。',NULL,'中医知识库','病因学说','湿热煎熬形成砂石样病理产物','2026-04-17 06:30:00.000000',NULL,NULL,'结石；湿热蕴结；胆结石；肾结石',NULL,NULL,NULL,NULL,'中医基础理论','结石是如何形成的？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(351,'内生五邪是指在疾病过程中，由于气血津液和脏腑功能失调而产生的类似风、寒、湿、燥、火五种外邪致病特征的病理变化，包括风气内动、寒从中生、湿浊内生、津伤化燥、火热内生。',NULL,'内生五邪又称内五气，不是真正的邪气，而是脏腑功能失调所产生的病理变化。风气内动：肝阳化风、热极生风、血虚生风等。寒从中生：阳气不足，温煦功能下降。湿浊内生：脾失健运，水湿内停。津伤化燥：津液亏少，滋润不足。火热内生：阳气过盛，阴虚火旺等。内生五邪与外感六淫在症状上相似，但本质不同。',NULL,'中医知识库','病因学说','脏腑功能失调产生类似六淫的病理变化','2026-04-17 06:30:00.000000',NULL,NULL,'内生五邪；风气内动；寒从中生；湿浊内生',NULL,NULL,NULL,NULL,'中医基础理论','什么是内生五邪？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(352,'风寒湿痹是风、寒、湿三种邪气夹杂侵袭人体，痹阻经络关节而引起的病证。风气偏盛为行痹，寒气偏盛为痛痹，湿气偏盛为着痹。',NULL,'风寒湿痹分三型：行痹（风痹），风邪偏盛，关节游走疼痛，痛无定处；痛痹（寒痹），寒邪偏盛，关节疼痛剧烈，遇寒加重，得温则减；着痹（湿痹），湿邪偏盛，关节酸痛重着，肌肤麻木，阴雨天气加重。治疗以祛风散寒除湿、通络止痛为主。方如蠲痹汤、独活寄生汤等。',NULL,'中医知识库','病因学说','风寒湿三邪合致痹证','2026-04-17 06:30:00.000000',NULL,NULL,'风寒湿痹；行痹；痛痹；着痹',NULL,NULL,NULL,NULL,'中医基础理论','风寒湿痹的特点是什么？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(353,'湿热疫毒是湿热之邪与疫毒之邪相合的病邪，具有湿热和疫毒的双重致病特点，以脾胃为病变重心，缠绵难愈。',NULL,'湿热疫毒致病特点：发病较急，但传变不如温热之邪迅速；以脾胃为病变重心，出现发热缠绵、身热不扬、脘痞腹胀、纳呆呕恶；湿热胶结，黏腻难解，病程较长，缠绵难愈；湿热酿痰，蒙蔽心包，可出现神识昏蒙。常见于湿温、伏暑等外感温病。治宜清热化湿解毒。',NULL,'中医知识库','病因学说','湿热疫毒以脾胃为病变重心','2026-04-17 06:30:00.000000',NULL,NULL,'湿热疫毒；脾胃；缠绵难愈',NULL,NULL,NULL,NULL,'中医基础理论','湿热疫毒的致病特点是什么？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(354,'情志致病直接伤及内脏，以心肝脾三脏多见；影响脏腑气机，导致气机紊乱；情志变化可使病情加重或诱发疾病。',NULL,'情志致病特点：一是直接伤及内脏，不同情志损伤不同脏腑；二是影响气机运动，怒则气上、喜则气缓、悲则气消、恐则气下、思则气结、惊则气乱；三是情志波动可加重病情或诱发疾病。情志之间还可相互影响，如怒伤肝后可影响脾的运化。治疗情志病除药物外，还应配合精神调摄。',NULL,'中医知识库','病因学说','情志直接伤脏，影响气机','2026-04-17 06:30:00.000000',NULL,NULL,'情志致病；伤及内脏；气机紊乱',NULL,NULL,NULL,NULL,'中医基础理论','情志致病的特点有哪些？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(355,'饮食失宜致病分三类：饥饱失常（过饥致气血不足，过饱致食积）；饮食不洁（引起胃肠病、寄生虫病）；饮食偏嗜（寒热偏嗜或五味偏嗜损伤相应脏腑）。',NULL,'饮食失宜致病的类型：饥饱失常，过饥则摄食不足，气血生化乏源，正气虚弱；过饱则饮食停滞，损伤脾胃，出现脘腹胀满、嗳腐吞酸。饮食不洁，进食不洁食物可引起泄泻、痢疾、寄生虫病等。饮食偏嗜，偏寒凉伤脾阳，偏辛热伤阴助火，五味偏嗜影响相应脏腑——酸入肝过多伤肝，苦入心过多伤心等。',NULL,'中医知识库','病因学说','饥饱不洁偏嗜三类饮食失宜','2026-04-17 06:30:00.000000',NULL,NULL,'饮食失宜类型；饥饱；不洁；偏嗜',NULL,NULL,NULL,NULL,'中医基础理论','饮食失宜致病的类型有哪些？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(356,'劳逸失度分过劳和过逸。过劳包括劳力过度（耗伤气血）、劳神过度（损伤心脾）、房劳过度（耗伤肾精）。过逸则气血不畅、脾胃虚弱。',NULL,'劳逸失度的类型：劳力过度，长时间繁重体力劳动，耗伤气血，出现气短懒言、四肢困倦、形体消瘦。劳神过度，思虑太过，损伤心脾，出现心悸失眠、健忘、纳差。房劳过度，房事不节，耗伤肾精，出现腰膝酸软、眩晕耳鸣、遗精早泄。过逸安闲，长期不劳动不运动，气血运行不畅，脾胃功能减退。',NULL,'中医知识库','病因学说','过劳过逸均可损伤人体','2026-04-17 06:30:00.000000',NULL,NULL,'劳逸失度类型；劳力；劳神；房劳；过逸',NULL,NULL,NULL,NULL,'中医基础理论','劳逸失度的类型有哪些？','中医基础理论',NULL,'理论','病因学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(357,'正虚感邪是指正气先虚，而后感受外邪发病。由于正气不足，抗邪能力下降，容易感受外邪而发病，且病情往往较重。',NULL,'正虚感邪的发病机理是正气先虚，然后感受外邪。正气不足是发病的内在根据，外邪是发病的重要条件。正虚感邪多见于体质虚弱者、老年人、大病初愈者。由于正气不足，抗邪无力，外邪容易侵入，且感邪后病情较重，传变较快，恢复较慢。治疗应在祛邪的同时注重扶正。',NULL,'中医知识库','病因学说','正气先虚而后感受外邪发病','2026-04-17 06:30:00.000000',NULL,NULL,'正虚感邪；正气先虚；外邪侵袭',NULL,NULL,NULL,NULL,'中医基础理论','什么是正虚感邪？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(358,'邪从寒化是指外邪侵入人体后，由于素体阳虚阴盛，邪气从寒化而表现为寒证。如同为外感风寒，阳虚体质者易从寒化，表现为寒重热轻。',NULL,'邪从寒化取决于体质因素。素体阳虚阴盛之人，感受外邪后，邪气容易从阴化寒。如外感风寒之邪，在阳虚体质者身上，表现为寒重热轻、无汗、肢冷、脉浮紧等寒证。治疗应以温阳散寒为主。邪从寒化与邪从热化是中医认识疾病传变的重要理论，体现了个体差异对疾病演变的影响。',NULL,'中医知识库','病因学说','阳虚体质感邪后邪从阴化寒','2026-04-17 06:30:00.000000',NULL,NULL,'邪从寒化；阳虚体质；从阴化寒',NULL,NULL,NULL,NULL,'中医基础理论','什么是邪从寒化？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(359,'邪从热化是指外邪侵入人体后，由于素体阳盛阴虚，邪气从热化而表现为热证。如同为外感风寒，阳盛体质者易从热化，表现为热重寒轻。',NULL,'邪从热化取决于体质因素。素体阳盛阴虚之人，感受外邪后，邪气容易从阳化热。如外感风寒之邪，在阳盛体质者身上，初起虽为风寒，但很快化热入里，表现为高热、烦渴、舌红苔黄等热证。治疗应以清热泻火为主。邪从寒化和邪从热化说明了体质对疾病性质和传变方向的重要影响。',NULL,'中医知识库','病因学说','阳盛体质感邪后邪从阳化热','2026-04-17 06:30:00.000000',NULL,NULL,'邪从热化；阳盛体质；从阳化热',NULL,NULL,NULL,NULL,'中医基础理论','什么是邪从热化？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(360,'伏邪发病是指感受邪气后不立即发病，邪气潜伏体内，待正气虚弱或感受诱因时才发病。如伏暑、伏气温病等。',NULL,'伏邪发病是中医病因学的重要理论。邪气侵入人体后，由于正气尚强，邪气不能立即发病，潜伏于体内。待正气虚弱、气候变化、劳累等诱因出现时，伏邪外发而发病。伏邪潜伏部位多在膜原、少阴等处。伏邪发病的特点是病情较重、传变较快、病程较长。治疗应清除伏邪，兼顾扶正。',NULL,'中医知识库','病因学说','邪气潜伏体内待时而发','2026-04-17 06:30:00.000000',NULL,NULL,'伏邪；潜伏发病；伏气温病',NULL,NULL,NULL,NULL,'中医基础理论','什么是伏邪发病？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(361,'继发病是指在原发疾病的基础上继发产生的新的疾病。如哮喘继发于反复感冒，水肿继发于久病等。',NULL,'继发病是由原发病引发的新的病证。原发病与继发病之间有因果关系。如反复感冒损伤肺气，继发哮喘；黄疸日久继发积聚；水肿日久继发虚劳。继发病的治疗应在治疗继发病的同时兼顾原发病，治标与治本相结合。',NULL,'中医知识库','病因学说','原发病基础上产生新的病证','2026-04-17 06:30:00.000000',NULL,NULL,'继发病；原发病；因果关系',NULL,NULL,NULL,NULL,'中医基础理论','什么是继发病？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(362,'合病是指两经或三经同时发病；并病是指一经病未愈，另一经病又起。两者都反映了疾病的复杂性和传变。',NULL,'合病和并病是《伤寒论》中的重要概念。合病：两经或三经的证候同时出现，如太阳阳明合病、太阳少阳合病、三阳合病等，说明邪气较盛，同时侵犯多经。并病：一经的证候未罢，另一经的证候又出现，如太阳少阳并病，说明疾病正在传变之中。合病和并病反映了外感病传变的复杂情况，治疗需兼顾多经。',NULL,'中医知识库','病因学说','合病为同时发病，并病为依次发病','2026-04-17 06:30:00.000000',NULL,NULL,'合病；并病；传变；多经同病',NULL,NULL,NULL,NULL,'中医基础理论','什么是合病与并病？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(363,'外感病的基本传变有三种形式：六经传变（由表入里，由阳入阴）、卫气营血传变（卫分-气分-营分-血分）、三焦传变（上焦-中焦-下焦），总体趋势由表入里、由浅入深。',NULL,'外感病的传变规律：六经传变是《伤寒论》理论，太阳-阳明-少阳-太阴-少阴-厥阴，由表入里，由阳转阴。卫气营血传变是温病理论，卫分-气分-营分-血分，由浅入深，由轻到重。三焦传变也是温病理论，上焦（肺心）-中焦（脾胃）-下焦（肝肾），由上而下。三种传变虽有不同，但总体趋势都是由表入里、由浅入深。',NULL,'中医知识库','病因学说','外感病由表入里由浅入深传变','2026-04-17 06:30:00.000000',NULL,NULL,'外感病传变；六经；卫气营血；三焦',NULL,NULL,NULL,NULL,'中医基础理论','外感病的基本传变规律是什么？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(364,'内伤病的传变主要表现为脏腑之间的传变，包括五脏之间的传变、脏与腑之间的传变，以及气病及血、血病及气等。',NULL,'内伤病的传变规律：五脏之间的传变，按五行相生相克关系传变，如肝病传脾（木乘土）、肾病及肝（母病及子）等。脏与腑之间的传变，通过表里关系传变，如肝病及胆、脾病及胃。气血之间的传变，气病及血、血病及气。内伤病传变较外感病缓慢，但病程较长，虚实夹杂。治疗应根据传变规律，既病防变。',NULL,'中医知识库','病因学说','内伤病通过脏腑和气血关系传变','2026-04-17 06:30:00.000000',NULL,NULL,'内伤病传变；脏腑传变；五行传变',NULL,NULL,NULL,NULL,'中医基础理论','内伤病的基本传变规律是什么？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(365,'三因学说是宋代陈言提出的病因分类方法，将病因分为外因（六淫）、内因（七情）和不内外因（饮食、劳逸、外伤等）三类。',NULL,'三因学说由宋代陈无择在《三因极一病证方论》中提出。外因：风、寒、暑、湿、燥、火六种外感病邪。内因：喜、怒、忧、思、悲、恐、惊七种情志变化。不内外因：不属于外因和内因的致病因素，包括饮食失宜、劳逸失度、跌打损伤、虫兽伤害等。三因学说使中医病因学更加系统化。',NULL,'中医知识库','病因学说','三因分类法系统归纳中医病因','2026-04-17 06:30:00.000000',NULL,NULL,'三因学说；陈无择；外因内因不内外因',NULL,NULL,NULL,NULL,'中医基础理论','三因学说的内容是什么？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(366,'药邪是指因用药不当而产生的致病因素。包括误用、过量、配伍不当等，可导致新的疾病或加重原有病情。',NULL,'药邪的形成原因：误用药物，辨证不准确导致用药与病情不符；用药过量，超过安全剂量产生毒副反应；配伍不当，药物之间产生不良反应；炮制不当，降低药效或增加毒性；用药禁忌不当，违反十八反、十九畏等配伍禁忌。预防药邪应做到辨证准确、用药适量、配伍合理、注意禁忌。',NULL,'中医知识库','病因学说','用药不当产生的致病因素','2026-04-17 06:30:00.000000',NULL,NULL,'药邪；用药不当；配伍禁忌',NULL,NULL,NULL,NULL,'中医基础理论','什么是药邪？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(367,'医过是指因医生的过失而导致的致病因素。包括辨证错误、用药不当、治疗失误等，使病情加重或产生新的病证。',NULL,'医过的常见类型：诊断失误，辨证不准确导致治疗方向错误；用药不当，药量过大或过小，药性过偏；操作不当，针灸、推拿等操作失误造成损伤；护理不当，未能正确指导患者调护。预防医过要求医生具备扎实的医学理论基础和丰富的临床经验，认真负责地对待每一位患者。',NULL,'中医知识库','病因学说','医生过失导致的致病因素','2026-04-17 06:30:00.000000',NULL,NULL,'医过；医疗过失；辨证失误',NULL,NULL,NULL,NULL,'中医基础理论','什么是医过？','中医基础理论',NULL,'理论','病因学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(368,'邪正盛衰是指在疾病过程中，致病邪气与人体正气之间的力量对比。邪正斗争的胜负决定疾病的发生、发展和转归。正胜邪退则病向愈，邪胜正衰则病恶化。',NULL,'邪正盛衰是疾病发展的内在依据。正气增长、邪气消退，表现为实证减轻或向愈；邪气增长、正气衰退，表现为病情加重或恶化。邪正双方的消长盛衰产生虚实证候：邪气盛则实，正气夺则虚。邪正相持不下则病情缠绵。治疗应根据邪正盛衰，扶正祛邪，调整邪正力量对比。',NULL,'中医知识库','病机学说','邪正力量对比决定疾病发展趋势','2026-04-17 06:30:00.000000',NULL,NULL,'邪正盛衰；虚实；正胜邪退；邪胜正衰',NULL,NULL,NULL,NULL,'中医基础理论','邪正盛衰与疾病的关系是什么？','中医基础理论',NULL,'理论','病机学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(369,'阴阳失调是疾病的基本病机之一。阴阳失调的表现形式包括阴阳偏盛、阴阳偏衰、阴阳互损、阴阳格拒、阴阳亡失等。',NULL,'阴阳失调的表现形式：阴阳偏盛，阳盛则热（实热证）、阴盛则寒（实寒证）；阴阳偏衰，阴虚则热（虚热证）、阳虚则寒（虚寒证）；阴阳互损，阴损及阳、阳损及阴，最终阴阳两虚；阴阳格拒，阴盛格阳（真寒假热）、阳盛格阴（真热假寒）；阴阳亡失，亡阴、亡阳。',NULL,'中医知识库','病机学说','阴阳失调是疾病的基本病机','2026-04-17 06:30:00.000000',NULL,NULL,'阴阳失调；偏盛偏衰；互损格拒；亡失',NULL,NULL,NULL,NULL,'中医基础理论','阴阳失调的基本病机是什么？','中医基础理论',NULL,'理论','病机学说','入门','2026-04-20 23:49:54.000000',NULL,NULL),(370,'气血失调包括气的失调和血的失调。气的失调有气虚、气滞、气逆、气陷、气闭、气脱；血的失调有血虚、血瘀、血热、出血等。',NULL,'气的失调：气虚，元气不足，功能衰退；气滞，气机郁滞不畅；气逆，气机上逆；气陷，气虚下陷；气闭，气机突然闭塞；气脱，气不内守而外脱。血的失调：血虚，血液不足，濡养功能减退；血瘀，血液运行不畅；血热，热入血分，迫血妄行；出血，血液逸出脉外。气血同病的病机有气滞血瘀、气虚血瘀、气不摄血、气随血脱等。',NULL,'中医知识库','病机学说','气血失调导致多种病证','2026-04-17 06:30:00.000000',NULL,NULL,'气血失调；气虚气滞；血虚血瘀',NULL,NULL,NULL,NULL,'中医基础理论','气血失调的病机有哪些？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(371,'津液代谢失常包括津液不足和津液停聚两个方面。津液不足表现为干燥失润；津液停聚表现为水湿痰饮潴留。',NULL,'津液不足：由于生成不足或消耗过多，出现口干舌燥、皮肤干燥、小便短少等津亏症状。津液停聚：由于输布排泄障碍，水湿痰饮潴留体内，出现水肿、痰多、胸水、腹水等。津液代谢失常与肺、脾、肾、三焦功能失调密切相关。肺失宣降则水道不通，脾失健运则水湿内停，肾不化水则水液泛滥。',NULL,'中医知识库','病机学说','津液不足或停聚的病理变化','2026-04-17 06:30:00.000000',NULL,NULL,'津液代谢失常；津液不足；津液停聚',NULL,NULL,NULL,NULL,'中医基础理论','津液代谢失常的病机是什么？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(372,'风气内动是指体内阳气亢逆变动而出现类似风动症状的病理变化。包括肝阳化风、热极生风、血虚生风、阴虚动风等。',NULL,'风气内动主要有四型：肝阳化风，肝肾阴虚，肝阳上亢化风，出现眩晕、震颤、甚则中风；热极生风，高热灼伤津液，筋脉失养，出现高热、抽搐；血虚生风，肝血不足，筋脉失养，出现肢体麻木、手足震颤、肌肉瞤动；阴虚动风，阴液亏虚，筋脉失养，出现手足蠕动、口干舌燥。风气内动以肝为中心。',NULL,'中医知识库','病机学说','阳气亢逆变动产生类似风的症状','2026-04-17 06:30:00.000000',NULL,NULL,'风气内动；肝阳化风；热极生风；血虚生风',NULL,NULL,NULL,NULL,'中医基础理论','风气内动的病机是什么？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(373,'寒从中生是指机体阳气虚衰，温煦气化功能减退，虚寒内生，或阴寒之邪弥漫的病理状态。主要与脾肾阳虚有关。',NULL,'寒从中生的病机是阳气不足，温煦功能下降。脾阳虚不能温煦肌肉四肢，出现形寒肢冷、腹痛绵绵、大便稀溏。肾阳虚不能温煦全身，出现畏寒怕冷、腰膝酸冷、小便清长。寒从中生的临床特点是面色苍白、四肢不温、疼痛喜温按、分泌物清稀、舌淡胖嫩、脉沉迟无力。治宜温阳散寒。',NULL,'中医知识库','病机学说','阳气虚衰导致虚寒内生','2026-04-17 06:30:00.000000',NULL,NULL,'寒从中生；阳气虚衰；脾肾阳虚',NULL,NULL,NULL,NULL,'中医基础理论','寒从中生的病机是什么？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(374,'湿浊内生是指脾运化水液功能失调，水湿停聚体内而产生的病理变化。脾虚生湿是湿浊内生的主要原因。',NULL,'湿浊内生的核心病机是脾失健运。脾主运化水液，脾虚则水液不能正常运化输布，停聚而为湿浊。湿浊内生可犯及多个部位：在上则头重如裹、胸闷；在中则脘痞腹胀、纳呆呕恶；在下则小便不利、大便黏滞。湿浊还常与痰饮合病，湿聚成痰。治宜健脾化湿，方如平胃散、参苓白术散。',NULL,'中医知识库','病机学说','脾失健运致水湿停聚','2026-04-17 06:30:00.000000',NULL,NULL,'湿浊内生；脾失健运；水湿停聚',NULL,NULL,NULL,NULL,'中医基础理论','湿浊内生的病机是什么？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(375,'津伤化燥是指津液亏少，滋润濡养功能减退，干燥失润的病理变化。多见于秋季、久病耗伤、大汗大吐大泻之后。',NULL,'津伤化燥的病机是津液亏耗，脏腑组织失于滋润濡养。常见原因：久病伤津，慢性病长期消耗津液；大汗大吐大泻，津液大量丢失；外感燥邪，直接损伤津液。临床表现以干燥为主：口干咽燥、皮肤干涩、目涩鼻干、大便干结、小便短少、干咳少痰、舌红少津。以肺胃最为常见。治宜滋阴润燥。',NULL,'中医知识库','病机学说','津液亏耗致干燥失润','2026-04-17 06:30:00.000000',NULL,NULL,'津伤化燥；津液亏耗；干燥失润',NULL,NULL,NULL,NULL,'中医基础理论','津伤化燥的病机是什么？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(376,'火热内生是指阳气过盛化火，或阴虚火旺，出现火热内扰的病理变化。包括阳气过盛化火、邪郁化火、五志过极化火、阴虚火旺。',NULL,'火热内生的四种类型：阳气过盛化火，阳气绝对偏盛，功能亢进而化火；邪郁化火，外感六淫或痰食瘀血等郁滞日久化火；五志过极化火，情志过激，气郁化火；阴虚火旺，阴液亏虚，虚火内生。火热内生以心肝胃最为多见。心火亢盛见心烦失眠、口舌生疮；肝火上炎见头痛目赤、急躁易怒；胃火炽盛见口臭、牙龈肿痛。',NULL,'中医知识库','病机学说','阳气过盛或阴虚导致火热内生','2026-04-17 06:30:00.000000',NULL,NULL,'火热内生；阳气过盛；邪郁化火；阴虚火旺',NULL,NULL,NULL,NULL,'中医基础理论','火热内生的病机是什么？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(377,'心病病机包括心气虚、心血虚、心阴虚、心阳虚、心火亢盛、心血瘀阻、痰蒙心窍、痰火扰心等。',NULL,'心病病机：心气虚，心气不足，推动无力，心悸气短、自汗。心血虚，心血不足，心失所养，心悸失眠、健忘面色不华。心阴虚，心阴不足，虚热内生，心悸心烦、盗汗。心阳虚，心阳不足，温煦无力，心悸胸闷、畏寒肢冷。心火亢盛，心火上炎，心烦失眠、口舌生疮。心血瘀阻，心血运行不畅，胸闷心痛。',NULL,'中医知识库','病机学说','心病病机以气血阴阳失调为核心','2026-04-17 06:30:00.000000',NULL,NULL,'心病病机；心气虚；心血虚；心火亢盛',NULL,NULL,NULL,NULL,'中医基础理论','心病病机的主要表现有哪些？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(378,'肺病病机包括肺气虚、肺阴虚、风寒犯肺、风热犯肺、燥邪犯肺、痰湿阻肺等。',NULL,'肺病病机：肺气虚，肺气不足，咳喘无力、气短懒言、自汗。肺阴虚，肺阴不足，干咳少痰、咽干口燥、潮热盗汗。风寒犯肺，风寒束表犯肺，咳嗽痰白、鼻塞流清涕。风热犯肺，风热犯肺，咳嗽痰黄、咽喉肿痛。燥邪犯肺，干咳少痰、鼻干咽燥。痰湿阻肺，痰多白黏、胸闷气喘。',NULL,'中医知识库','病机学说','肺病以宣降失常为核心病机','2026-04-17 06:30:00.000000',NULL,NULL,'肺病病机；肺气虚；肺阴虚；外感犯肺',NULL,NULL,NULL,NULL,'中医基础理论','肺病病机的主要表现有哪些？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(379,'脾病病机包括脾气虚、脾阳虚、脾气下陷、脾不统血、寒湿困脾、湿热蕴脾等。',NULL,'脾病病机：脾气虚，脾运化无力，纳少腹胀、便溏乏力。脾阳虚，脾阳不足，腹痛喜温、大便稀溏、形寒肢冷。脾气下陷，升举无力，脘腹坠胀、久泻脱肛、内脏下垂。脾不统血，统摄无权，便血、崩漏、皮下出血。寒湿困脾，湿邪困遏脾阳，脘腹痞闷、纳呆呕恶。湿热蕴脾，湿热熏蒸，脘腹痞满、口苦口黏。',NULL,'中医知识库','病机学说','脾病以运化失常为核心病机','2026-04-17 06:30:00.000000',NULL,NULL,'脾病病机；脾气虚；脾阳虚；脾不统血',NULL,NULL,NULL,NULL,'中医基础理论','脾病病机的主要表现有哪些？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(380,'肝病病机包括肝气郁结、肝火上炎、肝血虚、肝阴虚、肝阳上亢、肝风内动、肝胆湿热、寒滞肝脉等。',NULL,'肝病病机：肝气郁结，疏泄不及，胸胁胀满、情志抑郁、善太息。肝火上炎，气郁化火，头痛目赤、急躁易怒、口苦。肝血虚，血不养肝，视物模糊、肢体麻木、爪甲不荣。肝阴虚，阴不制阳，头晕目眩、两目干涩。肝阳上亢，肝肾阴虚阳亢，眩晕耳鸣、面红目赤。肝风内动，抽搐震颤、眩晕。肝胆湿热，湿热蕴结，黄疸胁痛。',NULL,'中医知识库','病机学说','肝病以疏泄失常为核心病机','2026-04-17 06:30:00.000000',NULL,NULL,'肝病病机；肝气郁结；肝火上炎；肝阳上亢',NULL,NULL,NULL,NULL,'中医基础理论','肝病病机的主要表现有哪些？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(381,'肾病病机以虚证为主，包括肾阳虚、肾阴虚、肾精不足、肾气不固、肾不纳气、肾虚水泛等。',NULL,'肾病病机：肾阳虚，命门火衰，畏寒肢冷、腰膝酸冷、阳痿早泄。肾阴虚，肾阴不足，五心烦热、潮热盗汗、腰膝酸软。肾精不足，精少不育、小儿发育迟缓、成人早衰。肾气不固，封藏失职，遗精滑泄、小便频数、带下清稀。肾不纳气，摄纳无权，呼多吸少、动则气喘。肾虚水泛，气化不行，全身水肿、腰以下为甚。',NULL,'中医知识库','病机学说','肾病以藏精纳气水液失调为核心','2026-04-17 06:30:00.000000',NULL,NULL,'肾病病机；肾阳虚；肾阴虚；肾精不足',NULL,NULL,NULL,NULL,'中医基础理论','肾病病机的主要表现有哪些？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(382,'经络病机是指经络气血运行失常，导致经络功能失调的病理变化。包括经络气血偏盛偏衰、经络气血运行不畅、经络气血衰竭等。',NULL,'经络病机：经络气血偏盛偏衰，某经气血过盛或不足，出现该经循行部位的异常。经络气血运行不畅，气血瘀滞于经络，出现疼痛、肿胀、麻木。经络气血衰竭，正气衰竭，经气败绝。经络病还表现为循经症状，如足阳明胃经病变可见齿痛、颈肿、下肢外侧疼痛等。治疗经络病常以疏通经络为基本原则。',NULL,'中医知识库','病机学说','经络气血运行失常','2026-04-17 06:30:00.000000',NULL,NULL,'经络病机；气血运行失常；循经症状',NULL,NULL,NULL,NULL,'中医基础理论','经络病机的主要内容是什么？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(383,'疾病的传变形式包括病位的传变（表里传变、上下传变、脏腑传变）和病性的转化（寒热转化、虚实转化）。',NULL,'疾病传变的形式：病位传变包括表里传变（由表入里或由里出表）、上下传变（由上至下或由下至上）、脏腑传变（按五行生克关系或表里关系传变）。病性转化包括寒热转化（寒证化热、热证转寒）和虚实转化（实证转虚、虚证致实）。掌握疾病传变规律可以预测疾病发展趋势，指导早期治疗。',NULL,'中医知识库','病机学说','疾病在病位和病性上的传变转化','2026-04-17 06:30:00.000000',NULL,NULL,'疾病传变；表里传变；寒热转化；虚实转化',NULL,NULL,NULL,NULL,'中医基础理论','疾病的传变形式有哪些？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(384,'疾病的转归有三种：痊愈（正胜邪退，完全恢复）、缠绵（邪正相持，病情迁延）、死亡（邪胜正衰，阴阳离决）。',NULL,'疾病转归：痊愈，正气渐复，邪气消除，脏腑功能恢复正常。缠绵，邪正双方势均力敌，病情迁延不愈，反复发作。死亡，正气极度衰竭，邪气极度亢盛，阴阳离决，生命活动停止。影响疾病转归的因素包括正气的强弱、邪气的轻重、治疗的及时与否、调护得当与否。积极治疗和正确调护有利于疾病向好的方向转归。',NULL,'中医知识库','病机学说','疾病的最终结局取决于邪正消长','2026-04-17 06:30:00.000000',NULL,NULL,'疾病转归；痊愈；缠绵；死亡',NULL,NULL,NULL,NULL,'中医基础理论','疾病的转归有哪些？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(385,'真实假虚是指疾病的本质为实证，却出现某些类似虚证的假象。即\"大实有羸状\"，如热结旁流、大便秘结却见下利清水。',NULL,'真实假虚，又称\"大实有羸状\"。病机为邪气亢盛，正气尚未大衰，但邪气内结，阻滞气血运行，脏腑功能受到严重障碍，外表呈现虚弱假象。如热结旁流，燥屎内结（实证），但下利清水（假虚象）；瘀血内阻，气血不能外达，出现面色苍白、神情沉默（假虚象）。辨证需透过假象辨明本质。',NULL,'中医知识库','病机学说','实证出现类似虚证的假象','2026-04-17 06:30:00.000000',NULL,NULL,'真实假虚；大实有羸状；假象',NULL,NULL,NULL,NULL,'中医基础理论','什么是真实假虚？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(386,'真虚假实是指疾病的本质为虚证，却出现某些类似实证的假象。即\"至虚有盛候\"，如脾虚腹胀、气虚便秘等。',NULL,'真虚假实，又称\"至虚有盛候\"。病机为正气虚弱，脏腑功能衰退，气血运行无力，导致某些部位出现阻滞不通的假实证表现。如脾虚腹胀，脾虚运化无力（虚证），却出现腹部胀满（假实证）；气虚便秘，气虚推动无力（虚证），却出现便秘不通（假实证）。治疗应以补虚为主，不可误用攻伐。',NULL,'中医知识库','病机学说','虚证出现类似实证的假象','2026-04-17 06:30:00.000000',NULL,NULL,'真虚假实；至虚有盛候；假实证',NULL,NULL,NULL,NULL,'中医基础理论','什么是真虚假实？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(387,'寒热真假包括真寒假热和真热假寒。真寒假热为阴盛格阳，内有真寒外有假热；真热假寒为阳盛格阴，内有真热外有假寒。辨别以里证、舌象、脉象为真。',NULL,'真寒假热（阴盛格阳）：本质为寒证，但外表出现面红、口渴、烦躁等热象假象。面红为两颧浮红如妆，口渴但不欲饮或喜热饮，烦躁但精神萎靡，脉虽浮大但按之无力，舌淡苔白。真热假寒（阳盛格阴）：本质为热证，但外表出现四肢厥冷、恶寒等寒象假象。虽四肢冷但胸腹灼热，虽恶寒但不愿加衣被，脉沉但有力，舌红苔黄。',NULL,'中医知识库','病机学说','辨别寒热真假以里证舌脉为准','2026-04-17 06:30:00.000000',NULL,NULL,'寒热真假；阴盛格阳；阳盛格阴；辨别要点',NULL,NULL,NULL,NULL,'中医基础理论','寒热真假如何辨别？','中医基础理论',NULL,'理论','病机学说','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(388,'望神是通过观察人体生命活动的总体表现来判断正气盛衰和病情轻重。神的表现有得神、失神、假神、神志异常等。',NULL,'望神是望诊的首要内容。得神（有神），表现为精神良好、神志清楚、面色荣润、目光精彩、呼吸平稳，说明正气充足，病情较轻。失神（无神），表现为精神萎靡、面色晦暗、目无光彩、反应迟钝，说明正气大伤，病情较重。假神，久病重病突然精神好转、面色红赤如妆，为回光返照之象，预后不良。',NULL,'中医知识库','四诊','望神判断正气盛衰和病情轻重','2026-04-17 06:30:00.000000',NULL,NULL,'望神；得神；失神；假神',NULL,NULL,NULL,NULL,'中医基础理论','望神的意义是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(389,'常色是健康人的面色，明润含蓄，有胃气、有神气。病色是疾病状态下的面色，分为善色和恶色。善色光明润泽，预后较好；恶色枯槁晦暗，预后较差。',NULL,'常色：中国人正常面色为红黄隐隐、明润含蓄。常色分主色（先天面色）和客色（因季节气候等变化的面包）。病色分善色和恶色。善色：面色虽有异常但光明润泽，说明气血未衰，胃气尚存，预后较好。恶色：面色枯槁晦暗，说明气血已衰，胃气败绝，预后较差。五色善恶的辨别关键在于有华无华。',NULL,'中医知识库','四诊','常色明润含蓄，病色分善恶','2026-04-17 06:30:00.000000',NULL,NULL,'望面色；常色；病色；善色恶色',NULL,NULL,NULL,NULL,'中医基础理论','望面色中常色与病色如何区分？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(390,'五色主病：青色主寒证、痛证、瘀血、惊风；赤色主热证；黄色主湿证、虚证；白色主虚证、寒证、脱血；黑色主肾虚、寒证、水饮、痛证。',NULL,'五色主病：青色——主寒证（阴寒内盛）、痛证（气滞血瘀）、瘀血（面色青紫）、惊风（小儿高热惊风面青）。赤色——主热证，满面通红为实热，午后颧红为虚热。黄色——主湿证（面黄如橘为湿热，面黄晦暗为寒湿）、虚证（面色萎黄为脾虚）。白色——主虚证（面色㿠白为阳虚）、寒证、脱血（面色苍白）。黑色——主肾虚、寒证、水饮、痛证。',NULL,'中医知识库','四诊','五色对应不同病证','2026-04-17 06:30:00.000000',NULL,NULL,'五色主病；青赤黄白黑；寒热虚实',NULL,NULL,NULL,NULL,'中医基础理论','五色主病的内容是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(391,'望形态包括望形体和望姿态。望形体观察体质强弱、胖瘦等；望姿态观察病人的动静姿态和异常动作，以判断疾病的寒热虚实。',NULL,'望形体：形体强壮为正气充足，形体衰弱为正气不足。胖人多痰湿，瘦人多阴虚。望姿态：动属阳、热、实证；静属阴、寒、虚证。如卧时仰面伸足、不欲近衣被为热证；卧时蜷缩、欲加衣被为寒证。抽搐属肝风内动；半身不遂属中风后遗症。手足拘挛属肝血不足或寒凝筋脉。',NULL,'中医知识库','四诊','形态反映体质和病证性质','2026-04-17 06:30:00.000000',NULL,NULL,'望形态；形体；姿态；动静',NULL,NULL,NULL,NULL,'中医基础理论','望形态包括哪些内容？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(392,'望舌质主要包括舌神、舌色、舌形、舌态四个方面。舌色分淡红（正常）、淡白（虚寒）、红（热）、绛（热盛）、青紫（瘀血）等。',NULL,'望舌质：舌神——舌体荣润有生气为有神，枯槁无生气为无神。舌色——淡红为正常，淡白主气血两虚或阳虚，红舌主热证，绛舌主热入营血或阴虚火旺，紫舌主瘀血或寒极。舌形——老嫩（老为实证，嫩为虚证）、胖大（脾虚湿盛或阳虚水泛）、瘦薄（气血两虚或阴虚火旺）、裂纹（阴虚或血虚）、齿痕（脾虚湿盛）。舌态——痿软、强硬、歪斜、颤动、吐弄等。',NULL,'中医知识库','四诊','舌质反映脏腑气血盛衰','2026-04-17 06:30:00.000000',NULL,NULL,'望舌质；舌色；舌形；舌态',NULL,NULL,NULL,NULL,'中医基础理论','望舌质包括哪些内容？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(393,'望舌苔包括苔色和苔质。苔色分白苔（表证、寒证）、黄苔（热证、里证）、灰黑苔（里热极盛或寒湿内阻）。苔质分厚薄、润燥、腐腻、剥脱等。',NULL,'望舌苔：苔色——白苔主表证、寒证；黄苔主热证、里证；灰苔主里热证或寒湿证；黑苔主热极或寒极。苔质——薄苔为病邪在表，厚苔为病邪入里；润苔为津液未伤，燥苔为津液已伤；腻苔为湿浊痰饮，腐苔为食积胃腐；剥苔（花剥苔、镜面舌）为胃阴不足或气血两虚。舌苔由胃气上蒸而生，舌苔变化反映病邪的性质和深浅。',NULL,'中医知识库','四诊','舌苔反映病邪性质和深浅','2026-04-17 06:30:00.000000',NULL,NULL,'望舌苔；苔色；苔质；厚薄润燥',NULL,NULL,NULL,NULL,'中医基础理论','望舌苔包括哪些内容？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(394,'舌诊在临床上有重要意义：判断正气盛衰，辨别病位深浅，区别病邪性质，推断病情进退。舌质反映脏腑气血，舌苔反映病邪性质。',NULL,'舌诊的临床意义：判断正气盛衰——舌质红润为气血旺盛，舌质淡白为气血不足。辨别病位深浅——舌苔薄为邪在表，苔厚为邪在里。区别病邪性质——白苔多为寒，黄苔多为热，腻苔多为湿。推断病情进退——舌苔由薄转厚为病进，由厚转薄为病退；舌质由淡转红为热化，由红转淡为向寒。舌诊是中医最具特色的诊断方法之一。',NULL,'中医知识库','四诊','舌诊判断正气盛衰和病邪性质','2026-04-17 06:30:00.000000',NULL,NULL,'舌诊；临床意义；判断正气；辨别病位',NULL,NULL,NULL,NULL,'中医基础理论','舌诊的临床意义是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(395,'闻诊听声音包括听语声、呼吸声、咳嗽声、呕吐声、呃逆声、嗳气声等。通过声音的强弱、高低、清浊来判断病证的性质。',NULL,'闻诊听声音：语声——语声高亢有力为实证，低微无力为虚证；谵语为热扰心神，郑声为心气大伤。呼吸——呼吸有力声高为实热，呼吸微弱声低为虚寒。咳嗽——咳声重浊为实证，咳声低微为虚证。呕吐——吐声壮厉为实热，吐声低弱为虚寒。呃逆——呃声高亢为实热，呃声低沉为虚寒。语声嘶哑为金破不鸣或金实不鸣。',NULL,'中医知识库','四诊','听声音辨别病证寒热虚实','2026-04-17 06:30:00.000000',NULL,NULL,'闻诊；听声音；语声；呼吸；咳嗽',NULL,NULL,NULL,NULL,'中医基础理论','闻诊听声音包括哪些内容？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(396,'闻诊嗅气味包括嗅病人的口气、各种排出物的气味以及病室的气味。气味酸腐臭秽多属热证，气味偏淡无臭多属寒证。',NULL,'闻诊嗅气味：口气——口臭为胃热、龋齿或食积；口中酸腐为食积内停；口中有尿味为肾衰尿毒。排出物气味——痰涕腥臭为肺热；大便酸臭为肠中积热；小便臊臭为湿热下注；白带臭秽为湿热。病室气味——血腥味为失血；尿臊味为水肿晚期；烂苹果味为消渴病重证。一般而言，气味臭秽者多实热，气味偏淡者多虚寒。',NULL,'中医知识库','四诊','嗅气味辨别病证寒热性质','2026-04-17 06:30:00.000000',NULL,NULL,'闻诊；嗅气味；口气；排出物',NULL,NULL,NULL,NULL,'中医基础理论','闻诊嗅气味包括哪些内容？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(397,'十问歌：\"一问寒热二问汗，三问头身四问便，五问饮食六问胸，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见。\"',NULL,'十问歌由明代张景岳提出，后经补充完善。内容依次为：一问寒热——辨别表里寒热；二问汗——辨别表里虚实；三问头身——了解头痛身痛的部位和性质；四问便——了解大小便情况；五问饮食——了解脾胃功能；六问胸——了解心肺情况；七聋——了解肝肾情况；八渴——辨别寒热津液；九问旧病——了解既往病史；十问因——了解发病原因。',NULL,'中医知识库','四诊','十问歌系统指导问诊','2026-04-17 06:30:00.000000',NULL,NULL,'十问歌；张景岳；问诊顺序',NULL,NULL,NULL,NULL,'中医基础理论','问诊十问歌的内容是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(398,'问寒热包括恶寒发热、但寒不热、但热不寒、寒热往来等类型。不同类型反映不同的病证性质和病位。',NULL,'问寒热的类型：恶寒发热——发热与恶寒同时出现，多属外感表证。但寒不热——只怕冷不发热，属里寒证。但热不寒——只发热不怕冷，属里热证。壮热为实热，潮热按时发热或按时热甚。寒热往来——恶寒与发热交替出现，属半表半里证（少阳病）。此外还有低热（阴虚发热、气虚发热）。通过问寒热可辨别表里、寒热、虚实。',NULL,'中医知识库','四诊','寒热类型辨别表里寒热','2026-04-17 06:30:00.000000',NULL,NULL,'问寒热；恶寒发热；但寒不热；寒热往来',NULL,NULL,NULL,NULL,'中医基础理论','问寒热包括哪些类型？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(399,'问汗包括有汗无汗、出汗时间、出汗部位、汗量多少等。表证无汗为表寒，表证有汗为表虚或表热。自汗为气虚，盗汗为阴虚。',NULL,'问汗的内容：有汗无汗——表证无汗属表实（风寒），表证有汗属表虚或风热。出汗时间——自汗（日间经常出汗，活动后加重）属气虚或阳虚；盗汗（夜间睡着出汗，醒来汗止）属阴虚。出汗部位——头汗多为上焦热或湿热；半身出汗多属经络不通；手足心汗多为阴虚内热。大汗——大热大汗为里热炽盛；冷汗淋漓为亡阳。战汗为正邪交争。',NULL,'中医知识库','四诊','出汗情况辨别表里虚实','2026-04-17 06:30:00.000000',NULL,NULL,'问汗；自汗；盗汗；表证出汗',NULL,NULL,NULL,NULL,'中医基础理论','问汗包括哪些内容？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(400,'问疼痛要问疼痛的部位、性质、程度、时间、诱因和伴随症状。疼痛的性质有胀痛、刺痛、冷痛、灼痛、重痛、绞痛、隐痛等。',NULL,'问疼痛的性质：胀痛——气滞所致；刺痛——瘀血所致；冷痛——寒邪所致，得温则减；灼痛——热邪所致；重痛——湿邪所致；绞痛——结石或虫积；隐痛——虚证，喜按；掣痛——经脉阻滞。疼痛的部位也提示病变脏腑：头痛辨经络，胸痛辨心肺，胁痛辨肝胆，胃脘痛辨脾胃，腹痛辨肠腑，腰痛辨肾。疼痛喜按属虚，拒按属实。',NULL,'中医知识库','四诊','疼痛性质和部位辨别病邪属性','2026-04-17 06:30:00.000000',NULL,NULL,'问疼痛；胀痛；刺痛；冷痛；绞痛',NULL,NULL,NULL,NULL,'中医基础理论','问疼痛包括哪些内容？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(401,'问饮食口味包括食欲、食量、口渴与饮水、口味变化等。食欲减退多脾胃虚弱，消谷善饥多胃火炽盛，口苦多热证，口淡多虚证。',NULL,'问饮食口味：食欲——食欲减退属脾胃虚弱或湿邪困脾；消谷善饥属胃火炽盛；饥不欲食属胃阴虚。口渴——口渴多饮属热证或消渴；口渴不多饮属湿热或痰饮；口不渴属寒证或湿证。口味——口苦属热证（肝胆湿热）；口甜属湿热蕴脾；口酸属肝胃不和或食积；口咸属肾虚；口淡属脾胃虚弱；口黏腻属湿浊内阻。',NULL,'中医知识库','四诊','饮食口味反映脾胃和脏腑状态','2026-04-17 06:30:00.000000',NULL,NULL,'问饮食；食欲；口渴；口味',NULL,NULL,NULL,NULL,'中医基础理论','问饮食口味包括哪些内容？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(402,'问二便包括大便和小便的情况。大便问次数、质地、颜色、排便感等；小便问次数、尿量、颜色、排尿感等。',NULL,'问大便：便次异常——便秘属热结、气滞、气虚、血虚、阴虚等；泄泻属寒湿、湿热、食积、脾虚、肾虚等。质地——便干为热或津亏，便溏为脾虚或湿盛。颜色——便黑为消化道出血。排便感——里急后重为痢疾，排便不爽为肝郁脾虚。问小便：尿频——属肾虚或湿热。尿量——尿多属肾阳虚，尿少属津亏或湿热。颜色——尿黄为热，尿清为寒。排尿感——尿痛为湿热下注，尿余沥为肾气不固。',NULL,'中医知识库','四诊','二便反映脾胃肾和津液代谢','2026-04-17 06:30:00.000000',NULL,NULL,'问二便；大便；小便；便秘泄泻',NULL,NULL,NULL,NULL,'中医基础理论','问二便包括哪些内容？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(403,'问睡眠包括失眠和嗜睡两方面。失眠有入睡困难、易醒、早醒、多梦等；嗜睡为睡眠过多。不同表现反映不同病证。',NULL,'问睡眠：失眠——入睡困难兼心烦多梦为心火亢盛或心阴虚；易醒兼心悸健忘为心脾两虚；夜寐不安兼口苦为肝火上炎。嗜睡——嗜睡兼头身困重为痰湿困脾；嗜睡兼神疲乏力为脾气虚；嗜睡兼畏寒肢冷为肾阳虚。失眠总属阳不入阴，神不守舍；嗜睡总属阳虚阴盛或痰湿蒙蔽清窍。',NULL,'中医知识库','四诊','睡眠反映阴阳和神志状态','2026-04-17 06:30:00.000000',NULL,NULL,'问睡眠；失眠；嗜睡',NULL,NULL,NULL,NULL,'中医基础理论','问睡眠包括哪些内容？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(404,'问经带是女性患者的专项问诊。问月经包括周期、经期、经量、经色、经质和伴随症状；问带下包括量、色、质、气味等。',NULL,'问月经：周期——月经先期（提前7天以上）多为血热或气虚；月经后期（延后7天以上）多为血虚或寒凝；先后无定期多为肝郁或肾虚。经量——月经过多属血热或气虚；月经过少属血虚或肾虚。经色——色鲜红为热，色淡为虚，色暗有块为瘀。问带下：白带量多清稀为脾虚湿盛；黄带量多黏稠为湿热；赤白带下为湿热或肿瘤可能。',NULL,'中医知识库','四诊','经带情况反映妇科病证','2026-04-17 06:30:00.000000',NULL,NULL,'问经带；月经；带下；妇科问诊',NULL,NULL,NULL,NULL,'中医基础理论','问经带包括哪些内容？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(405,'脉诊的部位主要在两手桡动脉腕部桡骨茎突内侧，即寸口脉法。寸口脉分寸、关、尺三部，左手依次为心、肝、肾，右手依次为肺、脾、命门。',NULL,'寸口脉法是临床最常用的脉诊方法。寸口脉分为寸、关、尺三部：以桡骨茎突内侧为关部，关前为寸部，关后为尺部。左手寸关尺分别候心、肝、肾；右手寸关尺分别候肺、脾、命门（肾阳）。寸口脉为脉之大会，五脏六腑之气皆汇于此，故诊寸口可察全身脏腑气血状况。此外还有遍诊法（三部九候）和人迎寸口诊法。',NULL,'中医知识库','四诊','寸口脉分寸关尺候五脏','2026-04-17 06:30:00.000000',NULL,NULL,'脉诊；寸口脉；寸关尺',NULL,NULL,NULL,NULL,'中医基础理论','脉诊的部位在哪里？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(406,'浮脉的特征为轻取即得，重按稍减而不空。浮脉主表证，亦主虚证。有力为表实，无力为表虚。',NULL,'浮脉的特征：手指轻放于皮肤上即可感觉脉搏跳动，稍重按则跳动减弱但不空虚。浮脉主表证——外邪侵袭肌表，正气抗邪，脉气鼓动于外，故脉浮。浮而有力为表实证，浮而无力为表虚证。此外，久病体虚脉浮而无根，为虚阳外越，属危象。正常人脉象也可偏浮，尤其是瘦人。秋季脉象偏浮属正常。',NULL,'中医知识库','四诊','浮脉主表证','2026-04-17 06:30:00.000000',NULL,NULL,'浮脉；表证；轻取即得',NULL,NULL,NULL,NULL,'中医基础理论','浮脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(407,'沉脉的特征为轻取不应，重按始得。沉脉主里证。有力为里实，无力为里虚。',NULL,'沉脉的特征：手指轻放感觉不到脉搏跳动，需重按才能感觉到。沉脉主里证——邪郁于里，或正虚气血不足以鼓脉于外。沉而有力为里实证，沉而无力为里虚证。此外，肥人脉偏沉属正常，冬季脉象偏沉亦属正常。伏脉比沉脉更深，重按推筋着骨始得，主邪闭、厥证或痛极。',NULL,'中医知识库','四诊','沉脉主里证','2026-04-17 06:30:00.000000',NULL,NULL,'沉脉；里证；重按始得',NULL,NULL,NULL,NULL,'中医基础理论','沉脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(408,'迟脉的特征为一息不足四至，即每分钟脉搏不足60次。迟脉主寒证。有力为实寒，无力为虚寒。',NULL,'迟脉的特征：脉搏跳动缓慢，一呼一吸之间不足四次跳动（每分钟不足60次）。迟脉主寒证——寒邪凝滞，气血运行缓慢，故脉迟。迟而有力为实寒证（寒邪亢盛），迟而无力为虚寒证（阳气不足）。此外，运动员或体力劳动者脉偏迟属正常。迟脉也可见于邪热结聚阻滞气机的里实证。',NULL,'中医知识库','四诊','迟脉主寒证','2026-04-17 06:30:00.000000',NULL,NULL,'迟脉；寒证；一息不足四至',NULL,NULL,NULL,NULL,'中医基础理论','迟脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(409,'数脉的特征为一息五至以上，即每分钟脉搏超过90次。数脉主热证。有力为实热，无力为虚热。',NULL,'数脉的特征：脉搏跳动加快，一呼一吸之间五次以上跳动（每分钟超过90次）。数脉主热证——热邪亢盛，气血运行加速，故脉数。数而有力为实热证（热邪亢盛），数而无力为虚热证（阴虚火旺）。此外，运动后、情绪激动时脉偏数属正常。儿童脉象偏数也属正常。',NULL,'中医知识库','四诊','数脉主热证','2026-04-17 06:30:00.000000',NULL,NULL,'数脉；热证；一息五至以上',NULL,NULL,NULL,NULL,'中医基础理论','数脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(410,'虚脉的特征为三部脉举之无力，按之空豁。虚脉主虚证，为气血不足之象。',NULL,'虚脉的特征：寸、关、尺三部脉轻取重按均无力，感觉空虚。虚脉是无力脉的总称，主虚证——气血不足，气虚无力推动血行，血虚不能充盈脉道，故脉虚无力。临床常见于气虚、血虚、气血两虚等证。虚脉常与其他脉象兼见，如虚浮、虚数等，兼脉不同主病各异。',NULL,'中医知识库','四诊','虚脉主气血不足','2026-04-17 06:30:00.000000',NULL,NULL,'虚脉；虚证；举按无力',NULL,NULL,NULL,NULL,'中医基础理论','虚脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(411,'实脉的特征为三部脉举按均有力。实脉主实证，为邪气亢盛、正气不虚之象。',NULL,'实脉的特征：寸、关、尺三部脉轻取重按均充实有力。实脉是有力脉的总称，主实证——邪气亢盛而正气不虚，正邪交争激烈，故脉实有力。临床常见于高热、便秘、食积、痰饮等实证。实脉也可见于正常人，说明正气充沛。',NULL,'中医知识库','四诊','实脉主邪气亢盛','2026-04-17 06:30:00.000000',NULL,NULL,'实脉；实证；举按有力',NULL,NULL,NULL,NULL,'中医基础理论','实脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(412,'滑脉的特征为往来流利，如盘走珠，应指圆滑。滑脉主痰饮、食积、实热，也可见于妊娠。',NULL,'滑脉的特征：脉搏跳动圆滑流利，像珠子在盘中滚动一样，有一种旋转感。滑脉主痰饮——痰浊内蕴，气血充盛而滑利；主食积——食滞胃脘，气实血涌；主实热——热邪亢盛，气血加速。此外，滑脉也是妊娠脉象的典型表现，因孕后气血充盛。正常人气血调和时脉也可偏滑。',NULL,'中医知识库','四诊','滑脉主痰饮食积实热','2026-04-17 06:30:00.000000',NULL,NULL,'滑脉；痰饮；食积；妊娠',NULL,NULL,NULL,NULL,'中医基础理论','滑脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(413,'涩脉的特征为往来艰涩不畅，如轻刀刮竹，与滑脉相反。涩脉主瘀血、精伤、血少等证。',NULL,'涩脉的特征：脉搏跳动不流畅，往来艰涩，像用刀在竹子上轻刮的感觉，脉力不匀。涩脉主瘀血——血脉瘀滞，气血运行不畅，故脉涩；主精伤血少——精血亏虚，脉道不充，运行不畅。涩而有力多为实证（瘀血），涩而无力多为虚证（精血不足）。',NULL,'中医知识库','四诊','涩脉主瘀血和精血亏虚','2026-04-17 06:30:00.000000',NULL,NULL,'涩脉；瘀血；精伤血少',NULL,NULL,NULL,NULL,'中医基础理论','涩脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(414,'弦脉的特征为端直以长，如按琴弦。弦脉主肝胆病、痛证、痰饮、疟疾等。',NULL,'弦脉的特征：脉搏跳动紧张有力，像按在绷紧的琴弦上，挺直而长。弦脉主肝胆病——肝主疏泄，肝气不舒则气机紧张，故脉弦；主痛证——疼痛致脉气紧张；主痰饮——痰饮阻滞气机；主疟疾。此外，春季脉象偏弦属正常。老年人脉偏弦为精气衰减之象。弦脉的紧张程度反映病情轻重。',NULL,'中医知识库','四诊','弦脉主肝胆病和痛证','2026-04-17 06:30:00.000000',NULL,NULL,'弦脉；肝胆病；痛证；如按琴弦',NULL,NULL,NULL,NULL,'中医基础理论','弦脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(415,'紧脉的特征为脉来绷急弹指，状如转索。紧脉主寒证、痛证、宿食。',NULL,'紧脉的特征：脉搏跳动紧张有力，左右弹指，像拧紧的绳索。紧脉主寒证——寒邪收引，脉道收缩拘急，故脉紧；主痛证——疼痛致经脉拘急；主宿食——食滞中焦，气机壅滞。紧脉与弦脉相似，但紧脉比弦脉更紧张有力。紧脉多见于实寒证，如太阳伤寒。',NULL,'中医知识库','四诊','紧脉主寒证和痛证','2026-04-17 06:30:00.000000',NULL,NULL,'紧脉；寒证；痛证；状如转索',NULL,NULL,NULL,NULL,'中医基础理论','紧脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(416,'细脉的特征为脉细如线，但应指明显。细脉主气血两虚、湿病。',NULL,'细脉的特征：脉道窄小，脉体细如线状，但跳动清晰可辨。细脉主气血两虚——气血不足，不能充盈脉道，故脉道细小；主湿病——湿邪阻滞脉道。细脉又称小脉。阴虚、血虚、气虚皆可见细脉。临床常见于贫血、慢性消耗性疾病。细而无力为虚证，细而数为阴虚内热。',NULL,'中医知识库','四诊','细脉主气血两虚','2026-04-17 06:30:00.000000',NULL,NULL,'细脉；气血两虚；湿病；脉细如线',NULL,NULL,NULL,NULL,'中医基础理论','细脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(417,'濡脉的特征为浮细而软，轻取即得，重按不显。濡脉主虚证、湿证。',NULL,'濡脉的特征：脉象浮而细软，轻触即可感觉，稍加压力即消失不见。濡脉又称软脉，主虚证——气血不足，脉道不充，故脉浮细而软；主湿证——湿邪弥漫，脉气受困。临床常见于脾虚湿盛、气血不足等证。濡脉与弱脉不同，弱脉为沉细而软，濡脉为浮细而软。',NULL,'中医知识库','四诊','濡脉主虚证和湿证','2026-04-17 06:30:00.000000',NULL,NULL,'濡脉；虚证；湿证；浮细而软',NULL,NULL,NULL,NULL,'中医基础理论','濡脉的特征与主病是什么？','中医基础理论',NULL,'理论','四诊','入门','2026-04-20 23:49:54.000000',NULL,NULL),(418,'八纲辨证是以阴阳、表里、寒热、虚实八个纲领来分析归纳疾病证候的辨证方法。阴阳为总纲，表、热、实属阳，里、寒、虚属阴。',NULL,'八纲辨证是中医各种辨证方法的总纲。表里辨别病位深浅；寒热辨别病证性质；虚实辨别邪正盛衰；阴阳统括其他六纲，为总纲。表、热、实属阳证，里、寒、虚属阴证。八纲之间相互联系、相互转化，如表寒里热、虚实夹杂等。八纲辨证是临床辨证的基础和第一步。',NULL,'中医知识库','辨证方法','八纲辨证是辨证的总纲','2026-04-17 06:30:00.000000',NULL,NULL,'八纲辨证；阴阳表里寒热虚实；总纲',NULL,NULL,NULL,NULL,'中医基础理论','八纲辨证概述的内容是什么？','中医基础理论',NULL,'理论','辨证方法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(419,'表证是指六淫邪气经皮毛、口鼻侵入时所产生的证候。表现以发热恶寒（或恶风）、头身疼痛、鼻塞、苔薄白、脉浮为主。',NULL,'表证的特点：起病急、病程短、病位浅。主要表现为发热恶寒（或恶风）同时并见——这是表证的标志性症状。此外还可见头身疼痛、鼻塞流涕、喷嚏、微咳、舌苔薄白、脉浮。表证见于外感病初期，有表寒、表热、表虚、表实之分。表寒证恶寒重发热轻，表热证发热重恶寒轻。',NULL,'中医知识库','辨证方法','表证以发热恶寒并见为特征','2026-04-17 06:30:00.000000',NULL,NULL,'表证；发热恶寒；脉浮；外感初起',NULL,NULL,NULL,NULL,'中医基础理论','表证的特点是什么？','中医基础理论',NULL,'理论','辨证方法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(420,'里证是病变部位在内，累及脏腑气血的证候。表现以脏腑症状为主，无发热恶寒并见，可见壮热、神昏、腹痛、便秘、舌红苔黄等。',NULL,'里证的特点：病位深在脏腑，病程可长可短。基本特点是无新起发热恶寒并见，以脏腑症状为主要表现。如壮热或但寒不热、神昏、心烦、腹痛、呕吐、便秘或泄泻、小便异常、舌质红或淡、苔厚、脉沉等。里证可由表证传变而来，也可由脏腑功能失调直接发生，或由饮食劳倦等引起。',NULL,'中医知识库','辨证方法','里证以脏腑症状为主无表证','2026-04-17 06:30:00.000000',NULL,NULL,'里证；脏腑症状；无表证表现',NULL,NULL,NULL,NULL,'中医基础理论','里证的特点是什么？','中医基础理论',NULL,'理论','辨证方法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(421,'寒证是感受寒邪或阳虚阴盛所表现的证候。表现为恶寒喜暖、面色苍白、肢冷蜷卧、口淡不渴、痰涕清稀、小便清长、大便稀溏、舌淡苔白、脉紧或迟。',NULL,'寒证的特点：以冷、凉、白、稀、润为主要特征。恶寒喜暖、面色苍白、肢冷蜷卧、口淡不渴或喜热饮、痰涕涎液清稀、小便清长、大便稀溏、舌淡苔白润滑、脉紧或迟或沉。寒证分实寒（感受寒邪）和虚寒（阳气不足），实寒脉紧有力，虚寒脉沉迟无力。',NULL,'中医知识库','辨证方法','寒证以冷凉白稀润为特征','2026-04-17 06:30:00.000000',NULL,NULL,'寒证；恶寒喜暖；冷凉白稀润',NULL,NULL,NULL,NULL,'中医基础理论','寒证的特点是什么？','中医基础理论',NULL,'理论','辨证方法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(422,'热证是感受热邪或阳盛阴虚所表现的证候。表现为发热喜凉、面红目赤、口渴喜冷饮、烦躁、痰涕黄稠、小便短赤、大便秘结、舌红苔黄、脉数。',NULL,'热证的特点：以热、红、黄、干、数为基本特征。发热喜凉、面红目赤、烦躁不安、口渴喜冷饮、痰涕黄稠、小便短赤、大便秘结、舌红苔黄干燥、脉数。热证分实热（热邪亢盛）和虚热（阴虚火旺），实热发病急、热势高，虚热发病缓、热势低、午后低热。',NULL,'中医知识库','辨证方法','热证以热红黄干数为特征','2026-04-17 06:30:00.000000',NULL,NULL,'热证；发热喜凉；热红黄干数',NULL,NULL,NULL,NULL,'中医基础理论','热证的特点是什么？','中医基础理论',NULL,'理论','辨证方法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(423,'虚证是正气不足所表现的证候。包括气虚、血虚、阴虚、阳虚等。总体表现为面色不华、精神萎靡、气短懒言、食少乏力、脉虚无力等。',NULL,'虚证的特点：以不足、衰退、松弛为特征。面色苍白或萎黄、精神萎靡不振、气短懒言、心悸自汗、食少乏力、大便稀溏或便秘无力、舌质淡嫩、脉虚无力。气虚以气短乏力为主；血虚以面色不华、头晕心悸为主；阴虚以五心烦热、潮热盗汗为主；阳虚以畏寒肢冷为主。虚证病程较长，发展缓慢。',NULL,'中医知识库','辨证方法','虚证以正气不足衰退为特征','2026-04-17 06:30:00.000000',NULL,NULL,'虚证；正气不足；不足衰退松弛',NULL,NULL,NULL,NULL,'中医基础理论','虚证的特点是什么？','中医基础理论',NULL,'理论','辨证方法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(424,'实证是邪气亢盛所表现的证候。表现为发热、腹胀痛拒按、胸闷烦躁、大便秘结、小便短赤、舌质苍老、苔厚腻、脉实有力等。',NULL,'实证的特点：以亢盛、有余、结实为特征。发热、腹胀痛拒按、胸闷烦躁甚至神昏谵语、呼吸气粗、大便秘结、小便短赤、舌质苍老、苔厚腻、脉实有力。实证病程较短，多见于外感病初中期或食积、痰饮、瘀血等有形之邪内结者。实证宜泻不宜补。',NULL,'中医知识库','辨证方法','实证以邪气亢盛有余为特征','2026-04-17 06:30:00.000000',NULL,NULL,'实证；邪气亢盛；亢盛有余结实',NULL,NULL,NULL,NULL,'中医基础理论','实证的特点是什么？','中医基础理论',NULL,'理论','辨证方法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(425,'阴证表现为面色苍白或晦暗、畏寒肢冷、精神萎靡、口淡不渴、舌淡苔白、脉沉迟无力。阳证表现为面红目赤、身热喜凉、烦躁、口渴、舌红苔黄、脉数有力。',NULL,'阴证与阳证的辨别：阴证——面色苍白或晦暗，精神萎靡不振，畏寒肢冷，口淡不渴，语声低微，小便清长，大便稀溏，舌淡胖苔白润，脉沉迟无力。阳证——面色红赤，身热喜凉，烦躁不安，口渴喜冷饮，语声高亢，小便短赤，大便秘结，舌红苔黄，脉数有力。阴证属寒属虚，阳证属热属实。',NULL,'中医知识库','辨证方法','阴证寒虚，阳证热实','2026-04-17 06:30:00.000000',NULL,NULL,'阴证阳证；辨别要点；寒热虚实',NULL,NULL,NULL,NULL,'中医基础理论','阴证与阳证如何辨别？','中医基础理论',NULL,'理论','辨证方法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(426,'心气虚证以心悸、气短、乏力为主症，伴面色淡白、精神疲惫、自汗，活动后加重，舌淡苔白，脉虚。',NULL,'心气虚证的表现：心气不足，推动无力。主症为心悸怔忡、气短、乏力。兼症为面色淡白或㿠白、精神疲惫、自汗，活动后诸症加重。舌象为舌质淡嫩、苔白。脉象为虚弱或结代。治宜补益心气，方如养心汤、炙甘草汤。心气虚进一步发展可致心阳虚。',NULL,'中医知识库','辨证方法','心气不足推动无力','2026-04-17 06:30:00.000000',NULL,NULL,'心气虚；心悸；气短；自汗',NULL,NULL,NULL,NULL,'中医基础理论','心气虚证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(427,'心血虚证以心悸、失眠、健忘为主症，伴面色不华、头晕目眩、唇舌色淡、脉细弱。',NULL,'心血虚证的表现：心血不足，心失所养。主症为心悸怔忡、失眠多梦、健忘。兼症为面色不华或萎黄、头晕目眩、唇甲色淡。舌象为舌质淡。脉象为细弱。治宜养血安神，方如归脾汤、天王补心丹。心血虚常与心气虚并见，形成心气血两虚证。',NULL,'中医知识库','辨证方法','心血不足心失所养','2026-04-17 06:30:00.000000',NULL,NULL,'心血虚；心悸失眠；面色不华',NULL,NULL,NULL,NULL,'中医基础理论','心血虚证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(428,'心阴虚证以心悸心烦、失眠多梦为主症，伴五心烦热、潮热盗汗、口燥咽干、舌红少苔、脉细数。',NULL,'心阴虚证的表现：心阴不足，虚热内生。主症为心悸心烦、失眠多梦。兼症为五心烦热、午后潮热、盗汗、口燥咽干、颧红。舌象为舌红少津、少苔或无苔。脉象为细数。治宜滋阴安神，方如天王补心丹、酸枣仁汤。心阴虚由心血虚发展而来，在血虚基础上见虚热征象。',NULL,'中医知识库','辨证方法','心阴不足虚热内生','2026-04-17 06:30:00.000000',NULL,NULL,'心阴虚；心烦失眠；五心烦热',NULL,NULL,NULL,NULL,'中医基础理论','心阴虚证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(429,'心火亢盛证以心烦失眠、口舌生疮为主症，伴面赤口渴、尿赤便结、舌红苔黄、脉数有力。',NULL,'心火亢盛证的表现：心火内炽，扰乱心神。主症为心烦失眠、甚则狂躁谵语、口舌生疮、糜烂疼痛。兼症为面赤、口渴、小便短赤、大便秘结，甚则吐血衄血。舌象为舌尖红赤、苔黄。脉象为数有力。治宜清心泻火，方如泻心汤、导赤散。心火亢盛多由情志不遂化火或外感热邪入心所致。',NULL,'中医知识库','辨证方法','心火内炽扰神伤络','2026-04-17 06:30:00.000000',NULL,NULL,'心火亢盛；心烦失眠；口舌生疮',NULL,NULL,NULL,NULL,'中医基础理论','心火亢盛证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(430,'肺气虚证以咳喘无力、气短懒言为主症，伴声音低微、自汗畏风、易感冒、舌淡苔白、脉虚弱。',NULL,'肺气虚证的表现：肺气不足，宣降无力。主症为咳喘无力、气短懒言、声音低微。兼症为自汗畏风、容易感冒、面色淡白、神疲乏力。舌象为舌淡苔白。脉象为虚弱。治宜补益肺气，方如补肺汤、玉屏风散。肺气虚多由久病咳喘耗伤肺气，或脾虚不能散精于肺所致。',NULL,'中医知识库','辨证方法','肺气不足宣降无力','2026-04-17 06:30:00.000000',NULL,NULL,'肺气虚；咳喘无力；自汗畏风',NULL,NULL,NULL,NULL,'中医基础理论','肺气虚证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(431,'肺阴虚证以干咳少痰或无痰为主症，伴口燥咽干、形体消瘦、五心烦热、盗汗、舌红少苔、脉细数。',NULL,'肺阴虚证的表现：肺阴不足，虚热内生。主症为干咳少痰或无痰、或痰少而黏、不易咳出。兼症为口燥咽干、形体消瘦、五心烦热、午后潮热、盗汗、声音嘶哑。舌象为舌红少津、少苔或无苔。脉象为细数。治宜滋阴润肺，方如百合固金汤、沙参麦冬汤。肺阴虚多由久咳伤阴或痨虫蚀肺所致。',NULL,'中医知识库','辨证方法','肺阴不足虚热内生','2026-04-17 06:30:00.000000',NULL,NULL,'肺阴虚；干咳少痰；五心烦热',NULL,NULL,NULL,NULL,'中医基础理论','肺阴虚证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(432,'脾气虚证以纳少腹胀、便溏为主症，伴面色萎黄、神疲乏力、少气懒言、舌淡苔白、脉缓弱。',NULL,'脾气虚证的表现：脾气不足，运化失健。主症为食欲不振、纳少腹胀、食后胀甚、大便稀溏。兼症为面色萎黄、神疲乏力、少气懒言、形体消瘦或浮肿。舌象为舌淡苔白。脉象为缓弱。治宜健脾益气，方如四君子汤、参苓白术散。脾气虚是脾虚证的起点，可发展为脾阳虚、脾气下陷、脾不统血。',NULL,'中医知识库','辨证方法','脾气不足运化失健','2026-04-17 06:30:00.000000',NULL,NULL,'脾气虚；纳少腹胀；便溏',NULL,NULL,NULL,NULL,'中医基础理论','脾气虚证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(433,'脾阳虚证以腹痛喜温按、大便稀溏为主症，伴形寒肢冷、面色㿠白、口淡不渴、舌淡胖有齿痕、脉沉迟无力。',NULL,'脾阳虚证的表现：脾阳不足，虚寒内生。主症为脘腹冷痛、喜温喜按、纳少腹胀、大便稀溏或完谷不化。兼症为形寒肢冷、面色㿠白、口淡不渴或喜热饮、肢体浮肿、小便不利。舌象为舌淡胖嫩、有齿痕、苔白润。脉象为沉迟无力。治宜温中健脾，方如理中丸、附子理中丸。脾阳虚多由脾气虚发展而来。',NULL,'中医知识库','辨证方法','脾阳不足虚寒内生','2026-04-17 06:30:00.000000',NULL,NULL,'脾阳虚；腹痛喜温按；形寒肢冷',NULL,NULL,NULL,NULL,'中医基础理论','脾阳虚证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(434,'肝气郁结证以胸胁胀痛、情志抑郁为主症，伴善太息、咽中如有异物、妇女乳房胀痛、月经不调、脉弦。',NULL,'肝气郁结证的表现：肝失疏泄，气机郁滞。主症为胸胁或少腹胀痛、情志抑郁或易怒、善太息。兼症为咽中如有异物梗阻（梅核气）、妇女乳房胀痛、月经不调。舌象为舌苔薄白。脉象为弦。治宜疏肝解郁，方如柴胡疏肝散、逍遥散。肝气郁结是肝病最基本的证型，进一步可化火、伤阴、致瘀。',NULL,'中医知识库','辨证方法','肝失疏泄气机郁滞','2026-04-17 06:30:00.000000',NULL,NULL,'肝气郁结；胸胁胀痛；情志抑郁',NULL,NULL,NULL,NULL,'中医基础理论','肝气郁结证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(435,'肝火上炎证以头痛眩晕、面红目赤、急躁易怒为主症，伴口苦咽干、便秘尿赤、舌红苔黄、脉弦数。',NULL,'肝火上炎证的表现：肝火炽盛，上炎头目。主症为头痛眩晕、面红目赤、急躁易怒。兼症为口苦咽干、耳鸣如潮、失眠多梦、胁肋灼痛、便秘尿赤、甚则咳血吐血。舌象为舌红苔黄。脉象为弦数。治宜清肝泻火，方如龙胆泻肝汤、丹栀逍遥散。肝火上炎多由肝气郁结化火而来。',NULL,'中医知识库','辨证方法','肝火炽盛上炎头目','2026-04-17 06:30:00.000000',NULL,NULL,'肝火上炎；头痛目赤；急躁易怒',NULL,NULL,NULL,NULL,'中医基础理论','肝火上炎证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(436,'肝血虚证以视物模糊、肢体麻木为主症，伴面色无华、爪甲不荣、头晕眼花、月经量少或闭经、舌淡、脉细。',NULL,'肝血虚证的表现：肝血不足，濡养功能减退。主症为视物模糊或夜盲、肢体麻木、筋脉拘挛、爪甲枯脆不荣。兼症为面色无华、头晕眼花、妇女月经量少或闭经。舌象为舌淡。脉象为细。治宜补血养肝，方如四物汤、补肝汤。肝血虚多由失血过多、脾虚化源不足或久病耗伤肝血所致。',NULL,'中医知识库','辨证方法','肝血不足濡养功能减退','2026-04-17 06:30:00.000000',NULL,NULL,'肝血虚；视物模糊；肢体麻木',NULL,NULL,NULL,NULL,'中医基础理论','肝血虚证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(437,'肾阳虚证以畏寒肢冷、腰膝酸冷为主症，伴面色苍白、精神萎靡、阳痿早泄、小便清长、五更泄泻、舌淡胖、脉沉弱。',NULL,'肾阳虚证的表现：肾阳不足，命门火衰。主症为畏寒肢冷、腰膝酸冷、腰痛。兼症为面色苍白或黧黑、精神萎靡、阳痿早泄、宫寒不孕、小便清长或不利、五更泄泻、水肿。舌象为舌淡胖嫩、苔白润。脉象为沉弱或沉迟。治宜温补肾阳，方如金匮肾气丸、右归丸。肾阳虚是各脏阳虚的根本。',NULL,'中医知识库','辨证方法','肾阳不足命门火衰','2026-04-17 06:30:00.000000',NULL,NULL,'肾阳虚；畏寒肢冷；腰膝酸冷；命门火衰',NULL,NULL,NULL,NULL,'中医基础理论','肾阳虚证的表现是什么？','中医基础理论',NULL,'理论','辨证方法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(438,'治病求本是指在治疗疾病时，必须寻求疾病的本质，针对其本质进行治疗。标本是一个相对概念，本为疾病的本质，标为疾病的现象。',NULL,'治病求本是中医治疗疾病的基本原则。\"本\"指疾病的本质、主要矛盾。在错综复杂的病证中，要透过现象看本质，抓住疾病的主要矛盾进行治疗。如大出血的\"本\"是气虚不能摄血，治当益气摄血。治病求本还涉及标本缓急、正治反治等问题，是指导临床治疗的核心思想。',NULL,'中医知识库','治则治法','治病必须抓住疾病本质','2026-04-17 06:30:00.000000',NULL,NULL,'治病求本；标本；主要矛盾',NULL,NULL,NULL,NULL,'中医基础理论','治病求本的含义是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(439,'标本缓急的原则是急则治标、缓则治本、标本同治。当标病紧急时先治标，病情缓和时治本，标本俱急或俱重时标本同治。',NULL,'标本缓急的三种情况：急则治标——当标病（次要矛盾）紧急，危及生命或影响治疗时，先治标病。如大出血时先止血。缓则治本——病情缓和时，针对本（主要矛盾）进行治疗。如脾虚泄泻治当健脾。标本同治——标本俱急或标本俱重时，同时治疗标本。如表里同病、虚实夹杂时，表里双解、攻补兼施。',NULL,'中医知识库','治则治法','分清标本缓急确定治疗顺序','2026-04-17 06:30:00.000000',NULL,NULL,'标本缓急；急则治标；缓则治本；标本同治',NULL,NULL,NULL,NULL,'中医基础理论','标本缓急的原则是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(440,'正治是逆其病证性质而治，即寒者热之、热者寒之、虚则补之、实则泻之。反治是顺其病证假象而治，即热因热用、寒因寒用、塞因塞用、通因通用。',NULL,'正治又称逆治，是常规的治法——寒证用温热药，热证用寒凉药，虚证用补益药，实证用攻泻药。反治又称从治，是在特殊情况下顺从疾病假象的治法——热因热用（用温热药治假热真寒），寒因寒用（用寒凉药治假寒真热），塞因塞用（用补益药治假实真虚），通因通用（用通利药治假虚真实）。',NULL,'中医知识库','治则治法','正治逆病性而治，反治顺假象而治','2026-04-17 06:30:00.000000',NULL,NULL,'正治；反治；寒者热之；热因热用',NULL,NULL,NULL,NULL,'中医基础理论','正治与反治的区别是什么？','中医基础理论',NULL,'理论','治则治法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(441,'扶正祛邪是治疗疾病的重要原则。扶正即补益正气，祛邪即消除邪气。应根据邪正盛衰，或扶正或祛邪或两者兼顾。',NULL,'扶正祛邪的应用原则：扶正适用于正虚为主者，用补益方法增强正气；祛邪适用于邪实为主者，用攻泻方法消除邪气；扶正祛邪兼用适用于虚实夹杂者，攻补兼施，但需分清主次。扶正不留邪，祛邪不伤正。先扶正后祛邪适用于正虚严重不耐攻伐者；先祛邪后扶正适用于邪实严重不宜补益者。',NULL,'中医知识库','治则治法','扶正祛邪分清主次','2026-04-17 06:30:00.000000',NULL,NULL,'扶正祛邪；补益正气；消除邪气',NULL,NULL,NULL,NULL,'中医基础理论','扶正祛邪的原则是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(442,'调整阴阳是治病的根本原则。阴阳偏盛者泻其有余，阴阳偏衰者补其不足。使阴阳恢复平衡协调。',NULL,'调整阴阳的方法：泻其有余——阳盛则热用清热泻火法（热者寒之），阴盛则寒用温散寒邪法（寒者热之）。补其不足——阴虚则热用滋阴法（壮水之主以制阳光），阳虚则寒用温阳法（益火之源以消阴翳）。此外，阴阳两虚者阴阳双补。调整阴阳还需注意阴阳互根关系，补阳时佐以补阴，补阴时佐以补阳。',NULL,'中医知识库','治则治法','调整阴阳恢复平衡','2026-04-17 06:30:00.000000',NULL,NULL,'调整阴阳；泻其有余；补其不足',NULL,NULL,NULL,NULL,'中医基础理论','调整阴阳的方法是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(443,'调理气血是根据气血失调的病机进行治疗。气病治气，血病治血。气虚补气，气滞行气，血虚补血，血瘀活血，气血同病气血同调。',NULL,'调理气血的原则：气病——气虚补气（四君子汤），气滞行气（柴胡疏肝散），气逆降气（苏子降气汤），气陷升提（补中益气汤）。血病——血虚补血（四物汤），血瘀活血（桃红四物汤），出血止血。气血同病——气虚血瘀则益气活血，气滞血瘀则行气活血，气不摄血则补气摄血，气随血脱则补气固脱。',NULL,'中医知识库','治则治法','根据气血失调类型分别调治','2026-04-17 06:30:00.000000',NULL,NULL,'调理气血；补气行气；补血活血',NULL,NULL,NULL,NULL,'中医基础理论','调理气血的原则是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(444,'调理脏腑是根据脏腑功能失调的病机进行治疗。原则包括补虚泻实、协调脏腑关系、根据五行关系调理。',NULL,'调理脏腑的原则：一脏一腑的调治——根据脏腑功能特点，虚则补之、实则泻之。如脾虚补脾、肝实泻肝。脏腑合治——利用表里关系，如肺与大肠同治。五行关系调理——虚则补其母、实则泻其子。协调多脏关系——如心肾不交交通心肾，肝脾不调疏肝健脾。调理脏腑是内伤杂病治疗的核心。',NULL,'中医知识库','治则治法','根据脏腑病机针对性调治','2026-04-17 06:30:00.000000',NULL,NULL,'调理脏腑；补虚泻实；五行调理',NULL,NULL,NULL,NULL,'中医基础理论','调理脏腑的原则是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(445,'三因制宜是指因时制宜、因地制宜、因人制宜。即根据不同季节气候、地理环境和个人体质来制定适宜的治疗方案。',NULL,'三因制宜是中医治疗的重要原则。因时制宜——根据季节气候特点用药，春夏慎用温热，秋冬慎用寒凉。因地制宜——根据地理环境特点用药，西北寒冷多温热，东南湿热多清凉。因人制宜——根据年龄、性别、体质、生活习惯等个体差异用药，老人慎攻伐，小儿量宜轻，孕妇慎用峻烈药。',NULL,'中医知识库','治则治法','根据时地人差异制定治疗方案','2026-04-17 06:30:00.000000',NULL,NULL,'三因制宜；因时；因地；因人',NULL,NULL,NULL,NULL,'中医基础理论','三因制宜的内容是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(446,'因时制宜是根据不同季节和气候特点来确定治疗用药。春夏阳气升发慎用温热，秋冬阴气收敛慎用寒凉，用药剂量也因季节调整。',NULL,'因时制宜的应用：春夏季节——阳气升发，人体腠理开泄，用药不宜过用温热发散之品，以免耗伤气阴。用温热药剂量宜小。秋冬季节——阴气渐盛，人体腠理致密，用药不宜过用寒凉，以免损伤阳气。用寒凉药剂量宜小。此外，暑天多湿，用药应注意化湿；燥季多干，用药应注意养阴润燥。',NULL,'中医知识库','治则治法','根据季节气候调整治疗用药','2026-04-17 06:30:00.000000',NULL,NULL,'因时制宜；季节；气候；用药调整',NULL,NULL,NULL,NULL,'中医基础理论','因时制宜的具体内容是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(447,'因地制宜是根据不同地区的地理环境和气候特点来确定治疗用药。西北寒冷干燥用药偏温润，东南湿热多雨用药偏清化。',NULL,'因地制宜的应用：西北地区——气候寒冷干燥，人们体质偏壮实，腠理致密，用药可稍重温热发散。东南地区——气候湿热多雨，人们体质偏柔弱，腠理疏松，用药宜轻清化湿。高原地区——气候干燥缺氧，应注意养阴润燥。此外，不同地区的药材也有差异，就地取材也是因地制宜的体现。',NULL,'中医知识库','治则治法','根据地域特点调整治疗用药','2026-04-17 06:30:00.000000',NULL,NULL,'因地制宜；地理环境；区域差异',NULL,NULL,NULL,NULL,'中医基础理论','因地制宜的具体内容是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(448,'因人制宜是根据患者的年龄、性别、体质、生活习惯等个体差异来确定治疗用药。老人慎攻伐，妇人注意经期，体强者可重剂。',NULL,'因人制宜的应用：年龄——小儿生机旺盛但脏腑娇嫩，用药宜轻，忌用峻烈；老人脏腑功能衰退，用药宜平和，慎用攻伐。性别——妇女经期、孕期、产后应特别注意，孕妇禁用峻烈、滑利、走窜之品。体质——阳虚体质慎用寒凉，阴虚体质慎用温燥。体强者用药可稍重，体弱者用药宜轻。',NULL,'中医知识库','治则治法','根据个体差异调整治疗用药','2026-04-17 06:30:00.000000',NULL,NULL,'因人制宜；年龄；性别；体质',NULL,NULL,NULL,NULL,'中医基础理论','因人制宜的具体内容是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(449,'汗法是通过发汗以解除表证的治疗方法。适用于外感表证、麻疹初期、水肿兼表证等。汗法分辛温发汗和辛凉发汗。',NULL,'汗法的应用：适应证——外感表证、麻疹初起未透、水肿兼有表证、疮疡初起兼有表证。分类——辛温发汗，适用于表寒证，方如麻黄汤、桂枝汤；辛凉发汗，适用于表热证，方如银翘散、桑菊饮。注意事项——发汗适度，不可太过，以微汗为佳；体虚者汗法宜慎，可配合扶正；不可大汗伤津。',NULL,'中医知识库','治则治法','发汗解除表证','2026-04-17 06:30:00.000000',NULL,NULL,'汗法；发汗解表；辛温辛凉',NULL,NULL,NULL,NULL,'中医基础理论','汗法的应用要点是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(450,'吐法是通过催吐以祛除病邪的治疗方法。适用于痰涎壅盛、食积胃脘、误食毒物等病在上焦者。',NULL,'吐法的应用：适应证——痰涎壅塞咽喉、食积停滞胃脘、误食毒物尚在胃中。方药如瓜蒂散、盐汤探吐。注意事项——吐法刺激性强，易伤胃气，现已少用；体虚、孕妇、出血患者禁用。吐后应调理脾胃，不可进食油腻。吐法在古代八法中较为特殊，现代临床已较少使用。',NULL,'中医知识库','治则治法','催吐祛除上焦病邪','2026-04-17 06:30:00.000000',NULL,NULL,'吐法；催吐；病在上焦',NULL,NULL,NULL,NULL,'中医基础理论','吐法的应用要点是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(451,'下法是通过通便排便以祛除里实病邪的治疗方法。适用于燥屎内结、积滞内停、水饮停聚等里实证。',NULL,'下法的应用：适应证——大便秘结燥屎内结、食积虫积内停、瘀血内结、水饮停聚。分类——寒下，适用于里热积滞，方如大承气汤；温下，适用于寒积内停，方如大黄附子汤；润下，适用于肠燥便秘，方如麻子仁丸；逐水，适用于水饮壅盛，方如十枣汤。注意事项——表证未解者慎用，年老体弱、孕妇慎用。',NULL,'中医知识库','治则治法','通便祛除里实病邪','2026-04-17 06:30:00.000000',NULL,NULL,'下法；通便；寒下温下润下',NULL,NULL,NULL,NULL,'中医基础理论','下法的应用要点是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(452,'和法是通过和解调和以祛除病邪的治疗方法。适用于少阳证、肝脾不和、肠胃不和、疟疾等半表半里证。',NULL,'和法的应用：适应证——少阳半表半里证（寒热往来）、肝脾不和、肠胃不和、疟疾、妇人热入血室。代表方——小柴胡汤和解少阳，逍遥散调和肝脾，半夏泻心汤调和肠胃。和法的特点是祛邪而不伤正，适用于邪不在表又未完全入里、正气未大虚而邪气不甚实的证候。',NULL,'中医知识库','治则治法','和解调和中焦气机','2026-04-17 06:30:00.000000',NULL,NULL,'和法；和解；少阳证；调和',NULL,NULL,NULL,NULL,'中医基础理论','和法的应用要点是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(453,'温法是通过温里散寒以治疗里寒证的方法。适用于中焦虚寒、亡阳欲脱、寒凝经脉等。分温中散寒和回阳救逆。',NULL,'温法的应用：适应证——中焦虚寒（脘腹冷痛）、亡阳欲脱（冷汗肢冷脉微）、寒凝经脉（关节冷痛）、寒饮内停。分类——温中散寒，适用于脾胃虚寒，方如理中丸；回阳救逆，适用于亡阳欲脱，方如四逆汤；温经散寒，适用于寒凝经脉，方如当归四逆汤。注意事项——热证、阴虚火旺者禁用。',NULL,'中医知识库','治则治法','温里散寒治疗里寒证','2026-04-17 06:30:00.000000',NULL,NULL,'温法；温里散寒；回阳救逆',NULL,NULL,NULL,NULL,'中医基础理论','温法的应用要点是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(454,'清法是通过清热泻火以治疗里热证的方法。适用于热在气分、热入营血、脏腑实热、暑热等。分清热泻火、清热凉血、清热解毒等。',NULL,'清法的应用：适应证——气分热盛（壮热烦渴）、热入营血（斑疹出血）、脏腑实热（心火、肝火、胃火）、暑热、热毒疮痈。分类——清热泻火，方如白虎汤；清热凉血，方如犀角地黄汤；清热燥湿，方如黄连解毒汤；清热解毒，方如五味消毒饮。注意事项——寒证、脾胃虚寒者慎用，中病即止不可过剂。',NULL,'中医知识库','治则治法','清热泻火治疗里热证','2026-04-17 06:30:00.000000',NULL,NULL,'清法；清热泻火；里热证',NULL,NULL,NULL,NULL,'中医基础理论','清法的应用要点是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(455,'消法是通过消导散结以消除有形实邪的方法。适用于食积、虫积、痰饮、瘀血、结石、肿块等。',NULL,'消法的应用：适应证——食积不化、虫积内扰、痰饮停聚、瘀血内结、结石阻滞、痞块积聚。分类——消食导滞，方如保和丸；消痞散结，方如枳实消痞丸；消痰化饮，方如二陈汤；活血化瘀，方如血府逐瘀汤。消法与下法的区别：下法适用于急证实证，以攻逐为主；消法适用于渐积而成的病证，以渐消缓散为主。',NULL,'中医知识库','治则治法','消导散结消除有形实邪','2026-04-17 06:30:00.000000',NULL,NULL,'消法；消导散结；食积痰饮瘀血',NULL,NULL,NULL,NULL,'中医基础理论','消法的应用要点是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(456,'补法是通过补益人体气血阴阳以治疗虚证的方法。适用于气虚、血虚、阴虚、阳虚、五脏虚损等。',NULL,'补法的应用：适应证——气虚、血虚、阴虚、阳虚及各脏腑虚损。分类——补气，方如四君子汤；补血，方如四物汤；补阴，方如六味地黄丸；补阳，方如金匮肾气丸。注意事项——辨别虚损性质和脏腑，对症进补；实邪未去者慎用补法（闭门留寇）；补法应中病即止，过补可致壅滞；注意脾胃运化功能，补而不滞。',NULL,'中医知识库','治则治法','补益气血阴阳治疗虚证','2026-04-17 06:30:00.000000',NULL,NULL,'补法；补益气血阴阳；虚证',NULL,NULL,NULL,NULL,'中医基础理论','补法的应用要点是什么？','中医基础理论',NULL,'理论','治则治法','入门','2026-04-20 23:49:54.000000',NULL,NULL),(457,'八法在临床中常需配合使用，如汗下并用、温清并用、攻补兼施、消补并用等。单一治法难以适应复杂病证，需灵活配合。',NULL,'八法的配合应用：汗下并用——表里同病，既需解表又需攻里，如防风通圣散。温清并用——寒热错杂证，寒热并治，如半夏泻心汤。攻补兼施——虚实夹杂证，祛邪与扶正兼顾，如黄龙汤。消补并用——虚中夹实证，消导与补益兼顾，如健脾丸。八法配合体现了中医辨证论治的灵活性，需根据具体病证灵活运用。',NULL,'中医知识库','治则治法','八法灵活配合应对复杂病证','2026-04-17 06:30:00.000000',NULL,NULL,'八法配合；汗下并用；温清并用；攻补兼施',NULL,NULL,NULL,NULL,'中医基础理论','八法的配合应用有哪些？','中医基础理论',NULL,'理论','治则治法','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(458,'手太阴肺经起于中焦，下络大肠，还循胃口，上膈属肺。沿喉咙，横出腋下，沿上肢内侧前缘下行，过肘窝，入寸口，上鱼际，出大指之端。',NULL,'手太阴肺经起于中焦（胃脘部），向下联络大肠，再回过来沿着胃的上口，穿过膈肌，入属肺脏。从肺系（气管、喉咙）横行出腋下，沿上臂内侧下行，行于手少阴心经和手厥阴心包经的前面，下至肘窝，沿前臂内侧桡侧缘下行，入寸口（桡动脉搏动处），上鱼际，直出拇指桡侧端（少商穴）。分支从腕后列缺穴分出，走向食指桡侧端与手阳明大肠经相交接。',NULL,'中医知识库','手太阴肺经','肺经起于中焦属肺络大肠沿上肢内侧前缘下行','2026-04-17 06:30:00.000000',NULL,NULL,'手太阴肺经；循行路线；起于中焦；属肺络大肠',NULL,NULL,NULL,NULL,'经络学说','手太阴肺经的循行路线是怎样的？','经络学说',NULL,'理论','手太阴肺经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(459,'手太阴肺经主要用于治疗肺系疾患，如咳嗽、气喘、咯血、咽喉肿痛、胸闷胸痛，以及经脉循行部位的其他病证。',NULL,'手太阴肺经主治：一是肺系疾患——咳嗽、气喘、咯血、咽喉肿痛、胸闷胸痛、失音。二是经脉循行部位的病证——肩背痛、手臂内侧前缘痛、手腕痛。三是相关兼症——发热、自汗、皮肤瘙痒等。肺经以治疗呼吸系统疾病为主，是临床常用的经脉之一。',NULL,'中医知识库','手太阴肺经','肺经主治肺系疾患和经脉循行部位病证','2026-04-17 06:30:00.000000',NULL,NULL,'肺经主治；肺系疾患；咳嗽气喘',NULL,NULL,NULL,NULL,'经络学说','手太阴肺经的主治概要是什么？','经络学说',NULL,'理论','手太阴肺经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(460,'中府穴在胸前壁外上方，前正中线旁开6寸，平第1肋间隙处。主治咳嗽、气喘、胸痛、肩背痛。',NULL,'中府穴是手太阴肺经的募穴。定位：胸前壁外上方，前正中线旁开6寸，平第1肋间隙处。取穴方法：正坐或仰卧，在锁骨外端下方，云门穴下约1寸处。主治：咳嗽、气喘、胸痛、胸闷、肩背痛、肺痈。因是肺之募穴，为肺脏之气聚积之处，故为治疗肺脏病证的要穴。针刺向外斜刺0.5~0.8寸，不可深刺以免伤及肺脏。',NULL,'中医知识库','手太阴肺经','中府为肺经募穴主治肺脏病证','2026-04-17 06:30:00.000000',NULL,NULL,'中府穴；定位；主治；肺募穴',NULL,NULL,NULL,NULL,'经络学说','中府穴的定位与主治是什么？','经络学说',NULL,'理论','手太阴肺经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(461,'尺泽穴在肘横纹中，肱二头肌腱桡侧凹陷处。主治咳嗽、气喘、咯血、潮热、咽喉肿痛、急性吐泻、肘臂挛痛。',NULL,'尺泽穴是手太阴肺经的合穴。定位：在肘横纹中，肱二头肌腱桡侧凹陷处。取穴方法：微屈肘，在肘横纹上，肱二头肌腱的桡侧缘。主治：咳嗽、气喘、咯血、潮热、咽喉肿痛、胸部胀满、急性吐泻、小儿惊风、肘臂挛痛、乳痈。本穴为肺经合穴，有清泻肺热、调理肺气的作用。直刺0.8~1.2寸，或点刺出血。',NULL,'中医知识库','手太阴肺经','尺泽为肺经合穴清泻肺热','2026-04-17 06:30:00.000000',NULL,NULL,'尺泽穴；定位；主治；合穴',NULL,NULL,NULL,NULL,'经络学说','尺泽穴的定位与主治是什么？','经络学说',NULL,'理论','手太阴肺经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(462,'列缺穴在前臂桡侧缘，桡骨茎突上方，腕横纹上1.5寸。主治咳嗽、气喘、咽喉肿痛、头痛、项强、牙痛。',NULL,'列缺穴是手太阴肺经的络穴，通任脉，为八脉交会穴之一。定位：在前臂桡侧缘，桡骨茎突上方，腕横纹上1.5寸。简便取穴法：两手虎口交叉，一手食指按在另一手桡骨茎突上，食指尖所指凹陷处即是。主治：咳嗽、气喘、咽喉肿痛、偏正头痛、项强、牙痛、面瘫、腕部疼痛。向上斜刺0.3~0.5寸。',NULL,'中医知识库','手太阴肺经','列缺为肺经络穴通任脉','2026-04-17 06:30:00.000000',NULL,NULL,'列缺穴；定位；主治；络穴；八脉交会穴',NULL,NULL,NULL,NULL,'经络学说','列缺穴的定位与主治是什么？','经络学说',NULL,'理论','手太阴肺经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(463,'太渊穴在腕掌侧横纹桡侧端，桡动脉搏动处。主治咳嗽、气喘、咯血、腕臂痛、无脉症。',NULL,'太渊穴是手太阴肺经的原穴和输穴，也是八会穴之脉会。定位：在腕掌侧横纹桡侧端，桡动脉的桡侧凹陷中。主治：咳嗽、气喘、咯血、咽喉肿痛、胸痹、腕臂痛、无脉症。本穴为肺经原穴，是肺脏原气经过和留止的部位，治疗肺脏病证效果显著。又是脉会，可治疗脉管疾病。避开桡动脉直刺0.3~0.5寸。',NULL,'中医知识库','手太阴肺经','太渊为肺经原穴脉会','2026-04-17 06:30:00.000000',NULL,NULL,'太渊穴；定位；主治；原穴；脉会',NULL,NULL,NULL,NULL,'经络学说','太渊穴的定位与主治是什么？','经络学说',NULL,'理论','手太阴肺经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(464,'少商穴在拇指桡侧指甲角旁约0.1寸处。主治咽喉肿痛、咳嗽、鼻衄、发热、昏迷、癫狂。',NULL,'少商穴是手太阴肺经的井穴。定位：在拇指桡侧指甲角旁约0.1寸处。主治：咽喉肿痛、咳嗽、气喘、鼻衄、发热、中风昏迷、癫狂、中暑呕吐。本穴为肺经井穴，有泻热开窍、清利咽喉的作用，是治疗咽喉肿痛的要穴，也常用于急救。浅刺0.1寸，或点刺出血。三棱针点刺放血效果更佳。',NULL,'中医知识库','手太阴肺经','少商为肺经井穴泻热开窍','2026-04-17 06:30:00.000000',NULL,NULL,'少商穴；定位；主治；井穴',NULL,NULL,NULL,NULL,'经络学说','少商穴的定位与主治是什么？','经络学说',NULL,'理论','手太阴肺经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(465,'肺经病证主要表现为肺胀、胸部满闷、咳嗽、气喘、缺盆中痛，甚则交两手而瞀（心胸闷乱），为臂厥。',NULL,'手太阴肺经病候：是动病——肺胀满、膨胀而喘咳、缺盆中痛，甚则交两手而瞀，此为臂厥。是主肺所生病——咳嗽、上气、喘渴、烦心、胸满、臑臂内前廉痛厥、掌中热。气盛有余——肩背痛风寒，汗出中风，小便数而欠。气虚——肩背痛寒，少气不足以息，溺色变。',NULL,'中医知识库','手太阴肺经','肺经病候以咳喘胸闷为主','2026-04-17 06:30:00.000000',NULL,NULL,'肺经病理；是动病；是主肺所生病',NULL,NULL,NULL,NULL,'经络学说','手太阴肺经的病理表现有哪些？','经络学说',NULL,'理论','手太阴肺经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(466,'手太阴肺经腧穴主治以肺系疾病为主，尤其对咳嗽、气喘、咽喉肿痛等呼吸系统病证有特效。穴性偏于宣肺止咳、清热平喘。',NULL,'手太阴肺经腧穴主治特点：本经腧穴以治疗肺脏及呼吸系统疾病为主。特定穴各有侧重——井穴少商善泻热开窍，荥穴鱼际善清肺热，输穴太渊善补肺气，经穴经渠善宣肺止咳，合穴尺泽善清泻肺热，络穴列缺善祛风解表通任脉。募穴中府善治肺脏本病。临床上根据辨证选取相应穴位。',NULL,'中医知识库','手太阴肺经','肺经穴以治肺系疾病为主','2026-04-17 06:30:00.000000',NULL,NULL,'肺经腧穴主治；特定穴；肺系疾病',NULL,NULL,NULL,NULL,'经络学说','手太阴肺经的腧穴主治特点是什么？','经络学说',NULL,'理论','手太阴肺经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(467,'手太阴肺经属肺络大肠，手阳明大肠经属大肠络肺，两经相互络属，构成表里关系。肺经属阴为里，大肠经属阳为表。',NULL,'肺经与大肠经的表里关系：在脏腑关系上，肺与大肠相表里，肺为脏属里，大肠为腑属表。在经脉络属上，手太阴肺经属肺络大肠，手阳明大肠经属大肠络肺。两经通过经别和别络互相沟通。在生理上，肺的肃降有助于大肠的传导，大肠的传导也有助于肺的肃降。在病理上，肺热可下传大肠致便秘，大肠热也可上传于肺致咳嗽。',NULL,'中医知识库','手太阴肺经','肺经大肠经互为表里相互络属','2026-04-17 06:30:00.000000',NULL,NULL,'肺经大肠经；表里关系；经脉络属',NULL,NULL,NULL,NULL,'经络学说','手太阴肺经与手阳明大肠经的表里关系是怎样的？','经络学说',NULL,'理论','手太阴肺经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(468,'手太阴肺经在临床常用于治疗感冒、咳嗽、哮喘、咽喉炎、扁桃体炎等呼吸系统疾病，以及上肢内侧前缘疼痛等经脉病证。',NULL,'手太阴肺经的临床应用：呼吸系统疾病——感冒取列缺、尺泽；咳嗽取太渊、尺泽、列缺；哮喘取尺泽、列缺、中府；咽喉肿痛取少商、鱼际。经脉病证——手腕痛取太渊、列缺；肘臂痛取尺泽。配穴：肺经穴位常与其他经穴位配合使用，如治疗咳嗽配足三里、膻中；治疗哮喘配肾俞、定喘。针刺时注意避开血管，中府穴不可深刺。',NULL,'中医知识库','手太阴肺经','肺经主治呼吸系统疾病','2026-04-17 06:30:00.000000',NULL,NULL,'肺经临床应用；呼吸系统；配穴',NULL,NULL,NULL,NULL,'经络学说','手太阴肺经的临床应用有哪些？','经络学说',NULL,'理论','手太阴肺经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(469,'手太阴肺经起于胸部，循上肢内侧前缘下行至拇指端。腧穴分布在胸部外上方、上肢内侧前缘和拇指桡侧。',NULL,'手太阴肺经腧穴分部：胸部——中府（前正中线旁开6寸，第1肋间隙）、云门（前正中线旁开6寸，锁骨下窝）。上臂——天府（腋前纹头下3寸）、侠白（天府下1寸）。前臂——尺泽（肘横纹中）、孔最（腕横纹上7寸）、列缺（腕横纹上1.5寸）、经渠（腕横纹上1寸）、太渊（腕横纹桡侧端）。手部——鱼际（第1掌骨中点桡侧）、少商（拇指桡侧指甲角旁），共11穴。',NULL,'中医知识库','手太阴肺经','肺经穴分布在胸外上方和上肢内侧前缘','2026-04-17 06:30:00.000000',NULL,NULL,'肺经腧穴分部；胸部；上肢内侧前缘',NULL,NULL,NULL,NULL,'经络学说','手太阴肺经的腧穴如何分部？','经络学说',NULL,'理论','手太阴肺经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(470,'肺经经脉病候主要表现为咳嗽、气喘、胸部胀满、缺盆中痛、心胸烦闷、上肢内侧前缘厥冷或疼痛、掌心发热等。',NULL,'手太阴肺经脉病候：是动病——肺胀满，膨膨而喘咳，缺盆中痛，甚则交两手而瞀，此为臂厥（经气逆乱所致的手臂厥冷不仁）。是主肺所生病——咳，上气，喘渴，烦心，胸满，臑臂内前廉痛厥，掌中热。气盛有余则肩背痛风寒，汗出中风，小便数而欠；气虚则肩背痛寒，少气不足以息，溺色变。',NULL,'中医知识库','手太阴肺经','肺经病候以肺胀喘咳臂痛为特征','2026-04-17 06:30:00.000000',NULL,NULL,'肺经脉病候；是动病；是主所生病',NULL,NULL,NULL,NULL,'经络学说','手太阴肺经的经脉病候是什么？','经络学说',NULL,'理论','手太阴肺经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(471,'手太阴肺经的络脉从列缺穴分出，走向手阳明大肠经。与手少阴心经并行，散入手鱼际边缘。',NULL,'手太阴肺经的络脉名曰列缺。从腕后上方的列缺穴处分出，走向手阳明大肠经。与手少阴心经的经脉并行，散入鱼际边缘。其病候：实证——手腕部发热；虚证——呵欠频作，小便遗溺。治疗取列缺穴。络脉有沟通表里经、加强经脉之间联系的作用。',NULL,'中医知识库','手太阴肺经','肺经络脉从列缺分出联络大肠经','2026-04-17 06:30:00.000000',NULL,NULL,'肺经络脉；列缺；沟通表里',NULL,NULL,NULL,NULL,'经络学说','手太阴肺经的络脉是怎样的？','经络学说',NULL,'理论','手太阴肺经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(472,'手太阴肺经的经别从腋上出于缺盆，循喉咙，复合于阳明。经别加强了肺经与大肠经之间的联系。',NULL,'手太阴肺经的经别从肺经分出后，走向腋下，出于缺盆（锁骨上窝），沿喉咙，再与手阳明大肠经的经别会合。经别是十二经脉别行深入体腔的支脉，加强了表里两经在体内的联系，扩大了经穴的主治范围。肺经经别的分布特点使其穴位可以治疗喉咙、缺盆等部位的病证。',NULL,'中医知识库','手太阴肺经','肺经经别加强表里经联系','2026-04-17 06:30:00.000000',NULL,NULL,'肺经经别；表里经联系；扩大主治',NULL,NULL,NULL,NULL,'经络学说','手太阴肺经的经别是怎样的？','经络学说',NULL,'理论','手太阴肺经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(473,'手阳明大肠经起于食指末端（商阳穴），沿食指桡侧上行，经过合谷，沿前臂外侧前缘上行，经肘外侧，沿上臂外侧前缘上肩，出肩峰前缘，上出于颈椎（大椎），下入缺盆，络肺，下膈，属大肠。',NULL,'手阳明大肠经起于食指桡侧端商阳穴，沿食指桡侧上行，经过第一、二掌骨间（合谷），沿前臂桡侧上行，经肘外侧（曲池），沿上臂外侧前缘上肩，出肩峰前缘（肩髃），向后交会于大椎穴，向下入缺盆，络肺，穿过膈肌，入属大肠。缺盆部支脉上行颈部，贯穿面颊，进入下齿龈，回出挟口唇，交会于人中（水沟），左脉向右，右脉向左，上行夹鼻孔旁（迎香穴），与足阳明胃经交接。',NULL,'中医知识库','手阳明大肠经','大肠经起于食指沿上肢外侧前缘上行至面','2026-04-17 06:30:00.000000',NULL,NULL,'手阳明大肠经；循行路线；食指端；属大肠络肺',NULL,NULL,NULL,NULL,'经络学说','手阳明大肠经的循行路线是怎样的？','经络学说',NULL,'理论','手阳明大肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(474,'手阳明大肠经主治头面五官病证（牙痛、面瘫、咽喉肿痛）、胃肠病证（腹痛、便秘、泄泻）、热病及经脉循行部位病证。',NULL,'手阳明大肠经主治概要：一是头面五官病证——牙痛、面瘫、面颊肿痛、咽喉肿痛、目赤肿痛、鼻衄、鼻塞不通。二是胃肠病证——腹痛、腹胀、便秘、泄泻、痢疾。三是热病——发热、风疹。四是经脉循行部位病证——肩臂痛、手指麻木、上肢不遂。大肠经穴位中以合谷、曲池、迎香临床应用最为广泛。',NULL,'中医知识库','手阳明大肠经','大肠经主治头面五官和胃肠病证','2026-04-17 06:30:00.000000',NULL,NULL,'大肠经主治；头面五官；胃肠病',NULL,NULL,NULL,NULL,'经络学说','手阳明大肠经的主治概要是什么？','经络学说',NULL,'理论','手阳明大肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(475,'合谷穴在手背，第1、2掌骨间，当第2掌骨桡侧的中点处。主治头痛、牙痛、面瘫、发热、咽喉肿痛，有\"面口合谷收\"之说。',NULL,'合谷穴是手阳明大肠经的原穴，别名虎口。定位：在手背，第1、2掌骨间，当第2掌骨桡侧的中点处。简便取穴：以一手的拇指指骨关节横纹，放在另一手拇、食指之间的指蹼缘上，当拇指尖下是穴。主治：头痛、牙痛、面瘫、面肿、发热恶寒、咽喉肿痛、目赤肿痛、鼻衄、耳聋、痄腮、口噤不开、滞产、闭经。为临床最常用穴位之一，有\"面口合谷收\"之称。直刺0.5~1寸。孕妇禁针。',NULL,'中医知识库','手阳明大肠经','合谷为大肠经原穴主治头面疾病','2026-04-17 06:30:00.000000',NULL,NULL,'合谷穴；定位；主治；原穴；面口合谷收',NULL,NULL,NULL,NULL,'经络学说','合谷穴的定位与主治是什么？','经络学说',NULL,'理论','手阳明大肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(476,'曲池穴在肘横纹外侧端，屈肘当尺泽与肱骨外上髁连线的中点处。主治发热、咽喉肿痛、上肢不遂、荨麻疹、高血压。',NULL,'曲池穴是手阳明大肠经的合穴。定位：在肘横纹外侧端，屈肘时当尺泽与肱骨外上髁连线的中点处。主治：发热、咽喉肿痛、牙痛、目赤肿痛、上肢不遂、手臂肿痛、肘关节疼痛、荨麻疹、湿疹、皮肤瘙痒、腹痛吐泻、痢疾、高血压。本穴为大肠经合穴，有疏风解表、清热利湿、调和气血的作用。直刺1~1.5寸。',NULL,'中医知识库','手阳明大肠经','曲池为大肠经合穴疏风清热','2026-04-17 06:30:00.000000',NULL,NULL,'曲池穴；定位；主治；合穴',NULL,NULL,NULL,NULL,'经络学说','曲池穴的定位与主治是什么？','经络学说',NULL,'理论','手阳明大肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(477,'迎香穴在鼻翼外缘中点旁开约0.5寸，当鼻唇沟中。主治鼻塞、鼻衄、口歪、面痒、胆道蛔虫症。',NULL,'迎香穴是手阳明大肠经的末端穴位。定位：在鼻翼外缘中点旁开约0.5寸，当鼻唇沟中。主治：鼻塞不通、鼻衄、鼻渊（鼻窦炎）、口眼歪斜、面痒、面肿、胆道蛔虫症。本穴位于鼻旁，是治疗鼻部疾病的要穴，\"迎香\"意为迎接香气，善通鼻窍。斜刺或平刺0.3~0.5寸，不宜灸。',NULL,'中医知识库','手阳明大肠经','迎香为治鼻病要穴','2026-04-17 06:30:00.000000',NULL,NULL,'迎香穴；定位；主治；鼻部疾病',NULL,NULL,NULL,NULL,'经络学说','迎香穴的定位与主治是什么？','经络学说',NULL,'理论','手阳明大肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(478,'肩髃穴在肩部，三角肌上，臂外展或向前平伸时，当肩峰前下方凹陷处。主治肩臂疼痛、上肢不遂、肩周炎。',NULL,'肩髃穴是手阳明大肠经与阳跷脉的交会穴。定位：在肩部，三角肌上，臂外展或向前平伸时，当肩峰前下方凹陷处。主治：肩臂疼痛、肩关节活动障碍、上肢不遂、肩周炎、风疹、瘰疬。本穴为治疗肩臂疾病的常用穴，也是上肢疾病局部取穴的首选穴之一。直刺或向下斜刺0.8~1.5寸。',NULL,'中医知识库','手阳明大肠经','肩髃为治肩臂病要穴','2026-04-17 06:30:00.000000',NULL,NULL,'肩髃穴；定位；主治；肩臂疾病',NULL,NULL,NULL,NULL,'经络学说','肩髃穴的定位与主治是什么？','经络学说',NULL,'理论','手阳明大肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(479,'偏历穴在前臂背面桡侧，当阳溪与曲池连线上，腕横纹上3寸。主治鼻衄、目赤、耳聋、水肿、手臂酸痛。',NULL,'偏历穴是手阳明大肠经的络穴。定位：在前臂背面桡侧，当阳溪与曲池连线上，腕横纹上3寸。主治：鼻衄、目赤、耳聋、耳鸣、口眼歪斜、喉痹、水肿、手臂酸痛。本穴为大肠经络穴，沟通大肠经与肺经的表里关系，故可治疗肺经和大肠经两经的病证。直刺或斜刺0.5~0.8寸。',NULL,'中医知识库','手阳明大肠经','偏历为大肠经络穴沟通肺经','2026-04-17 06:30:00.000000',NULL,NULL,'偏历穴；定位；主治；络穴',NULL,NULL,NULL,NULL,'经络学说','偏历穴的定位与主治是什么？','经络学说',NULL,'理论','手阳明大肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(480,'温溜穴在前臂背面桡侧，当阳溪与曲池连线上，腕横纹上5寸。主治头痛、面肿、咽喉肿痛、肩臂酸痛、肠鸣腹痛。',NULL,'温溜穴是手阳明大肠经的郄穴。定位：在前臂背面桡侧，当阳溪与曲池连线上，腕横纹上5寸。主治：头痛、面肿、咽喉肿痛、口舌肿痛、肩臂酸痛、肠鸣腹痛、疔疮。本穴为大肠经郄穴，郄穴是经气深聚之处，多用于治疗本经急性病证。直刺0.5~0.8寸。',NULL,'中医知识库','手阳明大肠经','温溜为大肠经郄穴主治急性病证','2026-04-17 06:30:00.000000',NULL,NULL,'温溜穴；定位；主治；郄穴',NULL,NULL,NULL,NULL,'经络学说','温溜穴的定位与主治是什么？','经络学说',NULL,'理论','手阳明大肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(481,'大肠经病证主要表现为牙痛、颈肿、咽喉肿痛、鼻塞鼻衄、口干、目黄、肩臂疼痛、食指不用等。',NULL,'手阳明大肠经病候：是动病——齿痛，颈肿。是主津所生病——目黄，口干，鼻衄，喉痹，肩前臑痛，大指次指痛不用。气有余则当脉所过者热肿，虚则寒栗不复。大肠经病理主要反映在经脉循行部位（头面、上肢外侧前缘）和津液代谢方面。临床常见牙痛、面瘫、肩臂痛、便秘等。',NULL,'中医知识库','手阳明大肠经','大肠经病候以齿痛颈肿肩臂痛为主','2026-04-17 06:30:00.000000',NULL,NULL,'大肠经病理；是动病；是主津所生病',NULL,NULL,NULL,NULL,'经络学说','手阳明大肠经的病理表现有哪些？','经络学说',NULL,'理论','手阳明大肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(482,'手阳明大肠经腧穴以治疗头面五官病证为特色，尤其对面部疾病、牙痛有特效。穴性偏于疏风清热、通经活络。',NULL,'手阳明大肠经腧穴主治特点：以治疗头面五官疾病为特色。特定穴各有侧重——井穴商阳善泻热开窍，荥穴二间善清热，输穴三间善泄热，原穴合谷善疏风解表止痛，经穴阳溪善清泻热邪，合穴曲池善疏风清热调和气血。络穴偏历善利水消肿。临床选穴应根据具体病证辨证取穴。',NULL,'中医知识库','手阳明大肠经','大肠经穴以治头面五官为特色','2026-04-17 06:30:00.000000',NULL,NULL,'大肠经腧穴主治；头面五官；疏风清热',NULL,NULL,NULL,NULL,'经络学说','手阳明大肠经的腧穴主治特点是什么？','经络学说',NULL,'理论','手阳明大肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(483,'手阳明大肠经属大肠络肺，手太阴肺经属肺络大肠，两经相互络属构成表里关系。大肠经属阳为表，肺经属阴为里。',NULL,'大肠经与肺经的表里关系：大肠经属阳为表，肺经属阴为里。手阳明大肠经属大肠络肺，手太阴肺经属肺络大肠。两经通过络脉互相沟通。在生理上，肺的肃降有助于大肠的传导排泄，大肠传导通畅有助于肺气肃降。在病理上互相影响，如肺热可下移大肠致便秘；便秘也可导致肺气上逆致咳嗽。治疗时常表里经配合取穴。',NULL,'中医知识库','手阳明大肠经','大肠经肺经互为表里病理互传','2026-04-17 06:30:00.000000',NULL,NULL,'大肠经肺经；表里关系；互相影响',NULL,NULL,NULL,NULL,'经络学说','手阳明大肠经与手太阴肺经的表里关系是怎样的？','经络学说',NULL,'理论','手阳明大肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(484,'手阳明大肠经临床常用于治疗面瘫、牙痛、咽喉肿痛、感冒发热、荨麻疹、肩周炎、上肢麻木等病证。',NULL,'手阳明大肠经临床应用：头面疾病——面瘫取合谷、迎香；牙痛取合谷、曲池；咽喉肿痛取商阳、曲池。胃肠疾病——便秘取合谷、曲池；腹泻取合谷配足三里。皮肤病——荨麻疹取曲池、合谷；湿疹取曲池配血海。上肢病——肩周炎取肩髃、曲池。感冒发热——合谷、曲池。临床常配合肺经、胃经穴位使用。',NULL,'中医知识库','手阳明大肠经','大肠经临床应用广泛以头面为主','2026-04-17 06:30:00.000000',NULL,NULL,'大肠经临床应用；面瘫；牙痛；皮肤病',NULL,NULL,NULL,NULL,'经络学说','手阳明大肠经的临床应用有哪些？','经络学说',NULL,'理论','手阳明大肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(485,'手阳明大肠经腧穴分布在食指桡侧、上肢外侧前缘、肩部和颈部、面部。自下而上共20穴。',NULL,'手阳明大肠经腧穴分部：手部——商阳（食指桡侧指甲角旁）、二间、三间、合谷（第1、2掌骨间）。前臂——阳溪（腕背横纹桡侧端）、偏历、温溜、下廉、上廉、手三里、曲池（肘横纹外侧端）。上臂——肘髎、手五里、臂臑。肩部——肩髃、巨骨。颈部——天鼎、扶突。面部——禾髎、迎香（鼻翼外缘中点旁），共20穴。',NULL,'中医知识库','手阳明大肠经','大肠经穴从食指至面部分布','2026-04-17 06:30:00.000000',NULL,NULL,'大肠经腧穴分部；食指至上肢外侧前缘至面',NULL,NULL,NULL,NULL,'经络学说','手阳明大肠经的腧穴如何分部？','经络学说',NULL,'理论','手阳明大肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(486,'大肠经脉病候表现为齿痛、颈肿、目黄、口干、鼻衄、喉痹、肩前臑痛、大指次指痛不用。',NULL,'手阳明大肠经脉病候：是动病——齿痛，颈肿。是主津所生病——目黄，口干，鼽衄，喉痹，肩前臑痛，大指次指痛不用。气有余则当脉所过者热肿；虚则寒栗不复。这些病候与经脉循行路线密切相关，大肠经循行经过手指、上肢外侧、肩颈和面部，故这些部位的病变都属大肠经主治范围。',NULL,'中医知识库','手阳明大肠经','大肠经病候与循行部位相关','2026-04-17 06:30:00.000000',NULL,NULL,'大肠经脉病候；齿痛颈肿；经脉循行',NULL,NULL,NULL,NULL,'经络学说','手阳明大肠经的经脉病候是什么？','经络学说',NULL,'理论','手阳明大肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(487,'手阳明大肠经的络脉从偏历穴分出，走向手太阴肺经。向上沿臂，经过肩髃，上行到下颌角，遍布齿龈。',NULL,'手阳明大肠经的络脉名曰偏历。从腕后3寸的偏历穴处分出，走向手太阴肺经。向上沿臂，经肩髃部，上行到下颌角处，遍布于齿龈。其别支走入耳中。病候：实证——齿痛、耳聋；虚证——齿寒、胸膈痹阻。治疗取偏历穴。络脉加强了大肠经与肺经的表里联系。',NULL,'中医知识库','手阳明大肠经','大肠经络脉从偏历分出沟通肺经','2026-04-17 06:30:00.000000',NULL,NULL,'大肠经络脉；偏历；沟通表里',NULL,NULL,NULL,NULL,'经络学说','手阳明大肠经的络脉是怎样的？','经络学说',NULL,'理论','手阳明大肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(488,'足阳明胃经起于鼻翼旁（迎香穴），挟鼻上行，交会于鼻根，旁行入目内眦，向下沿鼻外入上齿龈，回出环绕口唇，交承浆，沿下颌骨后下缘到大迎，上行耳前，上头角，交督脉神庭。',NULL,'足阳明胃经起于鼻翼旁迎香穴，挟鼻上行交鼻根，旁入目内眦，向下沿鼻外入上齿龈，复出环绕口唇，交承浆，沿下颌角大迎，上耳前，过客主人，沿发际至额颅。其支脉从大迎前下人迎，沿喉咙入缺盆，下膈属胃络脾。直行者从缺盆下乳内廉，挟脐入气街。支脉从胃口下循腹里，下至气街与前脉会合，下行髀关，抵伏兔，下膝膑，沿胫骨外侧下足背，入中趾内间。支脉从膝下3寸分出，下入中趾外间。支脉从足背分出，入大趾端，交足太阴脾经。',NULL,'中医知识库','足阳明胃经','胃经起于鼻旁下行至足中趾属胃络脾','2026-04-17 06:30:00.000000',NULL,NULL,'足阳明胃经；循行路线；面部至足；属胃络脾',NULL,NULL,NULL,NULL,'经络学说','足阳明胃经的循行路线是怎样的？','经络学说',NULL,'理论','足阳明胃经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(489,'足阳明胃经主治胃肠病证（胃痛、呕吐、腹胀、泄泻）、头面五官病证（牙痛、面瘫、面痛）、神志病、热病及经脉循行部位病证。',NULL,'足阳明胃经主治概要：一是胃肠病证——胃痛、呕吐、腹胀、腹痛、泄泻、便秘、痢疾。二是头面五官病证——头痛、牙痛、面瘫、面痛、面肿、目赤肿痛、鼻疾。三是神志病——癫狂、失眠。四是热病——发热、壮热。五是经脉循行部位病证——胸腹痛、下肢外侧前缘疼痛、膝痛、足背痛。胃经穴位多、分布广、应用范围广泛。',NULL,'中医知识库','足阳明胃经','胃经主治胃肠和头面五官病证','2026-04-17 06:30:00.000000',NULL,NULL,'胃经主治；胃肠病；头面五官',NULL,NULL,NULL,NULL,'经络学说','足阳明胃经的主治概要是什么？','经络学说',NULL,'理论','足阳明胃经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(490,'足三里在小腿前外侧，当犊鼻穴下3寸，距胫骨前缘一横指。主治胃痛、呕吐、腹胀、泄泻、便秘、虚劳、保健要穴。',NULL,'足三里是足阳明胃经的合穴，也是胃的下合穴。定位：在小腿前外侧，当犊鼻穴下3寸，距胫骨前缘一横指（中指）。主治：胃痛、呕吐、噎膈、腹胀、泄泻、便秘、痢疾、疳积、肠鸣、消化不良。此外，本穴有强壮保健作用，为全身强壮要穴，可增强免疫力、抗衰老。治虚劳羸瘦、气虚乏力。还有疏通经络、调和气血的作用。直刺1~2寸，可灸。常灸足三里有防病保健之效。',NULL,'中医知识库','足阳明胃经','足三里为胃经合穴全身强壮要穴','2026-04-17 06:30:00.000000',NULL,NULL,'足三里；定位；主治；合穴；保健要穴',NULL,NULL,NULL,NULL,'经络学说','足三里穴的定位与主治是什么？','经络学说',NULL,'理论','足阳明胃经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(491,'天枢穴在腹部，脐中旁开2寸。主治腹胀、便秘、泄泻、痢疾、痛经、月经不调，为治疗肠胃病的重要穴位。',NULL,'天枢穴是足阳明胃经穴，也是大肠的募穴。定位：在腹部，横平脐中，前正中线旁开2寸。主治：腹痛、腹胀、便秘、泄泻、痢疾、肠鸣、绕脐痛、水肿、痛经、月经不调。本穴为大肠募穴，是治疗肠道疾病的要穴，对各种肠道功能紊乱均有良好调节作用。直刺1~1.5寸，孕妇禁针。',NULL,'中医知识库','足阳明胃经','天枢为大肠募穴主治肠道疾病','2026-04-17 06:30:00.000000',NULL,NULL,'天枢穴；定位；主治；大肠募穴',NULL,NULL,NULL,NULL,'经络学说','天枢穴的定位与主治是什么？','经络学说',NULL,'理论','足阳明胃经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(492,'丰隆穴在小腿前外侧，当外踝尖上8寸，条口外，距胫骨前缘二横指。主治痰多、咳嗽、眩晕、头痛、便秘、下肢痿痹。为化痰要穴。',NULL,'丰隆穴是足阳明胃经的络穴。定位：在小腿前外侧，当外踝尖上8寸，条口穴外侧一横指处。主治：痰多咳嗽、哮喘、眩晕、头痛、咽喉肿痛、便秘、下肢痿痹、癫狂、痫证。本穴为化痰要穴，有健脾化痰、和胃降逆的作用，临床广泛用于治疗各种痰证。直刺1~1.5寸。',NULL,'中医知识库','足阳明胃经','丰隆为胃经络穴化痰要穴','2026-04-17 06:30:00.000000',NULL,NULL,'丰隆穴；定位；主治；络穴；化痰要穴',NULL,NULL,NULL,NULL,'经络学说','丰隆穴的定位与主治是什么？','经络学说',NULL,'理论','足阳明胃经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(493,'犊鼻穴在膝部，髌骨与髌韧带外侧凹陷中，又名外膝眼。主治膝痛、关节屈伸不利、下肢麻痹。',NULL,'犊鼻穴定位：在膝部，髌骨下缘，髌韧带外侧凹陷中，屈膝取穴，又名外膝眼。主治：膝痛、膝关节屈伸不利、下肢麻痹、脚气。本穴位于膝关节前方，是治疗膝关节疾病的局部取穴。常与内膝眼（经外奇穴）配合使用，治疗各种膝关节病变。向后内斜刺0.5~1寸。',NULL,'中医知识库','足阳明胃经','犊鼻主治膝关节疾病','2026-04-17 06:30:00.000000',NULL,NULL,'犊鼻穴；定位；主治；膝关节',NULL,NULL,NULL,NULL,'经络学说','犊鼻穴的定位与主治是什么？','经络学说',NULL,'理论','足阳明胃经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(494,'梁丘穴在大腿前面，当髂前上棘与髌底外侧端的连线上，髌底上2寸。主治胃痛、膝痛、乳腺炎。',NULL,'梁丘穴是足阳明胃经的郄穴。定位：在大腿前面，当髂前上棘与髌底外侧端的连线上，髌底上2寸。主治：急性胃痛、膝肿痛、下肢不遂、乳痈。本穴为胃经郄穴，郄穴善于治疗急性病证，故梁丘穴对急性胃痛有较好的止痛效果。直刺1~1.5寸。',NULL,'中医知识库','足阳明胃经','梁丘为胃经郄穴善治急性胃痛','2026-04-17 06:30:00.000000',NULL,NULL,'梁丘穴；定位；主治；郄穴',NULL,NULL,NULL,NULL,'经络学说','梁丘穴的定位与主治是什么？','经络学说',NULL,'理论','足阳明胃经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(495,'下关穴在面部耳前方，当颧弓与下颌切迹所形成的凹陷中。主治牙痛、下颌关节痛、面瘫、耳聋。',NULL,'下关穴定位：在面部耳前方，当颧弓与下颌切迹所形成的凹陷中。闭口取穴。主治：牙痛、面痛、下颌关节痛、面瘫、口噤不开、耳聋、耳鸣。本穴为治疗下颌关节疾病和牙痛的常用穴。直刺0.5~1寸，注意闭口取穴。',NULL,'中医知识库','足阳明胃经','下关主治下颌关节和牙痛','2026-04-17 06:30:00.000000',NULL,NULL,'下关穴；定位；主治；下颌关节',NULL,NULL,NULL,NULL,'经络学说','下关穴的定位与主治是什么？','经络学说',NULL,'理论','足阳明胃经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(496,'胃经病证表现为洒洒振寒、善呻数欠、颜黑、病至则恶人与火、闻木声则惕然而惊、心欲动、独闭户塞牖而处，甚则欲上高而歌、弃衣而走。',NULL,'足阳明胃经病候：是动病——洒洒振寒，善呻数欠，颜黑，病至则恶人与火，闻木声则惕然而惊，心欲动，独闭户塞牖而处。甚则欲上高而歌，弃衣而走，贲响腹胀，是为骭厥。是主血所生病——狂疟温淫，汗出，鼽衄，口歪，唇胗，颈肿，喉痹，大腹水肿，膝膑肿痛，循膺、乳、气街、股、伏兔、骭外廉、足跗上皆痛，中趾不用。',NULL,'中医知识库','足阳明胃经','胃经病候以胃肠和精神症状为主','2026-04-17 06:30:00.000000',NULL,NULL,'胃经病理；是动病；是主血所生病',NULL,NULL,NULL,NULL,'经络学说','足阳明胃经的病理表现有哪些？','经络学说',NULL,'理论','足阳明胃经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(497,'足阳明胃经腧穴以治疗消化系统疾病和头面疾病为主。穴性偏于健脾和胃、疏通经络。足三里、天枢、丰隆最为常用。',NULL,'足阳明胃经腧穴主治特点：以治疗消化系统疾病为核心。头面部穴位主治头面五官病；胸腹部穴位主治胃肠病；下肢部穴位主治胃肠病、下肢病。特定穴各有侧重——合穴足三里善调理脾胃、强壮保健；络穴丰隆善化痰降逆；郄穴梁丘善止痛；下合穴足三里、上巨虚、下巨虚分别治胃、大肠、小肠病。',NULL,'中医知识库','足阳明胃经','胃经穴以治消化系统疾病为核心','2026-04-17 06:30:00.000000',NULL,NULL,'胃经腧穴主治；消化系统；特定穴',NULL,NULL,NULL,NULL,'经络学说','足阳明胃经的腧穴主治特点是什么？','经络学说',NULL,'理论','足阳明胃经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(498,'足阳明胃经临床用于治疗胃炎、消化不良、面瘫、牙痛、膝关节炎、偏瘫、便秘、泄泻等，足三里为保健要穴。',NULL,'足阳明胃经临床应用：消化系统——胃痛取足三里、梁丘；便秘取天枢、足三里；泄泻取天枢、上巨虚；呕吐取足三里、内庭。头面疾病——面瘫取地仓、颊车、下关；牙痛取下关、颊车、内庭。下肢疾病——膝关节痛取犊鼻、足三里；下肢痿痹取足三里、伏兔。保健——常灸足三里增强体质。',NULL,'中医知识库','足阳明胃经','胃经临床以治胃肠病为主','2026-04-17 06:30:00.000000',NULL,NULL,'胃经临床应用；消化系统；面瘫；保健',NULL,NULL,NULL,NULL,'经络学说','足阳明胃经的临床应用有哪些？','经络学说',NULL,'理论','足阳明胃经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(499,'胃经脉病候表现为洒洒振寒、善呻、颜面发黑、狂躁不安、腹胀、水肿、膝膑肿痛、下肢外侧疼痛等。',NULL,'足阳明胃经脉病候：是动病——洒洒振寒，善呻数欠，颜黑，病至则恶人与火，闻木声则惕然而惊，心欲动，独闭户塞牖而处。甚则欲上高而歌，弃衣而走，贲响腹胀，是为骭厥。是主血所生病——狂，疟，温淫，汗出，鼽衄，口歪，唇胗，颈肿，喉痹，大腹水肿，膝膑肿痛。循膺乳气街股伏兔骭外廉足跗上皆痛，中趾不用。',NULL,'中医知识库','足阳明胃经','胃经病候循经分布涉及全身','2026-04-17 06:30:00.000000',NULL,NULL,'胃经脉病候；骭厥；血所生病',NULL,NULL,NULL,NULL,'经络学说','足阳明胃经的经脉病候是什么？','经络学说',NULL,'理论','足阳明胃经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(500,'足阳明胃经腧穴自头面至足趾，分布在面部、颈部、胸腹、大腿前面、小腿前外侧和足背。共45穴，为十二经中穴位最多的经脉。',NULL,'足阳明胃经腧穴分部：面部——承泣、四白、巨髎、地仓、大迎、颊车、下关、头维。颈部——人迎、水突、气舍。胸腹部——缺盆、气户、库房、屋翳、膺窗、乳中、乳根、不容至气冲共12穴。大腿——髀关、伏兔、阴市、梁丘。小腿——犊鼻、足三里、上巨虚、条口、下巨虚、丰隆、解溪、冲阳、陷谷、内庭、厉兑。共45穴。',NULL,'中医知识库','足阳明胃经','胃经45穴从头面至足分布','2026-04-17 06:30:00.000000',NULL,NULL,'胃经腧穴分部；头面至足；45穴',NULL,NULL,NULL,NULL,'经络学说','足阳明胃经的腧穴如何分部？','经络学说',NULL,'理论','足阳明胃经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(501,'足阳明胃经的络脉从丰隆穴分出，走向足太阴脾经。向上沿着胫骨外缘，上行络于头项，合诸经之气，下络喉嗌。',NULL,'足阳明胃经的络脉名曰丰隆。从外踝上8寸的丰隆穴处分出，走向足太阴脾经。向上沿着胫骨外缘，上行络于头顶部，会合各经脉气，向下络于喉咽。病候：实证——癫狂、足胫部肌肉拘挛；虚证——足胫部肌肉松弛无力。治疗取丰隆穴。',NULL,'中医知识库','足阳明胃经','胃经络脉从丰隆分出沟通脾经','2026-04-17 06:30:00.000000',NULL,NULL,'胃经络脉；丰隆；沟通脾经',NULL,NULL,NULL,NULL,'经络学说','足阳明胃经的络脉是怎样的？','经络学说',NULL,'理论','足阳明胃经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(502,'足阳明胃经属胃络脾，足太阴脾经属脾络胃，两经相互络属构成表里关系。胃经属阳为表，脾经属阴为里。',NULL,'胃经与脾经的表里关系：胃经属阳为表，脾经属阴为里。足阳明胃经属胃络脾，足太阴脾经属脾络胃。在生理上，胃主受纳腐熟，脾主运化，共同完成消化吸收。脾升胃降，共同维持气机升降。在病理上互相影响，如胃热可伤脾阴，脾虚可致胃弱。治疗时常表里经配穴，如足三里配三阴交。',NULL,'中医知识库','足阳明胃经','胃经脾经互为表里脾升胃降','2026-04-17 06:30:00.000000',NULL,NULL,'胃经脾经；表里关系；脾升胃降',NULL,NULL,NULL,NULL,'经络学说','足阳明胃经与足太阴脾经的表里关系是怎样的？','经络学说',NULL,'理论','足阳明胃经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(503,'足太阴脾经起于足大趾端（隐白穴），沿足大趾内侧赤白肉际上行，经内踝前，沿小腿内侧中线上行，交出足厥阴肝经之前，上膝股内侧前缘，入腹属脾络胃，上膈挟咽，连舌本，散舌下。',NULL,'足太阴脾经起于足大趾端隐白穴，沿大趾内侧赤白肉际，经第一跖趾关节后面，上行至内踝前面，再上小腿内侧，沿胫骨后缘上行，交出足厥阴肝经之前，经膝股内侧前缘入腹部，入属脾脏，联络胃腑，向上穿过膈肌，沿食管两旁上行，挟咽部，连舌根，散布舌下。胃部支脉再从胃分出，上行通过膈肌，注入心中，与手少阴心经交接。',NULL,'中医知识库','足太阴脾经','脾经起于大趾沿下肢内侧上行属脾络胃','2026-04-17 06:30:00.000000',NULL,NULL,'足太阴脾经；循行路线；大趾端；属脾络胃',NULL,NULL,NULL,NULL,'经络学说','足太阴脾经的循行路线是怎样的？','经络学说',NULL,'理论','足太阴脾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(504,'足太阴脾经主治脾胃病证（胃痛、腹胀、便溏、呕吐）、妇科病证（月经不调、痛经、带下）和经脉循行部位病证。',NULL,'足太阴脾经主治概要：一是脾胃病证——胃痛、腹胀、食欲不振、便溏、泄泻、呕吐、黄疸。二是妇科病证——月经不调、痛经、闭经、带下、阴挺、不孕。三是前阴病证——遗尿、尿失禁、小便不利。四是经脉循行部位病证——下肢内侧疼痛、膝股内侧痛。脾经穴位以三阴交、血海、阴陵泉、太白最为常用。',NULL,'中医知识库','足太阴脾经','脾经主治脾胃和妇科病证','2026-04-17 06:30:00.000000',NULL,NULL,'脾经主治；脾胃病；妇科病',NULL,NULL,NULL,NULL,'经络学说','足太阴脾经的主治概要是什么？','经络学说',NULL,'理论','足太阴脾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(505,'三阴交在小腿内侧，当内踝尖上3寸，胫骨内侧缘后方。主治月经不调、痛经、带下、遗精、失眠、消化不良，为肝脾肾三经交会穴。',NULL,'三阴交是足太阴脾经穴，为足三阴经（肝、脾、肾）交会穴。定位：在小腿内侧，当内踝尖上3寸，胫骨内侧缘后方。主治：月经不调、痛经、闭经、带下、阴挺、产后血晕、遗精、阳痿、遗尿、小便不利、失眠、眩晕、消化不良、腹胀、泄泻、下肢痿痹。本穴为妇科要穴和保健要穴，临床应用极为广泛。直刺1~1.5寸。孕妇禁针。',NULL,'中医知识库','足太阴脾经','三阴交为足三阴经交会妇科要穴','2026-04-17 06:30:00.000000',NULL,NULL,'三阴交；定位；主治；足三阴交会穴',NULL,NULL,NULL,NULL,'经络学说','三阴交穴的定位与主治是什么？','经络学说',NULL,'理论','足太阴脾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(506,'血海穴在大腿内侧，髌底内侧端上2寸，当股四头肌内侧头的隆起处。主治月经不调、痛经、荨麻疹、湿疹，为治疗血证的要穴。',NULL,'血海穴定位：在大腿内侧，髌底内侧端上2寸，当股四头肌内侧头的隆起处。简便取穴：患者屈膝，医者以左手掌心按于患者右膝髌骨上缘，二至五指向上伸直，拇指约呈45度斜置，拇指尖下是穴。主治：月经不调、痛经、经闭、崩漏、荨麻疹、湿疹、皮肤瘙痒、丹毒、股内侧痛。本穴有理血调经、疏风止痒的作用，是治疗血分病证和皮肤病的要穴。直刺1~1.5寸。',NULL,'中医知识库','足太阴脾经','血海为理血调经疏风止痒要穴','2026-04-17 06:30:00.000000',NULL,NULL,'血海穴；定位；主治；理血要穴',NULL,NULL,NULL,NULL,'经络学说','血海穴的定位与主治是什么？','经络学说',NULL,'理论','足太阴脾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(507,'阴陵泉在小腿内侧，当胫骨内侧髁后下方凹陷处。主治腹胀、泄泻、水肿、小便不利、膝痛，为利湿要穴。',NULL,'阴陵泉穴是足太阴脾经的合穴。定位：在小腿内侧，当胫骨内侧髁后下方凹陷处。主治：腹胀、泄泻、水肿、小便不利或失禁、黄疸、膝痛。本穴为利湿要穴，有健脾利湿、通利小便的作用。临床常配足三里治腹胀，配水分、水道治水肿。直刺1~2寸。',NULL,'中医知识库','足太阴脾经','阴陵泉为脾经合穴利湿要穴','2026-04-17 06:30:00.000000',NULL,NULL,'阴陵泉；定位；主治；合穴；利湿要穴',NULL,NULL,NULL,NULL,'经络学说','阴陵泉穴的定位与主治是什么？','经络学说',NULL,'理论','足太阴脾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(508,'太白穴在足内侧缘，当第1跖趾关节后下方赤白肉际凹陷处。主治胃痛、腹胀、肠鸣、泄泻、便秘，为脾经原穴。',NULL,'太白穴是足太阴脾经的输穴和原穴。定位：在足内侧缘，当第一跖趾关节后下方赤白肉际凹陷处。主治：胃痛、腹胀、肠鸣、泄泻、便秘、痔漏、脚气、体重节痛。本穴为脾经原穴，是脾脏原气留止之处，治疗脾脏本病效果显著，有健脾化湿、理气和胃的作用。直刺0.5~0.8寸。',NULL,'中医知识库','足太阴脾经','太白为脾经原穴健脾化湿','2026-04-17 06:30:00.000000',NULL,NULL,'太白穴；定位；主治；原穴',NULL,NULL,NULL,NULL,'经络学说','太白穴的定位与主治是什么？','经络学说',NULL,'理论','足太阴脾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(509,'脾经病证表现为舌本强、食则呕、胃脘痛、腹胀善噫、身体皆重、股膝内肿厥、足大趾不用。',NULL,'足太阴脾经病候：是动病——舌本强，食则呕，胃脘痛，腹胀善噫，得后与气则快然如衰，身体皆重。是主脾所生病——舌本痛，体不能动摇，食不下，烦心，心下急痛，溏瘕泄，水闭，黄疸，不能卧，强立股膝内肿厥，足大趾不用。脾经病候以消化系统症状和经脉循行部位症状为主。',NULL,'中医知识库','足太阴脾经','脾经病候以消化和水湿症状为主','2026-04-17 06:30:00.000000',NULL,NULL,'脾经病理；是动病；是主脾所生病',NULL,NULL,NULL,NULL,'经络学说','足太阴脾经的病理表现有哪些？','经络学说',NULL,'理论','足太阴脾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(510,'足太阴脾经腧穴以治疗脾胃病和妇科病为主。穴性偏于健脾益气、化湿利水、调经统血。',NULL,'足太阴脾经腧穴主治特点：以治疗脾脏病和消化系统疾病为主，妇科病证为特色。特定穴各有侧重——输穴太白善健脾化湿；合穴阴陵泉善利湿消肿；三阴交善调妇科病；血海善理血调经。脾经穴位大多有健脾益气的作用，又因脾主统血、主运化水湿，故脾经穴还善治血证和水湿病证。',NULL,'中医知识库','足太阴脾经','脾经穴以治脾胃妇科为特色','2026-04-17 06:30:00.000000',NULL,NULL,'脾经腧穴主治；健脾益气；调经统血',NULL,NULL,NULL,NULL,'经络学说','足太阴脾经的腧穴主治特点是什么？','经络学说',NULL,'理论','足太阴脾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(511,'足太阴脾经临床用于治疗消化不良、腹胀泄泻、月经不调、痛经、水肿、荨麻疹、下肢内侧痛等病证。',NULL,'足太阴脾经临床应用：消化系统——腹胀泄泻取太白、阴陵泉、三阴交；食欲不振取太白、公孙。妇科疾病——月经不调取三阴交、血海；痛经取三阴交、血海、地机；带下取三阴交。皮肤病——荨麻疹取血海、三阴交；湿疹取血海配曲池。水肿——阴陵泉配水分。脾经与胃经常配合使用，增强疗效。',NULL,'中医知识库','足太阴脾经','脾经临床治消化妇科皮肤病','2026-04-17 06:30:00.000000',NULL,NULL,'脾经临床应用；消化；妇科；皮肤',NULL,NULL,NULL,NULL,'经络学说','足太阴脾经的临床应用有哪些？','经络学说',NULL,'理论','足太阴脾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(512,'脾经脉病候表现为舌体强硬、食后呕吐、胃脘疼痛、腹胀善噫、身体沉重、股膝内侧肿胀厥冷、足大趾活动不利。',NULL,'足太阴脾经脉病候：是动病——舌本强，食则呕，胃脘痛，腹胀善噫，得后与气则快然如衰，身体皆重。是主脾所生病——舌本痛，体不能动摇，食不下，烦心，心下急痛，溏、瘕、泄，水闭，黄疸，不能卧，强立股膝内肿厥，足大趾不用。脾经病候与脾主运化、主四肢肌肉的功能密切相关。',NULL,'中医知识库','足太阴脾经','脾经病候反映运化和四肢功能','2026-04-17 06:30:00.000000',NULL,NULL,'脾经脉病候；舌本强；胃脘痛；身体沉重',NULL,NULL,NULL,NULL,'经络学说','足太阴脾经的经脉病候是什么？','经络学说',NULL,'理论','足太阴脾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(513,'足太阴脾经属脾络胃，足阳明胃经属胃络脾，两经互为表里。脾为脏属阴为里，胃为腑属阳为表。',NULL,'脾经与胃经的表里关系：脾经属阴为里，胃经属阳为表。足太阴脾经属脾络胃，足阳明胃经属胃络脾。生理上脾主运化、胃主受纳，脾升胃降，共同完成消化吸收。病理上脾虚可影响胃的受纳，胃弱也可影响脾的运化。治疗上脾经穴与胃经穴常配合使用，如足三里配三阴交，调理脾胃功能。',NULL,'中医知识库','足太阴脾经','脾经胃经互为表里脾升胃降','2026-04-17 06:30:00.000000',NULL,NULL,'脾经胃经；表里关系；脾升胃降',NULL,NULL,NULL,NULL,'经络学说','足太阴脾经与足阳明胃经的表里关系是怎样的？','经络学说',NULL,'理论','足太阴脾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(514,'足太阴脾经腧穴分布在足大趾内侧、内踝前、小腿内侧、大腿内侧前缘、腹部和胸部。共21穴。',NULL,'足太阴脾经腧穴分部：足部——隐白（大趾内侧）、大都、太白、公孙、商丘。小腿——三阴交、漏谷、地机、阴陵泉。大腿——血海、箕门。腹部——冲门、府舍、腹结、大横、腹哀。胸部——食窦、天溪、胸乡、周荣、大包。共21穴。',NULL,'中医知识库','足太阴脾经','脾经21穴从大趾至胸部分布','2026-04-17 06:30:00.000000',NULL,NULL,'脾经腧穴分部；大趾至胸；21穴',NULL,NULL,NULL,NULL,'经络学说','足太阴脾经的腧穴如何分部？','经络学说',NULL,'理论','足太阴脾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(515,'足太阴脾经的络脉从公孙穴分出，走向足阳明胃经。入络肠胃。',NULL,'足太阴脾经的络脉名曰公孙。从足大趾本节后1寸的公孙穴处分出，走向足阳明胃经。另有一支入络肠胃。病候：实证——腹中绞痛；虚证——腹胀。治疗取公孙穴。公孙为八脉交会穴，通冲脉。',NULL,'中医知识库','足太阴脾经','脾经络脉从公孙分出通冲脉','2026-04-17 06:30:00.000000',NULL,NULL,'脾经络脉；公孙；沟通胃经',NULL,NULL,NULL,NULL,'经络学说','足太阴脾经的络脉是怎样的？','经络学说',NULL,'理论','足太阴脾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(516,'足太阴脾经的经筋起于大趾端内侧，上行结于内踝，沿小腿内侧上行结于膝内辅骨，沿大腿内侧上行结于髀，聚于阴器，上腹结于脐。',NULL,'足太阴脾经的经筋起于足大趾端内侧，上结于内踝，沿小腿内侧上行结于胫骨内髁，沿大腿内侧上行结于髀部，聚于阴器，上行腹部结于脐，上行腹结于胁肋，散于胸中，其内者着于脊。经筋病候主要表现为循行部位的筋脉拘挛和疼痛。',NULL,'中医知识库','足太阴脾经','脾经经筋从大趾至腹部脊柱','2026-04-17 06:30:00.000000',NULL,NULL,'脾经经筋；大趾至腹；筋脉拘挛',NULL,NULL,NULL,NULL,'经络学说','足太阴脾经的经筋是怎样的？','经络学说',NULL,'理论','足太阴脾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(517,'公孙穴在足内侧缘，当第1跖骨基底前下方。主治胃痛、呕吐、腹痛、泄泻、痢疾，为八脉交会穴通冲脉。',NULL,'公孙穴是足太阴脾经的络穴，也是八脉交会穴通冲脉。定位：在足内侧缘，当第一跖骨基底前下方。主治：胃痛、呕吐、腹痛、腹胀、泄泻、痢疾、心烦失眠。本穴为脾经络穴，沟通脾经与胃经的表里关系；又是八脉交会穴通冲脉，与内关穴配合可治疗胃心胸疾病。直刺0.5~0.8寸。',NULL,'中医知识库','足太阴脾经','公孙为脾经络穴通冲脉治胃病','2026-04-17 06:30:00.000000',NULL,NULL,'公孙穴；定位；主治；络穴；八脉交会穴',NULL,NULL,NULL,NULL,'经络学说','公孙穴的定位与主治是什么？','经络学说',NULL,'理论','足太阴脾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(518,'手少阴心经起于心中，出属心系，下膈络小肠。其支脉从心系上挟咽，系目系。直行者从心系上肺，出腋下，沿上肢内侧后缘下行，经肘内，达腕，入掌内后缘，出小指桡侧端。',NULL,'手少阴心经起于心中，出属心系（心与其他脏器联系的脉络），下穿膈肌，联络小肠。支脉从心系上行挟咽喉，联系目系（眼球与脑相连的脉络）。直行者从心系上行至肺，横出腋窝极泉穴，沿上臂内侧后缘下行，经肘内侧少海穴，沿前臂内侧后缘下行，过腕部神门穴，入掌内，沿小指桡侧至末端少冲穴，与手太阳小肠经交接。',NULL,'中医知识库','手少阴心经','心经起于心中沿上肢内侧后缘至小指','2026-04-17 06:30:00.000000',NULL,NULL,'手少阴心经；循行路线；起于心中；属心络小肠',NULL,NULL,NULL,NULL,'经络学说','手少阴心经的循行路线是怎样的？','经络学说',NULL,'理论','手少阴心经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(519,'手少阴心经主治心病（心悸、失眠、健忘、癫狂）、胸胁痛、咽喉痛及经脉循行部位病证。',NULL,'手少阴心经主治概要：一是心胸病证——心悸、心痛、胸闷、失眠、健忘、癫狂、痫证。二是经脉循行部位病证——肘臂挛痛、手掌热痛、小指不用。三是相关兼症——咽喉干燥、目黄、渴欲饮水。心经穴位以神门最为常用，为治疗失眠、心悸的要穴。',NULL,'中医知识库','手少阴心经','心经主治心病和神志病','2026-04-17 06:30:00.000000',NULL,NULL,'心经主治；心病；失眠心悸',NULL,NULL,NULL,NULL,'经络学说','手少阴心经的主治概要是什么？','经络学说',NULL,'理论','手少阴心经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(520,'神门穴在腕部，腕掌侧横纹尺侧端，尺侧腕屈肌腱的桡侧凹陷处。主治失眠、心悸、癫狂、健忘、心痛，为治疗神志病的要穴。',NULL,'神门穴是手少阴心经的输穴和原穴。定位：在腕部，腕掌侧横纹尺侧端，尺侧腕屈肌腱的桡侧凹陷处。主治：失眠、健忘、心悸、怔忡、癫狂、痫证、心痛、心烦、痴呆、掌中热。本穴为心经原穴，有宁心安神的作用，是治疗失眠、心悸等神志疾病的要穴。直刺0.3~0.5寸。',NULL,'中医知识库','手少阴心经','神门为心经原穴安神要穴','2026-04-17 06:30:00.000000',NULL,NULL,'神门穴；定位；主治；原穴；安神要穴',NULL,NULL,NULL,NULL,'经络学说','神门穴的定位与主治是什么？','经络学说',NULL,'理论','手少阴心经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(521,'少海穴在肘横纹内侧端，屈肘当尺泽与肱骨内上髁连线的中点处。主治心痛、肘臂挛痛、腋胁痛、瘰疬。',NULL,'少海穴是手少阴心经的合穴。定位：在肘横纹内侧端，与肱骨内上髁连线的中点处，屈肘取穴。主治：心痛、肘臂挛痛、手臂麻木、腋胁痛、头项痛、瘰疬。本穴有宁心安神、疏通经络的作用。直刺0.5~1寸。',NULL,'中医知识库','手少阴心经','少海为心经合穴宁心安神','2026-04-17 06:30:00.000000',NULL,NULL,'少海穴；定位；主治；合穴',NULL,NULL,NULL,NULL,'经络学说','少海穴的定位与主治是什么？','经络学说',NULL,'理论','手少阴心经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(522,'通里穴在前臂掌侧，当尺侧腕屈肌腱的桡侧缘，腕横纹上1寸。主治心悸、暴喑、舌强不语、腕臂痛。',NULL,'通里穴是手少阴心经的络穴。定位：在前臂掌侧，当尺侧腕屈肌腱的桡侧缘，腕横纹上1寸。主治：心悸、怔忡、暴喑（突然失语）、舌强不语、腕臂痛。本穴为心经络穴，沟通心经与小肠经的表里关系。直刺0.3~0.5寸。',NULL,'中医知识库','手少阴心经','通里为心经络穴善治失语','2026-04-17 06:30:00.000000',NULL,NULL,'通里穴；定位；主治；络穴',NULL,NULL,NULL,NULL,'经络学说','通里穴的定位与主治是什么？','经络学说',NULL,'理论','手少阴心经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(523,'心经病证表现为咽干、心痛、口渴、目黄、胁痛、臑臂内后廉痛厥、掌中热痛。',NULL,'手少阴心经病候：是动病——嗌干，心痛，渴而欲饮，是为臂厥。是主心所生病——目黄，胁痛，臑臂内后廉痛厥，掌中热痛。心经病候以心脏症状和经脉循行部位（上肢内侧后缘、手掌）的病变为主。',NULL,'中医知识库','手少阴心经','心经病候以心痛和上肢内侧后缘痛为主','2026-04-17 06:30:00.000000',NULL,NULL,'心经病理；是动病；是主心所生病',NULL,NULL,NULL,NULL,'经络学说','手少阴心经的病理表现有哪些？','经络学说',NULL,'理论','手少阴心经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(524,'手少阴心经临床用于治疗失眠、心悸、焦虑、心痛、心律失常、健忘等心病和神志病。神门穴最为常用。',NULL,'手少阴心经临床应用：神志病——失眠取神门，配内关、三阴交；心悸怔忡取神门，配心俞、厥阴俞；健忘取神门，配百会、四神聪。心痛——取少海、神门，配膻中。其他——暴喑取通里；肘臂痛取少海。心经穴位较少但临床应用集中，以神门为核心。',NULL,'中医知识库','手少阴心经','心经临床以治神志心病为主','2026-04-17 06:30:00.000000',NULL,NULL,'心经临床应用；失眠；心悸；神门',NULL,NULL,NULL,NULL,'经络学说','手少阴心经的临床应用有哪些？','经络学说',NULL,'理论','手少阴心经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(525,'手少阴心经属心络小肠，手太阳小肠经属小肠络心，两经互为表里。心经属阴为里，小肠经属阳为表。',NULL,'心经与小肠经的表里关系：心经属阴为里，小肠经属阳为表。手少阴心经属心络小肠，手太阳小肠经属小肠络心。生理上心主神明、主血脉，小肠主受盛化物、泌别清浊。心火下移于小肠则小便黄赤；小肠有热也可上熏于心出现心烦。治疗时常配合取穴。',NULL,'中医知识库','手少阴心经','心经小肠经互为表里病理互传','2026-04-17 06:30:00.000000',NULL,NULL,'心经小肠经；表里关系；心火下移',NULL,NULL,NULL,NULL,'经络学说','手少阴心经与手太阳小肠经的表里关系是怎样的？','经络学说',NULL,'理论','手少阴心经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(526,'心经脉病候表现为咽喉干燥、心痛、口渴欲饮、目黄、胁痛、上臂内侧后缘痛厥、掌中热痛。',NULL,'手少阴心经脉病候：是动病——嗌干，心痛，渴而欲饮，是为臂厥。是主心所生病——目黄，胁痛，臑臂内后廉痛厥，掌中热痛。这些症状与心经循行路线密切相关，心经循喉咙，经上肢内侧后缘至掌中，故上述部位出现病候。',NULL,'中医知识库','手少阴心经','心经病候循经分布','2026-04-17 06:30:00.000000',NULL,NULL,'心经脉病候；心痛；臂厥',NULL,NULL,NULL,NULL,'经络学说','手少阴心经的经脉病候是什么？','经络学说',NULL,'理论','手少阴心经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(527,'手少阴心经腧穴以治疗心病和神志病为特色。穴性偏于宁心安神、清心泻火。',NULL,'手少阴心经腧穴主治特点：以治疗心病和神志病为核心。原穴神门善宁心安神，合穴少海善疏经活络，络穴通里善通窍利舌。心经9穴各有侧重，但总体以宁心安神为共同特点。临床以神门穴应用最为广泛。',NULL,'中医知识库','手少阴心经','心经穴以宁心安神为核心','2026-04-17 06:30:00.000000',NULL,NULL,'心经腧穴主治；宁心安神；神志病',NULL,NULL,NULL,NULL,'经络学说','手少阴心经的腧穴主治特点是什么？','经络学说',NULL,'理论','手少阴心经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(528,'手太阳小肠经起于小指外侧端（少泽穴），沿手背外侧上行，经腕骨、前臂外侧后缘，经肘内侧两筋间，沿上臂外侧后缘，出肩关节后方，绕行肩胛，交肩上，入缺盆，络心，沿食管下膈至胃，下行属小肠。',NULL,'手太阳小肠经起于手小指外侧端少泽穴，沿手掌外侧上行，经腕骨、前臂外侧后缘，上出肘内侧两筋之间，沿上臂外侧后缘，出肩关节后方的肩贞、臑俞，绕行肩胛部，交会于大椎，向下入缺盆，联络心，沿食管穿过膈肌，到胃部，下行属小肠。缺盆部支脉沿颈上颊，到目外眦，转入耳中。颊部支脉从颊部分出，上行目眶下，抵鼻旁，至目内眦，与足太阳膀胱经交接。',NULL,'中医知识库','手太阳小肠经','小肠经起于小指沿上肢外侧后缘至面属小肠','2026-04-17 06:30:00.000000',NULL,NULL,'手太阳小肠经；循行路线；小指外侧端；属小肠络心',NULL,NULL,NULL,NULL,'经络学说','手太阳小肠经的循行路线是怎样的？','经络学说',NULL,'理论','手太阳小肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(529,'手太阳小肠经主治头面五官病（耳聋、目黄、咽喉痛）、肩背疼痛、项强及经脉循行部位病证。',NULL,'手太阳小肠经主治概要：一是头面五官病证——耳聋、耳鸣、目黄、目赤、咽喉肿痛、颊肿。二是肩背部病证——肩背疼痛、肩关节活动不利、项强。三是经脉循行部位病证——肘臂外侧后缘痛、手指麻木。四是其他——乳痈、乳汁少、热病。小肠经以治疗后头痛、耳病、肩背痛为特色。',NULL,'中医知识库','手太阳小肠经','小肠经主治头面五官和肩背疼痛','2026-04-17 06:30:00.000000',NULL,NULL,'小肠经主治；头面五官；肩背痛',NULL,NULL,NULL,NULL,'经络学说','手太阳小肠经的主治概要是什么？','经络学说',NULL,'理论','手太阳小肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(530,'后溪穴在手尺侧，第5掌指关节后的远侧掌横纹头赤白肉际。主治头项强痛、腰背痛、手指挛痛、癫狂，通督脉。',NULL,'后溪穴是手太阳小肠经的输穴，也是八脉交会穴通督脉。定位：在手尺侧，微握拳，第5掌指关节后的远侧掌横纹头赤白肉际。主治：头项强痛、腰背痛、手指及肘臂挛痛、耳聋、目赤、咽喉肿痛、癫狂、痫证、疟疾。本穴通督脉，为治疗头项腰背疼痛的要穴。直刺0.5~1寸。',NULL,'中医知识库','手太阳小肠经','后溪通督脉善治头项腰背痛','2026-04-17 06:30:00.000000',NULL,NULL,'后溪穴；定位；主治；输穴；通督脉',NULL,NULL,NULL,NULL,'经络学说','后溪穴的定位与主治是什么？','经络学说',NULL,'理论','手太阳小肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(531,'天宗穴在肩胛骨冈下窝的中央。主治肩胛疼痛、肩背部酸痛、乳痈、气喘。',NULL,'天宗穴定位：在肩胛部，冈下窝中央凹陷处，约与第4胸椎相平。主治：肩胛疼痛、肩背部酸痛、肘臂外后侧痛、乳痈、气喘。本穴为治疗肩胛部疼痛的常用穴，在肩背部推拿按摩中也是重要穴位。直刺或斜刺0.5~1寸。',NULL,'中医知识库','手太阳小肠经','天宗主治肩胛疼痛','2026-04-17 06:30:00.000000',NULL,NULL,'天宗穴；定位；主治；肩胛疼痛',NULL,NULL,NULL,NULL,'经络学说','天宗穴的定位与主治是什么？','经络学说',NULL,'理论','手太阳小肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(532,'听宫穴在面部，耳屏前，下颌骨髁状突的后方，张口时呈凹陷处。主治耳聋、耳鸣、中耳炎、牙痛。',NULL,'听宫穴定位：在面部，耳屏前，下颌骨髁状突的后方，张口时呈凹陷处。主治：耳聋、耳鸣、耳中蝉鸣、中耳炎、牙痛、面瘫、下颌关节炎。本穴为治疗耳部疾病的要穴。张口取穴，直刺0.5~1寸。',NULL,'中医知识库','手太阳小肠经','听宫为治耳病要穴','2026-04-17 06:30:00.000000',NULL,NULL,'听宫穴；定位；主治；耳病',NULL,NULL,NULL,NULL,'经络学说','听宫穴的定位与主治是什么？','经络学说',NULL,'理论','手太阳小肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(533,'小肠经病证表现为耳聋、目黄、颊肿、咽喉肿痛、肩臂外侧后缘痛、颈项强痛。',NULL,'手太阳小肠经病候：是动病——嗌痛，颔肿，不可以顾，肩似拔，臑似折。是主液所生病——耳聋，目黄，颊肿，颈、颔、肩、臑、肘、臂外后廉痛。小肠经病候主要表现在头面五官和经脉循行部位。',NULL,'中医知识库','手太阳小肠经','小肠经病候以耳病肩臂痛为主','2026-04-17 06:30:00.000000',NULL,NULL,'小肠经病理；是动病；是主液所生病',NULL,NULL,NULL,NULL,'经络学说','手太阳小肠经的病理表现有哪些？','经络学说',NULL,'理论','手太阳小肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(534,'手太阳小肠经临床用于治疗颈椎病、肩周炎、耳聋耳鸣、腰背痛等，后溪穴治疗急性腰扭伤有特效。',NULL,'手太阳小肠经临床应用：头面疾病——耳聋耳鸣取听宫、后溪；面瘫取颧髎。肩背疾病——肩周炎取天宗、肩贞；肩背痛取天宗、后溪。颈项疾病——落枕取后溪、天宗；颈椎病取后溪。腰背痛——急性腰扭伤取后溪。小肠经后溪通督脉，故可治头项腰背痛。',NULL,'中医知识库','手太阳小肠经','小肠经临床治肩背颈项耳病','2026-04-17 06:30:00.000000',NULL,NULL,'小肠经临床应用；肩背痛；耳病',NULL,NULL,NULL,NULL,'经络学说','手太阳小肠经的临床应用有哪些？','经络学说',NULL,'理论','手太阳小肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(535,'手太阳小肠经属小肠络心，手少阴心经属心络小肠，两经互为表里。小肠经属阳为表，心经属阴为里。',NULL,'小肠经与心经的表里关系：小肠经属阳为表，心经属阴为里。手太阳小肠经属小肠络心，手少阴心经属心络小肠。病理上心热可移于小肠，出现尿赤涩痛；小肠有热也可上扰于心，出现心烦失眠。治疗时配合取穴，如心经神门配小肠经后溪治失眠。',NULL,'中医知识库','手太阳小肠经','小肠经心经互为表里心移热小肠','2026-04-17 06:30:00.000000',NULL,NULL,'小肠经心经；表里关系；心移热于小肠',NULL,NULL,NULL,NULL,'经络学说','手太阳小肠经与手少阴心经的表里关系是怎样的？','经络学说',NULL,'理论','手太阳小肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(536,'小肠经脉病候表现为咽喉痛、颔肿、不能回顾、肩臂外后廉疼痛、耳聋、目黄、颊肿。',NULL,'手太阳小肠经脉病候：是动病——嗌痛，颔肿，不可以顾，肩似拔，臑似折。是主液所生病——耳聋，目黄，颊肿，颈、颔、肩、臑、肘、臂外后廉痛。小肠经循行经过肩臂外后廉和头面，故病候以这些部位为主。',NULL,'中医知识库','手太阳小肠经','小肠经病候以肩臂外后廉痛为特征','2026-04-17 06:30:00.000000',NULL,NULL,'小肠经脉病候；肩似拔臑似折',NULL,NULL,NULL,NULL,'经络学说','手太阳小肠经的经脉病候是什么？','经络学说',NULL,'理论','手太阳小肠经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(537,'养老穴在前臂背面尺侧，当尺骨小头近端桡侧凹陷中。主治目视不明、肩背肘臂酸痛、急性腰痛。',NULL,'养老穴是手太阳小肠经的郄穴。定位：在前臂背面尺侧，当尺骨小头近端桡侧凹陷中。简便取穴：屈肘，掌心向胸，在尺骨小头的桡侧缘缝隙中。主治：目视不明、目赤肿痛、肩背肘臂酸痛、急性腰痛。本穴为小肠经郄穴，善治急性病。直刺或斜刺0.5~0.8寸。',NULL,'中医知识库','手太阳小肠经','养老为小肠经郄穴善治急性腰痛','2026-04-17 06:30:00.000000',NULL,NULL,'养老穴；定位；主治；郄穴',NULL,NULL,NULL,NULL,'经络学说','养老穴的定位与主治是什么？','经络学说',NULL,'理论','手太阳小肠经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(538,'足太阳膀胱经起于目内眦（睛明穴），上额交巅，从巅入络脑，还出别下项，沿肩胛内侧挟脊抵腰，入循膂络肾属膀胱。',NULL,'足太阳膀胱经起于目内眦睛明穴，上额交会于巅顶百会穴。从巅顶入里联络于脑，回出分开下行项后，沿肩胛骨内侧，脊柱两旁，到达腰部，从脊旁肌肉深入腹腔，联络肾脏，属膀胱。腰部分支从腰下行，贯穿臀部，入腘窝中。另一分支从项部分出，经肩胛内侧下行，沿脊旁至环跳，经大腿后外侧下行，与前支会合于腘窝委中穴，下行穿过小腿后部，经外踝后方昆仑穴，沿足外侧至小趾外侧端至阴穴，与足少阴肾经交接。',NULL,'中医知识库','足太阳膀胱经','膀胱经起于目内眦沿背至足属膀胱络肾','2026-04-17 06:30:00.000000',NULL,NULL,'足太阳膀胱经；循行路线；起于目内眦；属膀胱络肾',NULL,NULL,NULL,NULL,'经络学说','足太阳膀胱经的循行路线是怎样的？','经络学说',NULL,'理论','足太阳膀胱经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(539,'足太阳膀胱经主治头项腰背下肢病证、神志病、脏腑病（背俞穴治相应脏腑病）。膀胱经穴位最多，应用广泛。',NULL,'足太阳膀胱经主治概要：一是头项腰背下肢病证——头痛、项强、腰背痛、坐骨神经痛、下肢痿痹。二是神志病——癫狂、痫证。三是脏腑病——通过背俞穴治疗各脏腑疾病。四是五官病——目赤肿痛、鼻塞。五是小便病——小便不利、遗尿。膀胱经有67穴，是十四经中穴位最多的经脉。',NULL,'中医知识库','足太阳膀胱经','膀胱经主治头项腰背下肢及脏腑病','2026-04-17 06:30:00.000000',NULL,NULL,'膀胱经主治；头项腰背；背俞穴',NULL,NULL,NULL,NULL,'经络学说','足太阳膀胱经的主治概要是什么？','经络学说',NULL,'理论','足太阳膀胱经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(540,'肾俞穴在腰部，第2腰椎棘突下，旁开1.5寸。主治腰痛、遗精、阳痿、遗尿、月经不调、耳鸣耳聋。',NULL,'肾俞穴是肾脏的背俞穴。定位：在腰部，第2腰椎棘突下，旁开1.5寸。主治：腰膝酸痛、遗精、阳痿、早泄、遗尿、小便不利、月经不调、带下、不孕、耳鸣、耳聋、水肿。本穴为肾脏之气输注之处，是治疗肾系疾病的重要穴位，有补肾益精、温阳利水的作用。直刺0.5~1寸。',NULL,'中医知识库','足太阳膀胱经','肾俞为肾之背俞穴补肾益精','2026-04-17 06:30:00.000000',NULL,NULL,'肾俞穴；定位；主治；背俞穴；补肾',NULL,NULL,NULL,NULL,'经络学说','肾俞穴的定位与主治是什么？','经络学说',NULL,'理论','足太阳膀胱经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(541,'委中穴在腘横纹中点，当股二头肌腱与半腱肌腱的中间。主治腰背痛、下肢痿痹、腹痛、吐泻，为治疗腰痛的要穴。',NULL,'委中穴是足太阳膀胱经的合穴，也是膀胱的下合穴。定位：在腘横纹中点，当股二头肌腱与半腱肌腱的中间。主治：腰背痛、下肢痿痹、腹痛、吐泻、丹毒、中暑。本穴为治疗腰背痛的要穴，有\"腰背委中求\"之说。直刺1~1.5寸，或用三棱针点刺出血。',NULL,'中医知识库','足太阳膀胱经','委中为膀胱经合穴治腰背痛要穴','2026-04-17 06:30:00.000000',NULL,NULL,'委中穴；定位；主治；合穴；腰背委中求',NULL,NULL,NULL,NULL,'经络学说','委中穴的定位与主治是什么？','经络学说',NULL,'理论','足太阳膀胱经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(542,'承山穴在小腿后面正中，当伸直小腿或足跟上提时腓肠肌肌腹下出现尖角凹陷处。主治腰背痛、小腿抽筋、痔疾、便秘。',NULL,'承山穴定位：在小腿后面正中，委中与昆仑之间，当伸直小腿或足跟上提时腓肠肌肌腹下出现尖角凹陷处。主治：腰背痛、腿痛转筋（小腿抽筋）、痔疾、便秘、脱肛、脚气。本穴有舒筋活络、理肠疗痔的作用，为治疗小腿抽筋和痔疮的常用穴。直刺1~1.5寸。',NULL,'中医知识库','足太阳膀胱经','承山善治小腿抽筋和痔疾','2026-04-17 06:30:00.000000',NULL,NULL,'承山穴；定位；主治；小腿抽筋；痔疾',NULL,NULL,NULL,NULL,'经络学说','承山穴的定位与主治是什么？','经络学说',NULL,'理论','足太阳膀胱经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(543,'昆仑穴在足部外踝后方，当外踝尖与跟腱之间的凹陷处。主治头痛、项强、腰痛、脚跟痛、难产。',NULL,'昆仑穴是足太阳膀胱经的经穴。定位：在足部外踝后方，当外踝尖与跟腱之间的凹陷处。主治：头痛、项强、目眩、腰痛、脚跟痛、难产、癫痫。本穴有舒筋活络的作用。直刺0.5~0.8寸。孕妇禁针。',NULL,'中医知识库','足太阳膀胱经','昆仑治头痛项强腰痛脚跟痛','2026-04-17 06:30:00.000000',NULL,NULL,'昆仑穴；定位；主治；经穴',NULL,NULL,NULL,NULL,'经络学说','昆仑穴的定位与主治是什么？','经络学说',NULL,'理论','足太阳膀胱经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(544,'申脉穴在足外侧部，外踝直下方凹陷中。主治头痛、眩晕、失眠、癫狂、腰腿痛，为八脉交会穴通阳跷脉。',NULL,'申脉穴是足太阳膀胱经穴，为八脉交会穴通阳跷脉。定位：在足外侧部，外踝直下方凹陷中。主治：头痛、眩晕、失眠、癫狂、痫证、腰腿痛、项强。本穴通阳跷脉，有安神定志、舒筋活络的作用。常配后溪治癫狂，配照海治失眠。直刺0.3~0.5寸。',NULL,'中医知识库','足太阳膀胱经','申脉通阳跷脉治失眠癫狂','2026-04-17 06:30:00.000000',NULL,NULL,'申脉穴；定位；主治；八脉交会穴；通阳跷',NULL,NULL,NULL,NULL,'经络学说','申脉穴的定位与主治是什么？','经络学说',NULL,'理论','足太阳膀胱经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(545,'至阴穴在足小趾外侧，趾甲角旁约0.1寸。主治胎位不正、难产、头痛、目痛。为矫正胎位要穴。',NULL,'至阴穴是足太阳膀胱经的井穴。定位：在足小趾外侧，距趾甲角旁约0.1寸。主治：胎位不正、难产、胞衣不下、头痛、目痛、鼻塞。本穴为矫正胎位的特效穴，艾灸至阴穴可转正异常胎位，是针灸临床的一大特色。浅刺0.1寸，胎位不正用艾条悬灸。',NULL,'中医知识库','足太阳膀胱经','至阴为矫正胎位特效穴','2026-04-17 06:30:00.000000',NULL,NULL,'至阴穴；定位；主治；井穴；矫正胎位',NULL,NULL,NULL,NULL,'经络学说','至阴穴的定位与主治是什么？','经络学说',NULL,'理论','足太阳膀胱经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(546,'肺俞穴在背部，第3胸椎棘突下，旁开1.5寸。主治咳嗽、气喘、咯血、鼻塞、皮肤瘙痒，为肺之背俞穴。',NULL,'肺俞穴是肺脏的背俞穴。定位：在背部，第3胸椎棘突下，旁开1.5寸。主治：咳嗽、气喘、咯血、鼻塞、喉痹、骨蒸潮热、盗汗、皮肤瘙痒、荨麻疹。本穴为肺脏之气输注之处，是治疗肺系疾病的重要穴位。斜刺0.5~0.8寸，不可深刺。',NULL,'中医知识库','足太阳膀胱经','肺俞为肺之背俞穴治肺系病','2026-04-17 06:30:00.000000',NULL,NULL,'肺俞穴；定位；主治；背俞穴',NULL,NULL,NULL,NULL,'经络学说','肺俞穴的定位与主治是什么？','经络学说',NULL,'理论','足太阳膀胱经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(547,'肝俞穴在背部，第9胸椎棘突下，旁开1.5寸。主治黄疸、胁痛、目赤、眩晕、癫狂、脊背痛，为肝之背俞穴。',NULL,'肝俞穴是肝脏的背俞穴。定位：在背部，第9胸椎棘突下，旁开1.5寸。主治：黄疸、胁肋疼痛、目赤肿痛、目视不明、眩晕、癫狂、痫证、脊背痛、吐血、鼻衄。本穴为肝脏之气输注之处，有疏肝利胆、清肝明目的作用。斜刺0.5~0.8寸。',NULL,'中医知识库','足太阳膀胱经','肝俞为肝之背俞穴疏肝明目','2026-04-17 06:30:00.000000',NULL,NULL,'肝俞穴；定位；主治；背俞穴',NULL,NULL,NULL,NULL,'经络学说','肝俞穴的定位与主治是什么？','经络学说',NULL,'理论','足太阳膀胱经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(548,'胃俞穴在背部，第12胸椎棘突下，旁开1.5寸。主治胃痛、呕吐、腹胀、肠鸣，为胃之背俞穴。',NULL,'胃俞穴是胃的背俞穴。定位：在背部，第12胸椎棘突下，旁开1.5寸。主治：胃脘痛、呕吐、腹胀、肠鸣、完谷不化、胸胁痛。本穴为胃腑之气输注之处，有和胃健脾、理中降逆的作用，是治疗胃病的重要穴位。斜刺0.5~0.8寸。',NULL,'中医知识库','足太阳膀胱经','胃俞为胃之背俞穴和胃健脾','2026-04-17 06:30:00.000000',NULL,NULL,'胃俞穴；定位；主治；背俞穴',NULL,NULL,NULL,NULL,'经络学说','胃俞穴的定位与主治是什么？','经络学说',NULL,'理论','足太阳膀胱经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(549,'足太阳膀胱经临床用于治疗腰背痛、坐骨神经痛、感冒、咳嗽、各脏腑疾病（通过背俞穴）、胎位不正等。',NULL,'足太阳膀胱经临床应用：腰背痛——委中、承山、昆仑；坐骨神经痛——秩边、承扶、委中、承山。脏腑病——肺俞治咳嗽、胃俞治胃痛、肾俞治腰痛、肝俞治目赤。其他——至阴灸矫正胎位；申脉治失眠；天柱治头痛。背俞穴是脏腑之气输注之处，是调节各脏腑功能的重要穴位群。',NULL,'中医知识库','足太阳膀胱经','膀胱经以背俞穴治脏腑病为特色','2026-04-17 06:30:00.000000',NULL,NULL,'膀胱经临床应用；腰背痛；背俞穴；胎位矫正',NULL,NULL,NULL,NULL,'经络学说','足太阳膀胱经的临床应用有哪些？','经络学说',NULL,'理论','足太阳膀胱经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(550,'膀胱经脉病候表现为头项痛、目似脱、项如拔、脊痛、腰似折、髀不可以曲、腘如结、腨如裂、足小趾不用。',NULL,'足太阳膀胱经脉病候：是动病——冲头痛，目似脱，项如拔，脊痛，腰似折，髀不可以曲，腘如结，腨如裂，是为踝厥。是主筋所生病——痔，疟，狂，癫疾，头囟项痛，目黄，泪出，鼽衄，项、背、腰、尻、腘、腨、脚皆痛，小趾不用。膀胱经循行最长，故病候范围也最广。',NULL,'中医知识库','足太阳膀胱经','膀胱经病候以头项腰背腿痛为特征','2026-04-17 06:30:00.000000',NULL,NULL,'膀胱经脉病候；头项痛；腰似折；踝厥',NULL,NULL,NULL,NULL,'经络学说','足太阳膀胱经的经脉病候是什么？','经络学说',NULL,'理论','足太阳膀胱经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(551,'足太阳膀胱经属膀胱络肾，足少阴肾经属肾络膀胱，两经互为表里。膀胱经属阳为表，肾经属阴为里。',NULL,'膀胱经与肾经的表里关系：膀胱经属阳为表，肾经属阴为里。足太阳膀胱经属膀胱络肾，足少阴肾经属肾络膀胱。生理上肾主水液，膀胱贮尿排尿，共同完成水液代谢。病理上肾阳虚不能化气行水，可致膀胱小便不利；膀胱湿热也可影响肾脏。治疗时常配合使用，如肾俞配太溪治肾虚腰痛。',NULL,'中医知识库','足太阳膀胱经','膀胱经肾经互为表里共同主水液','2026-04-17 06:30:00.000000',NULL,NULL,'膀胱经肾经；表里关系；水液代谢',NULL,NULL,NULL,NULL,'经络学说','足太阳膀胱经与足少阴肾经的表里关系是怎样的？','经络学说',NULL,'理论','足太阳膀胱经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(552,'足太阳膀胱经腧穴分布在目内眦、头顶、项部、背部（分两行）、腰部、臀部、大腿后面、小腿后面和足外侧，共67穴。',NULL,'足太阳膀胱经腧穴分部：头部——睛明、攒竹等。头顶——通天、玉枕等。项部——天柱、大杼等。背部第一行线（棘突下旁开1.5寸）——风门、肺俞、心俞、肝俞、胆俞、脾俞、胃俞、三焦俞、肾俞、大肠俞、小肠俞、膀胱俞等。背部第二行线（棘突下旁开3寸）。下肢后面——承扶、殷门、委中、承山、昆仑等。足外侧——申脉、至阴等。共67穴。',NULL,'中医知识库','足太阳膀胱经','膀胱经67穴从头至足分布最广','2026-04-17 06:30:00.000000',NULL,NULL,'膀胱经腧穴分部；67穴；背俞穴',NULL,NULL,NULL,NULL,'经络学说','足太阳膀胱经的腧穴如何分部？','经络学说',NULL,'理论','足太阳膀胱经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(553,'足少阴肾经起于足小趾之下，斜行足心（涌泉），出于舟骨粗隆下，沿内踝后，上行小腿内侧，出腘内侧，上大腿内侧后缘，通脊柱属肾络膀胱。直行者从肾上行贯肝膈入肺，沿喉咙挟舌本。支脉从肺出络心，注胸中。',NULL,'足少阴肾经起于足小趾之下，斜向足心涌泉穴，出于舟骨粗隆下方，沿内踝后方上行，经小腿内侧，出腘窝内侧，上行大腿内侧后缘，进入脊柱，属肾，络膀胱。直行者从肾上行，穿过肝脏和膈肌，进入肺中，沿喉咙上行至舌根两侧。支脉从肺中分出，联络心脏，注入胸中，与手厥阴心包经交接。',NULL,'中医知识库','足少阴肾经','肾经起于足心沿下肢内侧上行属肾络膀胱','2026-04-17 06:30:00.000000',NULL,NULL,'足少阴肾经；循行路线；起于小趾下；属肾络膀胱',NULL,NULL,NULL,NULL,'经络学说','足少阴肾经的循行路线是怎样的？','经络学说',NULL,'理论','足少阴肾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(554,'足少阴肾经主治肾系疾病（腰痛、遗精、阳痿、遗尿）、妇科病（月经不调、不孕）、咽喉痛、咳血及经脉循行部位病证。',NULL,'足少阴肾经主治概要：一是肾系疾病——腰痛、遗精、阳痿、遗尿、小便不利、水肿。二是妇科病证——月经不调、痛经、不孕、带下。三是肺系疾病——咳嗽、咯血、咽喉肿痛。四是神志病——失眠、善恐。五是经脉循行部位病证——下肢内侧后缘痛、足心痛、咽喉干燥。肾经以涌泉、太溪、照海最为常用。',NULL,'中医知识库','足少阴肾经','肾经主治肾系妇科和肺系病证','2026-04-17 06:30:00.000000',NULL,NULL,'肾经主治；肾系疾病；妇科病',NULL,NULL,NULL,NULL,'经络学说','足少阴肾经的主治概要是什么？','经络学说',NULL,'理论','足少阴肾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(555,'涌泉穴在足底部，卷足时足前部凹陷处，约当足底第2、3趾趾缝纹头端与足跟连线的前1/3与后2/3交点上。主治头痛、昏厥、中暑、失眠、小儿惊风。',NULL,'涌泉穴是足少阴肾经的井穴。定位：在足底部，卷足时足前部凹陷处，约当足底第2、3趾趾缝纹头端与足跟连线的前1/3与后2/3交点上。主治：头痛、头晕、昏厥、中暑、中风昏迷、小儿惊风、癫痫、失眠、足心热。本穴为急救要穴之一，有开窍醒神、引火归元的作用。直刺0.5~0.8寸。',NULL,'中医知识库','足少阴肾经','涌泉为肾经井穴开窍醒神引火归元','2026-04-17 06:30:00.000000',NULL,NULL,'涌泉穴；定位；主治；井穴；急救要穴',NULL,NULL,NULL,NULL,'经络学说','涌泉穴的定位与主治是什么？','经络学说',NULL,'理论','足少阴肾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(556,'太溪穴在足内侧，内踝后方，当内踝尖与跟腱之间的凹陷处。主治腰痛、遗精、阳痿、咽喉痛、耳鸣、月经不调。为肾经原穴。',NULL,'太溪穴是足少阴肾经的输穴和原穴。定位：在足内侧，内踝后方，当内踝尖与跟腱之间的凹陷处。主治：头痛目眩、咽喉肿痛、齿痛、耳聋、耳鸣、咳嗽、气喘、消渴、月经不调、失眠、健忘、遗精、阳痿、腰脊痛、下肢厥冷。本穴为肾经原穴，是肾经原气留止之处，有滋补肾阴、壮肾阳的作用，为补肾要穴。直刺0.5~0.8寸。',NULL,'中医知识库','足少阴肾经','太溪为肾经原穴补肾要穴','2026-04-17 06:30:00.000000',NULL,NULL,'太溪穴；定位；主治；原穴；补肾要穴',NULL,NULL,NULL,NULL,'经络学说','太溪穴的定位与主治是什么？','经络学说',NULL,'理论','足少阴肾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(557,'照海穴在足内侧，内踝尖下方凹陷处。主治失眠、咽干、月经不调、小便不利、癫狂，为八脉交会穴通阴跷脉。',NULL,'照海穴是足少阴肾经穴，为八脉交会穴通阴跷脉。定位：在足内侧，内踝尖下方凹陷处。主治：失眠、嗜睡、咽干咽痛、月经不调、赤白带下、小便频数、癃闭、便秘、癫狂、痫证。本穴通阴跷脉，有滋阴安神的作用，常与申脉配合使用。直刺0.5~0.8寸。',NULL,'中医知识库','足少阴肾经','照海通阴跷脉滋阴安神','2026-04-17 06:30:00.000000',NULL,NULL,'照海穴；定位；主治；通阴跷脉',NULL,NULL,NULL,NULL,'经络学说','照海穴的定位与主治是什么？','经络学说',NULL,'理论','足少阴肾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(558,'复溜穴在小腿内侧，太溪直上2寸，跟腱的前方。主治水肿、腹胀、泄泻、盗汗、热病汗不出，为肾经经穴。',NULL,'复溜穴是足少阴肾经的经穴。定位：在小腿内侧，太溪穴直上2寸，跟腱的前方。主治：水肿、腹胀、泄泻、肠鸣、腿肿、盗汗、热病汗不出、消渴。本穴有补肾利水的作用，是治疗水肿和汗证的要穴。直刺0.5~1寸。',NULL,'中医知识库','足少阴肾经','复溜为肾经经穴善利水止汗','2026-04-17 06:30:00.000000',NULL,NULL,'复溜穴；定位；主治；经穴',NULL,NULL,NULL,NULL,'经络学说','复溜穴的定位与主治是什么？','经络学说',NULL,'理论','足少阴肾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(559,'肾经病证表现为饥不欲食、面如漆柴、咳唾有血、喝喝而喘、心如悬若饥状、善恐、心惕惕如人将捕之。',NULL,'足少阴肾经病候：是动病——饥不欲食，面如漆柴，咳唾有血，喝喝而喘，坐而欲起，目（盳盳）如无所见，心如悬若饥状，气不足则善恐，心惕惕如人将捕之，是为骨厥。是主肾所生病——口热，舌干，咽肿，上气，嗌干及痛，烦心，心痛，黄疸，肠澼，脊股内后廉痛，痿厥，嗜卧，足下热而痛。',NULL,'中医知识库','足少阴肾经','肾经病候以肾虚和循经痛为特征','2026-04-17 06:30:00.000000',NULL,NULL,'肾经病理；是动病；是主肾所生病',NULL,NULL,NULL,NULL,'经络学说','足少阴肾经的病理表现有哪些？','经络学说',NULL,'理论','足少阴肾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(560,'足少阴肾经腧穴以治疗肾系疾病为主。穴性偏于滋补肾阴、温补肾阳、利水消肿。',NULL,'足少阴肾经腧穴主治特点：以治疗肾系疾病为核心。井穴涌泉善开窍醒神，原穴太溪善补肾，经穴复溜善利水消肿，照海善滋阴安神。肾经穴位总体以补益肾气、滋阴温阳为特点，临床多用于虚证治疗。',NULL,'中医知识库','足少阴肾经','肾经穴以补肾为核心','2026-04-17 06:30:00.000000',NULL,NULL,'肾经腧穴主治；滋补肾阴；温补肾阳',NULL,NULL,NULL,NULL,'经络学说','足少阴肾经的腧穴主治特点是什么？','经络学说',NULL,'理论','足少阴肾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(561,'足少阴肾经临床用于治疗腰痛、失眠、遗精、阳痿、水肿、咽喉肿痛、不育、更年期综合征等。',NULL,'足少阴肾经临床应用：肾系疾病——腰痛取太溪、肾俞配合；遗精阳痿取太溪、复溜。水肿——复溜、太溪配水分。妇科——月经不调取照海、太溪配三阴交。失眠——照海配神门。咽喉肿痛——太溪配鱼际。急救——涌泉用于昏迷急救。保健——常按涌泉穴可强身健体。',NULL,'中医知识库','足少阴肾经','肾经临床治肾系疾病为主','2026-04-17 06:30:00.000000',NULL,NULL,'肾经临床应用；腰痛；失眠；水肿',NULL,NULL,NULL,NULL,'经络学说','足少阴肾经的临床应用有哪些？','经络学说',NULL,'理论','足少阴肾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(562,'肾经脉病候表现为饥不欲食、面色晦暗、咳血、气喘、心慌善恐、脊股内侧后缘痛、足心热痛。',NULL,'足少阴肾经脉病候：是动病——饥不欲食，面如漆柴，咳唾有血，喝喝而喘，坐而欲起，目盳盳如无所见，心如悬若饥状。气不足则善恐，心惕惕如人将捕之，是为骨厥。是主肾所生病——口热舌干，咽肿上气，嗌干及痛，烦心痛，黄疸肠澼，脊股内后廉痛，痿厥嗜卧，足下热而痛。',NULL,'中医知识库','足少阴肾经','肾经病候以肾虚恐怯为特征','2026-04-17 06:30:00.000000',NULL,NULL,'肾经脉病候；善恐；骨厥',NULL,NULL,NULL,NULL,'经络学说','足少阴肾经的经脉病候是什么？','经络学说',NULL,'理论','足少阴肾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(563,'足少阴肾经属肾络膀胱，足太阳膀胱经属膀胱络肾，两经互为表里。肾经属阴为里，膀胱经属阳为表。',NULL,'肾经与膀胱经的表里关系：肾经属阴为里，膀胱经属阳为表。足少阴肾经属肾络膀胱，足太阳膀胱经属膀胱络肾。肾主水，膀胱主贮尿排尿，共同完成水液代谢。治疗肾系疾病时常肾经与膀胱经配合取穴，如太溪配肾俞治腰痛，复溜配膀胱俞治小便不利。',NULL,'中医知识库','足少阴肾经','肾经膀胱经互为表里共同主水','2026-04-17 06:30:00.000000',NULL,NULL,'肾经膀胱经；表里关系；水液代谢',NULL,NULL,NULL,NULL,'经络学说','足少阴肾经与足太阳膀胱经的表里关系是怎样的？','经络学说',NULL,'理论','足少阴肾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(564,'足少阴肾经腧穴分布在足底、内踝后、小腿内侧、大腿内侧后缘、腹部和胸部，共27穴。',NULL,'足少阴肾经腧穴分部：足部——涌泉（足底）、然谷、太溪、大钟、照海、复溜、交信、筑宾。小腿——阴谷。腹部——横骨、大赫、气穴、四满、中注、肓俞、商曲、石关、阴都、腹谷、通谷、幽门。胸部——步廊、神封、灵墟、神藏、彧中、俞府。共27穴。',NULL,'中医知识库','足少阴肾经','肾经27穴从足底至胸部分布','2026-04-17 06:30:00.000000',NULL,NULL,'肾经腧穴分部；足底至胸；27穴',NULL,NULL,NULL,NULL,'经络学说','足少阴肾经的腧穴如何分部？','经络学说',NULL,'理论','足少阴肾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(565,'足少阴肾经的络脉从大钟穴分出，绕足内踝，走向足太阳膀胱经。其别支与经别并行，上至心包下，贯穿腰脊。',NULL,'足少阴肾经的络脉名曰大钟。从足内踝后下方的大钟穴处分出，绕行足内踝，走向足太阳膀胱经。其别支与经别并行走行，上至心包之下，向外贯穿腰脊。病候：实证——小便不通、闭癃；虚证——腰痛。治疗取大钟穴。',NULL,'中医知识库','足少阴肾经','肾经络脉从大钟分出沟通膀胱经','2026-04-17 06:30:00.000000',NULL,NULL,'肾经络脉；大钟；沟通膀胱经',NULL,NULL,NULL,NULL,'经络学说','足少阴肾经的络脉是怎样的？','经络学说',NULL,'理论','足少阴肾经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(566,'然谷穴在足内侧缘，足舟骨粗隆下方，赤白肉际。主治月经不调、遗精、消渴、泄泻、咽喉肿痛，为肾经荥穴。',NULL,'然谷穴是足少阴肾经的荥穴。定位：在足内侧缘，足舟骨粗隆下方，赤白肉际处。主治：月经不调、阴挺、遗精、消渴、泄泻、咽喉肿痛、小儿脐风、口噤。本穴有滋阴补肾、清虚热的作用。直刺0.5~0.8寸。',NULL,'中医知识库','足少阴肾经','然谷为肾经荥穴滋阴清虚热','2026-04-17 06:30:00.000000',NULL,NULL,'然谷穴；定位；主治；荥穴',NULL,NULL,NULL,NULL,'经络学说','然谷穴的定位与主治是什么？','经络学说',NULL,'理论','足少阴肾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(567,'阴谷穴在腘窝内侧，屈膝时当半腱肌腱与半膜肌腱之间。主治阳痿、月经不调、崩漏、膝股内侧痛，为肾经合穴。',NULL,'阴谷穴是足少阴肾经的合穴。定位：在腘窝内侧，屈膝时当半腱肌腱与半膜肌腱之间。主治：阳痿、遗精、月经不调、崩漏、小便不利、膝股内侧痛。本穴有补肾益精的作用。直刺1~1.5寸。',NULL,'中医知识库','足少阴肾经','阴谷为肾经合穴补肾益精','2026-04-17 06:30:00.000000',NULL,NULL,'阴谷穴；定位；主治；合穴',NULL,NULL,NULL,NULL,'经络学说','阴谷穴的定位与主治是什么？','经络学说',NULL,'理论','足少阴肾经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(568,'手厥阴心包经起于胸中，出属心包络，下膈历络三焦。支脉从胸出胁，当腋下3寸处上行抵腋，沿上肢内侧中线入掌中，出中指端。支脉从掌中分出至无名指端。',NULL,'手厥阴心包经起于胸中，出属心包络，向下穿过膈肌，依次联络上、中、下三焦。支脉从胸中分出，沿胸出胁肋部，当腋下3寸处上行至腋窝，沿上臂内侧中线，行于手太阴肺经和手少阴心经之间，经肘窝，沿前臂内侧两筋之间下行，入掌中，沿中指到指端中冲穴。另一支脉从掌中劳宫穴分出，沿无名指到指端关冲穴，与手少阳三焦经交接。',NULL,'中医知识库','手厥阴心包经','心包经起于胸中沿上肢内侧中线至中指','2026-04-17 06:30:00.000000',NULL,NULL,'手厥阴心包经；循行路线；起于胸中；属心包络三焦',NULL,NULL,NULL,NULL,'经络学说','手厥阴心包经的循行路线是怎样的？','经络学说',NULL,'理论','手厥阴心包经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(569,'手厥阴心包经主治心病（心悸、心痛）、胸胁痛、胃痛、呕吐、神志病（癫狂、痫证）及经脉循行部位病证。',NULL,'手厥阴心包经主治概要：一是心胸病证——心悸、心痛、胸闷、心烦。二是神志病——癫狂、痫证、失眠。三是胃病——胃痛、呕吐、呃逆。四是经脉循行部位病证——肘臂挛痛、手掌热。心包经以内关穴最为常用，为临床要穴。',NULL,'中医知识库','手厥阴心包经','心包经主治心病胸胁病神志病','2026-04-17 06:30:00.000000',NULL,NULL,'心包经主治；心病；胸胁痛；神志病',NULL,NULL,NULL,NULL,'经络学说','手厥阴心包经的主治概要是什么？','经络学说',NULL,'理论','手厥阴心包经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(570,'内关穴在前臂掌侧，当曲泽与大陵连线上，腕横纹上2寸，掌长肌腱与桡侧腕屈肌腱之间。主治心悸、心痛、胸闷、恶心、呕吐、失眠，为八脉交会穴通阴维脉。',NULL,'内关穴是手厥阴心包经的络穴，为八脉交会穴通阴维脉。定位：在前臂掌侧，当曲泽与大陵连线上，腕横纹上2寸，掌长肌腱与桡侧腕屈肌腱之间。主治：心悸、心痛、胸闷、胃痛、恶心、呕吐、呃逆、失眠、眩晕、癫狂、痫证、肘臂挛痛。本穴为临床最常用穴位之一，有宁心安神、和胃止呕、宽胸理气的作用。直刺0.5~1寸。',NULL,'中医知识库','手厥阴心包经','内关为心包经络穴通阴维脉临床要穴','2026-04-17 06:30:00.000000',NULL,NULL,'内关穴；定位；主治；络穴；通阴维脉',NULL,NULL,NULL,NULL,'经络学说','内关穴的定位与主治是什么？','经络学说',NULL,'理论','手厥阴心包经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(571,'大陵穴在腕掌横纹的中点处，当掌长肌腱与桡侧腕屈肌腱之间。主治心痛、心悸、胃痛、呕吐、癫狂、腕关节痛，为心包经输穴和原穴。',NULL,'大陵穴是手厥阴心包经的输穴和原穴。定位：在腕掌横纹的中点处，当掌长肌腱与桡侧腕屈肌腱之间。主治：心痛、心悸、胃痛、呕吐、癫狂、痫证、腕关节疼痛、手臂麻木。本穴有宁心安神、和胃宽胸的作用。直刺0.3~0.5寸。',NULL,'中医知识库','手厥阴心包经','大陵为心包经原穴宁心安神','2026-04-17 06:30:00.000000',NULL,NULL,'大陵穴；定位；主治；原穴',NULL,NULL,NULL,NULL,'经络学说','大陵穴的定位与主治是什么？','经络学说',NULL,'理论','手厥阴心包经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(572,'曲泽穴在肘横纹中，当肱二头肌腱的尺侧缘。主治心痛、心悸、胃痛、呕吐、泄泻、肘臂挛痛，为心包经合穴。',NULL,'曲泽穴是手厥阴心包经的合穴。定位：在肘横纹中，当肱二头肌腱的尺侧缘。主治：心痛、心悸、胃痛、呕吐、泄泻、热病、肘臂挛痛。本穴有清心泻热、和胃降逆的作用。直刺0.8~1寸，或点刺出血。',NULL,'中医知识库','手厥阴心包经','曲泽为心包经合穴清心和胃','2026-04-17 06:30:00.000000',NULL,NULL,'曲泽穴；定位；主治；合穴',NULL,NULL,NULL,NULL,'经络学说','曲泽穴的定位与主治是什么？','经络学说',NULL,'理论','手厥阴心包经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(573,'心包经病证表现为手心热、臂肘挛急、腋肿、胸胁满闷、心悸、面赤、目黄、喜笑不休。',NULL,'手厥阴心包经病候：是动病——手心热，臂肘挛急，腋肿，甚则胸胁支满，心中憺憺大动，面赤目黄，喜笑不休。是主脉所生病——烦心，心痛，掌中热。心包代心受邪，故心包经病候与心病类似，以心胸症状和神志症状为主。',NULL,'中医知识库','手厥阴心包经','心包经病候以心胸和神志症状为主','2026-04-17 06:30:00.000000',NULL,NULL,'心包经病理；是动病；是主脉所生病',NULL,NULL,NULL,NULL,'经络学说','手厥阴心包经的病理表现有哪些？','经络学说',NULL,'理论','手厥阴心包经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(574,'手厥阴心包经临床用于治疗心绞痛、心律失常、恶心呕吐、失眠、胸闷等。内关穴为最常用穴位。',NULL,'手厥阴心包经临床应用：心脏疾病——心绞痛取内关、郄门；心悸取内关、大陵。胃病——恶心呕吐取内关；呃逆取内关。神志病——失眠取内关配神门；癫狂取内关配丰隆。内关穴配公孙治胃心胸疾病。手厥阴心包经在临床以内关穴为核心，配伍灵活。',NULL,'中医知识库','手厥阴心包经','心包经以内关为核心治心病胃病','2026-04-17 06:30:00.000000',NULL,NULL,'心包经临床应用；内关；心绞痛；呕吐',NULL,NULL,NULL,NULL,'经络学说','手厥阴心包经的临床应用有哪些？','经络学说',NULL,'理论','手厥阴心包经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(575,'心包经脉病候表现为手心发热、臂肘挛急、腋下肿胀、胸胁支满、心中跳动不安、面赤目黄、喜笑不休。',NULL,'手厥阴心包经脉病候：是动病——手心热，臂肘挛急腋肿，甚则胸胁支满，心中憺憺大动，面赤目黄，喜笑不休。是主脉所生病——烦心，心痛，掌中热。心包为心之外卫，代心行令，故心包病候表现以心神症状为主。',NULL,'中医知识库','手厥阴心包经','心包经病候代心受邪以神志为主','2026-04-17 06:30:00.000000',NULL,NULL,'心包经脉病候；心中大动；喜笑不休',NULL,NULL,NULL,NULL,'经络学说','手厥阴心包经的经脉病候是什么？','经络学说',NULL,'理论','手厥阴心包经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(576,'手厥阴心包经属心包络三焦，手少阳三焦经属三焦络心包，两经互为表里。心包经属阴为里，三焦经属阳为表。',NULL,'心包经与三焦经的表里关系：心包经属阴为里，三焦经属阳为表。手厥阴心包经属心包络三焦，手少阳三焦经属三焦络心包。心包代心行令，三焦为元气和水液通道。临床常配合取穴，如内关配外关治疗胸胁胀满、耳鸣等。',NULL,'中医知识库','手厥阴心包经','心包经三焦经互为表里','2026-04-17 06:30:00.000000',NULL,NULL,'心包经三焦经；表里关系',NULL,NULL,NULL,NULL,'经络学说','手厥阴心包经与手少阳三焦经的表里关系是怎样的？','经络学说',NULL,'理论','手厥阴心包经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(577,'郄门穴在前臂掌侧，当曲泽与大陵连线上，腕横纹上5寸，掌长肌腱与桡侧腕屈肌腱之间。主治心痛、心悸、呕血、咳血，为心包经郄穴。',NULL,'郄门穴是手厥阴心包经的郄穴。定位：在前臂掌侧，当曲泽与大陵连线上，腕横纹上5寸，掌长肌腱与桡侧腕屈肌腱之间。主治：心痛、心悸、呕血、咳血、疔疮、癫痫。本穴为心包经郄穴，善治急性心脏病和出血证。直刺0.5~1寸。',NULL,'中医知识库','手厥阴心包经','郄门为心包经郄穴善治急性心病','2026-04-17 06:30:00.000000',NULL,NULL,'郄门穴；定位；主治；郄穴',NULL,NULL,NULL,NULL,'经络学说','郄门穴的定位与主治是什么？','经络学说',NULL,'理论','手厥阴心包经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(578,'手少阳三焦经起于无名指末端（关冲穴），沿手背第4、5掌骨间上行，经前臂外侧中线，过肘尖，沿上臂外侧上行至肩，交出足少阳之后，入缺盆，分布于膻中，散络心包，下膈属三焦。',NULL,'手少阳三焦经起于无名指末端关冲穴，向上沿手背第四、五掌骨间上行，经腕背阳池穴，沿前臂外侧尺骨和桡骨之间上行，过肘尖天井穴，沿上臂外侧上行至肩部肩髎穴，交出足少阳胆经之后，向前入缺盆，分布于膻中，散络心包，向下穿过膈肌，依次属上、中、下三焦。支脉从膻中上行出缺盆，上项系耳后，上行出耳上角，前下行经面颊至目眶下。另一支脉从耳后入耳中，出走耳前，与前一脉交于面颊部，至目外眦丝竹空穴，与足少阳胆经交接。',NULL,'中医知识库','手少阳三焦经','三焦经起于无名指沿上肢外侧中线至头','2026-04-17 06:30:00.000000',NULL,NULL,'手少阳三焦经；循行路线；起于无名指端；属三焦络心包',NULL,NULL,NULL,NULL,'经络学说','手少阳三焦经的循行路线是怎样的？','经络学说',NULL,'理论','手少阳三焦经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(579,'手少阳三焦经主治侧头耳病（偏头痛、耳聋、耳鸣）、胸胁痛、肩臂外侧痛及经脉循行部位病证。',NULL,'手少阳三焦经主治概要：一是侧头部病证——偏头痛、耳鸣、耳聋。二是胸胁病证——胸胁胀满、胁痛。三是经脉循行部位病证——肩臂外侧痛、肘臂挛痛、手指麻木。四是其他——热病、咽喉肿痛、目赤肿痛。三焦经以外关、翳风最为常用。',NULL,'中医知识库','手少阳三焦经','三焦经主治侧头耳病和肩臂痛','2026-04-17 06:30:00.000000',NULL,NULL,'三焦经主治；偏头痛；耳病；肩臂痛',NULL,NULL,NULL,NULL,'经络学说','手少阳三焦经的主治概要是什么？','经络学说',NULL,'理论','手少阳三焦经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(580,'外关穴在前臂背侧，当阳池与肘尖连线上，腕横纹上2寸，尺骨与桡骨之间。主治偏头痛、耳鸣、热病、上肢痹痛，为八脉交会穴通阳维脉。',NULL,'外关穴是手少阳三焦经的络穴，为八脉交会穴通阳维脉。定位：在前臂背侧，当阳池与肘尖连线上，腕横纹上2寸，尺骨与桡骨之间。主治：偏头痛、耳鸣、耳聋、目赤肿痛、热病、上肢痹痛、肘臂挛痛、手指疼痛。本穴通阳维脉，有疏风解表、通经活络的作用。直刺0.5~1寸。',NULL,'中医知识库','手少阳三焦经','外关为三焦经络穴通阳维脉','2026-04-17 06:30:00.000000',NULL,NULL,'外关穴；定位；主治；络穴；通阳维脉',NULL,NULL,NULL,NULL,'经络学说','外关穴的定位与主治是什么？','经络学说',NULL,'理论','手少阳三焦经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(581,'支沟穴在前臂背侧，当阳池与肘尖连线上，腕横纹上3寸，尺骨与桡骨之间。主治便秘、胁痛、耳鸣、热病，为三焦经经穴。',NULL,'支沟穴是手少阳三焦经的经穴。定位：在前臂背侧，当阳池与肘尖连线上，腕横纹上3寸，尺骨与桡骨之间。主治：便秘、胁肋疼痛、耳鸣、耳聋、暴喑、热病。本穴为治疗便秘的要穴，有清热通便的作用。常配照海、足三里治便秘。直刺0.5~1寸。',NULL,'中医知识库','手少阳三焦经','支沟为三焦经经穴善治便秘','2026-04-17 06:30:00.000000',NULL,NULL,'支沟穴；定位；主治；经穴；便秘',NULL,NULL,NULL,NULL,'经络学说','支沟穴的定位与主治是什么？','经络学说',NULL,'理论','手少阳三焦经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(582,'翳风穴在耳垂后方，当乳突与下颌角之间的凹陷中。主治耳聋、耳鸣、面瘫、牙痛、腮腺炎。',NULL,'翳风穴定位：在耳垂后方，当乳突与下颌角之间的凹陷中。主治：耳聋、耳鸣、面瘫、口眼歪斜、牙痛、颊肿、腮腺炎。本穴为治疗耳部和面部疾病的常用穴。直刺0.8~1.2寸。',NULL,'中医知识库','手少阳三焦经','翳风主治耳部和面部疾病','2026-04-17 06:30:00.000000',NULL,NULL,'翳风穴；定位；主治；耳病面瘫',NULL,NULL,NULL,NULL,'经络学说','翳风穴的定位与主治是什么？','经络学说',NULL,'理论','手少阳三焦经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(583,'三焦经病证表现为耳聋、耳鸣、嗌肿喉痹、汗出、目锐眦痛、颊痛、耳后肩臑肘臂外皆痛。',NULL,'手少阳三焦经病候：是动病——耳聋，浑浑焞焞，嗌肿喉痹。是主气所生病——汗出，目锐眦痛，颊痛，耳后、肩、臑、肘、臂外皆痛，小指次指不用。三焦经循行经过耳部和上肢外侧，故病候以这些部位为主。',NULL,'中医知识库','手少阳三焦经','三焦经病候以耳病上肢外痛为主','2026-04-17 06:30:00.000000',NULL,NULL,'三焦经病理；是动病；是主气所生病',NULL,NULL,NULL,NULL,'经络学说','手少阳三焦经的病理表现有哪些？','经络学说',NULL,'理论','手少阳三焦经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(584,'手少阳三焦经临床用于治疗偏头痛、耳聋耳鸣、面瘫、便秘、上肢外侧疼痛等。外关、翳风为常用穴。',NULL,'手少阳三焦经临床应用：耳病——耳聋耳鸣取翳风、外关、听会。面瘫——翳风配地仓、颊车。偏头痛——外关配风池、太阳。便秘——支沟配天枢、足三里。上肢病——外关配曲池治肘臂痛。三焦经常与心包经、胆经配合使用。',NULL,'中医知识库','手少阳三焦经','三焦经临床治耳病偏头痛便秘','2026-04-17 06:30:00.000000',NULL,NULL,'三焦经临床应用；偏头痛；耳病；便秘',NULL,NULL,NULL,NULL,'经络学说','手少阳三焦经的临床应用有哪些？','经络学说',NULL,'理论','手少阳三焦经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(585,'三焦经脉病候表现为耳聋浑浑焞焞、咽喉肿痛、汗出、目外眦痛、耳后肩臑肘臂外侧皆痛。',NULL,'手少阳三焦经脉病候：是动病——耳聋浑浑焞焞，嗌肿喉痹。是主气所生病——汗出，目锐眦痛，颊痛，耳后、肩、臑、肘、臂外皆痛，小指次指不用。三焦经的病候与其循行路线密切相关。',NULL,'中医知识库','手少阳三焦经','三焦经病候循经分布','2026-04-17 06:30:00.000000',NULL,NULL,'三焦经脉病候；耳聋；浑浑焞焞',NULL,NULL,NULL,NULL,'经络学说','手少阳三焦经的经脉病候是什么？','经络学说',NULL,'理论','手少阳三焦经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(586,'手少阳三焦经属三焦络心包，手厥阴心包经属心包络三焦，两经互为表里。三焦经属阳为表，心包经属阴为里。',NULL,'三焦经与心包经的表里关系：三焦经属阳为表，心包经属阴为里。手少阳三焦经属三焦络心包，手厥阴心包经属心包络三焦。三焦为元气和水液通道，心包为心之外卫。临床常内关配外关治疗胸部和上肢疾病。',NULL,'中医知识库','手少阳三焦经','三焦经心包经互为表里','2026-04-17 06:30:00.000000',NULL,NULL,'三焦经心包经；表里关系',NULL,NULL,NULL,NULL,'经络学说','手少阳三焦经与手厥阴心包经的表里关系是怎样的？','经络学说',NULL,'理论','手少阳三焦经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(587,'手少阳三焦经腧穴以治疗耳部和侧头部病证为特色。穴性偏于疏风清热、通经活络。',NULL,'手少阳三焦经腧穴主治特点：以治疗耳部和侧头部疾病为核心。络穴外关善疏风解表通络，经穴支沟善通便，翳风善治耳面疾病。三焦经穴位大多有疏风清热、通经活络的作用。',NULL,'中医知识库','手少阳三焦经','三焦经穴以治耳病侧头痛为特色','2026-04-17 06:30:00.000000',NULL,NULL,'三焦经腧穴主治；耳部；疏风清热',NULL,NULL,NULL,NULL,'经络学说','手少阳三焦经的腧穴主治特点是什么？','经络学说',NULL,'理论','手少阳三焦经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(588,'足少阳胆经起于目外眦（瞳子髎），上行至额角，下行耳后，沿颈侧至肩上，交出手少阳三焦经后入缺盆。分支从耳后入耳中出走耳前。下行支从缺盆下腋，沿胸侧过季肋，下行至环跳，沿大腿外侧下行，经膝外侧，沿小腿外侧下行，出外踝前，至足第四趾端。',NULL,'足少阳胆经起于目外眦瞳子髎，上行至额角，下行耳后风池穴，沿颈侧至肩上，交出手少阳之后入缺盆。支脉从耳后入耳中出走耳前至目外眦后方。支脉从目外眦下行至大迎，会合手少阳抵目眶下，经颊车至颈。下行支从缺盆下腋，沿胸侧过季肋，经环跳穴，沿大腿外侧下行，经膝外侧阳陵泉，沿小腿外侧下行至外踝前丘墟穴，沿足背至第四趾端足窍阴穴。支脉从足背分出至大趾端，与足厥阴肝经交接。',NULL,'中医知识库','足少阳胆经','胆经起于目外眦沿体侧下行至四趾','2026-04-17 06:30:00.000000',NULL,NULL,'足少阳胆经；循行路线；起于目外眦；属胆络肝',NULL,NULL,NULL,NULL,'经络学说','足少阳胆经的循行路线是怎样的？','经络学说',NULL,'理论','足少阳胆经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(589,'足少阳胆经主治侧头耳目病（偏头痛、耳聋、目赤）、胸胁病（胁痛、口苦）及经脉循行部位病证。',NULL,'足少阳胆经主治概要：一是侧头耳目病证——偏头痛、耳聋、耳鸣、目赤肿痛。二是胸胁病证——胁肋疼痛、口苦、善太息。三是经脉循行部位病证——肩颈痛、腰腿痛、膝外侧痛、小腿外侧痛、足背痛。四是其他——疟疾、热病。胆经以风池、环跳、阳陵泉最为常用。',NULL,'中医知识库','足少阳胆经','胆经主治侧头耳目和胸胁病证','2026-04-17 06:30:00.000000',NULL,NULL,'胆经主治；偏头痛；胁痛；耳病',NULL,NULL,NULL,NULL,'经络学说','足少阳胆经的主治概要是什么？','经络学说',NULL,'理论','足少阳胆经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(590,'风池穴在项部，当枕骨之下，与风府相平，胸锁乳突肌与斜方肌上端之间的凹陷处。主治头痛、眩晕、颈项强痛、感冒、中风。',NULL,'风池穴是足少阳胆经与阳维脉的交会穴。定位：在项部，当枕骨之下，与风府穴相平，胸锁乳突肌与斜方肌上端之间的凹陷处。主治：头痛、眩晕、颈项强痛、感冒、中风、口眼歪斜、目赤肿痛、鼻塞、鼻渊、耳鸣。本穴为治疗头面部疾病的常用穴，有疏风解表、清头明目的作用。向鼻尖方向斜刺0.5~0.8寸，不可向上深刺。',NULL,'中医知识库','足少阳胆经','风池为疏风解表清头明目要穴','2026-04-17 06:30:00.000000',NULL,NULL,'风池穴；定位；主治；疏风要穴',NULL,NULL,NULL,NULL,'经络学说','风池穴的定位与主治是什么？','经络学说',NULL,'理论','足少阳胆经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(591,'环跳穴在股外侧部，侧卧屈股，当股骨大转子最凸点与骶管裂孔连线的外1/3与中1/3交点处。主治腰腿痛、下肢痿痹、坐骨神经痛。',NULL,'环跳穴是足少阳胆经与足太阳膀胱经的交会穴。定位：在股外侧部，侧卧屈股，当股骨大转子最凸点与骶管裂孔连线的外1/3与中1/3交点处。主治：腰腿痛、下肢痿痹、半身不遂、坐骨神经痛。本穴为治疗腰腿痛和坐骨神经痛的要穴。直刺2~3寸。',NULL,'中医知识库','足少阳胆经','环跳为治腰腿痛坐骨神经痛要穴','2026-04-17 06:30:00.000000',NULL,NULL,'环跳穴；定位；主治；坐骨神经痛',NULL,NULL,NULL,NULL,'经络学说','环跳穴的定位与主治是什么？','经络学说',NULL,'理论','足少阳胆经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(592,'阳陵泉在小腿外侧，当腓骨小头前下方凹陷处。主治胁痛、口苦、黄疸、膝痛、下肢痿痹，为八会穴之筋会。',NULL,'阳陵泉穴是足少阴胆经的合穴，为八会穴之筋会。定位：在小腿外侧，当腓骨小头前下方凹陷处。主治：胁肋疼痛、口苦、呕吐、黄疸、膝肿痛、下肢痿痹、半身不遂、小儿惊风。本穴为筋会，有疏肝利胆、舒筋活络的作用，是治疗筋脉疾病的要穴。直刺1~1.5寸。',NULL,'中医知识库','足少阳胆经','阳陵泉为筋会疏肝利胆舒筋','2026-04-17 06:30:00.000000',NULL,NULL,'阳陵泉；定位；主治；合穴；筋会',NULL,NULL,NULL,NULL,'经络学说','阳陵泉穴的定位与主治是什么？','经络学说',NULL,'理论','足少阳胆经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(593,'悬钟穴在小腿外侧，当外踝尖上3寸，腓骨前缘。主治颈项强痛、胸胁胀满、下肢痿痹，为八会穴之髓会。',NULL,'悬钟穴又名绝骨，为八会穴之髓会。定位：在小腿外侧，当外踝尖上3寸，腓骨前缘。主治：颈项强痛、胸胁胀满、下肢痿痹、脚气、痔血。本穴为髓会，有填精充髓、舒筋活络的作用。常配肾俞、太溪治下肢痿软无力。直刺0.5~0.8寸。',NULL,'中医知识库','足少阳胆经','悬钟为髓会舒筋活络','2026-04-17 06:30:00.000000',NULL,NULL,'悬钟穴；定位；主治；髓会',NULL,NULL,NULL,NULL,'经络学说','悬钟穴的定位与主治是什么？','经络学说',NULL,'理论','足少阳胆经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(594,'足临泣在足背外侧，当第4跖趾关节后方，小趾伸肌腱外侧凹陷处。主治偏头痛、目赤、胁痛、月经不调，为输穴通带脉。',NULL,'足临泣穴是足少阳胆经的输穴，为八脉交会穴通带脉。定位：在足背外侧，当第4跖趾关节后方，小趾伸肌腱外侧凹陷处。主治：偏头痛、目赤肿痛、目眩、耳鸣、胁肋疼痛、乳房胀痛、月经不调。本穴通带脉，有疏肝利胆的作用。直刺0.5~0.8寸。',NULL,'中医知识库','足少阳胆经','足临泣为胆经输穴通带脉','2026-04-17 06:30:00.000000',NULL,NULL,'足临泣；定位；主治；输穴；通带脉',NULL,NULL,NULL,NULL,'经络学说','足临泣穴的定位与主治是什么？','经络学说',NULL,'理论','足少阳胆经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(595,'胆经病证表现为口苦、善太息、心胁痛、不能转侧、头痛颌痛、目锐眦痛、缺盆中肿痛、腋下肿、汗出振寒、疟。',NULL,'足少阳胆经病候：是动病——口苦，善太息，心胁痛，不能转侧，甚则面微有尘，体无膏泽，足外反热，是为阳厥。是主骨所生病——头痛，颌痛，目锐眦痛，缺盆中肿痛，腋下肿，马刀侠瘿，汗出振寒，疟，胸、胁、肋、髀、膝外至胫、绝骨、外踝前及诸节皆痛，小指次指不用。',NULL,'中医知识库','足少阳胆经','胆经病候以口苦胁痛体侧痛为特征','2026-04-17 06:30:00.000000',NULL,NULL,'胆经病理；是动病；是主骨所生病',NULL,NULL,NULL,NULL,'经络学说','足少阳胆经的病理表现有哪些？','经络学说',NULL,'理论','足少阳胆经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(596,'足少阳胆经腧穴以治疗侧头部和胆腑疾病为特色。穴性偏于疏肝利胆、疏通经络。',NULL,'足少阳胆经腧穴主治特点：以治疗侧头耳目疾病和胆腑病为核心。合穴阳陵泉善疏肝利胆，筋会善舒筋活络；风池善疏风解表清头目；环跳善治腰腿痛。胆经穴位大多有疏肝利胆、疏通经络的作用，临床广泛应用于偏头痛、胁痛、腰腿痛等。',NULL,'中医知识库','足少阳胆经','胆经穴以疏肝利胆通络为特色','2026-04-17 06:30:00.000000',NULL,NULL,'胆经腧穴主治；疏肝利胆；侧头耳目',NULL,NULL,NULL,NULL,'经络学说','足少阳胆经的腧穴主治特点是什么？','经络学说',NULL,'理论','足少阳胆经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(597,'足少阳胆经临床用于治疗偏头痛、落枕、颈椎病、胁痛、坐骨神经痛、膝关节炎、面瘫等。',NULL,'足少阳胆经临床应用：偏头痛——风池配外关、太阳。落枕——风池配后溪。胁痛——阳陵泉配太冲。坐骨神经痛——环跳配委中、阳陵泉。膝痛——阳陵泉配犊鼻。面瘫——风池配翳风、地仓。胆经在体侧分布广泛，是治疗半身疾病的重要经脉。',NULL,'中医知识库','足少阳胆经','胆经临床治侧头痛腰腿痛面瘫','2026-04-17 06:30:00.000000',NULL,NULL,'胆经临床应用；偏头痛；坐骨神经痛；胁痛',NULL,NULL,NULL,NULL,'经络学说','足少阳胆经的临床应用有哪些？','经络学说',NULL,'理论','足少阳胆经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(598,'胆经脉病候表现为口苦、善太息、面有尘色、足外侧发热、头痛、目外眦痛、胸胁以下至足外侧各关节疼痛。',NULL,'足少阳胆经脉病候：是动病——口苦，善太息，心胁痛不能转侧，甚则面微有尘，体无膏泽，足外反热，是为阳厥。是主骨所生病——头痛颌痛，目锐眦痛，缺盆中肿痛，腋下肿，马刀侠瘿，汗出振寒，疟，胸胁肋髀膝外至胫绝骨外踝前及诸节皆痛，小指次指不用。',NULL,'中医知识库','足少阳胆经','胆经病候以体侧疼痛口苦为特征','2026-04-17 06:30:00.000000',NULL,NULL,'胆经脉病候；口苦；阳厥',NULL,NULL,NULL,NULL,'经络学说','足少阳胆经的经脉病候是什么？','经络学说',NULL,'理论','足少阳胆经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(599,'足少阳胆经属胆络肝，足厥阴肝经属肝络胆，两经互为表里。胆经属阳为表，肝经属阴为里。',NULL,'胆经与肝经的表里关系：胆经属阳为表，肝经属阴为里。足少阳胆经属胆络肝，足厥阴肝经属肝络胆。生理上肝主疏泄，胆贮藏排泄胆汁，共同参与消化和情志调节。病理上肝气郁结可影响胆汁排泄，胆热也可影响肝的疏泄。治疗时常配伍，如太冲配阳陵泉治胁痛。',NULL,'中医知识库','足少阳胆经','胆经肝经互为表里疏泄胆汁','2026-04-17 06:30:00.000000',NULL,NULL,'胆经肝经；表里关系；肝主疏泄',NULL,NULL,NULL,NULL,'经络学说','足少阳胆经与足厥阴肝经的表里关系是怎样的？','经络学说',NULL,'理论','足少阳胆经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(600,'足少阳胆经腧穴分布在目外眦、耳后、头侧、项部、肩部、胸胁部、腰臀部、下肢外侧和足背，共44穴。',NULL,'足少阳胆经腧穴分部：头部——瞳子髎、听会、上关、颔厌等。项肩部——风池、肩井。胸胁部——渊腋、辄筋、日月、京门、带脉等。腰臀部——环跳。下肢外侧——风市、中渎、膝阳关、阳陵泉、阳交、外丘、光明、阳辅、悬钟。足背——丘墟、足临泣、侠溪、足窍阴。共44穴。',NULL,'中医知识库','足少阳胆经','胆经44穴沿体侧分布','2026-04-17 06:30:00.000000',NULL,NULL,'胆经腧穴分部；44穴；体侧分布',NULL,NULL,NULL,NULL,'经络学说','足少阳胆经的腧穴如何分部？','经络学说',NULL,'理论','足少阳胆经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(601,'足少阳胆经的络脉从光明穴分出，走向足厥阴肝经，向下联络足背。',NULL,'足少阳胆经的络脉名曰光明。从外踝上5寸的光明穴处分出，走向足厥阴肝经，向下联络足背。病候：实证——突然气绝不省人事；虚证——足部痿软无力不能行走。治疗取光明穴。',NULL,'中医知识库','足少阳胆经','胆经络脉从光明分出沟通肝经','2026-04-17 06:30:00.000000',NULL,NULL,'胆经络脉；光明；沟通肝经',NULL,NULL,NULL,NULL,'经络学说','足少阳胆经的络脉是怎样的？','经络学说',NULL,'理论','足少阳胆经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(602,'丘墟穴在足外踝前下方，当趾长伸肌腱外侧凹陷处。主治胸胁胀痛、下肢痿痹、外踝肿痛，为胆经原穴。',NULL,'丘墟穴是足少阳胆经的原穴。定位：在足外踝前下方，当趾长伸肌腱外侧凹陷处。主治：胸胁胀痛、下肢痿痹、外踝肿痛、颈项痛。本穴为胆经原穴，有疏肝利胆的作用。直刺0.5~0.8寸。',NULL,'中医知识库','足少阳胆经','丘墟为胆经原穴疏肝利胆','2026-04-17 06:30:00.000000',NULL,NULL,'丘墟穴；定位；主治；原穴',NULL,NULL,NULL,NULL,'经络学说','丘墟穴的定位与主治是什么？','经络学说',NULL,'理论','足少阳胆经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(603,'足厥阴肝经起于足大趾背毫毛处（大敦穴），沿足背上行至内踝前，沿小腿内侧上行，交足太阴之后，上膝内侧，沿大腿内侧入阴毛中，环绕阴器，上达小腹，挟胃属肝络胆，上贯膈，布胁肋，沿喉咙后方入鼻咽部，连目系，上出额部与督脉交会于巅。',NULL,'足厥阴肝经起于足大趾背毫毛处大敦穴，沿足背第1、2跖骨间上行，经内踝前缘上行，沿小腿内侧中线上行，至内踝上8寸处交出足太阴脾经之后，上膝内侧，沿大腿内侧中线入阴毛中，环绕生殖器，上达小腹，挟胃两旁，入属肝脏，联络胆腑，向上穿过膈肌，分布于胁肋部，沿喉咙后方上行至鼻咽部，连目系（眼球与脑相连的脉络），上出额部，与督脉会于巅顶。支脉从目系下行面颊里，环绕唇内。另一支脉从肝分出穿过膈肌注入肺中。',NULL,'中医知识库','足厥阴肝经','肝经起于大趾沿下肢内侧上行属肝络胆','2026-04-17 06:30:00.000000',NULL,NULL,'足厥阴肝经；循行路线；起于大趾；属肝络胆',NULL,NULL,NULL,NULL,'经络学说','足厥阴肝经的循行路线是怎样的？','经络学说',NULL,'理论','足厥阴肝经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(604,'足厥阴肝经主治肝病（胁痛、黄疸、头痛眩晕）、妇科病（月经不调、痛经）、前阴病及经脉循行部位病证。',NULL,'足厥阴肝经主治概要：一是肝病——胁肋疼痛、黄疸、头痛眩晕、口苦。二是妇科病证——月经不调、痛经、闭经、带下。三是前阴病证——疝气、遗精、小便不利。四是神志病——癫狂、痫证、善怒。五是经脉循行部位病证——下肢内侧痛、足跗肿痛。肝经以太冲、期门最为常用。',NULL,'中医知识库','足厥阴肝经','肝经主治肝胆妇科前阴病证','2026-04-17 06:30:00.000000',NULL,NULL,'肝经主治；肝病；妇科病；前阴病',NULL,NULL,NULL,NULL,'经络学说','足厥阴肝经的主治概要是什么？','经络学说',NULL,'理论','足厥阴肝经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(605,'太冲穴在足背，当第1、2跖骨结合部前方凹陷处。主治头痛、眩晕、胁痛、月经不调、癫痫、急躁易怒，为肝经输穴和原穴。',NULL,'太冲穴是足厥阴肝经的输穴和原穴。定位：在足背，当第1、2跖骨结合部前方凹陷处。主治：头痛、眩晕、目赤肿痛、口苦、胁肋疼痛、疝气、月经不调、遗尿、小儿惊风、癫狂、痫证、下肢痿痹。本穴为肝经原穴，有疏肝解郁、平肝潜阳、清肝泻火的作用，是临床最常用的穴位之一。直刺0.5~0.8寸。',NULL,'中医知识库','足厥阴肝经','太冲为肝经原穴疏肝解郁要穴','2026-04-17 06:30:00.000000',NULL,NULL,'太冲穴；定位；主治；原穴；疏肝要穴',NULL,NULL,NULL,NULL,'经络学说','太冲穴的定位与主治是什么？','经络学说',NULL,'理论','足厥阴肝经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(606,'期门穴在胸部，当乳头直下，第6肋间隙，前正中线旁开4寸。主治胸胁胀痛、呕吐、呃逆、乳痈，为肝之募穴。',NULL,'期门穴是足厥阴肝经的募穴。定位：在胸部，当乳头直下，第6肋间隙，前正中线旁开4寸。主治：胸胁胀痛、呕吐、呃逆、腹胀、乳痈、郁证。本穴为肝之募穴，是肝气聚会之处，有疏肝理气、和胃降逆的作用。斜刺或平刺0.5~0.8寸，不可深刺。',NULL,'中医知识库','足厥阴肝经','期门为肝募穴疏肝理气','2026-04-17 06:30:00.000000',NULL,NULL,'期门穴；定位；主治；肝之募穴',NULL,NULL,NULL,NULL,'经络学说','期门穴的定位与主治是什么？','经络学说',NULL,'理论','足厥阴肝经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(607,'行间穴在足背，当第1、2趾间，趾蹼缘后方赤白肉际处。主治头痛、目赤肿痛、胁痛、月经不调、中风，为肝经荥穴。',NULL,'行间穴是足厥阴肝经的荥穴。定位：在足背，当第1、2趾间，趾蹼缘后方赤白肉际处。主治：头痛、眩晕、目赤肿痛、口歪、胁痛、疝气、月经不调、痛经、中风。本穴有清肝泻火、疏肝理气的作用。直刺0.5~0.8寸。',NULL,'中医知识库','足厥阴肝经','行间为肝经荥穴清肝泻火','2026-04-17 06:30:00.000000',NULL,NULL,'行间穴；定位；主治；荥穴',NULL,NULL,NULL,NULL,'经络学说','行间穴的定位与主治是什么？','经络学说',NULL,'理论','足厥阴肝经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(608,'蠡沟穴在小腿内侧，当足内踝尖上5寸，胫骨内侧面的中央。主治月经不调、赤白带下、小便不利、足胫痿痹，为肝经络穴。',NULL,'蠡沟穴是足厥阴肝经的络穴。定位：在小腿内侧，当足内踝尖上5寸，胫骨内侧面的中央。主治：月经不调、赤白带下、阴挺、小便不利、疝气、足胫痿痹。本穴为肝经络穴，沟通肝经与胆经。直刺0.5~0.8寸。',NULL,'中医知识库','足厥阴肝经','蠡沟为肝经络穴治妇科前阴病','2026-04-17 06:30:00.000000',NULL,NULL,'蠡沟穴；定位；主治；络穴',NULL,NULL,NULL,NULL,'经络学说','蠡沟穴的定位与主治是什么？','经络学说',NULL,'理论','足厥阴肝经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(609,'肝经病证表现为腰痛不可以俯仰、丈夫㿉疝、妇人少腹肿、嗌干、面尘脱色、胸满呕逆。',NULL,'足厥阴肝经病候：是动病——腰痛不可以俯仰，丈夫㿉疝，妇人少腹肿，甚则嗌干，面尘脱色。是主肝所生病——胸满，呕逆，飧泄，狐疝，遗溺，闭癃。肝经病候以腰腹疼痛、生殖系统症状和情志症状为主。',NULL,'中医知识库','足厥阴肝经','肝经病候以腰腹疼痛生殖症状为主','2026-04-17 06:30:00.000000',NULL,NULL,'肝经病理；是动病；是主肝所生病',NULL,NULL,NULL,NULL,'经络学说','足厥阴肝经的病理表现有哪些？','经络学说',NULL,'理论','足厥阴肝经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(610,'足厥阴肝经腧穴以治疗肝胆疾病和妇科疾病为特色。穴性偏于疏肝理气、清肝泻火。',NULL,'足厥阴肝经腧穴主治特点：以治疗肝胆病和妇科病为核心。原穴太冲善疏肝解郁，荥穴行间善清肝泻火，募穴期门善疏肝理气，络穴蠡沟善调妇科。肝经穴位大多有疏肝理气的作用，临床广泛应用于情志病、妇科病和肝胆病。',NULL,'中医知识库','足厥阴肝经','肝经穴以疏肝理气为核心','2026-04-17 06:30:00.000000',NULL,NULL,'肝经腧穴主治；疏肝理气；妇科',NULL,NULL,NULL,NULL,'经络学说','足厥阴肝经的腧穴主治特点是什么？','经络学说',NULL,'理论','足厥阴肝经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(611,'足厥阴肝经临床用于治疗头痛眩晕、高血压、胁痛、月经不调、痛经、情志病等。太冲穴最为常用。',NULL,'足厥阴肝经临床应用：头痛眩晕——太冲配风池、百会。高血压——太冲配曲池。胁痛——太冲配阳陵泉、期门。月经不调——太冲配三阴交、血海。痛经——太冲配三阴交。情志病——太冲配神门、内关。太冲穴为临床最常用的穴位之一，应用范围极广。',NULL,'中医知识库','足厥阴肝经','肝经临床以治肝病妇科为主','2026-04-17 06:30:00.000000',NULL,NULL,'肝经临床应用；头痛；高血压；妇科',NULL,NULL,NULL,NULL,'经络学说','足厥阴肝经的临床应用有哪些？','经络学说',NULL,'理论','足厥阴肝经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(612,'肝经脉病候表现为腰痛不能俯仰、疝气、少腹肿、咽喉干燥、面色晦暗、胸满呕逆、泄泻、遗尿。',NULL,'足厥阴肝经脉病候：是动病——腰痛不可以俯仰，丈夫㿉疝，妇人少腹肿，甚则嗌干，面尘脱色。是主肝所生病——胸满，呕逆，飧泄，狐疝，遗溺，闭癃。肝经循行经过生殖器和少腹，故这些部位的病变为肝经所主。',NULL,'中医知识库','足厥阴肝经','肝经病候循经涉及腰腹生殖','2026-04-17 06:30:00.000000',NULL,NULL,'肝经脉病候；腰痛；疝气；遗溺',NULL,NULL,NULL,NULL,'经络学说','足厥阴肝经的经脉病候是什么？','经络学说',NULL,'理论','足厥阴肝经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(613,'足厥阴肝经属肝络胆，足少阳胆经属胆络肝，两经互为表里。肝经属阴为里，胆经属阳为表。',NULL,'肝经与胆经的表里关系：肝经属阴为里，胆经属阳为表。足厥阴肝经属肝络胆，足少阳胆经属胆络肝。肝主疏泄、藏血，胆贮藏排泄胆汁，肝胆相表里。临床常配伍取穴，如太冲配阳陵泉治胁痛，期门配日月治胆病。',NULL,'中医知识库','足厥阴肝经','肝经胆经互为表里肝胆同治','2026-04-17 06:30:00.000000',NULL,NULL,'肝经胆经；表里关系；肝胆相表里',NULL,NULL,NULL,NULL,'经络学说','足厥阴肝经与足少阳胆经的表里关系是怎样的？','经络学说',NULL,'理论','足厥阴肝经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(614,'足厥阴肝经腧穴分布在足大趾背、足背内侧、小腿内侧、大腿内侧、阴部和胸胁部，共14穴。',NULL,'足厥阴肝经腧穴分部：足部——大敦（大趾外侧）、行间、太冲、中封。小腿——蠡沟、中都、膝关。大腿——曲泉、阴包、足五里、阴廉。腹部——急脉。胸部——章门、期门。共14穴。',NULL,'中医知识库','足厥阴肝经','肝经14穴从大趾至胸部分布','2026-04-17 06:30:00.000000',NULL,NULL,'肝经腧穴分部；14穴；下肢内侧至胸',NULL,NULL,NULL,NULL,'经络学说','足厥阴肝经的腧穴如何分部？','经络学说',NULL,'理论','足厥阴肝经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(615,'足厥阴肝经的络脉从蠡沟穴分出，走向足少阳胆经。其别支沿小腿上行至睾丸，聚于阴茎。',NULL,'足厥阴肝经的络脉名曰蠡沟。从内踝上5寸蠡沟穴处分出，走向足少阳胆经。其别支沿胫骨上至睾丸，聚于阴茎。病候：实证——阴茎勃起异常；虚证——阴部瘙痒。治疗取蠡沟穴。',NULL,'中医知识库','足厥阴肝经','肝经络脉从蠡沟分出联络前阴','2026-04-17 06:30:00.000000',NULL,NULL,'肝经络脉；蠡沟；沟通胆经',NULL,NULL,NULL,NULL,'经络学说','足厥阴肝经的络脉是怎样的？','经络学说',NULL,'理论','足厥阴肝经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(616,'足厥阴肝经的经筋起于足大趾之上，上结于内踝之前，沿胫骨上行结于膝内辅骨，沿大腿内侧上行结于阴器，联络各经筋。',NULL,'足厥阴肝经的经筋起于足大趾之上，上结于内踝之前，沿胫骨内侧上行，结于胫骨内髁，沿大腿内侧上行结于阴器，与各经筋相联络。经筋病候主要表现为循行部位的筋脉拘挛、疼痛和功能障碍。',NULL,'中医知识库','足厥阴肝经','肝经经筋从大趾至阴器','2026-04-17 06:30:00.000000',NULL,NULL,'肝经经筋；大趾至阴器',NULL,NULL,NULL,NULL,'经络学说','足厥阴肝经的经筋是怎样的？','经络学说',NULL,'理论','足厥阴肝经','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(617,'曲泉穴在膝内侧，屈膝当膝关节内侧面横纹内侧端，半腱肌、半膜肌止端的前缘凹陷处。主治膝痛、月经不调、痛经、遗精、阴痒，为肝经合穴。',NULL,'曲泉穴是足厥阴肝经的合穴。定位：在膝内侧，屈膝，当膝关节内侧面横纹内侧端，半腱肌、半膜肌止端的前缘凹陷处。主治：膝痛、月经不调、痛经、遗精、阳痿、阴痒、小便不利。本穴有清利湿热、调理经血的作用。直刺1~1.5寸。',NULL,'中医知识库','足厥阴肝经','曲泉为肝经合穴清利湿热','2026-04-17 06:30:00.000000',NULL,NULL,'曲泉穴；定位；主治；合穴',NULL,NULL,NULL,NULL,'经络学说','曲泉穴的定位与主治是什么？','经络学说',NULL,'理论','足厥阴肝经','入门','2026-04-20 23:49:54.000000',NULL,NULL),(618,'督脉起于胞中，下出会阴，沿脊柱内上行至项后风府穴处入脑，上巅顶，沿前额下行至鼻柱，止于上唇内龈交穴。',NULL,'督脉起于胞中（小腹内），下出会阴部，向后沿脊柱内上行，至项后风府穴处进入脑内，上行巅顶百会穴，沿前额下行鼻柱，至上唇系带处龈交穴。其支脉络肾。另一支脉从小腹内直上，穿过脐中，上贯心，入喉，上颐环唇，上系两目之下。督脉为\"阳脉之海\"，总督一身之阳经。',NULL,'中医知识库','督脉','督脉沿脊柱上行入脑总督诸阳','2026-04-17 06:30:00.000000',NULL,NULL,'督脉；循行路线；起于胞中；阳脉之海',NULL,NULL,NULL,NULL,'经络学说','督脉的循行路线是怎样的？','经络学说',NULL,'理论','督脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(619,'督脉主治神志病（癫狂、痫证、失眠）、热病、腰骶痛、头痛、项强，以及相应的内脏病证。督脉为阳脉之海。',NULL,'督脉主治概要：一是神志病——癫狂、痫证、失眠、中风昏迷。二是热病——发热、中暑。三是头项病——头痛、项强、眩晕。四是腰脊病——腰脊强痛。五是前阴病——遗精、阳痿、不孕。六是妇科病——月经不调、带下。督脉为阳脉之海，调节全身阳气，以百会、大椎、命门最为常用。',NULL,'中医知识库','督脉','督脉主治神志热病腰脊病','2026-04-17 06:30:00.000000',NULL,NULL,'督脉主治；神志病；热病；腰脊病',NULL,NULL,NULL,NULL,'经络学说','督脉的主治概要是什么？','经络学说',NULL,'理论','督脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(620,'百会穴在头部，当前发际正中直上5寸，或两耳尖连线的中点处。主治头痛、眩晕、中风昏迷、脱肛、子宫脱垂，有升阳举陷作用。',NULL,'百会穴定位：在头部，当前发际正中直上5寸，或两耳尖连线与头正中线的交点处。主治：头痛、眩晕、中风昏迷、癫狂、痫证、脱肛、阴挺（子宫脱垂）、胃下垂、失眠。本穴为督脉与诸阳经交会穴，有醒脑开窍、升阳举陷的作用，是治疗神志病和气虚下陷证的要穴。平刺0.5~0.8寸，可灸。',NULL,'中医知识库','督脉','百会为诸阳之会升阳举陷醒脑','2026-04-17 06:30:00.000000',NULL,NULL,'百会穴；定位；主治；升阳举陷；醒脑开窍',NULL,NULL,NULL,NULL,'经络学说','百会穴的定位与主治是什么？','经络学说',NULL,'理论','督脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(621,'大椎穴在后正中线上，第7颈椎棘突下凹陷中。主治发热、感冒、咳嗽、项强、癫狂，为退热要穴。',NULL,'大椎穴定位：在后正中线上，第7颈椎棘突下凹陷中。低头时颈后最高骨下方的凹陷处即是。主治：发热、感冒、咳嗽、气喘、项强、肩背痛、癫狂、痫证、疟疾。本穴为督脉与手足三阳经交会穴，有清热解表、疏风散寒的作用，是退热的要穴。向上斜刺0.5~1寸。',NULL,'中医知识库','督脉','大椎为退热要穴疏风解表','2026-04-17 06:30:00.000000',NULL,NULL,'大椎穴；定位；主治；退热要穴',NULL,NULL,NULL,NULL,'经络学说','大椎穴的定位与主治是什么？','经络学说',NULL,'理论','督脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(622,'命门穴在后正中线上，第2腰椎棘突下凹陷中。主治腰痛、遗精、阳痿、月经不调、带下、泄泻，为补肾要穴。',NULL,'命门穴定位：在后正中线上，第2腰椎棘突下凹陷中。约与肋弓下缘相平。主治：腰脊强痛、遗精、阳痿、早泄、月经不调、带下、不孕、五更泄泻、下肢痿痹。本穴有温肾壮阳、强健腰膝的作用，是补肾要穴。向上斜刺0.5~1寸，可灸。',NULL,'中医知识库','督脉','命门为补肾壮阳要穴','2026-04-17 06:30:00.000000',NULL,NULL,'命门穴；定位；主治；补肾壮阳',NULL,NULL,NULL,NULL,'经络学说','命门穴的定位与主治是什么？','经络学说',NULL,'理论','督脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(623,'水沟穴（人中）在面部，当人中沟的上1/3与中1/3交点处。主治昏迷、晕厥、中暑、癫狂、面瘫，为急救要穴。',NULL,'水沟穴又名人中穴。定位：在面部，当人中沟的上1/3与中1/3交点处。主治：昏迷、晕厥、中暑、中风昏迷、癫狂、痫证、面瘫、牙关紧闭、急性腰扭伤。本穴为临床最重要的急救穴之一，有醒脑开窍的作用。向上斜刺0.3~0.5寸，或用指甲按掐。',NULL,'中医知识库','督脉','水沟为急救醒脑要穴','2026-04-17 06:30:00.000000',NULL,NULL,'水沟穴；人中；定位；主治；急救要穴',NULL,NULL,NULL,NULL,'经络学说','水沟穴的定位与主治是什么？','经络学说',NULL,'理论','督脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(624,'腰阳关穴在后正中线上，第4腰椎棘突下凹陷中。主治腰骶疼痛、下肢痿痹、月经不调、遗精、阳痿。',NULL,'腰阳关穴定位：在后正中线上，第4腰椎棘突下凹陷中。约与髂嵴相平。主治：腰骶疼痛、下肢痿痹、月经不调、遗精、阳痿、带下。本穴有温经散寒、舒筋活络的作用。向上斜刺0.5~1寸，可灸。',NULL,'中医知识库','督脉','腰阳关温经散寒治腰骶痛','2026-04-17 06:30:00.000000',NULL,NULL,'腰阳关穴；定位；主治',NULL,NULL,NULL,NULL,'经络学说','腰阳关穴的定位与主治是什么？','经络学说',NULL,'理论','督脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(625,'督脉病候表现为脊柱强直角弓反张、头痛、项强、癫狂、癔病、腰脊痛、不孕、遗精。',NULL,'督脉经脉病候：实则脊柱强直、角弓反张；虚则头重、眩晕。此外还可见癫狂、痫证、癔病等神志病，以及腰脊强痛、不孕、遗精、痔疾等。督脉为阳脉之海，总督诸阳，故病候以阳经和督脉循行部位病变为主。',NULL,'中医知识库','督脉','督脉病候以脊强神志病为主','2026-04-17 06:30:00.000000',NULL,NULL,'督脉病候；脊强；角弓反张；神志病',NULL,NULL,NULL,NULL,'经络学说','督脉的经脉病候是什么？','经络学说',NULL,'理论','督脉','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(626,'长强穴在尾骨端下，当尾骨端与肛门连线的中点处。主治痔疮、脱肛、便秘、腹泻、腰脊痛，为督脉络穴。',NULL,'长强穴是督脉的络穴。定位：在尾骨端下，当尾骨端与肛门连线的中点处。主治：痔疮、脱肛、便秘、腹泻、腰脊疼痛、癫狂、痫证。本穴有清热利湿、固脱止泻的作用。紧靠尾骨前面斜刺0.8~1寸。',NULL,'中医知识库','督脉','长强为督脉络穴治痔疾脱肛','2026-04-17 06:30:00.000000',NULL,NULL,'长强穴；定位；主治；络穴',NULL,NULL,NULL,NULL,'经络学说','长强穴的定位与主治是什么？','经络学说',NULL,'理论','督脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(627,'督脉与任脉同起于胞中，一前一后，督脉行于背主一身之阳，任脉行于腹主一身之阴。阴阳相贯，循环不止。',NULL,'督脉与任脉的关系：两脉同起于胞中（小腹内），一出会阴向后沿脊柱上行，一出会阴向前沿腹部上行，形成前后对应。督脉为\"阳脉之海\"，总督诸阳经；任脉为\"阴脉之海\"，总任诸阴经。两脉在口唇部位相连接，构成阴阳循环。临床常督任配穴，如百会配关元，治疗阴阳失调。',NULL,'中医知识库','督脉','督脉任脉一阳一阴前后相应','2026-04-17 06:30:00.000000',NULL,NULL,'督脉任脉；阴阳；前后对应',NULL,NULL,NULL,NULL,'经络学说','督脉与任脉的关系是怎样的？','经络学说',NULL,'理论','督脉','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(628,'任脉起于胞中，下出会阴，沿腹部正中线上行，经关元、气海、神阙、中脘、膻中，至咽喉，上行环绕口唇，沿面部入目眶下。',NULL,'任脉起于胞中（小腹内），下出会阴部，向前沿腹部正中线上行，经耻骨联合上方，沿腹部正中线，经过关元、气海、神阙、水分、中脘、膻中等穴，至咽喉部，再上行环绕口唇，沿面部进入目眶下。任脉为\"阴脉之海\"，总任一身之阴经，调节月经，妊养胎儿，故称\"任主胞胎\"。',NULL,'中医知识库','任脉','任脉起于胞中沿腹正中上行至面','2026-04-17 06:30:00.000000',NULL,NULL,'任脉；循行路线；起于胞中；阴脉之海',NULL,NULL,NULL,NULL,'经络学说','任脉的循行路线是怎样的？','经络学说',NULL,'理论','任脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(629,'任脉主治腹部及脏腑病证、妇科病（月经不调、不孕）、男科病（遗精、阳痿）、虚证及神志病。',NULL,'任脉主治概要：一是腹部脏腑病证——胃痛、呕吐、腹胀、泄泻。二是妇科病证——月经不调、痛经、闭经、带下、不孕、产后病。三是男科病证——遗精、阳痿、早泄。四是虚证——气虚、血虚、阴虚、阳虚。五是神志病——癫狂、失眠。六是胸肺部病证——咳嗽、气喘。任脉以关元、气海、中脘、膻中最为常用。',NULL,'中医知识库','任脉','任脉主治脏腑妇科男科虚证','2026-04-17 06:30:00.000000',NULL,NULL,'任脉主治；脏腑病；妇科病；虚证',NULL,NULL,NULL,NULL,'经络学说','任脉的主治概要是什么？','经络学说',NULL,'理论','任脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(630,'关元穴在下腹部，前正中线上，当脐中下3寸。主治遗精、阳痿、月经不调、痛经、虚劳、泄泻，为培元固本要穴。',NULL,'关元穴是任脉穴，为小肠募穴，有\"下丹田\"之称。定位：在下腹部，前正中线上，当脐中下3寸。主治：遗精、阳痿、早泄、月经不调、痛经、闭经、带下、不孕、虚劳羸瘦、泄泻、脱肛、小便不利。本穴有培元固本、补益下焦的作用，为保健强壮要穴。直刺1~1.5寸，可灸。',NULL,'中医知识库','任脉','关元为培元固本保健要穴','2026-04-17 06:30:00.000000',NULL,NULL,'关元穴；定位；主治；培元固本；强壮要穴',NULL,NULL,NULL,NULL,'经络学说','关元穴的定位与主治是什么？','经络学说',NULL,'理论','任脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(631,'气海穴在下腹部，前正中线上，当脐中下1.5寸。主治气虚、腹痛、泄泻、遗精、月经不调，有补气作用。',NULL,'气海穴有\"上丹田\"下气海之称。定位：在下腹部，前正中线上，当脐中下1.5寸。主治：腹痛、腹胀、泄泻、便秘、遗精、阳痿、月经不调、痛经、闭经、气虚乏力、虚脱。本穴有补气固本、调经止带的作用。直刺1~1.5寸，可灸。常灸气海可强壮身体。',NULL,'中医知识库','任脉','气海补气固本强壮身体','2026-04-17 06:30:00.000000',NULL,NULL,'气海穴；定位；主治；补气固本',NULL,NULL,NULL,NULL,'经络学说','气海穴的定位与主治是什么？','经络学说',NULL,'理论','任脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(632,'中脘穴在上腹部，前正中线上，当脐中上4寸。主治胃痛、呕吐、腹胀、泄泻，为胃募穴和腑会。',NULL,'中脘穴是任脉穴，为胃的募穴，也是八会穴之腑会。定位：在上腹部，前正中线上，当脐中上4寸。主治：胃痛、呕吐、腹胀、泄泻、便秘、食积、胃下垂、呃逆。本穴有健脾和胃、降逆止呕的作用，是治疗脾胃病的要穴。直刺1~1.5寸。',NULL,'中医知识库','任脉','中脘为胃募穴腑会治脾胃病','2026-04-17 06:30:00.000000',NULL,NULL,'中脘穴；定位；主治；胃募穴；腑会',NULL,NULL,NULL,NULL,'经络学说','中脘穴的定位与主治是什么？','经络学说',NULL,'理论','任脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(633,'膻中穴在胸部，当前正中线上，平第4肋间隙，两乳头连线的中点。主治胸闷、气喘、心悸、乳少、呃逆，为气会。',NULL,'膻中穴是任脉穴，为八会穴之气会，也是心包募穴。定位：在胸部，当前正中线上，平第4肋间隙，两乳头连线的中点。主治：胸闷、气喘、咳嗽、心悸、心烦、呃逆、噎膈、乳少、乳痈。本穴有宽胸理气、止咳平喘的作用，是治疗气机和胸肺部疾病的要穴。平刺0.3~0.5寸，可灸。',NULL,'中医知识库','任脉','膻中为气会宽胸理气要穴','2026-04-17 06:30:00.000000',NULL,NULL,'膻中穴；定位；主治；气会；宽胸理气',NULL,NULL,NULL,NULL,'经络学说','膻中穴的定位与主治是什么？','经络学说',NULL,'理论','任脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(634,'神阙穴在脐中央。主治腹痛、泄泻、脱肛、虚脱、中风昏迷。此穴禁针，常用艾灸或隔盐灸、隔姜灸。',NULL,'神阙穴即肚脐中央。定位：在脐中央。主治：腹痛、泄泻、脱肛、虚脱、中风昏迷、水肿。本穴为先天之气出入之所，有培元固本、回阳救脱的作用。注意：此穴禁针，只能用灸法，常用隔盐灸、隔姜灸，有温阳救逆的效果。治疗虚寒性疾病效果显著。',NULL,'中医知识库','任脉','神阙为先天之气穴禁针只灸','2026-04-17 06:30:00.000000',NULL,NULL,'神阙穴；定位；主治；禁针；灸法',NULL,NULL,NULL,NULL,'经络学说','神阙穴的定位与主治是什么？','经络学说',NULL,'理论','任脉','入门','2026-04-20 23:49:54.000000',NULL,NULL),(635,'任脉临床用于治疗胃痛、腹痛、虚脱、月经不调、阳痿遗精、咳喘、产后缺乳等。关元、气海、中脘为最常用穴位。',NULL,'任脉临床应用：消化系统——胃痛取中脘配足三里；泄泻取神阙、气海。妇科——月经不调取关元、气海配三阴交；痛经取关元配太冲。男科——遗精阳痿取关元配肾俞。呼吸系统——气喘取膻中配定喘。虚脱急救——关元、气海重灸回阳救脱。保健——常灸关元、气海可强身健体延年益寿。',NULL,'中医知识库','任脉','任脉临床治脏腑虚寒妇科男科','2026-04-17 06:30:00.000000',NULL,NULL,'任脉临床应用；胃痛；妇科；保健',NULL,NULL,NULL,NULL,'经络学说','任脉的临床应用有哪些？','经络学说',NULL,'理论','任脉','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(636,'任脉病候表现为男子内结七疝、女子带下瘕聚，以及腹部疼痛、月经不调、不孕等。',NULL,'任脉经脉病候：男子——内结七疝；女子——带下瘕聚。此外还可见腹部疼痛、月经不调、不孕、遗精、阳痿等。任脉总任一身之阴经，\"任主胞胎\"，故病候以生殖系统和腹部病证为主。',NULL,'中医知识库','任脉','任脉病候以生殖系统腹部病为主','2026-04-17 06:30:00.000000',NULL,NULL,'任脉病候；疝气；带下；瘕聚',NULL,NULL,NULL,NULL,'经络学说','任脉的经脉病候是什么？','经络学说',NULL,'理论','任脉','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(637,'任脉与督脉同起于胞中，任脉行于腹主阴，督脉行于背主阳。两脉在口唇部位相连接，构成阴阳循环。',NULL,'任脉与督脉的关系：两脉同起于胞中，一前一后，一阴一阳。任脉行于腹部正中，为\"阴脉之海\"，总任诸阴；督脉行于背部正中，为\"阳脉之海\"，总督诸阳。两脉在口唇部（龈交穴）相连接，形成阴阳循环。临床常督任配穴调理阴阳，如百会配关元升阳益气。',NULL,'中医知识库','任脉','任脉督脉一阴一阳构成循环','2026-04-17 06:30:00.000000',NULL,NULL,'任脉督脉；阴阳循环；一前一后',NULL,NULL,NULL,NULL,'经络学说','任脉与督脉的关系是怎样的？','经络学说',NULL,'理论','任脉','进阶','2026-04-20 23:49:54.000000',NULL,NULL),(638,'【定位】拇指桡侧指甲角旁约0.1寸\n【归经】手太阴肺经\n【功效】清热利咽，醒脑开窍\n【主治】咽喉肿痛，鼻衄，发热，昏迷，癫狂\n【配伍】配人中治昏厥；配合谷治咽喉肿痛\n【刺灸法】浅刺0.1寸或点刺出血',NULL,NULL,NULL,NULL,'手太阴肺经','肺经井穴','2026-04-17 06:39:13.000000',NULL,NULL,'肺经井穴，清热开窍',NULL,NULL,NULL,NULL,NULL,'少商','针灸学',NULL,'穴位',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(639,'【定位】前臂桡侧缘，腕横纹上1.5寸\n【归经】手太阴肺经\n【功效】宣肺利气，通经活络\n【主治】咳嗽气喘，咽喉肿痛，头痛项强，口眼歪斜，牙痛\n【配伍】配合谷治头痛、面口疾患\n【刺灸法】向上斜刺0.3~0.5寸',NULL,NULL,NULL,NULL,'手太阴肺经','络穴通任脉','2026-04-17 06:39:13.000000',NULL,NULL,'列缺任脉行肺系，头项寻列缺',NULL,NULL,NULL,NULL,NULL,'列缺','针灸学',NULL,'穴位',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(640,'【定位】腕掌侧横纹桡侧端，桡动脉搏动处\n【归经】手太阴肺经\n【功效】止咳化痰，通调血脉\n【主治】咳嗽气喘，咯血，胸痛，无脉症\n【配伍】配列缺治咳嗽\n【刺灸法】避开桡动脉，直刺0.3~0.5寸',NULL,NULL,NULL,NULL,'手太阴肺经','原穴脉会','2026-04-17 06:39:13.000000',NULL,NULL,'肺经原穴，脉会太渊',NULL,NULL,NULL,NULL,NULL,'太渊','针灸学',NULL,'穴位',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(641,'【定位】肘横纹中，肱二头肌腱桡侧缘\n【归经】手太阴肺经\n【功效】清热和胃，止咳平喘\n【主治】咳嗽咯血，气喘，潮热，咽喉肿痛，肘臂挛痛\n【配伍】配孔最治咯血\n【刺灸法】直刺0.8~1.2寸或点刺出血',NULL,NULL,NULL,NULL,'手太阴肺经','肺经合穴','2026-04-17 06:39:13.000000',NULL,NULL,'肺经合穴，泻肺热要穴',NULL,NULL,NULL,NULL,NULL,'尺泽','针灸学',NULL,'穴位',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(642,'【定位】第一掌骨中点桡侧，赤白肉际处\n【归经】手太阴肺经\n【功效】清热利咽，止咳平喘\n【主治】咳嗽咯血，咽喉肿痛，失音，发热\n【配伍】配少商治咽喉肿痛\n【刺灸法】直刺0.5~0.8寸',NULL,NULL,NULL,NULL,'手太阴肺经','肺经荥穴','2026-04-17 06:39:13.000000',NULL,NULL,'肺经荥穴，善治咽喉',NULL,NULL,NULL,NULL,NULL,'鱼际','针灸学',NULL,'穴位',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(643,'【定位】食指末节桡侧指甲角旁约0.1寸\n【归经】手阳明大肠经\n【功效】清热解表，开窍醒神\n【主治】咽喉肿痛，齿痛，耳鸣耳聋，热病昏迷\n【刺灸法】浅刺0.1寸或点刺出血',NULL,NULL,NULL,NULL,'手阳明大肠经','大肠经井穴','2026-04-17 06:39:13.000000',NULL,NULL,'大肠经井穴，泻热要穴',NULL,NULL,NULL,NULL,NULL,'商阳','针灸学',NULL,'穴位',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(644,'【定位】手背第1、2掌骨间，第2掌骨桡侧中点处\n【归经】手阳明大肠经\n【功效】镇静止痛，通经活络，清热解表\n【主治】头痛眩晕，目赤肿痛，鼻衄齿痛，面肿口歪，发热恶寒，无汗多汗，痛经经闭\n【配伍】配太冲治头痛、惊风；配风池治感冒\n【刺灸法】直刺0.5~1寸',NULL,NULL,NULL,NULL,'手阳明大肠经','四总穴之一','2026-04-17 06:39:13.000000',NULL,NULL,'面口合谷收，四总穴之一',NULL,NULL,NULL,NULL,NULL,'合谷','针灸学',NULL,'穴位',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(645,'【定位】肘横纹外侧端，屈肘时尺泽与肱骨外上髁连线中点\n【归经】手阳明大肠经\n【功效】清热解表，疏经活络\n【主治】热病，咽喉肿痛，上肢不遂，手臂肿痛，高血压，瘾疹，湿疹\n【配伍】配合谷治发热；配血海治荨麻疹\n【刺灸法】直刺1~1.5寸',NULL,NULL,NULL,NULL,'手阳明大肠经','大肠经合穴','2026-04-17 06:39:13.000000',NULL,NULL,'大肠经合穴，祛风清热',NULL,NULL,NULL,NULL,NULL,'曲池','针灸学',NULL,'穴位',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(646,'【定位】肩峰前下方，三角肌上部，肩峰与肱骨大结节之间\n【归经】手阳明大肠经\n【功效】疏经活络，理气化痰\n【主治】肩臂疼痛，手臂挛急，上肢不遂，瘾疹\n【刺灸法】直刺或向下斜刺0.8~1.5寸',NULL,NULL,NULL,NULL,'手阳明大肠经','治肩臂要穴','2026-04-17 06:39:13.000000',NULL,NULL,'通利关节要穴，治肩周炎',NULL,NULL,NULL,NULL,NULL,'肩髃','针灸学',NULL,'穴位',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(647,'【定位】鼻翼外缘中点旁开0.5寸，鼻唇沟中\n【归经】手阳明大肠经\n【功效】通鼻窍，散风热\n【主治】鼻塞不闻香臭，鼻衄，鼻渊，面痒面肿，口眼歪斜\n【配伍】配合谷治鼻疾\n【刺灸法】斜刺或平刺0.3~0.5寸',NULL,NULL,NULL,NULL,'手阳明大肠经','通鼻窍','2026-04-17 06:39:13.000000',NULL,NULL,'治鼻病要穴',NULL,NULL,NULL,NULL,NULL,'迎香','针灸学',NULL,'穴位',NULL,NULL,'2026-04-20 23:49:54.000000',NULL,NULL),(648,'【定位】瞳孔