INSERT INTO `wizard_combined_formula` VALUES (2,11,1,'test','{\n  \"analysis\": \"太阳少阳合病为《伤寒论》经典合病类型，主因风寒之邪初犯太阳（表证未解），随即邪郁少阳（半表半里），呈现‘发热微恶寒、口苦、咽干、目眩、胸胁苦满、脉弦’等典型症候。本例兼夹‘肝胆风寒郁闭证’，提示少阳枢机不利进一步深涉肝胆经络——风寒束表未散，又遏少阳升发之气，致肝胆疏泄失司、经气不利，可见头项强痛连及颞侧、胁肋拘急、善太息、舌边淡白薄滑、脉浮弦紧等表现，属‘寒郁少阳，风袭厥阴之络’的过渡态；此非单纯少阳热化，而是寒郁化机不展之‘少阳寒化’倾向，与典型少阳证（偏热）有别。‘test’为占位符，无临床意义，不予纳入辨证体系，视为信息冗余或待确认项，暂不参与合方构建。\",\n  \"formula\": \"柴胡桂枝汤加减：以小柴胡汤（柴胡、黄芩、人参、半夏、甘草、生姜、大枣）和解少阳、疏利枢机；合桂枝汤（桂枝、芍药、甘草、生姜、大枣）解肌发表、调和营卫。二方相合，既透太阳之邪于外，又开少阳之郁于中，契合‘太少双解、表里同治’之法。其中柴胡配桂枝，升散少阳与宣通太阳并行；黄芩制桂枝之温燥，防郁而化火；芍药敛阴和营，防柴胡、桂枝辛散太过；姜枣草调和中焦，助枢机运转——全方体现‘和法’之精要，正合《伤寒论》第146条‘伤寒六七日，发热微恶寒……支节烦疼，微呕，心下支结，外证未去者，柴胡桂枝汤主之’之旨。\",\n  \"modification\": \"若见明显风寒郁闭之象（如颈项强痛甚、颞部冷痛、遇风加重、无汗、脉紧如绳），加羌活、川芎各9g——羌活入太阳膀胱与少阳胆经，善祛上部风寒；川芎为‘血中气药’，上行头目、旁通少阳，助柴胡升达清阳、开郁止痛；若兼胁肋胀闷、情绪抑郁，加香附9g、郁金6g以疏肝解郁；若舌苔白滑、脘痞纳呆，提示寒湿内阻，去人参，加茯苓15g、苍术9g健脾化湿；若口苦、目赤稍显热象，可酌加栀子6g清三焦郁热，但须慎防过用苦寒伤阳，宜佐以姜汁炒制以制其寒性。\"\n}',0,'2026-04-17 23:00:10','2026-04-17 23:00:09.848723'),(4,12,1,'test','{\n  \"analysis\": \"太阳伤寒与少阳枢机不利构成经典‘太少两感’合病格局：太阳主表，寒邪束表则见恶寒、无汗、头身痛、脉浮紧；少阳居半表半里，枢机不利则见口苦、咽干、目眩、胸胁满闷、往来寒热或情绪郁滞。二者常相因为患——外寒郁遏太阳，气机不得宣达，进而内郁少阳；而素体肝胆气郁者，枢机本已不畅，更易招致外寒直中少阳之界，形成‘外寒引动内郁’的内外合邪机制。肝胆气郁为本，阳气不升为继发性病机：胆属少阳而寄相火，主升发疏泄；气郁日久则清阳不升，可见头晕沉、神疲、两胁坠胀、晨起恍惚、便溏不爽等症，实为少阳气机壅滞向‘清阳陷而不举’的病势延伸。‘test’为占位符，无临床意义，不予纳入辨证分析，建议用户核实录入是否误填。\",\n  \"formula\": \"柴胡桂枝汤（《伤寒论》）合升麻葛根汤（《太平惠民和剂局方》）加减：以柴胡桂枝汤和解少阳、兼散太阳之邪，为核心方；配升麻葛根汤升举阳明与少阳清阳之气，助枢机运转、促阳气升发。二方同用，体现‘和解+解表+升清’三法并施，契合‘太少同治、郁升并调’之旨。其中柴胡疏少阳之郁，桂枝解太阳之寒，黄芩清少阳之热，人参、甘草、生姜、大枣扶正和营卫，升麻、葛根升发清阳、透邪外出，共奏‘开郁、散寒、升阳、和枢’之效。\",\n  \"modification\": \"若恶寒重、无汗明显，加麻黄6g（先煎）、杏仁10g，增强太阳开腠之力（即合麻黄汤意）；若胁胀甚、善太息，加香附10g、青皮6g以疏肝破滞；若头晕沉、神倦乏力突出，加黄芪15g、党参12g益气助升；若口苦咽干明显、小便微黄，可加竹叶10g、连翘10g轻清泄热，防郁久化火；若便溏日久，去葛根，加炒白术12g、茯苓15g健脾运湿，体现‘见肝之病，当先实脾’之旨。禁用苦寒沉降之品（如黄连、龙胆草），以防遏抑清阳、加重气陷。\"\n}',0,'2026-04-17 23:35:55','2026-04-17 23:35:54.514862'),(5,13,1,'test syndrome','{\n  \"analysis\": \"太阳少阳合病为《伤寒论》经典合病类型，主因外感风寒之邪未解，郁而化热或枢机不利，致表证（太阳）与半表半里证（少阳）并见，症见恶寒发热、头项强痛、口苦咽干、胸胁满闷、脉浮弦等。肝胆风寒郁闭证属少阳病之变型，强调寒邪束遏少阳枢机，兼夹风性主动之性，故可见目眩、肢麻、颈项拘急、偏头痛、脉弦紧等，非纯热象，而是‘寒郁少阳、阳气不达’之机，与太阳表寒相引，形成‘表寒未解，枢机闭塞’的双重郁遏状态。气血不足则为本虚之基，既可为素体亏虚（如脾失健运、生化乏源，或久病耗伤），亦可因太阳少阳长期郁滞，气机不畅→气滞则血行涩滞→渐致气血两亏，表现为神疲、面色少华、动则汗出、舌淡苔薄、脉细弱等，构成‘标实本虚、虚实夹杂’之局。三者关系为：太阳表寒为始动之因，少阳枢机不利为传变之枢，肝胆风寒郁闭为其病理深化表现，而气血不足则是久郁伤正、累及营卫之果，四者互为因果，形成‘外寒束表—枢机壅遏—肝胆气郁—风寒闭络—气血暗耗’的病机链。注：‘test syndrome’为占位符，无临床定义，不参与辨证分析，建议用户核实或补充具体证型名称（如疑似‘痰瘀阻络’‘肝肾阴虚’等），此处不予纳入合方逻辑。\",\n  \"formula\": \"柴胡桂枝汤合当归四逆汤加减：以柴胡桂枝汤（小柴胡汤+桂枝汤）和解少阳、调和营卫、疏解太阳；合当归四逆汤（当归、桂枝、芍药、细辛、通草、甘草、大枣）温经散寒、养血通脉，专治肝胆风寒郁闭兼血虚寒凝之证。二方相合，共奏‘和解枢机、解散表寒、温通肝络、补益气血’之效——柴胡、黄芩清解少阳郁热；桂枝、生姜、甘草、大枣调和营卫以解太阳；当归、白芍养血柔肝；细辛、通草宣通肝胆经络之寒痹；炙甘草、大枣健中生气血之源。此配伍体现‘祛邪不伤正，扶正不留邪’之经方思想，契合《伤寒论》‘观其脉证，知犯何逆，随证治之’之旨。\",\n  \"modification\": \"若恶寒重、无汗、项背强几几者，加葛根15g、麻黄6g（去节），增强太阳经输布之力，即合葛根汤意；若口苦明显、心烦易怒、脉弦数，提示少阳郁热偏盛，酌减细辛、桂枝量，加牡丹皮9g、栀子6g清肝胆郁火；若头晕甚、视物模糊、肢体麻木，属风阳上扰兼络脉失养，加天麻10g、钩藤15g（后下）、鸡血藤30g以平肝通络；若气短乏力、食少便溏明显，为中气不足，加党参15g、炒白术12g、茯苓15g健脾益气，助气血生化；若舌质紫暗或有瘀斑，加丹参15g、川芎9g活血化瘀，兼顾久病入络之机。所有加减均宜据四诊动态调整，忌峻猛攻伐，重在调畅气机、徐图缓治。\"\n}',0,'2026-04-17 23:43:58','2026-04-17 23:43:58.330479'),(11,14,1,'test','{\n  \"analysis\": \"太阳少阳并病为《伤寒论》典型合病格局（第142条：\'太阳与少阳并病，头项强痛，或眩晕，时如结胸，心下痞硬者，当刺大椎第一间、肺俞、肝俞，慎勿下之\'），主因风寒之邪未解，郁而化热或枢机不利，由太阳表证渐涉少阳半表半里。肝胆风寒郁闭证为其深层病机延伸——风寒束于少阳枢机，致胆气不升、肝络失疏，胆经循行部位（如偏头痛、耳鸣、胁肋拘急、目眩）及肝主筋功能（项强、肢体微颤）皆受扰；\'test\'为占位符，无临床实义，故不予纳入辨证体系，视为信息冗余或录入误差，不参与合病分析。三者关系为：太阳表邪未罢为始动因素，少阳枢机不利为传变枢纽，肝胆风寒郁闭为脏腑-经络层面的实质性病机深化，属\'六经—脏腑—经络\'三维一体的病机链，符合\'太阳→少阳→肝胆\'的纵向传变与横向郁闭特征。\",\n  \"formula\": \"柴胡桂枝汤合止痉散加味：以柴胡桂枝汤（小柴胡汤+桂枝汤各半量）为底方，和解少阳、调和营卫、疏达太阳；配伍止痉散（全蝎、蜈蚣）搜风通络、开郁解痉，直入肝胆经络以宣散风寒郁闭。二方相合，体现\'和、解、散、通\'四法并用：柴胡、黄芩清少阳之郁热，桂枝、芍药调太阳之营卫，姜枣草扶中助运，全蝎、蜈蚣走窜肝经、祛风通痹，契合\'少阳枢机贵在通达，肝胆郁闭重在搜剔\'之机理。\",\n  \"modification\": \"若寒甚肢冷、脉紧者，加制附子6g（先煎）、细辛3g，温经散寒以助通阳；若兼口苦明显、烦躁易怒，为郁热渐盛，加牡丹皮9g、栀子6g，清肝胆郁火；若颈项强痛突出，加葛根15g、羌活9g，升津舒筋、祛风胜湿；若舌苔白腻、脘闷纳呆，提示兼太阴脾湿，加茯苓15g、苍术9g健脾化湿；孕妇及过敏体质者禁用全蝎、蜈蚣，可代以僵蚕9g、钩藤12g（后下）平肝息风、轻清透络。\"\n}',0,'2026-04-18 00:36:44','2026-04-18 00:36:44.254597'),(41,92,1,'痰湿内阻证','{\n  \"analysis\": \"风热犯肺证（外感风热邪气侵袭肺脏，导致咳嗽、咽痛、黄痰、发热、鼻塞流黄涕等）与痰湿内阻证（体内本有湿气积聚，脾运化失职，水湿停聚成痰，痰浊阻滞气机，表现为痰多黏白或咯吐不爽、胸闷、脘痞、舌苔腻、脉滑）并非孤立存在。通俗来说就是：外来的风热像一阵猛烈的热风，吹进了原本就潮湿闷热的房间（肺），而这个房间里的湿气（痰湿）又没来得及打扫，结果热+湿一搅和，变成又黏又黄、咳起来费劲的痰——这就是‘痰热郁肺’的雏形。风热为标，是新感之邪；痰湿为本，是素体脾虚湿盛所致。二者互为因果：风热灼津可炼液为痰，加重痰湿；痰湿壅肺又阻碍肺气宣降，使风热更难外散，形成‘外邪未解、内痰已生’的缠绵状态。\",\n  \"formula\": \"银翘散合二陈汤加减。银翘散（金银花、连翘、薄荷、牛蒡子、荆芥穗、淡豆豉、桔梗、甘草、竹叶、芦根）疏风清热、宣肺透邪；二陈汤（半夏、陈皮、茯苓、炙甘草、生姜、乌梅）燥湿化痰、理气和中。两方相合，一解其表、一治其里，体现‘表里同治、风痰并调’的思路：银翘散如开窗驱热风，二陈汤如除湿机抽潮气，共同恢复肺的清净与通利。\",\n  \"modification\": \"若痰黄稠难咯，加瓜蒌、黄芩清热化痰；若咽红肿痛明显，加玄参、马勃清利咽喉；若咳嗽剧烈、气逆作呕，加枇杷叶、苏子降肺止咳；若兼见乏力、食少、便溏等脾虚之象，去银翘散中辛凉发散过甚之品（如荆芥、豆豉可减量），加白术、党参健脾益气以绝生痰之源；若舌苔厚腻、胸闷甚，可加苍术、厚朴增强燥湿宽中之力。\"\n}',1,'2026-04-21 00:16:04','2026-04-21 00:16:03.599004'),(42,108,1,'清阳不升、气阴两虚','{\n  \"analysis\": \"少阳三焦郁热湿阻证是核心病机——相当于身体的‘交通调度系统’（三焦）被郁热和湿气堵住了，像梅雨季的下水道又热又堵，导致气机升降失常、水液代谢紊乱；清阳不升是其直接后果——清轻上升之气（如头脑清醒、精力充沛、耳目灵敏）被郁热湿浊往下压、托不上去，所以容易头昏沉、精神疲倦、食欲不振、大便黏滞；气阴两虚则是长期郁滞耗伤的结果——就像发动机长时间高温闷烧，既烧坏了‘燃料’（气），也蒸干了‘冷却液’（阴液），出现口干、乏力、心悸、舌红少苔等表现。三者形成恶性循环：郁热湿阻→清阳被遏→气化无力→气阴更虚→运化更差→湿热更盛。因此不是简单叠加，而是‘因-果-果中生因’的动态链，必须同步疏解郁热湿邪、升举清阳、补益气阴，单用一方难以兼顾。\",\n  \"formula\": \"小柴胡汤合升阳益胃汤加减（小柴胡汤：柴胡、黄芩、半夏、人参、炙甘草、生姜、大枣；升阳益胃汤：黄芪、半夏、人参、炙甘草、白术、陈皮、茯苓、泽泻、防风、羌活、独活、柴胡、黄连、白芍、生姜、大枣）。小柴胡汤专解少阳三焦郁热，调畅气机枢机，如打开卡住的阀门；升阳益胃汤以黄芪、人参、白术健脾气，柴胡、升麻、防风升清阳，黄连、泽泻清湿热，茯苓、半夏化痰湿，一升一降、一补一泄，恰对清阳不升兼气阴两虚之本虚标实。两方相合，共奏‘和解少阳、升清降浊、益气养阴、化湿清热’之效。\",\n  \"modification\": \"若口干咽燥明显、舌红少津，去黄连、羌活、独活，加南沙参、麦冬、石斛以加强养阴生津；若头重如裹、胸闷恶心突出，加藿香、佩兰芳香化湿醒脾；若午后低热、手足心热，加青蒿、地骨皮透热养阴；若大便溏稀日行二三次，去黄连、泽泻，加炒薏苡仁、山药健脾止泻；若乏力甚、动则气短，重用黄芪至30克，加西洋参6克另煎兑服以益气养阴。\"\n}',1,'2026-04-21 21:46:48','2026-04-21 21:46:47.600529');
/*!40000 ALTER TABLE `wizard_combined_formula` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `wizard_consultation`
--

DROP TABLE IF EXISTS `wizard_consultation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wizard_consultation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` bigint NOT NULL,
  `consultation_results` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '各流派会诊结果JSON',
  `selected_school` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最终采纳的流派',
  `final_plan` longtext COLLATE utf8mb4_unicode_ci COMMENT '最终方案JSON',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_session_id` (`session_id`),
  KEY `idx_consultation_session` (`session_id`),
  CONSTRAINT `wizard_consultation_ibfk_1` FOREIGN KEY (`session_id`) REFERENCES `wizard_diagnosis_session` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='步骤7-多流派会诊';
/*!40101 SET character_set_client = @saved_cs_client */;

