DROP TABLE IF EXISTS `wizard_followup`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wizard_followup` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` bigint NOT NULL,
  `overall_evaluation` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `symptom_evaluations` longtext COLLATE utf8mb4_unicode_ci COMMENT '各症状复诊评估JSON',
  `adjusted_plan` longtext COLLATE utf8mb4_unicode_ci COMMENT '调整后方案JSON',
  `feedback` text COLLATE utf8mb4_unicode_ci COMMENT '医患反馈',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_session_id` (`session_id`),
  KEY `idx_followup_session` (`session_id`),
  CONSTRAINT `wizard_followup_ibfk_1` FOREIGN KEY (`session_id`) REFERENCES `wizard_diagnosis_session` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='步骤6-疗效评估复诊';
